        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_ALFACE_ERVILHAS + "', '<h3>Ingredientes</h3><ul><li>1 alface média (cortada ou ripada)</li><li>200 g a 300 g de ervilhas (pode usar frescas ou congeladas)</li><li>1 cebola média (ou 2 chalotas) picada</li><li>1 dente de alho</li><li>1 pedaço pequeno de alho-francês (só a parte branca, opcional)</li><li>2 colheres de sopa de azeite</li><li>Sal a gosto</li><li>Água ou caldo de legumes (cerca de 1 litro)</li><li>Opcional: Hortelã fresca, umas gotas de sumo de limão ou iogurte natural para dar frescura</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, coloque o azeite, a cebola picada, o alho e o alho-francês. Deixe refogar até a cebola ficar translúcida.</p><p><b>Cozer:</b> Adicione as ervilhas e a água (ou caldo) e tempere com uma pitada de sal. Tape e deixe cozinhar em lume brando por cerca de 10 a 15 minutos.</p><p><b>Adicionar a alface:</b> Junte as folhas de alface ao tacho (juntamente com umas folhinhas de hortelã, se desejar). Deixe cozinhar por mais 5 a 8 minutos, pois a alface coze muito rapidamente.</p><p><b>Triturar:</b> Retire do lume e use a varinha mágica para triturar tudo até obter um creme aveludado e homogéneo.</p><p><b>Ajustar e Servir:</b> Retifique o sal e, se preferir o creme mais líquido, adicione um pouco mais de água e deixe ferver novamente por 1 minuto. Antes de servir, pode regar com um fio de azeite cru e adicionar algumas gotas de sumo de limão.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_TOFU_GRELHADO_LEGUMES + "', '<h3>Ingredientes</h3><ul><li>1 bloco de tofu firme (aprox. 250 g - 300 g)</li><li>Legumes variados a gosto (ex: 1 cebola, 1/2 pimento vermelho, 1 cenoura e 100 g de cogumelos)</li><li>2 colheres de sopa de azeite (ou óleo de sésamo)</li><li>3 colheres de sopa de molho de soja (shoyu)</li><li>1 colher de chá de alho em pó ou 1 dente de alho picado</li><li>Pitada de gengibre ralado (opcional)</li><li>Sementes de sésamo (para polvilhar)</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Pressione o tofu com um pano limpo ou papel de cozinha para retirar o excesso de água. Corte-o em fatias ou em cubos.</p><p><b>Marinar:</b> Numa taça, misture 1 colher de sopa de molho de soja, 1 colher de sopa de azeite e o alho. Envolva o tofu nesta mistura e deixe repousar por cerca de 10 a 15 minutos.</p><p><b>Grelhar o tofu:</b> Aqueça uma frigideira antiaderente ou grelhador. Coloque o tofu e grelhe durante 2 a 3 minutos de cada lado até ganhar uma crosta dourada. Retire e reserve.</p><p><b>Preparar os legumes:</b> Lave e corte todos os legumes em juliana (tiras finas) ou rodelas.</p><p><b>Saltear os legumes:</b> Na mesma frigideira, adicione o restante azeite e salteie os legumes em lume médio-alto. Comece pelos mais rijos (cenoura, pimento) e adicione os mais moles (cogumelos, cebola) passados alguns minutos. Tempere com o restante molho de soja, sal e pimenta.</p><p><b>Finalizar:</b> Quando os legumes estiverem tenros mas ainda crocantes, junte novamente o tofu à frigideira para aquecer tudo. Polvilhe com sementes de sésamo antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_TOMATE_PEPINO + "', '<h3>Ingredientes</h3><ul><li>2 tomates médios ou 1 chávena de tomate-cereja</li><li>1 pepino (de preferência pepino-japonês)</li><li>1 colher de sopa de sementes (escolha entre sementes de sésamo, chia ou linhaça)</li><li>1/4 de cebola roxa (opcional, para dar um toque mais aromático)</li></ul><h3>Molho e Temperos</h3><ul><li>2 colheres de sopa de azeite virgem extra</li><li>1 colher de sopa de sumo de limão ou vinagre de maçã</li><li>Sal e pimenta a gosto</li><li>Ervas frescas a gosto (salsa, coentros ou orégãos)</li></ul><h3>Preparação</h3><p><b>Preparar os vegetais:</b> Lave bem o tomate e o pepino. Corte o tomate em cubos ou em metades (se usar tomate-cereja). Corte o pepino em cubos.</p><p><b>Dica para não acumular água:</b> Se preferir uma salada mais firme, corte o pepino ao meio e retire o miolo com as sementes usando uma colher.</p><p><b>Cebola:</b> Corte a cebola roxa em fatias muito finas.</p><p><b>Misturar:</b> Numa saladeira, junte o tomate, o pepino e a cebola.</p><p><b>Temperar:</b> Adicione o azeite, o sumo de limão (or vinagre), o sal e a pimenta. Misture tudo muito bem.</p><p><b>Finalizar com as sementes:</b> Polvilhe a salada com as sementes escolhidas e adicione as ervas frescas picadas.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_CENOURA_COENTROS + "', '<h3>Ingredientes</h3><ul><li>500 g de cenouras</li><li>2 a 3 batatas (para dar textura cremosa)</li><li>1 cebola média</li><li>1 dente de alho (opcional)</li><li>1 ramo ou molho de coentros frescos</li><li>Azeite virgem extra q.b.</li><li>Sal e pimenta q.b.</li><li>Água q.b. (cerca de 1 a 1,5 litros)</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque a cenoura, a batata, a cebola e o alho. Corte tudo em pedaços médios.</p><p><b>Refogar (opcional):</b> Numa panela, coloque um fio de azeite e leve a cebola e o alho a alourar até ficarem transparentes.</p><p><b>Cozer:</b> Junte os pedaços de cenoura e batata ao refogado. Adicione água até cobrir os legumes (ou adicione cerca de 1 a 1,2 litros de água para uma textura perfeita), tempere com sal e tape a panela. Deixe cozinhar em lume médio durante cerca de 20 a 25 minutos, ou até que os legumes estejam bem tenros.</p><p><b>Triturar:</b> Retire a panela do lume e triture tudo com a ajuda de uma varinha mágica ou liquidificador até obter um creme aveludado e sem pedaços.</p><p><b>Finalizar:</b> Leve novamente a panela ao lume brando. Junte a maior parte dos coentros previamente lavados e picados e um fio de azeite. Deixe ferver por mais 2 a 3 minutos para apurar o sabor.</p><p><b>Servir:</b> Retifique o sal e a pimenta se necessário. Sirva o creme bem quente, polvilhado com mais alguns coentros frescos picados por cima e, se gostar, acompanhe com pequenos cubos de pão torrado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_COGUMELOS_SALTEADOS_ALHO + "', '<h3>Ingredientes (para 2 pessoas)</h3><ul><li>400 g de cogumelos frescos (Paris, marrons ou Portobello)</li><li>2 a 3 dentes de alho picados ou esmagados</li><li>3 colheres de sopa de azeite</li><li>1 colher de sopa de manteiga (opcional, para dar cremosidade)</li><li>Sumo de meio limão (opcional, para refrescar)</li><li>Sal e pimenta preta a gosto</li><li>Salsa ou coentros frescos picados</li></ul><h3>Preparação</h3><p><b>Limpeza:</b> Limpe os cogumelos com um pano ou papel de cozinha húmido. Evite lavá-los diretamente em água para que não fiquem encharcados. Corte-os em fatias ou em metades.</p><p><b>Refogado:</b> Leve uma frigideira ao lume com o azeite e aqueça. Adicione o alho picado e deixe alourar levemente, tendo cuidado para não o queimar.</p><p><b>Saltear:</b> Junte os cogumelos à frigideira. Deixe cozinhar em lume médio-alto, mexendo ocasionalmente. Notará que vão libertar água; deixe cozinhar até que essa água evapore e os cogumelos comecem a dourar.</p><p><b>Finalização:</b> Quando estiverem macios e dourados, adicione a manteiga (se desejar), o sumo de limão, tempere com sal e pimenta. Envolva tudo durante cerca de 1 a 2 minutos.</p><p><b>Servir:</b> Desligue o lume, polvilhe com salsa ou coentros picados e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_FEIJAO_VERDE_MASSA + "', '<h3>Ingredientes</h3><ul><li>300 g de feijão verde (lavado e cortado em juliana)</li><li>1 chávena de massa miúda (ex: cotovelos, pevide, estrelinhas)</li><li>2 batatas médias (para dar textura)</li><li>2 cenouras médias</li><li>1 cebola</li><li>2 dentes de alho</li><li>1 pedaço de abóbora ou curgete (opcional, para mais creme)</li><li>Azeite e sal q.b.</li><li>Água q.b. (cerca de 1 a 1,5 litros)</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque as batatas, as cenouras, a cebola e o alho. Corte tudo em pedaços médios.</p><p><b>Cozer a base:</b> Coloque todos estes legumes num tacho, adicione uma pitada de sal e regue com água (suficiente para cobrir e ficar ligeiramente acima dos legumes). Leve ao lume e deixe cozer cerca de 20 minutos.</p><p><b>Fazer o creme:</b> Retire o tacho do lume e triture tudo com a varinha mágica até obter um creme liso e aveludado. Se estiver muito espesso, adicione um pouco de água a ferver.</p><p><b>Adicionar o feijão verde e a massa:</b> Leve novamente o creme ao lume. Quando começar a ferver, adicione o feijão verde e a massinha. Mexa ocasionalmente para a massa não colar ao fundo.</p><p><b>Finalizar:</b> Deixe cozer em lume brando por cerca de 8 a 10 minutos (ou até a massa e o feijão verde estarem tenros).</p><p><b>Tempera:</b> Retifique o sal e adicione um fio de azeite a gosto antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_BROCOLOS + "', '<h3>Ingredientes</h3><ul><li>1 cabeça de brócolos grande (cerca de 500 g)</li><li>3 batatas médias (ou 1 curgete média para uma versão mais leve)</li><li>1 cebola média</li><li>2 dentes de alho</li><li>3 a 4 colheres de sopa de azeite</li><li>1 litro de água (aproximadamente)</li><li>Sal a gosto</li><li>Opcional: 100 ml de natas (ou leite) para um toque mais cremoso</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque a cebola, os dentes de alho e as batatas, cortando tudo em cubos. Lave bem os brócolos e separe-os em floretes (pode aproveitar o talo descascado e cortado em pedaços para a sopa).</p><p><b>Refogar:</b> Num tacho largo, adicione o azeite, a cebola e o alho. Deixe refogar em lume brando até a cebola ficar translúcida.</p><p><b>Cozer:</b> Adicione as batatas (ou curgete) e os talos dos brócolos. Cubra com a água, tempere com sal e deixe levantar fervura. Tape e deixe cozinhar durante cerca de 15 a 20 minutos.</p><p><b>Adicionar os brócolos:</b> Junte os floretes de brócolos ao tacho e deixe cozinhar por mais 10 minutos (não deixe cozer demasiado tempo para manter uma cor verde viva).</p><p><b>Triturar:</b> Retire o tacho do lume e passe tudo com a varinha mágica até obter um creme aveludado e sem pedaços.</p><p><b>Finalizar:</b> Se optar por usar natas ou leite, junte nesta fase e envolva bem. Rectifique o sal, se necessário, e leve novamente ao lume apenas para aquecer antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_RUSSA_VEG + "', '<h3>Ingredientes Base</h3><ul><li>3 batatas médias</li><li>2 cenouras</li><li>100 g de ervilhas (frescas ou congeladas)</li><li>100 g de feijão-verde ou vagem cortado em pedaços pequenos</li><li>1 pitada de sal (para a cozedura)</li><li>Pimenta preta a gosto</li></ul><h3>Sugestões de Molhos (Escolha um)</h3><ul><li><b>Maionese Vegetal (Vegan):</b> Maionese de compra à base de plantas ou caseira (feita com bebida de soja, azeite, alho e limão).</li><li><b>Maionese Tradicional:</b> 3 colheres de sopa de maionese e 1 colher de chá de mostarda.</li><li><b>Alternativa Saudável:</b> 2 colheres de sopa de iogurte grego ou natural, sumo de limão, azeite e salsa picada.</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque as batatas e as cenouras e corte-as em cubos pequenos e uniformes (cerca de 1 cm). Corte também o feijão-verde.</p><p><b>Cozer:</b> Numa panela com água a ferver e sal, coloque a batata e a cenoura. Deixe cozer por cerca de 10 a 15 minutos (verifique com um garfo, devem ficar tenras mas não desfeitas). Se usar ervilhas e feijão-verde frescos, pode juntar na mesma panela nos últimos 8 a 10 minutos.</p><p><b>Arrefecer:</b> Escorra muito bem todos os vegetais e deixe-os arrefecer completamente (pode passar por água fria corrente para parar a cozedura).</p><p><b>Adicionar o molho:</b> Transfira os legumes para uma taça grande, adicione a maionese ou molho de iogurte e envolva tudo cuidadosamente com uma espátula.</p><p><b>Temperar:</b> Retifique o sal, junte pimenta a gosto e salsa picada.</p><p><b>Servir:</b> Leve ao frigorífico para refrescar antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_LEGUMES_VARIADOS + "', '<h3>Ingredientes (base de 4 a 6 doses):</h3><ul><li>300g de batata</li><li>200g de cenoura</li><li>200g de curgete</li><li>150g de abóbora</li><li>1 cebola média</li><li>2 dentes de alho</li><li>1 alho-francês</li><li>Azeite e sal q.b.</li><li>Água para cobrir (cerca de 1,5 a 2 litros)</li></ul><h3>Preparação:</h3><p><b>Descasque e corte:</b> Descasque e corte todos os legumes em pedaços médios.</p><p><b>Refogar:</b> Numa panela grande, coloque a cebola, o alho e o azeite e deixe refogar ligeiramente.</p><p><b>Cozer:</b> Adicione os restantes legumes, o sal e cubra com água.</p><p><b>Apurar:</b> Tape a panela e deixe cozer em lume médio por 30 minutos.</p><p><b>Triturar:</b> Triture tudo com a varinha mágica até obter um creme aveludado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_OMELETE_ERVAS_SALADA + "', '<h3>Ingredientes</h3><p><b>Para a Omelete:</b></p><ul><li>2 ovos médios</li><li>1 a 2 colheres de sopa de ervas frescas picadas (salsa, cebolinho/cebolinha, coentros ou orégãos)</li><li>1 colher de chá de azeite ou manteiga (para untar a frigideira)</li><li>Sal marinho e pimenta preta moída na hora (a gosto)</li></ul><p><b>Para a Salada:</b></p><ul><li>80 g de folhas verdes frescas (rúcula, alface, ou agrião)</li><li>5 a 6 tomates-cereja cortados ao meio</li><li>1/4 de cebola roxa cortada em rodelas finas (opcional)</li><li>Molho: 1 colher de sopa de azeite, sumo de limão (ou vinagre), e uma pitada de sal</li></ul><h3>Preparação</h3><p><b>Preparar a Salada:</b> Numa saladeira, junte as folhas verdes, o tomate-cereja e a cebola roxa. Tempere com o azeite, o sumo de limão e o sal. Misture delicadamente e reserve.</p><p><b>Bater os Ovos:</b> Parta os ovos para uma taça, tempere com uma pitada de sal e pimenta. Bata com um garfo até obter uma mistura homogénea e ligeiramente fofa.</p><p><b>Adicionar as Ervas:</b> Junte as ervas frescas picadas aos ovos batidos e envolva bem.</p><p><b>Cozinhar a Omelete:</b> Aqueça uma frigideira antiaderente em lume médio e unte com o azeite ou manteiga. Verta a mistura de ovos para a frigideira e deixe cozinhar por 3 a 4 minutos, até as bordas começarem a soltar-se e a base ficar firme.</p><p><b>Dobrar e Servir:</b> Com a ajuda de uma espátula, dobre a omelete ao meio. Deixe cozinhar por mais 1 minuto para o interior ficar no ponto desejado e transfira para o prato. Sirva de imediato com a salada fresca a acompanhar.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_ABOBORA_SEMENTES + "', '<h3>Ingredientes</h3><ul><li>800 g de abóbora descascada e cortada em cubos</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 cenoura média (opcional, para dar mais textura e cor)</li><li>3 colheres de sopa de azeite</li><li>1 litro de caldo de legumes (ou água)</li><li>Sal e pimenta preta a gosto</li><li>4 colheres de sopa de sementes de abóbora (para a cobertura)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, aqueça o azeite. Adicione a cebola e o alho e deixe refogar até começarem a alourar.</p><p><b>Cozimento:</b> Junte a abóbora e a cenoura ao tacho e envolva bem. Adicione o caldo de legumes (ou água) até cobrir os legumes, tempere com sal e pimenta. Tape e deixe cozinhar em lume brando durante 20 a 25 minutos, até os vegetais estarem tenros.</p><p><b>Triturar:</b> Retire o tacho do lume e use uma varinha mágica para triturar tudo até obter um creme liso e homogéneo. Se o creme estiver demasiado espesso, adicione um pouco mais de água quente até atingir a consistência desejada. Retifique os temperos.</p><p><b>Sementes:</b> Numa frigideira pequena, sem adicionar gordura, coloque as sementes de abóbora e deixe-as tostar ligeiramente em lume brando até começarem a estalar (cerca de 3 a 5 minutos).</p><p><b>Servir:</b> Distribua o creme de abóbora por pratos ou taças e polvilhe generosamente com as sementes tostadas por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_GASPACHO_TOMATE + "', '<h3>Ingredientes (Gaspacho Tradicional)</h3><ul><li>1 kg de tomates maduros e vermelhos</li><li>1 pepino (cerca de 150g)</li><li>1 pimento vermelho</li><li>1/2 cebola ou cebola roxa</li><li>1 a 2 dentes de alho</li><li>1 fatia de pão amanhecido (opcional, para dar textura)</li><li>50 a 75 ml de azeite de oliva virgem extra</li><li>25 a 30 ml de vinagre (de vinho ou de maçã)</li><li>Sal e pimenta preta a gosto</li><li>Cerca de 100 a 150 ml de água bem gelada</li></ul><h3>Preparação</h3><p><b>Preparar os vegetais:</b> Lave bem os tomates, o pepino e o pimento. Descasque o alho e a cebola. Retire as sementes e as partes brancas do pimento. Corte todos os ingredientes em pedaços médios.</p><p><b>Triturar:</b> Coloque tudo num liquidificador ou processador de alimentos. Junte o azeite, o vinagre, a água gelada, o sal, a pimenta e o pão (se optar por o usar).</p><p><b>Emulsionar:</b> Bata tudo até obter uma mistura cremosa e homogénea.</p><p><b>Coar (Opcional):</b> Para um resultado mais fino e elegante, passe o creme por um passador de rede fina ou coador.</p><p><b>Refrigerar:</b> Leve ao frigorífico por pelo menos 1 a 2 horas para servir bem fresco.</p><p><b>Servir:</b> Sirva em taças fundas, podendo decorar com pedacinhos de pepino, tomate e um fio de azeite.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_LENTILHAS_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>250 g de lentilhas (vermelhas ou castanhas)</li><li>1 molho de espinafres frescos, lavados e cortados</li><li>1 cebola média picada</li><li>2 a 3 dentes de alho picados</li><li>1 ou 2 cenouras cortadas em cubos</li><li>2 batatas médias cortadas em cubos (opcional, para engrossar)</li><li>1,5 litros de água ou caldo de legumes</li><li>3 colheres de sopa de azeite</li><li>Sal e pimenta preta a gosto</li><li>Cominhos ou curcuma a gosto (opcional)</li></ul><h3>Preparação</h3><p><b>Preparar as lentilhas:</b> Passe as lentilhas por água. Se usar lentilhas castanhas, pode deixá-las de molho em água durante 15 a 20 minutos antes de cozinhar para acelerar o processo. Se usar lentilhas vermelhas, não precisa de demolhar.</p><p><b>Fazer o refogado:</b> Num tacho grande, coloque o azeite e leve ao lume médio. Adicione a cebola e o alho picados e deixe alourar até ficarem macios.</p><p><b>Adicionar os vegetais e lentilhas:</b> Junte as cenouras e as batatas (se optar por usar). Adicione também as lentilhas escorridas e os cominhos.</p><p><b>Cozinhar:</b> Regue tudo com a água ou o caldo de legumes e tempere com sal. Tape o tacho e deixe cozinhar em lume brando por cerca de 20 a 25 minutos, até que as lentilhas e os vegetais fiquem tenros.</p><p><b>Adicionar os espinafres:</b> Quando os legumes estiverem cozidos, junte os espinafres ao tacho. Deixe cozinhar por mais 3 a 5 minutos, até as folhas murcharem e perderem volume.</p><p><b>Retificar temperos:</b> Prove e ajuste o sal e a pimenta. Para uma sopa mais cremosa, pode triturar uma parte dos vegetais e da batata antes de adicionar os espinafres.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_GREGA_FETA + "', '<h3>Ingredientes Essenciais</h3><ul><li><b>Tomates:</b> 3 a 4 tomates médios maduros ou 200 g de tomate cherry, cortados em pedaços.</li><li><b>Pepino:</b> 1 pepino grande, cortado em rodelas ou meias-luas.</li><li><b>Cebola Roxa:</b> 1/2 cebola roxa cortada em rodelas finas (pode mergulhar em água fria para retirar o travo mais forte).</li><li><b>Azeitonas:</b> Cerca de 100 g de azeitonas pretas, preferencialmente Kalamata com caroço.</li><li><b>Queijo Feta:</b> 150 a 200 g de queijo Feta de qualidade (em bloco ou fatiado).</li><li><b>Pimento (Opcional):</b> 1/2 pimento verde ou amarelo cortado em tiras.</li><li><b>Tempero:</b> Azeite virgem extra, vinagre de vinho tinto, orégãos secos e uma pitada de sal.</li></ul><h3>Preparação da Salada</h3><p><b>Preparar os vegetais:</b> Numa saladeira grande, junte o tomate, o pepino, a cebola e o pimento.</p><p><b>Adicionar as azeitonas:</b> Junte as azeitonas à taça.</p><p><b>Temperar:</b> Tempere ligeiramente com sal (atenção que o queijo já é salgado). Regue generosamente com azeite e um pouco de vinagre e polvilhe com bastantes orégãos.</p><p><b>Colocar o Queijo:</b> Coloque o bloco ou fatias de queijo Feta por cima de toda a salada (a tradição dita não o esfarelar logo).</p><p><b>Servir:</b> Finalize com um fio de azeite extra por cima do queijo.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_COUVE_FLOR + "', 'Ingredientes1 couve-flor média (cortada em raminhos/floretes)2 alhos-franceses grandes (cortados em rodelas)1 cebola média picada1 a 2 dentes de alho picados2 a 3 colheres de sopa de azeite1 curgete (opcional, para maior cremosidade sem precisar de batata)Água ou caldo de legumes q.b.Sal e pimenta q.b.PreparaçãoPreparar os vegetais: Lave muito bem o alho-francês (especialmente entre as folhas, onde se acumula areia) e corte em rodelas. Separe a couve-flor em floretes e lave.Refogar: Numa panela grande, coloque o azeite e adicione a cebola picada e o alho-francês. Deixe cozinhar em lume brando até amolecer e ficar translúcido, sem deixar queimar.Adicionar os restantes legumes: Junte o alho picado e os floretes de couve-flor. Se optar por usar curgete para dar textura, adicione-a também nesta fase.Cozer: Cubra tudo com água ou caldo de legumes quente (cerca de 1 litro, ou até cobrir os vegetais) e tempere com sal. Deixe ferver, tape a panela e deixe cozinhar em lume médio-baixo durante cerca de 20 a 25 minutos, ou até a couve-flor estar bem tenra.Triturar: Retire a panela do lume e passe a sopa com a varinha mágica ou um liquidificador até obter um creme liso e aveludado. Se estiver muito espessa, adicione um pouco mais de água até atingir a consistência desejada.Finalizar: Retifique o tempero com sal e pimenta. Pode servir com um fio de azeite cru e ervas frescas picadas (como coentros ou salsa)');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_TOFU_SOJA_GENGIBRE + "', '<h3>Ingredientes</h3><ul><li>400g de tofu firme</li><li>4 colheres de sopa de molho de soja (shoyu)</li><li>1 pedaço de 3cm de gengibre fresco ralado</li><li>2 dentes de alho picados</li><li>1 colher de sopa de mel ou xarope de ácer (para o toque agridoce)</li><li>1 colher de sopa de amido de milho (opcional, para uma textura mais estaladiça)</li><li>1 a 2 colheres de sopa de óleo de sésamo ou azeite para grelhar</li><li>Cebolinha fresca picada para decorar</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Escorra o bloco de tofu e pressione-o suavemente com um pano limpo ou papel de cozinha para retirar o excesso de água. Corte em cubos ou triângulos.</p><p><b>Marinar:</b> Numa taça, misture o molho de soja, o gengibre ralado, o alho e o mel. Se desejar usar o amido de milho para o tornar mais crocante, envolva os cubos de tofu primeiro numa colher de sopa do amido antes de adicionar o molho.</p><p><b>Cozinhar:</b> Aqueça o óleo de sésamo ou azeite numa frigideira antiaderente em lume médio-alto. Adicione o tofu e deixe alourar durante alguns minutos de cada lado até ficar crocante e dourado.</p><p><b>Finalizar com o molho:</b> Verta o resto da marinada para a frigideira. Deixe o molho borbulhar e reduzir durante cerca de 1 a 2 minutos até engrossar e envolver todos os cubos de tofu.</p><p><b>Servir:</b> Retire do lume, polvilhe com cebolinha fresca picada e sirva com arroz ou vegetais.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_GRAO_MASSA + "', '<h3>Ingredientes (4 pessoas)</h3><ul><li>500 g de grão-de-bico (cozido)</li><li>100 g de massa para sopa (ex: cotovelinhos ou letras)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 a 2 cenouras médias (cortadas em pedaços ou rodelas)</li><li>1 batata média (para dar textura aveludada)</li><li>Azeite, sal e água q.b.</li><li>Opcional: 1 folha de louro, espinafres ou couve cortada em juliana</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho grande, leve ao lume o azeite, a cebola picada, o alho e a folha de louro. Deixe alourar ligeiramente.</p><p><b>Cozer os legumes:</b> Adicione a cenoura, a batata cortada em cubos e metade do grão-de-bico. Cubra com água (cerca de 1,5 litros) e tempere com sal. Deixe cozinhar em lume brando até os legumes estarem macios.</p><p><b>Triturar:</b> Retire a folha de louro. Com a varinha mágica, reduza a mistura a um creme homogéneo. Se o creme estiver demasiado espesso, adicione um pouco mais de água quente.</p><p><b>Adicionar a massa e o grão:</b> Leve o tacho novamente ao lume. Junte a massa e o restante grão-de-bico inteiro. Deixe ferver durante cerca de 8 a 10 minutos (ou o tempo indicado na embalagem da massa).</p><p><b>Finalizar:</b> Se desejar adicionar espinafres ou couve, junte-os 5 minutos antes de a massa estar pronta. Rectifique os temperos, adicione um fio de azeite cru e sirva quente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_ESPINAFRES_MACA + "', '<h3>Ingredientes</h3><ul><li>150 g de espinafres frescos (baby)</li><li>1 maçã (Royal Gala ou Granny Smith)</li><li>40 g de nozes</li><li>50 a 100 g de queijo (feta esfarelado ou lascas de parmesão)</li><li>Opcional: 1/4 de cebola roxa fatiada finamente</li></ul><p><b>Para o molho:</b></p><ul><li>2 colheres de sopa de azeite virgem extra</li><li>1 colher de sopa de vinagre de maçã (ou sumo de limão)</li><li>Sal e pimenta a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Lave e seque bem os espinafres. Lave a maçã, retire o caroço e corte-a em fatias finas ou cubos. Para evitar que a maçã oxide e escureça, regue-a com umas gotas de sumo de limão.</p><p><b>Tostar as nozes:</b> Numa frigideira sem gordura, leve as nozes ao lume durante 3 a 5 minutos para libertarem aroma e ficarem mais estaladiças. Deixe arrefecer e pique grosseiramente.</p><p><b>Fazer o molho:</b> Numa pequena taça, misture o azeite, o vinagre de maçã, o sal e a pimenta até emulsionar.</p><p><b>Montar a salada:</b> Numa saladeira, coloque a base de espinafres, adicione a maçã, a cebola roxa (se utilizar) e as nozes.</p><p><b>Finalizar:</b> Adicione o queijo e regue tudo com o molho preparado. Envolva delicadamente antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_ERVILHAS_HORTELA + "', '<h3>Ingredientes principais</h3><ul><li><b>Ervilhas:</b> 500 g (frescas ou congeladas)</li><li><b>Hortelã:</b> um ramo ou cerca de 15 g de folhas frescas</li><li><b>Base:</b> 1 cebola média e 2 dentes de alho</li><li><b>Textura:</b> 1 courgette média ou 2 batatas médias</li><li><b>Líquido:</b> 700 ml a 800 ml de água ou caldo de legumes</li><li><b>Tempero:</b> azeite, sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Numa panela, coloque um fio generoso de azeite e adicione a cebola e o alho picados. Deixe refogar em lume brando até a cebola ficar translúcida.</p><p><b>Cozer a base:</b> Adicione a batata ou courgette cortada em pedaços pequenos. Junte a água ou o caldo de legumes e deixe ferver por cerca de 15 minutos até os vegetais estarem macios.</p><p><b>Adicionar as ervilhas:</b> Junte as ervilhas à panela e deixe cozinhar por mais 5 minutos. (Se usar ervilhas congeladas, não precisa de descongelar antes).</p><p><b>Triturar:</b> Retire a panela do lume, junte as folhas de hortelã e triture com a varinha mágica até obter um creme homogéneo e aveludado.</p><p><b>Ajustar e servir:</b> Se o creme estiver demasiado espesso, adicione um pouco mais de água quente. Tempere com sal e pimenta a gosto. Pode servir quente ou levar ao frigorífico para servir frio nos dias mais quentes.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_OVOS_TOMATE_SHAKSHUKA + "', '<h3>Ingredientes</h3><p><b>Para preparar a sua Shakshuka, vai precisar de:</b></p><ul><li>4 a 6 ovos</li><li>1 lata (400 g) de tomate pelado ou tomate em cubos</li><li>1 cebola média picada</li><li>1/2 pimento (pimentão) vermelho cortado em cubos ou tiras</li><li>2 a 3 dentes de alho picados</li><li>1 colher de chá de páprica (doce ou fumada)</li><li>1/2 colher de chá de cominho em pó</li><li>1 colher de sopa de azeite</li><li>Sal e pimenta-do-reino a gosto</li><li>Ervas frescas (salsa, coentros ou cebolinho) para decorar</li><li>Opcional: Queijo Feta esfarelado e pão para acompanhar</li></ul><h3>Preparação</h3><p><b>Refogado base:</b> Leve uma frigideira grande ao lume médio com o azeite. Junte a cebola e o pimento, e deixe refogar até começarem a amaciar (cerca de 5 minutos). Adicione o alho picado e mexa até sentir o aroma.</p><p><b>Adicionar especiarias:</b> Junte a páprica e o cominho, mexendo sempre durante um minuto.</p><p><b>Fazer o molho:</b> Adicione os tomates pelados à frigideira. Se usar tomates inteiros, esmague-os com uma colher de pau. Tempere com sal e pimenta. Deixe o molho apurar em lume brando durante 10 a 15 minutos, até engrossar e ficar com uma boa consistência.</p><p><b>Cozinhar os ovos:</b> Com a ajuda de uma colher, abra pequenas covas no molho de tomate. Parta os ovos e coloque um em cada cavidade.</p><p><b>Finalizar:</b> Tempere os ovos com uma pitada de sal. Tape a frigideira e deixe cozinhar em lume brando durante 5 a 8 minutos, ou até as claras estarem firmes mas as gemas ainda líquidas e cremosas.</p><p><b>Servir:</b> Retire do lume e polvilhe com as ervas frescas e o queijo feta, se desejar. Sirva de imediato com fatias de pão torrado para molhar no molho.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_MINESTRONE_MAR + "', '<h3>Ingredientes Recomendados</h3><ul><li>1 cebola picada</li><li>2 dentes de alho picados</li><li>1 cenoura média em cubos</li><li>1 curgete (abobrinha) em cubos</li><li>1 chávena de feijão branco cozido</li><li>1/4 chávena de massa curta (ex: cotovelos ou ave-maria)</li><li>1 folha de louro</li><li>2 tomates maduros picados (ou 4 colheres de sopa de polpa de tomate)</li><li>Legumes verdes de primavera (ex: espargos, ervilhas, vagem)</li><li>Azeite, sal e pimenta preta a gosto</li><li>Água ou caldo de legumes</li></ul><h3>Preparação</h3><p><b>Refogado base:</b> Numa panela grande, aqueça um fio de azeite e salte a cebola e o alho até dourarem.</p><p><b>Adicionar os vegetais duros:</b> Junte a cenoura, o louro e os tomates picados. Deixe cozinhar por cerca de 5 a 10 minutos para amaciar e apurar os sabores.</p><p><b>Cozimento:</b> Adicione a água ou caldo de legumes (cerca de 1,5 litros). Quando ferver, adicione a massa e os legumes de primavera (ervilhas, vagem, espargos). Deixe cozinhar em lume brando por 10 minutos.</p><p><b>Finalização:</b> Adicione a curgete e o feijão branco cozido. Deixe ferver por mais 5 minutos até a curgete e a massa estarem al dente.</p><p><b>Temperos:</b> Retire a folha de louro. Tempere com sal e pimenta a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_BETERRABA_LARANJA + "', '<h3>Ingredientes Base</h3><ul><li>300 g de beterraba (cozida ou assada)</li><li>2 laranjas grandes</li><li>Azeite virgem extra q.b.</li><li>Sal e pimenta-preta moída na hora q.b.</li><li>Folhas de hortelã fresca ou salsa picada</li></ul><p><b>Opcionais para enriquecer a salada:</b></p><ul><li>1/2 cebola roxa cortada em fatias finas</li><li>1 colher de sopa de alcaparras</li><li>Queijo feta (esfarelado) ou queijo de cabra</li><li>Frutos secos picados (nozes, amêndoas ou pistácios)</li></ul><h3>Preparação</h3><p><b>Preparar as laranjas:</b> Descasque as laranjas com uma faca afiada, retirando toda a casca e a pele branca (película). Corte a laranja em rodelas ou separe os gomos (supremes). Reserve.</p><p><b>Preparar a beterraba:</b> Escorra o excesso de líquido da beterraba cozida e corte-a em rodelas, cubos ou quartos.</p><p><b>Montagem:</b> Numa saladeira, disponha alternadamente as fatias ou pedaços de beterraba e de laranja.</p><p><b>Adicionar extras:</b> Se optar por usar, espalhe a cebola roxa, as alcaparras, o queijo e os frutos secos por cima dos ingredientes principais.</p><p><b>Temperar:</b> Polvilhe com a hortelã ou salsa picada. Regue generosamente com azeite e tempere com sal e pimenta a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_COURGETTE + "', '<h3>Ingredientes</h3><ul><li>500 g de curgetes (cortadas em pedaços com ou sem casca)</li><li>1 cebola média (picada ou fatiada)</li><li>2 dentes de alho</li><li>2 batatas médias (opcional, para engrossar)</li><li>1 colher de sopa de azeite</li><li>Sal e pimenta a gosto</li><li>750 ml a 800 ml de água ou caldo de legumes</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, coloque o azeite, a cebola e o alho e deixe refogar suavemente até a cebola ficar translúcida.</p><p><b>Cozedura:</b> Adicione a curgete (e a batata, se usar) ao refogado, envolva e deixe saltear durante alguns minutos. Adicione a água ou o caldo de legumes e tempere com sal. Deixe cozer em lume médio durante 15 a 20 minutos.</p><p><b>Trituração:</b> Retire do lume e use a varinha mágica para triturar tudo até obter um creme liso e aveludado.</p><p><b>Finalização:</b> Prove o creme e rectifique o sal ou a pimenta. Se o creme estiver demasiado espesso, adicione um pouco mais de água fervente até atingir a consistência desejada. Sirva quente com um fio de azeite por cima e coentros frescos picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_PORTOBELLO_GRELHADO_SALADA + "', '<h3>Ingredientes (para 2 doses)</h3><ul><li><b>Cogumelos:</b> 4 unidades grandes de Cogumelos Portobello</li><li><b>Tempero dos cogumelos:</b> 2 dentes de alho picados, 2 colheres de sopa de azeite, sal e pimenta a gosto</li><li><b>Base da Salada:</b> 100g de folhas verdes frescas (rúcula, espinafre ou alface baby)</li><li><b>Complementos:</b> 100g de Tomate Cherry cortado ao meio</li><li><b>Molho:</b> 3 colheres de sopa de azeite e 1 colher de sopa de vinagre balsâmico ou sumo de limão</li></ul><h3>Preparação</h3><p><b>Limpar:</b> Limpe delicadamente os Cogumelos Portobello com uma escova ou papel toalha úmido. Evite passar por água corrente para que não absorvam líquido. Remova os pés (pode picá-los para a salada).</p><p><b>Grelhar:</b> Numa frigideira grande, aqueça o azeite e doure o alho. Coloque os cogumelos virados para baixo. Tempere com sal e pimenta. Deixe grelhar em lume médio-baixo por 3 a 4 minutos de cada lado até ficarem tenros.</p><p><b>Salada:</b> Numa taça grande, misture as folhas verdes, o Tomate Cherry e outros vegetais a gosto (como cebola roxa ou beterraba em cubos).</p><p><b>Montagem:</b> Disponha os Cogumelos Portobello mornos por cima da salada, regue tudo com o azeite e o vinagre ou limão.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_TOMATE_MANJERICO + "', '<h3>Ingredientes</h3><ul><li>1 kg de tomates maduros e cortados (ou tomate pelado)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>500 ml de água</li><li>Folhas de manjericão fresco a gosto</li><li>Azeite e sal a gosto</li><li>Opcional: 1 folha de louro e pimenta</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, coloque um fio de azeite e leve ao lume. Junte a cebola e os alhos picados, deixando refogar até a cebola ficar translúcida.</p><p><b>Cozedura:</b> Adicione os tomates cortados ao tacho (e a folha de louro, se desejar). Deixe cozinhar por alguns minutos até o tomate começar a amolecer.</p><p><b>Ferver:</b> Acrescente a água e o sal. Deixe levantar fervura e, em seguida, reduza para lume brando, deixando cozer durante cerca de 15 a 20 minutos.</p><p><b>Triturar:</b> Retire o tacho do lume, remova a folha de louro e triture tudo com uma varinha mágica ou liquidificador até obter um creme liso e homogéneo.</p><p><b>Finalização:</b> Junte as folhas de manjericão fresco e triture ligeiramente apenas para libertar o aroma, ou envolva-as na sopa quente. Retifique os temperos, regue com um fio de azeite cru e sirva.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_ALFACE_MILHO + "', '<h3>Ingredientes</h3><ul><li>1 pé ou maço médio de alface</li><li>1 lata (ou xícara) de milho verde escorrido</li><li>1 cenoura média ralada</li></ul><p><b>Opcionais para enriquecer a salada:</b></p><ul><li>Tomate em cubos</li><li>Ervilha em conserva</li><li>Presunto em cubos ou peito de peru</li></ul><h3>Preparação</h3><p><b>Higienização:</b> Lave bem as folhas de alface e seque-as. Pique ou rasgue a alface em pedaços médios, ideais para uma garfada.</p><p><b>Preparo dos Vegetais:</b> Rale a cenoura no ralo fino ou grosso, conforme a sua preferência, e corte o tomate se for utilizar.</p><p><b>Montagem:</b> Numa saladeira grande, coloque a alface, a cenoura ralada e o milho. Misture tudo com cuidado para não amassar as folhas.</p><p><b>Tempero:</b> Tempere apenas no momento de servir para manter a alface crocante. Pode usar sal, azeite e vinagre (ou sumo de limão).</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_ESPARGOS + "', '<h3>Ingredientes</h3><ul><li>1 molho de espargos verdes frescos</li><li>2 a 3 batatas médias ou 1 curgete (para dar textura cremosa)</li><li>1 cebola média</li><li>1 dente de alho</li><li>Azeite q.b.</li><li>Sal e pimenta a gosto</li><li>Água (cerca de 700ml)</li><li>Natas (ou leite de coco / creme de soja) para finalizar (opcional)</li></ul><h3>Preparação</h3><p><b>Preparar os vegetais:</b> Lave bem os espargos e corte a parte mais dura e fibrosa do talo. Pode reservar as pontas mais tenras e bonitas para decorar no final. Descasque a cebola, o alho e as batatas (ou curgete) e corte tudo em pedaços.</p><p><b>Refogar:</b> Numa panela, coloque um fio de azeite e adicione a cebola e o alho picados. Deixe alourar ligeiramente.</p><p><b>Cozer:</b> Junte os talos dos espargos e as batatas/curgete cortados. Envolva bem, adicione água até cobrir os legumes (ou adicione os 700ml) e tempere com sal. Tape a panela e deixe cozinhar em lume médio por cerca de 20 a 25 minutos, até que tudo esteja bem tenro.</p><p><b>Triturar:</b> Retire a panela do lume e triture tudo com a varinha mágica até obter um creme liso e aveludado. Se estiver demasiado espesso, adicione um pouco mais de água a ferver.</p><p><b>Finalizar:</b> Volte a colocar em lume brando. Se desejar um creme mais rico, adicione as natas (ou alternativa) e mexa. Se reservou as pontas dos espargos, adicione-as agora e deixe cozinhar por mais 5 a 8 minutos até ficarem tenras.</p><p><b>Servir:</b> Rectifique os temperos com sal e pimenta e sirva quente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_TOFU_MEXIDO_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>250 g a 400 g de tofu firme</li><li>60 g a 100 g de espinafres frescos</li><li>1 cebola pequena picada</li><li>2 dentes de alho picados</li><li>1 colher de sopa de azeite</li><li>½ colher de chá de curcuma (açafrão-da-terra)</li><li>Sal e pimenta-preta a gosto</li><li>Opcional: Cogumelos fatiados ou tomate cherry</li></ul><h3>Preparação</h3><p><b>Preparar o Tofu:</b> Retire o tofu da embalagem e escorra o excesso de líquido. Com as mãos, esfarele o tofu numa tigela para obter uma textura semelhante à de ovos mexidos.</p><p><b>Refogar:</b> Aqueça o azeite numa frigideira em lume médio. Adicione a cebola e o alho picados e deixe refogar até começarem a dourar.</p><p><b>Temperar e Cozinhar o Tofu:</b> Adicione o tofu esfarelado à frigideira. Polvilhe com a curcuma, o sal e a pimenta-preta. Envolva tudo muito bem e deixe cozinhar durante cerca de 3 a 5 minutos, mexendo ocasionalmente.</p><p><b>Adicionar os Espinafres:</b> Junte as folhas de espinafre frescos ao preparado. Tape a frigideira durante 1 a 2 minutos até que as folhas murchem.</p><p><b>Servir:</b> Misture tudo uma última vez, rectifique os temperos se necessário, e sirva de imediato. Acompanha muito bem com pão integral ou como recheio para wraps.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SOPA_CEBOLA + "', '<h3>Ingredientes</h3><ul><li>1 kg de cebolas cortadas em meias-luas finas</li><li>50 g de manteiga</li><li>1 colher de sopa de azeite</li><li>2 colheres de sopa de farinha de trigo</li><li>120 ml a 250 ml de vinho branco seco (opcional)</li><li>1,5 litros de caldo de carne ou legumes</li><li>Sal e pimenta-do-reino a gosto</li><li>Fatias de pão (tipo cacete, baguete ou italiano)</li><li>Queijo ralado (Gruyère, Emmental ou Mozarela)</li></ul><h3>Preparação</h3><p><b>Caramelizar:</b> Numa panela grande, derreta a manteiga com o azeite em lume brando. Adicione as cebolas e deixe cozinhar lentamente, mexendo ocasionalmente, durante 30 a 40 minutos até ficarem bem douradas e macias.</p><p><b>Polvilhar:</b> Junte a farinha de trigo, mexa bem e deixe cozinhar por cerca de 2 minutos.</p><p><b>Adicionar Líquidos:</b> Verta o vinho branco e raspe o fundo da panela para soltar todos os sabores. Deixe o álcool evaporar por alguns minutos. Aos poucos, adicione o caldo quente e tempere com sal e pimenta.</p><p><b>Ferver:</b> Deixe a sopa levantar fervura, reduza o lume e deixe apurar durante 15 a 20 minutos.</p><p><b>Gratinar:</b> Distribua a sopa por cumbucas que possam ir ao forno. Coloque uma fatia de pão torrado por cima e cubra com uma boa camada de queijo. Leve ao forno a gratinar até o queijo derreter e ficar dourado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_SALADA_GRAO_COUVE_FLOR + "', '<h3>Ingredientes</h3><ul><li>1 couve-flor média, cortada em pequenos floretes (buquês)</li><li>400 g de grão-de-bico cozido (cerca de 2 chávenas)</li><li>3 colheres de sopa de azeite</li><li>1 colher de chá de cominhos em pó ou paprika</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p>Pré-aqueça o forno a 200°C.</p><p>Num tabuleiro, disponha os floretes de couve-flor e o grão-de-bico escorrido.</p><p>Regue com o azeite e tempere com os cominhos (ou paprika), o sal e a pimenta. Envolva bem.</p><p>Leve ao forno por cerca de 30 minutos, mexendo a meio do tempo, até a couve-flor ficar dourada e o grão estaladiço.</p><p>Retire, deixe arrefecer ligeiramente e sirva simples ou com um molho à base de iogurte e limão.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAR_CREME_LEGUMES_CROUTONS + "', '<h3>Ingredientes</h3><p><b>Para o Creme:</b></p><ul><li>2 cenouras médias picadas</li><li>1 curgete (abobrinha) média picada</li><li>1 abóbora pequena ou 1 pedaço de abóbora (aprox. 300g)</li><li>2 batatas médias para dar cremosidade (ou batata-doce)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>2 colheres de sopa de azeite</li><li>Água (aprox. 750ml a 1 litro)</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para os Crôutons:</b></p><ul><li>3 a 4 fatias de pão (de forma ou rústico)</li><li>2 colheres de sopa de azeite</li><li>Alho em pó ou orégãos a gosto</li></ul><h3>Preparação do Creme</h3><p><b>Refogado base:</b> Numa panela grande, adicione o azeite e refogue a cebola e o alho até dourarem.</p><p><b>Cozinhar os legumes:</b> Adicione a cenoura, a curgete, a abóbora e a batata. Cubra com água a ferver, adicione sal e deixe cozinhar em lume brando por cerca de 20-25 minutos, até que todos os legumes estejam bem macios.</p><p><b>Triturar:</b> Retire do lume e use uma varinha mágica ou liquidificador para triturar tudo até obter um creme liso e aveludado. Se estiver muito espesso, adicione um pouco mais de água até atingir a consistência desejada. Rectifique os temperos (sal e pimenta).</p><h3>Preparação dos Crôutons</h3><p>Corte as fatias de pão em cubos pequenos e uniformes.</p><p>Coloque os cubos de pão num tabuleiro de forno e regue com o azeite. Polvilhe com sal e os temperos desejados (como alho em pó ou orégãos).</p><p>Leve ao forno pré-aquecido a 180°C por cerca de 10 a 15 minutos. Vá vigiando e mexendo a meio do tempo para que fiquem tostados e crocantes por igual. Retire e deixe arrefecer.</p>');");

        // ==========================================
// PEQUENOS-ALMOÇOS - ABRIL (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_MORANGO_CHIA + "', '<h3>Ingredientes</h3><ul><li>1 chávena de morangos (frescos ou congelados)</li><li>1 colher de sopa de sementes de chia</li><li>1/2 banana (ajuda a dar consistência cremosa)</li><li>200 ml a 250 ml de leite de amêndoa, leite magro ou água de coco</li><li>Opcional: 1 colher de chá de mel, xarope de ácer ou adoçante a gosto</li><li>Opcional: 1 a 2 cubos de gelo</li></ul><h3>Modo de Preparo</h3><p>Coloque os ingredientes líquidos no liquidificador primeiro (leite ou água de coco), para facilitar o processo de mistura.</p><p>Adicione os sólidos como os morangos, a banana e as sementes de chia.</p><p>Se desejar uma bebida mais gelada, adicione os cubos de gelo nesta fase.</p><p>Triture tudo na potência máxima durante 1 a 2 minutos, até obter uma textura aveludada e sem pedaços.</p><p>Verta para um copo e sirva de imediato. Se preferir sementes de chia mais hidratadas, pode deixar repousar no frigorífico por 10 minutos antes de beber.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_AVEIA_AMENDOA_MEL + "', '<h3>Ingredientes (1 pessoa)</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>200 ml de leite ou bebida vegetal (a de amêndoa é ideal para realçar o sabor)</li><li>1 colher de chá de mel (ou a gosto)</li><li>1 colher de sopa de amêndoas (laminadas ou picadas)</li><li>1 pitada de canela em pó</li><li>Opcional: casca de limão ou pau de canela para aromatizar a cozedura</li></ul><h3>Preparação no Tacho</h3><p><b>Misturar:</b> Num tacho, junte os flocos de aveia, o leite ou bebida vegetal e a canela. Se desejar, adicione uma casca de limão.</p><p><b>Cozinhar:</b> Leve a lume brando e mexa com frequência para não pegar ao fundo. Deixe cozinhar durante cerca de 5 minutos até obter uma textura cremosa.</p><p><b>Servir:</b> Retire do lume e descarte a casca de limão, caso a tenha utilizado. Verta para uma taça.</p><p><b>Decorar:</b> Adicione o mel e as amêndoas por cima. Pode também tostar ligeiramente as amêndoas numa frigideira antes de as colocar nas papas.</p><h3>Preparação no Micro-ondas</h3><p>Numa taça larga e funda, coloque os flocos de aveia, o leite e a canela.</p><p>Leve ao micro-ondas na potência máxima por 2 a 3 minutos.</p><p>Pare o micro-ondas a cada 30 segundos e mexa bem, para que a mistura ganhe uma consistência cremosa e uniforme.</p><p>Retire, adicione o mel e as amêndoas e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_ABACATE_OVO + "', '<h3>Ingredientes</h3><ul><li>2 a 3 fatias de pão grosso</li><li>1 abacate maduro</li><li>2 ovos</li><li>Sumo de 1/2 lima ou limão</li><li>1 colher de sopa de vinagre (para a água do ovo)</li><li>Azeite, sal e pimenta preta a gosto</li><li>Opcionais: Tomate cherry, folhas de rúcula ou sementes de sésamo/chia</li></ul><h3>Preparação</h3><p><b>O Abacate:</b> Numa taça, esmague a polpa do abacate com um garfo. Junte o sumo de lima, um fio de azeite, uma pitada de sal e pimenta. Misture até obter uma pasta cremosa.</p><p><b>O Pão:</b> Toste as fatias de pão numa torradeira ou numa frigideira com umas gotas de azeite até ficarem bem estaladiças.</p><p><b>O Ovo Escalfado:</b> Encha uma panela com água e adicione o vinagre. Quando começar a levantar fervura suave, mexa a água com uma colher para criar um redemoinho. Abra um ovo para o centro desse redemoinho e deixe cozinhar durante 3 a 4 minutos (para que a clara fique firme e a gema cremosa). Retire com uma escumadeira e repita para o segundo ovo.</p><p><b>Montagem:</b> Barre as torradas com a pasta de abacate. Por cima, coloque o ovo escalfado e dê um pequeno golpe na gema para esta se espalhar. Tempere o ovo com uma pitada de sal e pimenta.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_IOGURTE_GRANOLA_TROPICAL + "', '<h3>Ingredientes</h3><ul><li><b>Iogurte:</b> 1 unidade (aprox. 125g a 200g) de iogurte natural, grego ou vegetal (soja, coco).</li><li><b>Frutas Tropicais:</b> 1 chávena de frutas frescas picadas (combinações excelentes incluem manga, abacaxi, maracujá, papaia ou banana).</li><li><b>Granola:</b> 3 a 4 colheres de sopa de granola (com frutos secos ou sementes).</li><li><b>Toque Final:</b> 1 colher de sopa de mel, xarope de ácer ou néctar de agave (opcional).</li></ul><h3>Preparação</h3><p><b>Prepare as frutas:</b> Descasque e corte as frutas tropicais em pedaços médios ou cubos.</p><p><b>Monte a taça:</b> Numa taça ou copo largo, adicione o iogurte como base.</p><p><b>Adicione as frutas:</b> Distribua as frutas tropicais cortadas por cima do iogurte.</p><p><b>Acrescente crocância:</b> Polvilhe a granola sobre a fruta.</p><p><b>Finalize:</b> Regue com um fio de mel ou xarope a gosto e sirva de imediato para manter a granola crocante.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PANQUECAS_ESPELTA + "', '<h3>Ingredientes Base</h3><ul><li><b>Farinha de espelta:</b> 6 colheres de sopa (aprox. 60g)</li><li><b>Líquido:</b> 200 ml de bebida vegetal (amêndoa ou soja) ou 60 ml de leite</li><li><b>Ovos:</b> 1 a 2 unidades (dependendo da textura desejada)</li><li><b>Fermento em pó:</b> 1 colher de chá</li><li><b>Adoçante:</b> 1 colher de sopa de mel, xarope de agave ou açúcar (opcional)</li><li><b>Topping:</b> Bagas frescas a gosto (mirtilos, framboesas ou morangos)</li><li><b>Gordura:</b> Um pouco de óleo de coco ou manteiga para untar a frigideira</li></ul><h3>Modo de Preparação</h3><p><b>Preparar a massa:</b> Coloque todos os ingredientes (exceto as bagas) numa taça ou copo alto e triture com a varinha mágica até obter uma massa homogénea e sem grumos.</p><p><b>Aquecer a frigideira:</b> Leve uma frigideira antiaderente ao lume médio-baixo e unte com uma noz de manteiga ou algumas gotas de óleo de coco.</p><p><b>Cozinhar:</b> Verta uma concha ou colherada da massa na frigideira. Deixe cozinhar até começarem a aparecer pequenas bolhas na superfície (cerca de 2 a 3 minutos).</p><p><b>Virar:</b> Vire a panqueca com a ajuda de uma espátula e deixe dourar do outro lado por mais 1 minuto.</p><p><b>Servir:</b> Retire e repita o processo até terminar a massa. Sirva as panquecas ainda quentes, decoradas com as bagas por cima e um fio de mel a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BOWL_SPIRULINA + "', '<h3>Ingredientes Base</h3><p>Para criar a taça ideal, vai precisar de:</p><ul><li><b>Fruta Congelada:</b> 1 banana congelada (crucial para a textura) e cerca de meia chávena de outra fruta à escolha (ex: manga, mirtilos ou pêssego).</li><li><b>Superalimento:</b> 1 colher de chá de pó de spirulina (verde ou azul).</li><li><b>Líquido:</b> 100 ml a 150 ml de bebida vegetal (aveia, amêndoa, coco) ou sumo de laranja fresco.</li><li><b>Adicionais (opcional):</b> 1 colher de sobremesa de pasta de amêndoa, metade de um abacate ou iogurte vegetal para maior cremosidade.</li></ul><h3>Preparação e Toppings</h3><p>A preparação é muito simples e divide-se em 3 passos:</p><p><b>Triturar:</b> Adicione todos os ingredientes (exceto os toppings) numa liquidificadora ou processador de alimentos.</p><p><b>Misturar:</b> Triture lentamente, aumentando a velocidade, até obter uma textura densa, homogénea e cremosa. Se estiver demasiado espesso, adicione um pouco mais de líquido aos poucos.</p><p><b>Servir:</b> Transfira o preparado para uma taça e decore com os seus toppings favoritos (ex: rodelas de kiwi, mirtilos frescos, sementes de chia, granola ou nozes).</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PUDIM_CHIA_KIWI + "', '<h3>Ingredientes base</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>200 ml de leite ou bebida vegetal (amêndoa, coco, aveia)</li><li>1 colher de café ou sopa de mel ou xarope de agave (a gosto)</li><li>1 a 2 kiwis maduros</li><li>Opcional: Iogurte natural ou grego, granola e aveia para enriquecer as camadas</li></ul><h3>Preparação passo a passo</h3><p><b>Preparar a base:</b> Numa taça ou frasco, misture as sementes de chia com o leite ou bebida vegetal e o mel. Mexa muito bem para garantir que não ficam grumos.</p><p><b>Deixar hidratar:</b> Tape o recipiente e leve ao frigorífico durante pelo menos 4 horas, sendo ideal deixar de um dia para o outro. As sementes vão absorver o líquido e formar um pudim cremoso.</p><p><b>Preparar o kiwi:</b> Descasque os kiwis. Pode cortar um em rodelas ou cubos para a montagem e esmagar o outro com um garfo para criar um puré.</p><p><b>Montagem:</b> Num copo ou frasco de vidro, alterne camadas do pudim de chia com o puré ou pedaços de kiwi e, se desejar, adicione iogurte e granola.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_AMENDOIM_MIRTILO + "', '<h3>Ingredientes (para 2 fatias)</h3><ul><li>2 fatias de pão (pode optar por pão integral, de centeio ou fatias de batata-doce)</li><li>2 colheres de sopa de manteiga de amendoim</li><li>1 punhado de mirtilos frescos</li><li>Opcional: 1/2 banana cortada em rodelas, um fio de mel ou xarope de ácer, e sementes de chia ou amêndoas picadas.</li></ul><h3>Preparação</h3><p><b>Tostar o pão:</b> Coloque as fatias de pão na torradeira ou numa frigideira até ficarem douradas e estaladiças.</p><p><b>Barrar:</b> Com o pão ainda quente, barre cada fatia com uma colher de sopa de manteiga de amendoim para que derreta ligeiramente.</p><p><b>Adicionar os toppings:</b> Distribua os mirtilos lavados e bem secos por cima da manteiga de amendoim. Se desejar uma versão mais composta, junte rodelas de banana e umas gotas de mel.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MEXIDO_TOFU_TOMATE + "', '<h3>Ingredientes</h3><ul><li>200 g a 250 g de tofu firme ou natural</li><li>1 tomate médio (ou uma mão-cheia de tomate-cereja) cortado em cubos</li><li>1/2 colher de café de açafrão/cúrcuma (para dar cor amarelada)</li><li>Folhas frescas de manjericão a gosto</li><li>1 dente de alho picado ou alho em pó (opcional)</li><li>1 fio de azeite</li><li>Sal e pimenta-do-reino a gosto</li><li>Gotas de sumo de limão ou molho de soja (shoyu) para intensificar o sabor</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Escorra a água da embalagem e seque o tofu com papel de cozinha. Com a ajuda de um garfo ou com as mãos, esfarele o tofu para obter uma textura semelhante à dos ovos mexidos.</p><p><b>Refogar o alho:</b> Aqueça uma frigideira com um fio de azeite em lume médio. Adicione o alho picado e deixe dourar levemente.</p><p><b>Temperar o tofu:</b> Adicione o tofu esfarelado à frigideira. Tempere com a cúrcuma (açafrão), sal e pimenta. Salteie durante cerca de 3 a 5 minutos até começar a criar textura.</p><p><b>Adicionar o tomate:</b> Junte os cubos de tomate à frigideira e envolva no tofu. Deixe cozinhar por mais 2 minutos para que o tomate fique macio, mas não se desfaça totalmente.</p><p><b>Finalizar:</b> Desligue o lume e adicione as folhas de manjericão fresco e, se desejar, umas gotas de sumo de limão ou molho de soja. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_MILHO_COCO + "', '<h3>Ingredientes (Versão com Flocos ou Farinha)</h3><ul><li>4 colheres de sopa de flocão de milho (ou farinha de milho fina / carolo)</li><li>300 ml de leite (ou bebida vegetal da sua preferência)</li><li>200 ml de leite de coco (meia garrafinha)</li><li>3 a 4 colheres de sopa de coco ralado</li><li>3 colheres de sopa de açúcar (ou mel/adoçante a gosto)</li><li>1 pitada de sal</li><li>Opcional: 1 tira de casca de limão ou pau de canela para aromatizar</li></ul><h3>Preparação</h3><p><b>Misturar os secos:</b> Num tacho ou caçarola, coloque os flocos de milho, o açúcar, o coco ralado e a pitada de sal. Misture bem.</p><p><b>Adicionar os líquidos:</b> Junte o leite e o leite de coco à mistura seca. Se desejar um aroma extra, adicione a casca de limão ou o pau de canela.</p><p><b>Cozinhar:</b> Leve o tacho ao lume (médio/baixo) e mexa continuamente com uma vara de arames para não formar grumos.</p><p><b>Engrossar:</b> Continue a mexer até começar a ferver e o preparado engrossar até atingir a consistência de papa cremosa.</p><p><b>Finalizar:</b> Retire do lume, retire a casca de limão ou o pau de canela, e verta para taças individuais. Sirva quente ou morna, polvilhada com canela em pó.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BANANA_ESPINAFRE + "', '<h3>Ingredientes</h3><ul><li>1 banana madura (idealmente congelada para maior cremosidade)</li><li>1 a 2 mãos cheias de folhas de espinafre fresco (cerca de 30 g a 50 g)</li><li>200 ml a 250 ml de leite ou bebida vegetal (amêndoa, aveia, coco)</li><li>Opcional (para mais textura e nutrientes): 1 colher de sopa de aveia, 1 colher de chá de manteiga de amendoim ou sementes de chia</li><li>Opcional (para adoçar): 1 colher de chá de mel ou tâmaras</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Lave bem as folhas de espinafre. Descasque a banana e corte-a em rodelas.</p><p><b>Adicionar ao liquidificador:</b> Coloque primeiro o leite ou bebida vegetal (ajuda a proteger as lâminas), seguido da banana, dos espinafres e de quaisquer ingredientes extra (aveia, sementes ou adoçante).</p><p><b>Triturar:</b> Triture na velocidade máxima durante 1 a 2 minutos, até obter uma consistência completamente cremosa, sem pedaços de folha visíveis.</p><p><b>Servir:</b> Verta para um copo e beba imediatamente. Se preferir a bebida mais fresca, pode juntar algumas pedras de gelo antes de bater.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TACA_ACAI_CANHAMO + "', '<h3>Ingredientes Base</h3><p>Para fazer 1 taça individual:</p><ul><li><b>Açaí:</b> 200g de polpa de açaí congelada (ou 2 a 3 colheres de sopa de açaí em pó puro).</li><li><b>Banana:</b> 1 banana madura cortada às rodelas e previamente congelada (essencial para dar cremosidade).</li><li><b>Líquido:</b> 50 ml de bebida vegetal (ex: amêndoa ou aveia) ou água de coco.</li></ul><h3>Coberturas (Toppings)</h3><ul><li><b>Sementes de Cânhamo:</b> 1 colher de chá (ricas em ómega-3 e proteína).</li><li><b>Fruta Fresca:</b> Morangos fatiados, mirtilos, framboesas ou kiwi.</li><li><b>Crocante:</b> 1 colher de sopa de granola.</li><li><b>Extras Opcionais:</b> Uma colher de chá de sementes de chia ou pasta de amendoim.</li></ul><h3>Preparação</h3><p><b>Bater:</b> Num liquidificador de alta velocidade, coloque a banana congelada, o açaí e a bebida vegetal ou água de coco.</p><p><b>Misturar:</b> Triture tudo até obter uma textura densa, cremosa e homogénea. Se estiver demasiado líquido, adicione mais fruta congelada; se estiver muito espesso, adicione um pouco mais de líquido.</p><p><b>Montar:</b> Verta o creme de açaí para uma taça funda.</p><p><b>Decorar:</b> Disponha as frutas frescas cortadas, a granola e as Sementes de Cânhamo artisticamente por cima do creme.</p><p><b>Servir:</b> Consuma de imediato para aproveitar a consistência fresca e cremosa.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_HUMUS_PIMENTOS + "', '<h3>Ingredientes</h3><p><b>Para o húmus de pimento assado:</b></p><ul><li>250 g de grão-de-bico cozido (1 lata)</li><li>1 a 2 pimentos vermelhos grandes</li><li>1 a 2 dentes de alho</li><li>2 colheres de sopa de tahini</li><li>Sumo de ½ limão</li><li>2 colheres de sopa de azeite virgem extra</li><li>½ colher de chá de cominhos em pó ou paprika</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para a montagem:</b></p><ul><li>Fatias de pão (integral, de fermentação natural ou rústico)</li><li>Toppings opcionais: Sementes (sésamo ou abóbora), salsa picada ou tomate cherry assado</li></ul><h3>Preparação</h3><p><b>Assar os pimentos:</b> Lave os pimentos, corte-os em quartos e retire as sementes. Coloque-os num tabuleiro juntamente com os dentes de alho. Leve ao forno pré-aquecido a 180° C por 20 a 30 minutos, até a pele ficar ligeiramente queimada.</p><p><b>Descascar:</b> Retire do forno e abafe os pimentos com papel de alumínio ou dentro de uma taça tapada durante 10 minutos. Retire a pele dos pimentos.</p><p><b>Fazer o Húmus:</b> Num processador de alimentos ou liquidificador, coloque o grão-de-bico escorrido, os pimentos assados, os dentes de alho, o tahini, o sumo de limão, o azeite, os cominhos, o sal e a pimenta. Triture até obter uma pasta homogénea e cremosa.</p><p><b>Tostar o pão:</b> Torre as fatias de pão até ficarem estaladiças.</p><p><b>Montar:</b> Espalhe uma camada generosa do húmus de pimento assado sobre cada fatia de pão torrado.</p><p><b>Finalizar:</b> Adicione um fio de azeite e decore com sementes ou salsa.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MUESLI_AVELA + "', '<h3>Ingredientes Base</h3><ul><li>1 chávena de flocos de aveia (finos ou grossos)</li><li>1 e 1/2 chávenas de leite de avelã (pode ajustar a quantidade dependendo da consistência desejada)</li><li>1 maçã média ralada (com a casca, mas sem sementes)</li><li>1/4 de chávena de uvas passas ou outros frutos secos picados (como alperces ou tâmaras)</li><li>1 colher de sopa de sementes (linhaça, chia ou abóbora)</li><li>1 colher de chá de mel ou xarope de ácer (opcional)</li><li>1 pitada de canela em pó (opcional)</li></ul><h3>Preparação</h3><p><b>Mistura inicial:</b> Numa tigela ou frasco de vidro, misture a aveia, as uvas passas, as sementes e a canela.</p><p><b>Adicionar o líquido:</b> Vaze o leite de avelã sobre os ingredientes secos. Adicione o mel, caso vá utilizar.</p><p><b>Repouso (Opcional, mas recomendado):</b> Se preferir uma textura mais cremosa (estilo o tradicional Bircher Muesli suíço), tape o recipiente e leve ao frigorífico durante pelo menos 4 a 6 horas ou prepare na noite anterior.</p><p><b>Finalizar com a fruta:</b> Na hora de consumir, rale a maçã e envolva no preparado. Se desejar, pode adicionar mais avelãs picadas por cima para dar um toque extra de crocância.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUINOA_MACA + "', '<h3>Ingredientes</h3><ul><li>1 chávena (cerca de 170g) de quinoa branca</li><li>2 chávenas de água (para cozer a quinoa)</li><li>1 maçã (preferencialmente verde) cortada em cubos</li><li>1/2 chávena de amêndoas laminadas e torradas</li><li>1/2 cebola roxa ou branca picada finamente</li><li>Folhas de hortelã fresca picadas</li><li><b>Molho:</b> Azeite, sumo de limão (ou vinagre balsâmico), sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Cozer a quinoa:</b> Lave muito bem a quinoa em água corrente e escorra. Num tacho, coloque a quinoa e as duas chávenas de água com uma pitada de sal. Deixe ferver, tape e reduza o lume, deixando cozinhar por 10 a 12 minutos até a água desaparecer. Retire e deixe arrefecer.</p><p><b>Preparar os ingredientes:</b> Misture a quinoa já fria numa taça grande com a maçã em cubos, a cebola picada, as amêndoas e a hortelã.</p><p><b>Temperar:</b> Num frasco à parte, agite o azeite, o sumo de limão, o sal e a pimenta. Vele sobre a salada, envolva bem e sirva.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_MANGA_HORTELA + "', '<h3>Ingredientes base</h3><p>A proporção perfeita rende cerca de duas porções:</p><ul><li><b>Manga:</b> 2 mangas médias ou 500g de cubos de manga (o ideal é usar a manga congelada para um efeito mais cremoso).</li><li><b>Hortelã:</b> 10 a 15 folhas de hortelã fresca.</li><li><b>Líquido:</b> 1 copo (cerca de 250g) de iogurte natural, grego ou leite de coco.</li><li><b>Adoçante (Opcional):</b> 1 colher de chá de mel, xarope de agave ou açúcar.</li><li><b>Gelo:</b> 5 a 6 cubos de gelo.</li></ul><h3>Modo de preparação</h3><p><b>Prepare a fruta:</b> Descasque as mangas e corte a polpa em cubos.</p><p><b>Misture no liquidificador:</b> Coloque os cubos de manga, as folhas de hortelã, o iogurte (ou leite vegetal) e o adoçante no copo do liquidificador.</p><p><b>Bata:</b> Triture tudo na potência máxima até a mistura ficar homogénea, sem pedaços.</p><p><b>Adicione o gelo:</b> Acrescente os cubos de gelo e bata novamente até o smoothie ganhar uma textura de frappé.</p><p><b>Decoração e serviço:</b> Verta para copos altos, decore com uma ou duas folhas frescas de hortelã e sirva imediatamente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PANQUECAS_BANANA_NOZ + "', '<h3>Ingredientes (para cerca de 4 a 6 panquecas)</h3><ul><li>2 bananas maduras</li><li>2 ovos L (ou 1 banana extra/linhaça hidratada para a versão vegan)</li><li>60 g a 70 g de flocos de aveia ou farinha de aveia</li><li>40 g de miolo de noz (picado finamente)</li><li>1 colher de chá de canela em pó (opcional, para dar aroma)</li><li>1 colher de chá de fermento em pó (opcional, para torná-las mais fofinhas)</li><li>1 pitada de sal</li><li><b>Q.b.</b> Óleo de coco ou manteiga (apenas para untar a frigideira)</li></ul><h3>Preparação</h3><p><b>Esmagar a banana:</b> Numa taça funda, descasque as bananas e esmague-as com um garfo até obter um puré consistente.</p><p><b>Juntar os líquidos:</b> Adicione os ovos à taça e bata bem com uma vara de arames (ou com a varinha mágica) até a mistura ficar homogénea.</p><p><b>Adicionar os secos:</b> Junte a aveia, a canela, o fermento e uma pitada de sal. Mexa tudo muito bem.</p><p><b>Incorporar as nozes:</b> Por fim, adicione o miolo de noz picado à massa e envolva delicadamente. Se a massa estiver muito espessa, pode adicionar um pequeno fio de bebida vegetal (ex: leite de amêndoa).</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente em lume brando e unte com um pouco de óleo de coco ou manteiga. Verta pequenas porções da massa (cerca de 2 colheres de sopa para cada panqueca).</p><p><b>Virar:</b> Deixe cozinhar durante cerca de 2 a 3 minutos até aparecerem pequenas bolhas à superfície e as bordas começarem a secar. Vire com uma espátula e deixe dourar do outro lado por mais 1 a 2 minutos.</p><p><b>Servir:</b> Retire do lume e repita até terminar a massa. Sirva simples, com mel ou xarope de ácer e algumas nozes laminadas por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_SARRACENO_MORANGO + "', '<h3>Ingredientes</h3><p>Para preparar duas doses destas papas nutritivas, vai precisar de:</p><ul><li><b>Trigo sarraceno:</b> 180 g de trigo sarraceno em grão (pode usar flocos, se preferir).</li><li><b>Morangos:</b> 150 g de morangos frescos cortados em pedaços.</li><li><b>Base cremosa:</b> 1 iogurte natural (ou de base vegetal) ou 1 a 2 dl de bebida vegetal (aveia, amêndoa ou coco).</li><li><b>Adoçante:</b> 2 a 3 tâmaras sem caroço (opcional).</li><li><b>Nutrição extra:</b> 1 colher de sopa de sementes de linhaça moída ou de chia.</li><li><b>Toque final:</b> Morangos extra fatiados e frutos secos para decorar.</li></ul><h3>Preparação</h3><p>Existem duas formas principais de preparar esta receita.</p><p><b>Opção 1: Papas cruas (Sem cozedura)</b></p><ul><li>Na noite anterior, coloque o trigo sarraceno em grão numa taça, cubra com água e deixe repousar no frigorífico durante pelo menos 4 horas ou durante a noite.</li><li>Na manhã seguinte, escorra a água e passe o trigo sarraceno por água corrente.</li><li>Coloque o trigo sarraceno demolhado numa liquidificadora ou robô de cozinha.</li><li>Adicione os morangos, o iogurte (ou bebida vegetal), as tâmaras e a linhaça.</li><li>Triture tudo até obter uma textura suave e cremosa. Se estiver muito espesso, adicione um pouco mais de bebida vegetal.</li><li>Transfira para uma taça e decore com morangos frescos fatiados e frutos secos a gosto.</li></ul><p><b>Opção 2: Papas quentes</b></p><ul><li>Se preferir morno, coloque 1 chávena de flocos de trigo sarraceno e 2 chávenas de água ou bebida vegetal num tacho.</li><li>Adicione uma pitada de sal e leve a lume brando, mexendo sempre, durante cerca de 5 a 8 minutos até engrossar.</li><li>Retire do lume, envolva os morangos picados na papa quente para que amoleçam ligeiramente e sirva com morangos frescos no topo.</li></ul>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_QUEIJO_MEL + "', '<h3>Ingredientes (para 2 tostas)</h3><ul><li>2 fatias de pão rústico, alentejano ou italiano</li><li>1 rolo de queijo de cabra (chèvre) fatiado ou em porções</li><li>Mel (a gosto)</li><li><b>Azeite ou manteiga:</b> q.b.</li><li>Opcional: Nozes picadas, amêndoas ou pistáchios</li><li>Opcional: Tomilho fresco ou orégãos</li><li>Opcional: 1 dente de alho (para esfregar no pão)</li></ul><h3>Preparação</h3><p><b>Torrar o pão:</b> Leve as fatias de pão à torradeira ou ao forno durante alguns minutos até ficarem ligeiramente estaladiças. Se desejar, esfregue um dente de alho nas fatias e pincele com um fio de azeite.</p><p><b>Adicionar o queijo:</b> Coloque as fatias ou rodelas de queijo de cabra por cima do pão.</p><p><b>Derreter:</b> Leve novamente ao forno (com a função de grelhador ligada) ou à Air Fryer durante 1 a 2 minutos, apenas até o queijo começar a derreter e dourar nas pontas.</p><p><b>Finalizar:</b> Retire do forno e decore com os frutos secos picados (nozes, amêndoas ou pistáchios) e as ervas aromáticas (tomilho ou orégãos).</p><p><b>O toque final:</b> Regue com um fio de mel a gosto imediatamente antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_IOGURTE_LINHACA_PAPAIA + "', '<h3>Ingredientes</h3><ul><li>1/2 mamão papaia maduro</li><li>1 iogurte natural ou iogurte proteico (aprox. 120 g a 170 g)</li><li>1 colher de chá ou de sopa de sementes de linhaça moída</li><li>Opcional: Mel, adoçante ou canela a gosto para dar sabor</li></ul><h3>Preparação</h3><p><b>Preparação da fruta:</b> Corte o mamão papaia ao meio, no sentido longitudinal, e retire todas as sementes com a ajuda de uma colher.</p><p><b>Montagem:</b> Preencha a cavidade de cada metade da fruta com o iogurte natural.</p><p><b>Adição das sementes:</b> Polvilhe a linhaça moída diretamente sobre o iogurte.</p><p><b>Finalização:</b> Se preferir um toque mais doce, adicione um fio de mel ou uma pitada de canela antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_SILVESTRES + "', '<h3>Ingredientes base</h3><ul><li>150 g de frutos silvestres congelados (ou frescos)</li><li>1 banana madura</li><li>125 g de iogurte natural (ou iogurte grego / vegetal)</li><li>100 ml a 200 ml de leite (ou bebida de soja, amêndoa ou água de coco)</li><li>Opcional: 1 colher de chá de mel, agave ou sementes de chia</li></ul><h3>Preparação</h3><p><b>Coloque os ingredientes no copo:</b> Adicione primeiro os ingredientes líquidos (leite e iogurte) e depois a fruta (a banana cortada em pedaços e os frutos).</p><p><b>Triture:</b> Triture tudo com a ajuda de uma varinha mágica ou no liquidificador até obter uma mistura cremosa e homogénea.</p><p><b>Ajuste e sirva:</b> Se preferir o batido mais líquido, adicione um pouco mais de leite ou água de coco. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TAPIOCA_QUEIJO_TOMATE + "', '<h3>Ingredientes</h3><ul><li>3 a 4 colheres de sopa de goma de tapioca hidratada</li><li>1 tomate pequeno (em rodelas ou cubos)</li><li>50g a 100g de queijo (mussarela, queijo fresco, Minas ou ricota)</li><li>Orégãos a gosto</li><li>Sal e uma pitada de azeite (opcional)</li></ul><h3>Preparação</h3><p><b>Prepare o tomate:</b> Corte o tomate em cubos ou rodelas finas, retire as sementes se preferir e tempere com sal e orégãos.</p><p><b>Peneire a tapioca:</b> Aqueça uma frigideira antiaderente em lume brando. Com uma colher, polvilhe a goma de tapioca peneirada até cobrir todo o fundo, formando um disco uniforme.</p><p><b>Cozinhe a massa:</b> Deixe cozinhar por cerca de 2 minutos até que as bordas comecem a soltar-se e a massa fique unida.</p><p><b>Adicione o recheio:</b> Numa das metades da tapioca, coloque o queijo e, por cima, o tomate.</p><p><b>Dobre e finalize:</b> Dobre a tapioca ao meio, tapando o recheio. Deixe na frigideira por mais 1 a 2 minutos até o queijo derreter completamente. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_AVEIA_TAMARAS + "', '<h3>Ingredientes (para 1 a 2 pessoas)</h3><ul><li><b>Flocos de aveia:</b> 1 chávena</li><li><b>Leite ou bebida vegetal:</b> 1 1/4 chávena</li><li><b>Água:</b> 1 chávena</li><li><b>Tâmaras:</b> 4 unidades (sem caroço, picadas)</li><li><b>Canela em pó:</b> a gosto</li><li><b>Toppings (opcional):</b> Maçã aos cubos, nozes, amêndoas ou manteiga de amendoim.</li></ul><h3>Preparação</h3><p><b>Misturar:</b> Num tacho, coloque os flocos de aveia, o leite (ou bebida vegetal), a água e as tâmaras cortadas.</p><p><b>Cozinhar:</b> Leve ao lume e deixe levantar fervura. Logo de seguida, reduza para lume brando.</p><p><b>Engrossar:</b> Deixe cozer durante cerca de 10 a 15 minutos, mexendo frequentemente até obter a textura cremosa desejada.</p><p><b>Finalizar:</b> Retire do lume, polvilhe com canela em pó e adicione os toppings da sua preferência antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BOWL_ABACATE + "', '<h3>Ingredientes base</h3><p>Para preparar uma taça individual, pode seguir esta combinação clássica e nutritiva:</p><ul><li>1 Abacate maduro</li><li>1 Banana média (preferencialmente congelada para dar textura)</li><li>120 ml a 180 ml de Bebida vegetal (amêndoa, aveia ou coco) ou iogurte</li><li>1 colher de sopa de Mel ou xarope de ácer (opcional, para adoçar)</li><li>Opcional: 1 mão de Espinafres baby (para um toque extra de nutrientes sem alterar o sabor)</li></ul><h3>Preparação</h3><p>O processo é muito rápido e garante uma consistência perfeita para comer à colher:</p><p><b>Preparar os ingredientes:</b> Descasque o abacate e retire o caroço. Corte a banana em rodelas.</p><p><b>Triturar:</b> Coloque todos os ingredientes na liquidificadora ou robot de cozinha.</p><p><b>Bater:</b> Triture na potência máxima até obter uma mistura aveludada, homogénea e muito cremosa. Se a mistura estiver demasiado espessa, adicione um pequeno fio extra de bebida vegetal e volte a bater.</p><p><b>Montar:</b> Verta o creme para uma taça larga.</p><p><b>Finalizar:</b> Decore com toppings da sua preferência, como granola, sementes de chia, rodelas frescas de banana, morangos fatiados ou manteiga de amendoim.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_COGUMELOS + "', '<h3>Ingredientes (para 2 pessoas)</h3><ul><li><b>Pão:</b> 4 fatias de pão rústico ou de fermentação natural (ex: pão alentejano ou de Mafra).</li><li><b>Cogumelos:</b> 250 g a 300 g de cogumelos frescos variados (Paris, Portobello ou Shimeji).</li><li><b>Gordura:</b> 1 a 2 colheres de sopa de azeite ou manteiga (ou ambos).</li><li><b>Alho:</b> 2 dentes de alho picados ou esmagados.</li><li><b>Ervas:</b> Tomilho fresco, alecrim ou salsa picada.</li><li><b>Tempero:</b> Sal e pimenta-preta a gosto.</li><li><b>Opcional (Base):</b> Queijo creme, queijo de cabra ou lascas de parmesão para barrar no pão.</li></ul><h3>Preparação</h3><p><b>Preparar os cogumelos:</b> Limpe os cogumelos com um pano ou papel de cozinha húmido (evite passar por água para não absorverem humidade) e corte-os em fatias ou pedaços médios.</p><p><b>Tostar o pão:</b> Leve as fatias de pão ao forno ou a uma frigideira com um fio de azeite até ficarem bem crocantes e douradas.</p><p><b>Saltear os cogumelos:</b> Numa frigideira larga, aqueça o azeite e a manteiga em lume médio. Adicione o alho e deixe libertar aroma (cerca de 30 segundos). De seguida, adicione os cogumelos.</p><p><b>Cozinhar:</b> Salteie os cogumelos durante cerca de 5 a 8 minutos, mexendo suavemente, até ficarem macios e tostados. Tempere com sal, pimenta e as ervas aromáticas a gosto.</p><p><b>Montagem:</b> Se desejar, barre as fatias de pão com um pouco de queijo creme ou coloque lascas de queijo por cima. Distribua os cogumelos salteados ainda quentes sobre as torradas e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MUFFIN_AVEIA_MACA + "', '<h3>Ingredientes</h3><ul><li>1 maçã grande (ou duas pequenas)</li><li>100 g de flocos de aveia (ou farinha de aveia)</li><li>4 ovos</li><li>Canela a gosto</li></ul><h3>Preparação</h3><p><b>Preparar a massa:</b> Coloque os ovos, os flocos de aveia e a canela no liquidificador ou numa tigela e triture bem até obter uma mistura homogénea.</p><p><b>Adicionar a maçã:</b> Descasque a maçã e corte-a em pedacinhos muito pequenos. Incorpore os pedaços na massa (pode também ralar a maçã, se preferir).</p><p><b>Cozer:</b> Viste a massa em forminhas de muffin (forradas com papel vegetal ou de silicone). Leve ao forno pré-aquecido a 180ºC durante cerca de 15 a 20 minutos. Se preferir utilizar a air fryer, pode cozer a 180ºC por cerca de 12 minutos.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_PERA_CANELA + "', '<h3>Ingredientes Base</h3><p>Para preparar uma dose individual ou para duas pessoas, vai precisar de:</p><ul><li>1 ou 2 peras maduras (como a pera rocha ou abade).</li><li>1 colher de chá de canela em pó (ajuste a gosto).</li><li>150 a 200 ml de leite (vaca, amêndoa, aveia ou soja).</li><li>Opcional: 1 banana para dar mais textura e doçura.</li><li>Opcional para adoçar: 1 colher de chá de mel, açúcar amarelo ou tâmaras.</li><li>Gelo (se preferir um batido bem fresco).</li></ul><h3>Preparação</h3><p><b>Preparar a fruta:</b> Lave bem a pera, descasque-a (se preferir) e corte-a em cubos ou pedaços, removendo o caroço.</p><p><b>Adicionar os ingredientes:</b> Coloque todos os ingredientes no copo do liquidificador: a pera, a canela, o leite e os opcionais que escolher (adoçante ou banana).</p><p><b>Triturar:</b> Bata na velocidade máxima até obter uma textura aveludada e sem pedaços.</p><p><b>Servir:</b> Verta para um copo e polvilhe com um pouco mais de canela por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_CEVADA_MEL + "', '<h3>Ingredientes</h3><ul><li>4 colheres de sopa de cevada (pode usar farinha de cevada, cevada solúvel ou flocos)</li><li>250 ml de leite (magro, meio-gordo ou gordo) ou de bebida vegetal (aveia, amêndoa, soja)</li><li>1 a 2 colheres de sopa de mel</li><li>Opcional: Uma pitada de canela em pó, nozes picadas ou fruta fresca.</li></ul><h3>Preparação</h3><p><b>Misturar:</b> Num tacho pequeno, coloque a cevada e adicione o leite ou bebida vegetal aos poucos, mexendo bem para não criar grumos.</p><p><b>Cozinhar:</b> Leve o tacho a lume médio-baixo. Deixe cozinhar durante cerca de 5 a 10 minutos (dependendo se usa farinha ou flocos).</p><p><b>Mexer:</b> Vá mexendo regularmente para que a papa não pegue ao fundo e ganhe uma textura cremosa.</p><p><b>Finalizar:</b> Assim que atingir a consistência desejada, retire do lume.</p><p><b>Servir:</b> Transfira para uma taça, deixe arrefecer ligeiramente e regue com o mel. Se desejar, polvilhe com canela ou adicione pedaços de fruta.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_CAJU_BANANA + "', '<h3>Ingredientes (por dose)</h3><ul><li>2 fatias do seu pão favorito (pode ser de fermento natural, integral ou sem glúten)</li><li>2 colheres de sopa de manteiga de caju</li><li>1 banana madura</li><li>Canela em pó a gosto</li><li>Opcional: Um fio de mel, xarope de ácer ou sementes de chia</li></ul><h3>Preparação</h3><p><b>Tostar o pão:</b> Coloque as fatias de pão na torradeira ou numa frigideira antiaderente até ficarem douradas e estaladiças.</p><p><b>Preparar o caju:</b> Barre generosamente cada fatia de pão quente com a manteiga de caju.</p><p><b>Adicionar a banana:</b> Descasque a banana e corte-a em rodelas (ou corte-a ao meio no sentido do comprimento). Disponha as fatias por cima do pão barrado.</p><p><b>Finalizar:</b> Polvilhe com canela em pó e, se desejar um toque mais doce, finalize com um fio de mel ou xarope.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TACA_IOGURTE_ABOBORA + "', '<h3>Ingredientes Base</h3><p>Para criar uma taça individual, pode usar os seguintes ingredientes:</p><ul><li>170 g de iogurte natural integral ou iogurte grego</li><li>1 colher de sobremesa (cerca de 10 g) de sementes de abóbora descascadas</li><li>Fruta a gosto (ex: morangos fatiados, rodelas de banana ou mirtilos)</li><li>1 colher de sopa de granola (opcional, para dar crocância)</li><li>Um fio de mel ou uma pitada de canela (opcional, para adoçar)</li></ul><h3>Modo de Preparação</h3><p>Coloque o iogurte numa taça bonita e larga.</p><p>Adicione os pedaços de fruta fresca.</p><p>Polvilhe por cima com as sementes de abóbora e a granola.</p><p>Finalize com um fio de mel e canela a gosto.</p>');");

        // ==========================================
// ALMOÇOS - ABRIL (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_RISOTO_ESPARGOS + "', '<h3>Ingredientes</h3><ul><li><b>Arroz:</b> 320 g de arroz para risoto (tipo Arborio ou Carnaroli)</li><li><b>Legumes:</b> 200 g a 300 g de espargos verdes frescos e 250 g de cogumelos (brancos, marrom ou Portobello)</li><li><b>Base de sabor:</b> 1 cebola (ou chalota) picada e 2 dentes de alho picados</li><li><b>Líquidos:</b> 100 ml de vinho branco seco e cerca de 1,2 L de caldo de legumes quente</li><li><b>Gordura:</b> 40 g de manteiga e azeite virgem extra q.b.</li><li><b>Finalização:</b> 50 g a 60 g de queijo parmesão ralado, sal e pimenta preta moída na hora.</li></ul><h3>Preparação</h3><p><b>Prepare os espargos e o caldo:</b> Dobre a base dos espargos até que partam naturalmente (descarte a parte mais fibrosa) e corte-os em pedaços pequenos, mantendo as pontas inteiras. Mantenha o caldo de legumes quente numa panela ao lado.</p><p><b>Salteie os vegetais:</b> Num tacho largo, coloque um fio de azeite e salteie os cogumelos laminados e os pedaços de espargos durante cerca de 5 minutos. Tempere com sal e pimenta, retire do tacho e reserve.</p><p><b>Sele o arroz:</b> No mesmo tacho, adicione mais um fio de azeite e a cebola (ou chalota) e o alho picados, deixando alourar. Junte o arroz e mexa bem para \"fritar\" ligeramente.</p><p><b>Adicione o vinho:</b> Verta o vinho branco e deixe evaporar mexendo sempre, até o álcool desaparecer.</p><p><b>Cozinhe o risoto:</b> Comece a adicionar o caldo de legumes quente a conchas de cada vez. Adicione mais caldo apenas quando o anterior tiver sido absorvido pelo arroz. Mexa constantemente.</p><p><b>Incorpore os vegetais:</b> A meio do processo de cozedura (cerca de 10 minutos após o início), junte os cogumelos e os espargos que foram salteados.</p><p><b>Finalize e sirva:</b> Quando o arroz estiver al dente e cremoso (o processo todo demora cerca de 20 minutos), desligue o lume. Envolva a manteiga e o queijo parmesão ralado para criar uma textura aveludada. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_QUINOA_GRAO + "', '<h3>Ingredientes Base</h3><ul><li>1 chávena de quinoa</li><li>2 chávenas de água (para cozinhar a quinoa)</li><li>1 frasco ou lata de grão-de-bico cozido (aprox. 400g)</li><li>1 pimento (vermelho ou amarelo) cortado em cubos</li><li>1 pepino pequeno picado</li><li>1/2 cebola roxa picada</li><li>Ervas frescas a gosto (salsa ou coentros)</li></ul><p><b>Para o Molho:</b></p><ul><li>Sumo de 1 limão ou lima</li><li>3 a 4 colheres de sopa de azeite extra virgem</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação Passo a Passo</h3><p><b>Preparar a Quinoa:</b> Passe a quinoa por água fria num passador. Num tacho, coloque a quinoa e o dobro da água com uma pitada de sal. Deixe ferver, tape e deixe cozinhar em lume brando durante 15 minutos. Retire, solte os grãos com um garfo e deixe arrefecer.</p><p><b>Preparar o Grão:</b> Escorra bem o grão-de-bico, passe por água e reserve.</p><p><b>Cortar os vegetais:</b> Numa saladeira grande, misture o pimento em cubos, o pepino, a cebola roxa e as ervas picadas.</p><p><b>Montar a salada:</b> Adicione o grão-de-bico e a quinoa já fria à saladeira.</p><p><b>Temperar:</b> Numa taça à parte, emulsione o azeite, o sumo de limão, o sal e a pimenta. Verta o molho sobre a salada e envolva tudo muito bem.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_PESTO_PINHOES + "', '<h3>Ingredientes</h3><p><b>Para o Molho Pesto:</b></p><ul><li>50 g de folhas de manjericão fresco</li><li>40 g de pinhões</li><li>60 g de queijo Parmesão (ou Pecorino) ralado</li><li>1 dente de alho</li><li>Azeite virgem extra (cerca de 80 a 100 ml)</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para a Massa:</b></p><ul><li>350 g de massa (esparguete, penne ou fusilli)</li><li>Sal grosso (para a água da massa)</li></ul><h3>Preparação</h3><p><b>Tostar os pinhões:</b> Numa frigideira sem gordura, torre os pinhões em lume brando durante 2 a 3 minutos até dourarem ligeiramente. Retire e deixe arrefecer.</p><p><b>Preparar o pesto:</b> Num processador de alimentos (ou com a ajuda de um almofariz e pilão), coloque o dente de alho, os pinhões, as folhas de manjericão limpas e uma pitada de sal. Triture e, enquanto tritura, adicione o azeite em fio até obter uma pasta homogénea e cremosa.</p><p><b>Misturar o queijo:</b> Junte o queijo Parmesão ralado ao preparado e envolva bem. Ajuste o sal e a pimenta.</p><p><b>Cozer a massa:</b> Coza a massa numa panela com água abundante e sal grosso, seguindo o tempo indicado na embalagem para ficar al dente. Antes de escorrer a massa, reserve cerca de meia chávena da água de cozedura.</p><p><b>Envolver e servir:</b> Escorra a massa, transfira-a para uma taça grande e envolva-a com o molho pesto. Se o molho estiver muito espesso, adicione um pouco da água de cozedura reservada para o soltar e criar uma textura sedosa.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CHILI_LENTILHAS_DOCE + "', '<h3>Ingredientes Base</h3><ul><li>2 batatas-doce médias cortadas em cubos</li><li>200g a 250g de lentilhas (castanhas ou vermelhas) secas, lavadas</li><li>1 cebola ou 4 chalotas picadas</li><li>2 a 4 dentes de alho picados</li><li>1 lata (aprox. 400g) de tomate pelado ou em pedaços</li><li>500ml a 700ml de água ou caldo de vegetais (para o cozimento)</li><li>1 colher de chá de cominhos em pó</li><li>1 colher de chá de pimentão doce (paprika)</li><li>1/2 colher de chá de pimenta caiena ou chili em pó (ajuste a gosto)</li><li>Azeite, sal e pimenta preta q.b.</li><li>Opcional: 1 lata de milho cozido, 1 abacate em cubos, iogurte natural e coentros picados (para servir)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho grande, aqueça um fio de azeite. Junte a cebola e o alho picados e deixe alourar até começarem a ficar macios.</p><p><b>Especiarias:</b> Adicione os cominhos, o pimentão doce e a pimenta caiena ao refogado. Envolva tudo durante cerca de 1 minuto para libertar os aromas.</p><p><b>Cozinhar o Tomate e a Batata:</b> Adicione o tomate pelado e os cubos de batata-doce. Deixe cozinhar por cerca de 3 minutos, esmagando um pouco o tomate com a colher.</p><p><b>Adicionar as Lentilhas:</b> Junte as lentilhas e adicione a água ou caldo de vegetais. Tempere com sal e pimenta.</p><p><b>Apurar:</b> Deixe levantar fervura, depois reduza para lume brando, tape e deixe cozinhar por 20 a 25 minutos, mexendo ocasionalmente, até que as lentilhas e a batata-doce estejam tenras.</p><p><b>Toque Final (Opcional):</b> Se estiver a usar milho, adicione-o nos últimos 5 minutos de cozedura.</p><p><b>Servir:</b> Retire do lume e sirva quente. Pode decorar com iogurte natural, cubos de abacate e coentros frescos picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ALMONDEGAS_BERINJELA + "', '<h3>Ingredientes</h3><ul><li><b>Berinjelas:</b> 2 unidades médias</li><li><b>Arroz cozido:</b> 1 chávena (bem cozido e levemente amassado)</li><li><b>Azeite de oliva:</b> 2 a 3 colheres de sopa</li><li><b>Cebola:</b> 1 unidade média picada</li><li><b>Alho:</b> 2 a 3 dentes picados</li><li><b>Salsinha e cebolinha (cheiro-verde):</b> a gosto</li><li><b>Farinha de arroz (ou de aveia/rosca):</b> 1/2 a 1 chávena (para dar o ponto)</li><li><b>Temperos:</b> Sal, pimenta-do-reino, orégano e páprica a gosto</li><li><b>Molho de tomate:</b> 1 frasco ou lata para servir</li></ul><h3>Preparação</h3><p><b>Assar a Berinjela:</b> Pré-aqueça o forno a 180°C. Corte as berinjelas em cubos, coloque-as numa assadeira, tempere com sal e um fio de azeite. Leve ao forno por cerca de 20 a 30 minutos, ou até murcharem e ficarem macias.</p><p><b>Refogar:</b> Numa frigideira, salteie a cebola e o alho no azeite até dourarem.</p><p><b>Misturar:</b> Numa taça grande, junte a berinjela assada (pode picá-la ou amassá-la ligeiramente), o arroz cozido, o refogado de cebola e alho, e o cheiro-verde.</p><p><b>Dar o Ponto:</b> Adicione os temperos e comece a acrescentar a farinha de arroz (ou de aveia) aos poucos. Misture tudo com as mãos até obter uma massa moldável que não se desfaça.</p><p><b>Modelar e Assar:</b> Modele as bolinhas e coloque-as numa travessa untada. Leve ao forno a 180°C por cerca de 20 a 25 minutos até dourarem.</p><p><b>Finalizar:</b> Aqueça o molho de tomate, coloque as almôndegas dentro dele e deixe apurar por alguns minutos.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORTA_ESPINAFRES + "', '<h3>Ingredientes</h3><p><b>Massa:</b></p><ul><li>2 rolos de massa folhada ou massa quebrada (prontas a usar)</li><li>1 ovo (para pincelar)</li></ul><p><b>Recheio:</b></p><ul><li>500 g de ricota</li><li>2 maços de espinafre fresco (cerca de 400 g)</li><li>3 ovos</li><li>1/2 cebola picada</li><li>2 dentes de alho picados</li><li>1/2 chávena (chá) de queijo parmesão ralado</li><li>Azeite ou manteiga (para saltear)</li><li>Sal, pimenta-do-reino e noz-moscada (a gosto)</li></ul><h3>Preparação</h3><p><b>Preparar os Espinafres:</b> Lave bem o espinafre e separe apenas as folhas. Numa frigideira, salteie a cebola e o alho em azeite até dourarem. Adicione as folhas de espinafre e deixe cozinhar até murcharem (cerca de 5 minutos). Retire do lume e esprema muito bem para retirar o excesso de água. Pique os espinafres.</p><p><b>Preparar o Recheio:</b> Numa tigela grande, esfarele a ricota com um garfo. Junte o espinafre picado, os ovos batidos, o queijo parmesão e misture bem. Tempere com sal, pimenta e uma pitada de noz-moscada.</p><p><b>Montagem:</b> Preaqueça o forno a 180 °C. Forre uma tarteira ou forma redonda com uma das bases de massa (mantendo o papel vegetal). Verta o preparado de ricota e espinafre sobre a massa.</p><p><b>Cobertura:</b> Cubra a torta com a segunda base de massa. Pressione e feche bem as bordas. Pique a superfície com um garfo e pincele com um ovo batido para dourar.</p><p><b>Cozedura:</b> Leve ao forno preaquecido por cerca de 35 a 45 minutos, ou até a massa estar folhada, estaladiça e bem dourada. Deixe repousar cerca de 10 minutos antes de fatiar.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ESTUFADO_FEIJAO_BRANCO + "', '<h3>Ingredientes</h3><ul><li>500 g de feijão-branco cozido (ou cerca de 2 frascos)</li><li>1/2 couve (lombarda ou coração) cortada em juliana ou gomos</li><li>1 cebola média picada</li><li>3 a 4 dentes de alho picados</li><li>2 tomates maduros picados (ou 1 lata de tomate em pedaços / polpa)</li><li>2 cenouras médias cortadas em rodelas</li><li>3 colheres de sopa de azeite</li><li>1 folha de louro</li><li>1 colher de chá de pimentão-doce (colorau)</li><li>Sal, pimenta preta e piripiri a gosto</li><li>Água (cerca de 100 a 200 ml)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho largo, aqueça o azeite e adicione a cebola, os alhos e a folha de louro. Deixe alourar até a cebola ficar translúcida.</p><p><b>Adicionar o Tomate:</b> Junte o tomate picado e o pimentão-doce. Mexa e deixe apurar durante cerca de 3 a 5 minutos.</p><p><b>Legumes:</b> Adicione as rodelas de cenoura e um pouco de água. Tape e deixe cozinhar em lume brando durante 5 minutos.</p><p><b>Juntar a Couve:</b> Acrescente a couve cortada e tempere com sal, pimenta e piripiri. Adicione mais um pouco de água se necessário, tape e deixe cozinhar até que a couve esteja tenra (cerca de 10 minutos).</p><p><b>Envolver o Feijão:</b> Adicione o feijão-branco já cozido (com um pouco do seu próprio caldo para ajudar a engrossar). Mexa cuidadosamente e deixe ferver em lume brando por 5 a 10 minutos para que o feijão absorva todos os sabores.</p><p><b>Servir:</b> Rectifique os temperos, retire a folha de louro e sirva quente. Pode acompanhar com broa de milho ou fatias de pão rústico.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_HAMBURGUER_GRAO_BATATA + "', '<h3>Ingredientes</h3><p><b>Para os Hambúrgueres:</b></p><ul><li>400 g de grão-de-bico cozido (escorrido)</li><li>1 cebola média (picada)</li><li>2 dentes de alho (picados)</li><li>4 a 5 colheres de sopa de aveia em flocos finos ou farinha de trigo</li><li>1 colher de sopa de azeite</li><li>Ervas aromáticas a gosto: salsa, coentros ou orégãos</li><li>Temperos: sal e pimenta-preta a gosto</li><li>Opcional (para dar cor e sabor extra): 1 colher de chá de páprica defumada ou cominhos</li></ul><p><b>Para as Batatas Assadas:</b></p><ul><li>4 a 5 batatas médias (ou batata-doce)</li><li>2 colheres de sopa de azeite</li><li>Sal, alho em pó e alecrim a gosto</li></ul><h3>Preparação</h3><p><b>Preparar as Batatas:</b> Pré-aqueça o forno a 200ºC. Lave, descasque e corte as batatas em palitos ou cubos. Tempere com o azeite, o sal, o alho em pó e o alecrim. Espalhe-as num tabuleiro de forno forrado com papel vegetal e leve a assar por cerca de 30 a 40 minutos (ou até dourarem).</p><p><b>Preparar a Base do Hambúrguer:</b> Numa frigideira com um fio de azeite, refogue a cebola e o alho picados até ficarem macios e translúcidos.</p><p><b>Triturar:</b> Coloque o grão-de-bico cozido numa taça e esmague-o com um garfo (ou passe levemente pelo processador de alimentos) até obter uma pasta rústica, mas sem desfazer todos os grãos.</p><p><b>Misturar:</b> Adicione o refogado de cebola e alho ao grão. Junte as ervas aromáticas picadas e os temperos (sal, pimenta e especiarias).</p><p><b>Dar Consistência:</b> Adicione a aveia ou farinha de trigo, uma colher de cada vez, e misture com as mãos. A massa deve ficar moldável e não muito pegajosa.</p><p><b>Moldar:</b> Divida a massa em 3 ou 4 partes iguais. Com as mãos, forme bolas e depois achate-as para criar os discos de hambúrguer. Se tiver tempo, deixe repousar no frigorífico por 15-20 minutos para ficarem mais firmes.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente (pode pincelar com umas gotas de azeite) e coloque os hambúrgueres. Deixe cozinhar cerca de 4 a 5 minutos de cada lado até ficarem dourados e crocantes.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_COUSCOUS_LEGUMES + "', '<h3>Ingredientes (Para 4 pessoas)</h3><ul><li><b>Couscous:</b> 150 g a 200 g de cuscuz marroquino</li><li><b>Líquido:</b> 200 ml a 250 ml de água ou caldo de legumes (preferencialmente quente)</li><li><b>Legumes para grelhar:</b> 1 curgete, 1 beringela pequena, 1/2 pimento vermelho e 1/2 pimento amarelo cortados em cubos ou tiras</li><li><b>Aromáticos:</b> 1 dente de alho picado</li><li><b>Tempero:</b> Azeite, sal, pimenta preta e ervas frescas a gosto (manjericão, hortelã ou tomilho)</li><li><b>Opcional:</b> Queijo feta ou parmesão em lascas, e amêndoas tostadas para dar textura</li></ul><h3>Preparação</h3><p><b>Hidratar o couscous:</b> Numa taça larga, coloque o cuscuz, uma pitada de sal e um fio de azeite. Despeje a água ou caldo de legumes a ferver por cima. Mexa rapidamente, tape a taça com um prato ou película aderente e deixe repousar durante 5 minutos para absorver o líquido.</p><p><b>Soltar o couscous:</b> Após os 5 minutos, retire a tampa e use um garfo para soltar delicadamente os grãos, deixando-os fofos e homogéneos. Reserve.</p><p><b>Grelhar os legumes:</b> Numa grelha ou frigideira antiaderente bem quente, coloque um fio de azeite. Grelhe os legumes aos poucos, temperando com uma pitada de sal, até que fiquem macios e com marcas tostadas. Junte o alho picado nos últimos minutos.</p><p><b>Misturar e servir:</b> Adicione os legumes grelhados à taça com o cuscuz. Envolva tudo suavemente.</p><p><b>Finalização:</b> Regue com mais um fio de azeite, ajuste o sal e a pimenta e polvilhe com as ervas aromáticas picadas e o queijo feta, se desejar.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_LASANHA_ABOBORINHA + "', '<h3>Ingredientes</h3><ul><li>2 a 3 abobrinhas cortadas em fatias longitudinais finas (use um ralador mandolim ou faca)</li><li>300g a 500g de tofu firme</li><li>3 chávenas de molho de tomate caseiro ou de compra</li><li>1 cebola picada e 2 dentes de alho</li><li>3 colheres de sopa de azeite</li><li><b>Temperos para o tofu:</b> açafrão-da-terra, noz-moscada, sal e pimenta-do-reino a gosto</li><li>Orégãos e manjericão fresco a gosto</li></ul><h3>Preparação</h3><p><b>Prepare o tofu:</b> Escorra bem a água do tofu. Num recipiente, amasse o tofu com um garfo até obter uma textura semelhante a ricota. Tempere com o azeite, o açafrão-da-terra, a noz-moscada, o sal e a pimenta.</p><p><b>Refogue:</b> Numa frigideira, refogue a cebola e o alho no azeite até dourarem. Junte o tofu temperado e deixe apurar por alguns minutos.</p><p><b>Grelhe a abobrinha:</b> Numa grelha ou frigideira com um fio de azeite, grelhe levemente as fatias de abobrinha por 1-2 minutos de cada lado para retirar o excesso de água e torná-las mais flexíveis.</p><p><b>Monte a lasanha:</b> Numa travessa retangular, coloque uma fina camada de molho de tomate. Alterne camadas de abobrinha, molho de tomate e a mistura de tofu refogado. Finalize com molho e, se desejar, adicione orégãos e folhas de manjericão.</p><p><b>Asse:</b> Leve ao forno pré-aquecido a 180°C por cerca de 20 a 30 minutos, ou até a abobrinha estar macia.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_MACARRAO_TOMATE + "', '<h3>Ingredientes</h3><ul><li>250g de macarrão curto (ex: parafuso, penne ou farfalle)</li><li>150g a 200g de tomate seco picado em tiras (pode aproveitar o azeite da conserva para temperar)</li><li>150g a 200g de muçarela de búfala (em bolinhas ou fatiada)</li><li>1/2 maço de rúcula ou manjericão fresco a gosto</li><li>Azeitonas pretas ou verdes picadas (a gosto)</li><li>Azeite de oliva extra virgem, sal e pimenta-do-reino a gosto</li><li>Opcional: Lascas de queijo parmesão, dente de alho ralado ou umas gotas de limão siciliano</li></ul><h3>Preparação</h3><p><b>Cozinhar a massa:</b> Numa panela grande, ferva água com sal e cozinhe o macarrão até ficar al dente (cuidado para não cozinhar demais e desfazer na salada).</p><p><b>Arrefecer:</b> Escorra a água da massa e passe-a por água fria para interromper o cozimento e evitar que o macarrão grude.</p><p><b>Preparar os ingredientes:</b> Enquanto o macarrão arrefece, corte o tomate seco em tiras, fatie a muçarela de búfala e higienize as folhas de rúcula/manjericão.</p><p><b>Misturar:</b> Numa saladeira grande, coloque o macarrão cozido e frio. Adicione o tomate seco, a muçarela de búfala e as azeitonas.</p><p><b>Temperar:</b> Regue generosamente com azeite, adicione sal, pimenta-do-reino e envolva tudo delicadamente.</p><p><b>Finalizar:</b> Adicione as folhas de rúcula ou manjericão por cima apenas no momento de servir para que não murchem. Se desejar, salpique queijo parmesão.</p><p><b>Servir:</b> Pode servir imediatamente ou guardar no frigorífico (geladeira) por algumas horas para apurar o sabor.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ARROZ_FEIJAO_VAPOR + "', '<h3>Ingredientes (4 doses)</h3><ul><li><b>Arroz:</b> 250 g de arroz (carolino ou agulha)</li><li><b>Feijão:</b> 1 frasco ou lata grande de feijão cozido (cerca de 400 g), escorrido</li><li><b>Base do refogado:</b> 1 cebola média, 2 dentes de alho e 1 folha de louro</li><li><b>Azeite:</b> 3 colheres de sopa</li><li><b>Tomate:</b> 1 tomate maduro picado ou 2 colheres de sopa de polpa de tomate</li><li><b>Legumes ao Vapor:</b> 300 g a 400 g de legumes variados (ex: floretes de brócolos, cenoura em rodelas finas, feijão-verde cortado ou curgete)</li><li><b>Temperos:</b> Sal e pimenta preta a gosto</li><li><b>Líquido:</b> 500 a 600 ml de água quente ou caldo de legumes</li></ul><h3>Preparação</h3><p><b>Preparar o refogado:</b> Num tacho largo, leve o azeite ao lume com a cebola picada, os alhos esmagados e a folha de louro. Deixe alourar até a cebola ficar translúcida.</p><p><b>Adicionar o tomate:</b> Junte o tomate picado (ou a polpa) e deixe cozinhar durante alguns minutos até o tomate começar a desfazer-se.</p><p><b>Temperar e juntar o arroz:</b> Adicione o arroz e envolva bem no refogado para absorver os sabores por cerca de 1 a 2 minutos.</p><p><b>Adicionar o feijão:</b> Acrescente o feijão já cozido. Se preferir um arroz mais cremoso, pode triturar uma pequena parte do feijão com um pouco de água antes de adicionar.</p><p><b>Cozinhar:</b> Tempere com sal e pimenta e adicione a água quente. Mexa, tape o tacho e deixe cozinhar em lume brando durante cerca de 10 minutos.</p><p><b>Colocar os legumes:</b> Enquanto o arroz cozinha, coloque um cesto próprio para cozedura a vapor sobre o tacho e adicione os legumes lavados e cortados. Tape tudo e deixe os legumes cozinhar a vapor com o calor do arroz durante os últimos 5 a 8 minutos.</p><p><b>Finalizar:</b> Quando o arroz estiver tenro e sem água e os legumes crocantes e cozinhados, retire o cesto, envolva tudo e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORTILHA_BATATA_ALHO + "', '<h3>Ingredientes</h3><p>Para 2 a 4 pessoas, vai precisar de:</p><ul><li>3 a 4 batatas médias</li><li>A parte branca de 1 alho-francês</li><li>1 cebola pequena e 2 dentes de alho</li><li>4 a 5 ovos grandes</li><li>Azeite, sal e pimenta preta a gosto</li><li>Salsa picada e um pouco de noz-moscada (opcional)</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque as batatas e corte-as em rodelas finas ou cubos pequenos. Lave bem o alho-francês e corte-o em rodelas finas. Pique a cebola e os alhos.</p><p><b>Cozinhar os legumes:</b> Numa frigideira antiaderente, aqueça duas colheres de sopa de azeite e refogue a cebola e o alho. Junte o alho-francês e as batatas. Deixe cozinhar em lume médio até as batatas ficarem macias e o alho-francês murchar.</p><p><b>Bater os ovos:</b> Numa taça, bata os ovos com uma pitada de sal, pimenta e noz-moscada.</p><p><b>Misturar:</b> Junte os legumes cozinhados aos ovos batidos e envolva tudo.</p><p><b>Fazer a tortilha:</b> Volte a colocar a mistura na frigideira untada com um pouco de azeite e espalhe bem. Deixe cozinhar em lume brando até a base firmar.</p><p><b>Virar:</b> Com a ajuda de um prato raso ou de uma tampa, vire a tortilha e deixe-a deslizar novamente para a frigideira para dourar do outro lado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUICHE_LEGUMES + "', '<h3>Ingredientes</h3><ul><li>1 base de massa quebrada ou massa folhada</li><li>4 ovos</li><li>200 ml de natas (ou natas vegetais/leite)</li><li>400 a 500 g de legumes variados (ex: curgete/abobrinha, cenoura, alho-francês, cogumelos, brócolos ou espinafres)</li><li>1 cebola e 2 dentes de alho picados (para o refogado)</li><li>1 fio de azeite</li><li>Sal, pimenta preta e noz-moscada q.b.</li><li>Queijo ralado (opcional, para polvilhar)</li></ul><h3>Preparação</h3><p><b>Preparar a massa:</b> Pré-aqueça o forno a 180 ºC. Estenda a massa numa tarteira, pique o fundo com um garfo e reserve.</p><p><b>Saltear os legumes:</b> Numa frigideira com um fio de azeite, refogue a cebola e o alho. Adicione os restantes legumes (previamente cortados em pedaços pequenos ou ralados) e deixe saltear até ficarem tenros e sem excesso de água. Tempere com sal e pimenta.</p><p><b>Fazer o creme:</b> Numa taça, bata os ovos com as natas. Tempere com sal, pimenta e uma pitada de noz-moscada.</p><p><b>Montar a quiche:</b> Distribua os legumes salteados sobre a massa na tarteira. Por cima, verta a mistura de ovos e natas de forma uniforme. Polvilhe com queijo ralado a gosto.</p><p><b>Cozer:</b> Leve ao forno a 180 ºC durante cerca de 30 a 35 minutos, ou até a quiche ficar dourada e firme ao toque.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_LENTILHAS_MACA + "', '<h3>Ingredientes</h3><p><b>Para a base:</b></p><ul><li>200 g de lentilhas (verdes ou castanhas)</li><li>1 folha de louro</li><li>1 ou 2 maçãs (de preferência Granny Smith para um toque mais ácido, ou outra variedade a gosto)</li><li>40 g a 50 g de nozes grosseiramente picadas</li><li>1 cebola roxa pequena, picada</li><li>Salsa ou coentros frescos picados a gosto</li></ul><p><b>Para o molho (vinagrete):</b></p><ul><li>2 colheres de sopa de azeite extra virgem</li><li>2 colheres de sopa de sumo de limão</li><li>1 colher de chá de mostarda Dijon</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Cozer as lentilhas:</b> Lave as lentilhas e coloque-as numa panela com água, uma pitada de sal e a folha de louro. Deixe ferver, reduza o lume e deixe cozinhar até estarem tenras, mas firmes (cerca de 20 a 25 minutos). Escorra bem e deixe arrefecer.</p><p><b>Preparar os vegetais e a fruta:</b> Descasque e corte a maçã em cubos pequenos. Pique a cebola roxa e as ervas aromáticas.</p><p><b>Fazer o molho:</b> Numa taça pequena, misture o azeite, o sumo de limão, a mostarda Dijon, o sal e a pimenta. Bata bem até emulsionar.</p><p><b>Misturar tudo:</b> Numa saladeira grande, junte as lentilhas já frias, os cubos de maçã, a cebola picada, as ervas e as nozes.</p><p><b>Envolver:</b> Verta o molho preparado sobre a salada e envolva tudo delicadamente. Pode servir de imediato ou levar ao frigorífico para servir fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_TOMATE_AZEITONAS + "', '<h3>Ingredientes</h3><ul><li>400 g de massa (esparguete, penne ou fusilli)</li><li>2 a 3 tomates maduros picados (ou 1 lata de tomate pelado/em cubos)</li><li>1 chávena de azeitonas (pretas ou verdes) sem caroço e fatiadas</li><li>3 colheres de sopa de azeite</li><li>2 dentes de alho picados</li><li>1/2 cebola picada (opcional)</li><li>Sal e pimenta-do-reino a gosto</li><li>Manjericão fresco ou orégãos a gosto</li><li><b>Opcional:</b> Alcaparras, 2 filés de aliche e uma pitada de pimenta calabresa</li></ul><h3>Preparação</h3><p><b>Cozer a massa:</b> Numa panela grande com água a ferver e sal, coloque a massa e deixe cozer até ficar al dente (cerca de 8 a 10 minutos). Guarde 1 chávena da água de cozimento da massa e escorra o resto.</p><p><b>Fazer o refogado:</b> Numa frigideira grande, aqueça o azeite e refogue o alho (e a cebola) até dourarem. Se for usar aliche e pimenta calabresa, adicione nesta etapa e deixe o aliche dissolver no azeite.</p><p><b>Adicionar o tomate:</b> Junte os tomates picados, tempere com sal, pimenta e deixe cozinhar em lume médio até começarem a desfazer-se e a criar um molho.</p><p><b>Incorporar as azeitonas:</b> Adicione as azeitonas (e as alcaparras, se desejar) e misture bem. Deixe apurar por 3 a 5 minutos.</p><p><b>Envolver tudo:</b> Junte a massa cozida diretamente à frigideira com o molho. Adicione um pouco da água de cozimento reservada para deixar o molho mais cremoso e envolva tudo durante 1 minuto.</p><p><b>Finalizar:</b> Desligue o lume, adicione o manjericão fresco e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_GRATINADO_COUVE_FLOR + "', '<h3>Ingredientes</h3><ul><li>1 couve-flor média ou grande, dividida em raminhos</li><li>200 ml a 400 ml de natas de soja (dependendo da cremosidade desejada)</li><li>2 dentes de alho picados (ou alho em pó)</li><li>q.b. de sal e pimenta-preta</li><li>q.b. de noz-moscada (moída na hora)</li><li>1 c. sopa de azeite</li><li>q.b. de queijo ralado (pode usar queijo vegan ou um queijo tradicional da sua preferência)</li><li><b>Opcional:</b> pão ralado, orégãos ou levedura nutricional para finalizar</li></ul><h3>Preparação</h3><p><b>Cozer a couve-flor:</b> Lave a couve-flor e corte-a em raminhos. Coza-a em água a ferver temperada com sal por cerca de 3 a 5 minutos, para que fique al dente (não deixe cozer demasiado para não se desfazer). Escorra bem.</p><p><b>Preparar o forno:</b> Pré-aqueça o forno a 200°C.</p><p><b>Temperar a couve:</b> Coloque os raminhos de couve-flor num tabuleiro ou pirex próprio para ir ao forno. Regue com um fio de azeite e polvilhe com o alho picado, sal, pimenta e uma pitada de noz-moscada.</p><p><b>Adicionar o creme:</b> Numa tigela, envolva as natas de soja com metade do queijo ralado e tempere com mais um pouco de noz-moscada. Verta este preparado uniformemente sobre a couve-flor no tabuleiro.</p><p><b>Gratinar:</b> Polvilhe o topo com o restante queijo ralado e um pouco de pão ralado se quiser uma camada extra crocante. Leve ao forno por cerca de 15 a 20 minutos, ou até o topo estar bem dourado e estaladiço.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_EMPADAO_LENTILHAS + "', '<h3>Ingredientes</h3><p><b>Para o recheio de lentilhas:</b></p><ul><li>1 lata grande de lentilhas cozidas (aprox. 400 g) ou 1 1/2 chávena de lentilhas cruas previamente cozidas</li><li>2 cenouras médias cortadas em cubos pequenos</li><li>1 cebola picada</li><li>2 dentes de alho picados</li><li>1 folha de louro</li><li>200 g de polpa de tomate ou tomate maduro em pedaços</li><li>Azeite, sal e pimenta preta a gosto</li><li>Água ou caldo de legumes q.b.</li></ul><p><b>Para o puré de cobertura:</b></p><ul><li>1 kg de batata (ou batata-doce) descascada e cortada em pedaços</li><li>1 colher de sopa de manteiga (ou manteiga/azeite vegetal)</li><li>Leite ou bebida vegetal q.b.</li><li>Sal, pimenta e noz-moscada a gosto</li></ul><h3>Preparação</h3><p><b>1. Preparar o Puré:</b> Coloque as batatas a cozer em água temperada com sal. Quando estiverem macias, escorra e reduza a puré. Junte a manteiga, um pouco de leite para atingir a consistência desejada e tempere com sal, pimenta e noz-moscada. Reserve.</p><p><b>2. Fazer o Refogado base:</b> Num tacho largo, leve ao lume o azeite, a cebola picada, o alho e a folha de louro. Deixe alourar até a cebola ficar translúcida.</p><p><b>3. Estufar os legumes:</b> Junte as cenouras cortadas em cubos pequenos e deixe cozinhar tapado em lume brando por cerca de 5 minutos. Adicione a polpa de tomate e o tomate. Tempere com sal e pimenta.</p><p><b>4. Adicionar as lentilhas:</b> Adicione as lentilhas cozidas ao preparado e adicione um pouco de água ou caldo de legumes (cerca de 100 ml). Deixe apurar em lume brando durante 10 a 15 minutos, mexendo ocasionalmente, até obter um estufado rico e húmido.</p><p><b>5. Montar o empadão:</b> Numa assadeira ou pirex, espalhe o preparado de lentilhas e cenoura no fundo. Cubra uniformemente com o puré de batata.</p><p><b>6. Levar ao forno:</b> Pode alisar a superfície do puré com um garfo e pincelar com uma gema de ovo ou polvilhar com pão ralado para criar uma crosta crocante. Leve ao forno pré-aquecido a 180°C por 10 a 15 minutos, ou até ficar dourado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_FEIJAO_FRADE + "', '<h3>Ingredientes</h3><p>Para preparar esta salada para 4 pessoas, vai precisar de:</p><ul><li>500g a 550g de feijão frade (previamente cozido)</li><li>1 a 2 latas de atum em conserva (escorrido)</li><li>2 ovos cozidos</li><li>1 cebola média picada</li><li>1 ramo de salsa fresca picada</li><li>Azeite, vinagre e sal a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os ovos:</b> Coloque os ovos num tacho com água e sal e deixe cozer durante 10 minutos. Depois de arrefecerem, descasque-os e corte-os às rodelas ou pique-os.</p><p><b>Preparar o feijão:</b> Se usar feijão seco, demolhe-o e coza-o até ficar tenro. Se utilizar feijão de conserva, passe-o bem por água e escorra-o.</p><p><b>Picar os aromáticos:</b> Pique finamente a cebola e a salsa.</p><p><b>Misturar:</b> Numa saladeira grande, junte o feijão frade, o atum escorrido, a cebola picada e a salsa.</p><p><b>Temperar e servir:</b> Tempere a mistura com azeite, vinagre e sal a gosto. Envolva tudo delicadamente e decore por cima com os ovos cozidos.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_ERVAS_ARROZ + "', '<h3>Ingredientes</h3><p><b>Para o Tofu com Crosta de Ervas:</b></p><ul><li>1 bloco de tofu firme (aprox. 400g), bem prensado e seco</li><li>2 a 3 colheres de sopa de azeite</li><li>2 colheres de sopa de molho de soja (shoyu)</li><li>3 colheres de sopa de pão ralado</li><li>1 colher de sopa de salsa fresca picada</li><li>1 colher de chá de orégãos secos</li><li>1 dente de alho picado ou alho em pó</li><li>Pitada de sal e pimenta preta a gosto</li></ul><p><b>Para o Arroz:</b></p><ul><li>1 chávena de arroz (basmati ou jasmim)</li><li>2 chávenas de água quente</li><li>1 colher de sopa de azeite</li><li>1 dente de alho picado</li><li>Sal a gosto</li></ul><h3>Preparação</h3><p><b>1. Preparar o Tofu:</b> Seque o bloco de tofu com um pano de cozinha limpo para retirar o excesso de água. Corte o tofu em fatias ou cubos médios. Numa taça, envolva o tofu com o molho de soja e deixe marinar por 10 a 15 minutos.</p><p><b>2. Preparar a Crosta e Selar:</b> Numa travessa funda, misture o pão ralado, a salsa, os orégãos, o alho, o sal e a pimenta. Pressione as fatias de tofu na mistura de ervas para criar uma crosta uniforme em ambos os lados. Aqueça o azeite numa frigideira. Quando estiver quente, adicione o tofu e deixe cozinhar em lume médio-alto até a crosta ficar dourada e estaladiça (cerca de 3 a 4 minutos por lado).</p><p><b>3. Preparar o Arroz:</b> Lave o arroz em água corrente até a água sair límpida. Num tacho, aqueça o azeite e refogue o alho picado. Junte o arroz e mexa por um minuto. Adicione a água quente e o sal. Tape o tacho, reduza o lume para o mínimo e deixe cozinhar até a água evaporar (cerca de 10 a 12 minutos). Desligue o lume e deixe repousar tapado por mais 5 minutos.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_RISOTO_ABOBORA_SALVIA + "', '<h3>Ingredientes Essenciais</h3><p>Para preparar esta receita (serve cerca de 4 pessoas), precisará de:</p><ul><li>2 xícaras (chá) de arroz para risoto (arbóreo ou carnaroli)</li><li>700 g a 1 kg de abóbora japonesa ou cabotiá (descascada e cortada em cubos)</li><li>1 cebola picada finamente</li><li>10 a 15 folhas de sálvia frescas</li><li>1,5 litro de caldo de legumes caseiro (quente)</li><li>150 ml de vinho branco seco</li><li>2 colheres (sopa) de azeite e 2 colheres (sopa) de manteiga</li><li>Queijo parmesão ralado a gosto</li><li>Sal e pimenta-do-reino a gosto</li></ul><h3>Modo de Preparo</h3><p><b>Preparar a abóbora:</b> Coza os cubos de abóbora em água a ferver ou asse-os no forno com um fio de azeite e sal até ficarem macios. Amasse metade da abóbora em puré e corte a outra metade em cubos menores para textura.</p><p><b>Infusão de sálvia:</b> Numa panela de fundo grosso, aqueça o azeite e uma colher de manteiga. Frite as folhas de sálvia até ficarem estaladiças e reserve-as.</p><p><b>Refogado base:</b> Na mesma panela, adicione a cebola picada e deixe dourar. Junte o arroz e deixe fritar por cerca de 2 minutos.</p><p><b>Adicionar vinho:</b> Verta o vinho branco e mexa até evaporar completamente.</p><p><b>Cozedura do risoto:</b> Adicione o caldo de legumes quente, uma concha de cada vez. Mexa continuamente e espere o líquido ser absorvido antes de adicionar mais caldo. A meio do processo, junte o puré e os cubos de abóbora.</p><p><b>Finalização:</b> Quando o arroz estiver al dente (cozido por fora, mas com um leve centro firme) e cremoso, desligue o lume. Adicione a manteiga restante, o queijo parmesão ralado e misture energicamente para criar cremosidade (técnica conhecida como mantecatura).</p><p><b>Servir:</b> Sirva de imediato, decorando com as folhas de sálvia crocantes reservadas e mais queijo a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CARIL_GRAO_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>400 g a 500 g de grão-de-bico cozido</li><li>100 g a 200 g de espinafres frescos</li><li>400 ml de leite de coco (uma lata)</li><li>2 a 3 colheres de sopa de polpa de tomate ou tomate pelado</li><li>1 cebola grande picada</li><li>2 dentes de alho picados</li><li>1 colher de chá de gengibre fresco ralado</li><li>1 a 2 colheres de chá de caril em pó (ou pasta de caril)</li><li>1 colher de chá de cominhos</li><li>Azeite ou óleo de coco (para o refogado)</li><li>Sal e pimenta q.b.</li><li>Coentros frescos (opcional, para guarnecer)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Leve um tacho ao lume com o azeite ou óleo de coco. Junte a cebola picada, o alho e o gengibre, e deixe refogar em lume brando até a cebola ficar dourada e macia.</p><p><b>Especiarias:</b> Adicione o caril em pó e os cominhos. Mexa bem durante cerca de 1 minuto para libertar todos os aromas e tostá-las ligeiramente.</p><p><b>Base de molho:</b> Acrescente a polpa de tomate e o leite de coco. Envolva tudo muito bem e tempere com sal e pimenta. Deixe levantar fervura e reduza o lume.</p><p><b>Grão:</b> Junte o grão-de-bico cozido e escorrido. Deixe cozinhar em lume brando durante cerca de 10 minutos para que o grão absorva os sabores do molho.</p><p><b>Espinafres:</b> Por fim, adicione as folhas de espinafre. Mexa e deixe cozinhar por mais 3 a 5 minutos, apenas até os espinafres murcharem.</p><p><b>Finalização:</b> Rectifique os temperos, polvilhe com coentros frescos picados e sirva quente, idealmente acompanhado com arroz basmati ou pão naan.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CANELONES_TOFU + "', '<h3>Ingredientes</h3><p><b>Para o recheio:</b></p><ul><li>400g de tofu firme</li><li>1 colher de sopa de azeite</li><li>Sumo de 1/2 limão</li><li>Manjericão fresco picado a gosto</li><li>Levedura nutricional ou alho em pó (opcional, para dar mais sabor)</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para a massa e base:</b></p><ul><li>1 embalagem de massa para canelones (cerca de 250g)</li><li>500ml de polpa de tomate ou molho de tomate caseiro</li><li>Queijo mozzarella ralado ou parmesão (pode usar alternativa vegana)</li><li>Folhas de manjericão fresco (para decorar)</li></ul><h3>Preparação</h3><p><b>Preparar o Recheio:</b> Escorra o tofu e esmague-o com um garfo ou triture-o num processador até obter uma pasta. Adicione o azeite, o sumo de limão, uma pitada de alho, sal, pimenta e uma quantidade generosa de manjericão fresco picado. Misture bem até ficar homogéneo.</p><p><b>Rechear os Canelones:</b> Pré-coza ligeiramente a massa dos canelones em água a ferver durante 2 a 3 minutos para amolecer (caso a embalagem o exija). Com a ajuda de uma colher ou saco de pasteleiro, recheie cada tubo com a pasta de tofu.</p><p><b>Montagem:</b> Espalhe uma camada fina de molho de tomate no fundo de um tabuleiro ou pirex. Disponha os canelones lado a lado por cima do molho.</p><p><b>Cobrir:</b> Cubra os canelones com o restante molho de tomate, polvilhe com o queijo ralado (ou levedura nutricional para a versão vegan) e adicione algumas folhas de manjericão fresco.</p><p><b>Cozinhar:</b> Leve ao forno pré-aquecido a 180ºC durante cerca de 25 a 30 minutos, ou até a massa estar cozida e o queijo derretido e dourado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_QUINOA_MANGA + "', '<h3>Ingredientes (para 3-4 pessoas)</h3><ul><li>1 xícara de quinoa (branca ou misturada)</li><li>2 xícaras de água (para cozer a quinoa)</li><li>1 manga madura grande, descascada e cortada em cubos</li><li>1/2 xícara de amêndoas (laminadas ou picadas)</li><li>Suco de 1 limão</li><li>2 a 3 colheres de sopa de azeite extra virgem</li><li>Sal e pimenta-do-reino a gosto</li><li><b>Opcional:</b> Folhas de espinafre, hortelã fresca picada ou cebola roxa para maior complexidade de sabor.</li></ul><h3>Preparação</h3><p><b>Cozer a quinoa:</b> Passe a quinoa por água corrente num coador fino para retirar a saponina (que pode dar um sabor amargo). Numa panela, misture a quinoa com as duas xícaras de água e uma pitada de sal. Deixe ferver, tape e reduza o lume, deixando cozinhar por cerca de 10 a 15 minutos até a água ser absorvida e os grãos ficarem translúcidos. Retire do lume e deixe arrefecer.</p><p><b>Tostar as amêndoas:</b> Numa frigideira sem óleo, coloque as amêndoas em lume brando e deixe tostar ligeiramente até ganharem cor e aroma. Retire e reserve.</p><p><b>Misturar:</b> Numa saladeira grande, coloque a quinoa já fria. Junte os cubos de manga e as amêndoas tostadas.</p><p><b>Temperar:</b> Numa pequena taça à parte, emulsione o azeite com o sumo de limão, o sal e a pimenta. Verta este molho sobre a salada e envolva tudo cuidadosamente para não desfazer a manga.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_BROCOLOS_ALHO + "', '<h3>Ingredientes</h3><p>Para 2 a 3 pessoas:</p><ul><li>250g de massa (ex: esparguete, fusilli, penne)</li><li>1 cabeça de brócolos média (ou cerca de 300g-400g)</li><li>4 a 5 dentes de alho (laminados ou picados)</li><li>Azeite virgem extra q.b.</li><li>Sal e pimenta preta moída q.b.</li><li><b>Opcional:</b> Queijo parmesão ralado, piripiri ou bacon aos cubos</li></ul><h3>Preparação</h3><p><b>Cozer a massa:</b> Numa panela grande com água a ferver e bastante sal, coloque a massa. Deixe cozer até ficar al dente (verifique o tempo na embalagem).</p><p><b>Preparar os brócolos:</b> Corte os brócolos em pequenos floretes e aproveite o talo cortando-o em fatias finas. Pode cozer os brócolos a vapor durante 5 minutos ou colocá-los diretamente na água da massa 3 a 4 minutos antes desta estar pronta.</p><p><b>Escorrer:</b> Retire os brócolos e a massa, escorrendo bem. Reserve cerca de meia chávena da água de cozedura da massa.</p><p><b>Fazer o refogado:</b> Numa frigideira grande, aqueça um fio generoso de azeite e adicione o alho. Deixe fritar em lume brando até alourar levemente, tendo cuidado para não queimar e ficar amargo.</p><p><b>Envolver:</b> Junte os brócolos ao azeite e alho e salteie por 1 minuto. Adicione a massa cozida e um pouco da água de cozedura reservada. Mexa tudo durante 1 a 2 minutos para criar um molho ligeiro e envolver os sabores.</p><p><b>Finalizar:</b> Tempere com sal, pimenta e, se desejar, adicione queijo parmesão ralado ou pinhões tostados no momento de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_HAMBURGUER_LENTILHAS_SALADA + "', '<h3>Ingredientes (rende 4 a 6 hambúrgueres)</h3><p><b>Para os Hambúrgueres:</b></p><ul><li>400 g de lentilhas (verdes ou castanhas) cozidas e escorridas</li><li>1/2 chávena de flocos de aveia finos (ou pão ralado)</li><li>1 cebola picada</li><li>2 dentes de alho picados</li><li>1 colher de sopa de sementes de linhaça moída (ajuda a dar liga)</li><li>Ervas aromáticas a gosto: salsa, coentros ou orégãos</li><li>Especiarias a gosto: cominhos, páprica (pimentão-doce) ou caril</li><li>Sal e pimenta preta q.b.</li><li>Azeite para pincelar/fritar</li></ul><p><b>Para a Salada:</b></p><ul><li>Folhas de alface variadas</li><li>2 tomates maduros cortados em cubos</li><li>1 cebola roxa em rodelas finas</li><li>1/2 pimento vermelho cortado em tiras</li><li>Azeite, vinagre (ou sumo de limão) e sal para temperar</li></ul><h3>Preparação</h3><p><b>Preparar a massa:</b> Numa tigela grande, coloque as lentilhas cozidas e escorridas. Esmague cerca de metade das lentilhas com um garfo para criar uma textura pastosa, mantendo alguns grãos inteiros.</p><p><b>Adicionar os ingredientes:</b> Junte a cebola, o alho, a aveia, a linhaça e as ervas aromáticas. Tempere com o sal, a pimenta e as especiarias que escolheu.</p><p><b>Misturar e moldar:</b> Misture tudo muito bem com as mãos até obter uma massa homogénea e moldável. Se estiver muito húmida, adicione mais um pouco de aveia. Divida a massa em 4 a 6 partes e molde os hambúrgueres.</p><p><b>Cozinhar:</b></p><ul><li><b>Na frigideira:</b> Aqueça um fio de azeite numa frigideira antiaderente. Cozinhe os hambúrgueres durante cerca de 3 a 4 minutos de cada lado, até ficarem dourados e crocantes.</li><li><b>No forno:</b> Coloque os hambúrgueres num tabuleiro com papel vegetal, pincele com azeite e leve ao forno pré-aquecido a 180ºC por cerca de 15 a 20 minutos, virando a meio.</li></ul><p><b>Preparar a salada:</b> Numa saladeira, misture a alface, o tomate, a cebola roxa e o pimento. Tempere com azeite, vinagre e sal a gosto.</p><p><b>Servir:</b> Sirva os hambúrgueres quentes acompanhados da salada fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ESTUFADO_ERVILHAS_OVOS + "', '<h3>Ingredientes (para 4 doses)</h3><ul><li>500 g a 800 g de ervilhas (frescas ou congeladas)</li><li>4 ovos</li><li>100 g a 150 g de chouriço de carne cortado em rodelas</li><li>1 cebola grande picada</li><li>3 a 4 dentes de alho picados</li><li>2 tomates maduros picados (sem pele e sem sementes) ou polpa de tomate</li><li>2 a 3 colheres de sopa de azeite</li><li>1 folha de louro</li><li>Sal e pimenta preta a gosto</li><li>Água ou caldo de legumes q.b.</li><li>Coentros ou salsa frescos picados (para guarnecer)</li></ul><h3>Preparação</h3><p><b>Faça o refogado:</b> Num tacho largo, coloque o azeite, a cebola picada, o alho e a folha de louro. Deixe alourar até a cebola ficar translúcida.</p><p><b>Adicione os enchidos:</b> Junte as rodelas de chouriço e deixe fritar ligeiramente para que larguem os seus sabores e gordura.</p><p><b>Incorpore o tomate:</b> Adicione o tomate picado (ou a polpa) e deixe cozinhar por alguns minutos até começar a desfazer-se. Se desejar, pode regar com umas gotas de vinho branco e deixar evaporar o álcool.</p><p><b>Cozinhe as ervilhas:</b> Acrescente as ervilhas e envolva bem no preparado. Tempere com sal e pimenta. Adicione água ou caldo suficiente para cobrir (mas sem tapar demasiado). Tape o tacho e deixe estufar em lume brando durante cerca de 15 a 20 minutos, até que as ervilhas estejam tenras.</p><p><b>Escalfe os ovos:</b> Abra um espaço entre as ervilhas e parta os ovos lá para dentro, um a um. Tape o tacho novamente e deixe os ovos escalfar durante cerca de 3 a 4 minutos, até as claras estarem sólidas mas as gemas ainda cremosas.</p><p><b>Finalize e sirva:</b> Polvilhe com coentros ou salsa picada por cima e sirva de imediato, acompanhando com pão fresco fatiado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_MACARRAO_MILHO + "', '<h3>Ingredientes da Salada</h3><ul><li>250g a 300g de macarrão (tipo parafuso, penne ou laço)</li><li>1 lata de milho verde escorrido (cerca de 170g a 200g)</li><li>1 cenoura média ralada</li><li>1/2 cebola roxa bem picadinha</li><li>1/2 xícara de azeitonas picadas</li><li>100g de presunto e 100g de queijo muçarela em cubos pequenos (opcional)</li><li>Salsinha e cebolinha picadas a gosto</li></ul><h3>Ingredientes do Molho</h3><ul><li>3 a 4 colheres de sopa de maionese</li><li>1 caixa de creme de leite (200g)</li><li>Suco de 1/2 limão</li><li>Fio de azeite</li><li>Sal e pimenta-do-reino a gosto</li></ul><h3>Preparação</h3><p><b>Cozinhar o macarrão:</b> Em uma panela com água fervente e sal, cozinhe o macarrão até ficar al dente (cerca de 7 a 9 minutos).</p><p><b>Esfriar:</b> Escorra a água quente e passe o macarrão por água fria para interromper o cozimento e esfriá-lo rapidamente.</p><p><b>Preparar os vegetais:</b> Numa tigela grande, misture o macarrão frio com o milho escorrido, a cenoura ralada, a cebola roxa e as azeitonas. Adicione o presunto e o queijo, se desejar.</p><p><b>Fazer o molho:</b> Numa tigela separada, misture a maionese, o creme de leite, o suco de limão e o azeite até obter um creme liso. Tempere com sal e pimenta.</p><p><b>Misturar:</b> Despeje o molho sobre o macarrão e os ingredientes reservados. Polvilhe a salsinha e misture tudo delicadamente.</p><p><b>Refrigerar:</b> Leve à geladeira por cerca de 30 a 60 minutos antes de servir para apurar os sabores.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ARROZ_TOMATE_TOFU + "', '<h3>Ingredientes</h3><p><b>Para os Panados de Tofu:</b></p><ul><li>1 bloco de tofu firme (aprox. 300g)</li><li>3 a 4 colheres de sopa de molho de soja (shoyu)</li><li>1 colher de chá de alho em pó</li><li>1 colher de chá de pimentão-doce (colorau)</li><li>Sumo de 1/2 limão</li><li>Farinha de trigo (ou de milho) e água para a polme</li><li>Pão ralado (para a crosta)</li><li>Azeite ou óleo para fritar</li></ul><p><b>Para o Arroz de Tomate:</b></p><ul><li>1 chávena de arroz agulha ou carolino</li><li>1 cebola picada</li><li>2 tomates maduros grandes (ou 1 lata pequena de tomate em pedaços)</li><li>2 dentes de alho picados</li><li>1 folha de louro</li><li>Azeite e sal a gosto</li><li>Salsa fresca picada (opcional)</li></ul><h3>\uD83C\uDF73 Preparação</h3><p><b>1. Temperar e Panar o Tofu:</b> Corte o tofu em fatias finas (tipo bife) ou em tiras. Num recipiente, misture o molho de soja, o alho em pó, o pimentão-doce e o sumo de limão. Envolva o tofu e deixe marinar durante pelo menos 15 a 30 minutos. Prepare o processo de panar: coloque farinha num prato; noutro prato, misture um pouco de farinha com água até obter uma textura líquida e espessa (substituto do ovo); e num terceiro prato coloque o pão ralado. Passe cada fatia de tofu primeiro pela farinha, depois pela mistura de água/farinha e, por fim, pressione no pão ralado. Frite os panados em azeite quente até dourarem de ambos os lados. Escorra em papel absorvente.</p><p><b>2. Fazer o Arroz de Tomate:</b> Num tacho, faça um refogado com o azeite, a cebola picada, os dentes de alho e a folha de louro até a cebola ficar translúcida. Adicione os tomates picados (sem pele) e deixe cozinhar até começarem a desfazer-se e criar molho. Junte o arroz e envolva bem no refogado durante 1 minuto. Adicione água a ferver (duas vezes e meia a quantidade de arroz) e tempere com sal. Tape o tacho e deixe cozinhar em lume brando durante 15 minutos, até o arroz estar tenro e o caldo aveludado. Retire do lume e envolva com salsa fresca picada antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUINOA_LEGUMES_TAHINI + "', '<h3>Ingredientes</h3><p><b>Para a Quinoa e os Legumes:</b></p><ul><li>1 xícara (chá) de quinoa</li><li>2 xícaras (chá) de água ou caldo de legumes</li><li>1 abobrinha e 1 berinjela (ou cenoura e batata-doce) cortadas em cubos</li><li>1 pimentão vermelho cortado em tiras</li><li>1 cebola roxa cortada em fatias</li><li>Azeite, sal e pimenta-do-reino a gosto</li></ul><p><b>Para o Molho de Tahini:</b></p><ul><li>3 colheres (sopa) de pasta de tahine</li><li>Sumo de 1/2 limão</li><li>3 a 4 colheres (sopa) de água morna (para ajustar a textura)</li><li>1 dente de alho pequeno espremido ou picado (opcional)</li><li>1 colher (chá) de xarope de ácer (maple syrup) ou mel (opcional)</li><li>Sal a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os Legumes:</b> Pré-aqueça o forno a 200°C. Numa assadeira, coloque todos os legumes, regue com azeite e tempere com sal e pimenta. Asse por cerca de 25 a 30 minutos, ou até dourarem e ficarem tenros.</p><p><b>Cozinhar a Quinoa:</b> Lave muito bem a quinoa em água corrente. Numa panela, junte a quinoa, a água (ou caldo) e uma pitada de sal. Deixe ferver, tape e reduza o lume. Deixe cozinhar por cerca de 15 minutos, ou até a água evaporar e os grãos ficarem soltinhos.</p><p><b>Fazer o Molho:</b> Numa tigela ou frasco, misture o tahine, o sumo de limão, o alho, o adoçante (se usar) e o sal. Adicione a água aos poucos e bata energicamente com um garfo até obter um molho liso e cremoso.</p><p><b>Montagem:</b> Numa saladeira grande, misture a quinoa cozida com os legumes assados e regue tudo com o molho de tahine. Pode servir morno ou frio.</p>');");

