        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_ALFACE_HORTELA + "', '<h3>Ingredientes</h3><p>Para 4 pessoas:</p><ul><li>1 alface média (limpa e sem o talo mais duro)</li><li>1 raminho de folhas de hortelã frescas</li><li>1 curgete (abobrinha) média</li><li>1 cebola</li><li>2 batatas médias (para dar textura aveludada)</li><li>2 dentes de alho</li><li>0,5 dl de azeite</li><li>1,2 litros de água</li><li>Sal e pimenta q.b.</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Descasque a cebola, os alhos e as batatas. Corte a curgete em cubos e as batatas em pedaços.</p><p><b>Refogar:</b> Num tacho, leve ao lume o azeite, a cebola e os alhos picados, deixando alourar ligeiramente.</p><p><b>Cozer a base:</b> Adicione a curgete e as batatas. Junte a água, tempere com sal e deixe cozinhar em lume brando durante cerca de 20 minutos.</p><p><b>Adicionar a alface:</b> Junte as folhas de alface ao tacho e deixe cozer por mais 5 a 10 minutos, até que fiquem tenras.</p><p><b>Triturar:</b> Retire o tacho do lume e passe tudo com a varinha mágica até obter um creme liso e homogéneo.</p><p><b>Aromatizar com hortelã:</b> Adicione as folhas de hortelã ao creme quente e triture novamente apenas o suficiente para as desfazer e libertar o aroma (evite cozinhar muito a hortelã para não perder o frescor).</p><p><b>Finalizar:</b> Rectifique o sal e a pimenta se necessário. Sirva quente ou, se preferir uma versão fria, leve ao frigorífico antes de consumir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_GRELHADO_VERDE + "', '<h3>Ingredientes</h3><p><b>Para o Tofu:</b></p><ul><li>1 bloco de tofu firme (aprox. 200g - 250g)</li><li>2 colheres de sopa de molho de soja (shoyu)</li><li>1 colher de sopa de azeite</li><li>1 colher de chá de sumo de limão ou vinagre balsâmico</li><li>1 dente de alho picado ou alho em pó</li><li><b>Opcional:</b> gengibre ralado, páprica ou pimenta a gosto</li></ul><p><b>Para a Salada Verde:</b></p><ul><li>150g de folhas verdes variadas (alface, rúcula, espinafres, canónigos)</li><li>50g de tomate cherry cortado ao meio</li><li><b>Opcional:</b> 1/4 de abacate fatiado, cenoura ralada ou sementes de abóbora/girassol</li></ul><p><b>Para o Molho da Salada:</b></p><ul><li>2 colheres de sopa de azeite</li><li>1 colher de chá de sumo de limão ou vinagre</li><li>Sal e pimenta a gosto</li><li><b>Opcional:</b> 1 colher de chá de mostarda (ver ou Dijon)</li></ul><h3>Preparação</h3><p><b>Preparar o Tofu:</b> Embrulhe o bloco de tofu em papel de cozinha e coloque um peso por cima durante 10-15 minutos para retirar o excesso de água. Corte em fatias ou cubos médios.</p><p><b>Marinar:</b> Numa tigela, misture o shoyu, o azeite, o limão e os temperos escolhidos (alho, gengibre, etc.). Envolva o tofu nesta mistura e deixe repousar pelo menos 15 a 30 minutos.</p><p><b>Grelhar:</b> Aqueça bem uma grelha ou frigideira antiaderente. Pincele com um pouco de azeite e coloque as fatias de tofu. Grelhe cerca de 2 a 3 minutos de cada lado, ou até formar uma crosta dourada e crocante.</p><p><b>Montar a Salada:</b> Numa saladeira, coloque as folhas verdes, o tomate cherry e os outros vegetais ou sementes que preferir.</p><p><b>Temperar e Servir:</b> Num pequeno frasco, agite os ingredientes do molho (azeite, limão, sal, pimenta e mostarda) até emulsificar. Regue a salada com este molho, envolva e disponha o tofu grelhado quente por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_CAPRESE + "', '<h3>Ingredientes da Salada Caprese</h3><ul><li><b>Tomates:</b> 3 a 4 tomates maduros, grandes e suculentos (tipo coração de boi ou cacho)</li><li><b>Queijo:</b> 1 a 2 bolas de queijo mozzarella fresco ou mozzarella de búfala (aprox. 250g a 400g)</li><li><b>Manjericão:</b> 1 ramo de folhas de manjericão fresco</li><li><b>Tempero:</b> Azeite virgem extra, flor de sal e pimenta-preta moída a gosto</li><li><b>Opcional:</b> Vinagre balsâmico de Modena (para regar no momento de servir)</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Lave bem os tomates e as folhas de manjericão. Seque tudo cuidadosamente.</p><p><b>Cortar:</b> Corte os tomates e a bola de mozzarella em rodelas com uma espessura semelhante (cerca de 0,5 a 1 cm).</p><p><b>Montar a travessa:</b> Numa travessa larga ou prato de servir, intercale as rodelas de tomate e de mozzarella. Coloque uma folha de manjericão fresco entre cada fatia de tomate e queijo.</p><p><b>Temperar:</b> Tempere o preparado com flor de sal e pimenta-preta moída na hora.</p><p><b>Finalizar:</b> Regue generosamente com azeite virgem extra. Se desejar um toque agridoce, finalize com um fio de vinagre balsâmico. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_CENOURA_GENGIBRE + "', '<h3>Ingredientes (4 pessoas)</h3><ul><li><b>Cenoura:</b> 1 kg, descascada e cortada em rodelas</li><li><b>Gengibre:</b> 1 colher de sopa de gengibre fresco ralado (a gosto)</li><li><b>Cebola:</b> 1 a 2 unidades médias, picadas</li><li><b>Alho:</b> 1 a 2 dentes (opcional)</li><li><b>Azeite:</b> 3 a 4 colheres de sopa</li><li><b>Água ou Caldo de Legumes:</b> cerca de 1 litro</li><li><b>Sal e Pimenta:</b> a gosto</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Numa panela grande, coloque o azeite, a cebola picada e o alho. Deixe refogar até a cebola ficar translúcida.</p><p><b>Aromatizar:</b> Adicione o gengibre ralado e as cenouras às rodelas. Deixe estufar por cerca de 2 a 3 minutos para libertar os aromas.</p><p><b>Cozer:</b> Adicione a água (ou caldo) até cobrir os legumes. Tape e deixe cozinhar em lume médio-baixo por 20 a 25 minutos, ou até que a cenoura fique bem macia.</p><p><b>Triturar:</b> Retire do lume e use uma varinha mágica para triturar tudo até obter um creme liso e homogéneo. Se o creme estiver muito grosso, adicione mais um pouco de água até atingir a consistência desejada.</p><p><b>Temperar e Servir:</b> Retifique o sal e a pimenta. Sirva quente com um fio de azeite e, se gostar, decore com salsa ou cebolinho picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_COGUMELOS_SALTEADOS + "', '<h3>Ingredientes</h3><ul><li>500g de cogumelos frescos (variedade à escolha: Paris, Portobello, Shitake, Shimeji)</li><li>2 a 3 colheres de sopa de azeite extra virgem</li><li>2 dentes de alho esmagados ou picados</li><li>Ervas aromáticas frescas a gosto (salsa, tomilho e orégãos são uma excelente combinação)</li><li>Sumo de meio limão (opcional, para refrescar)</li><li>Sal e pimenta preta moída na hora a gosto</li></ul><h3>Preparação</h3><p><b>Limpar os cogumelos:</b> Limpe os cogumelos com um pano húmido ou uma escova própria para retirar eventuais vestígios de terra. Evite lavá-los diretamente em água, pois absorvem humidade e perdem a textura estaladiça. Corte-os em fatias ou quartos.</p><p><b>Aquecer a frigideira:</b> Leve uma frigideira grande ou wok ao lume alto.</p><p><b>Selar os cogumelos:</b> Adicione os cogumelos à frigideira bem quente e deixe-os saltear sem adicionar azeite nos primeiros minutos. Isto ajuda a evaporar o excesso de água.</p><p><b>Adicionar os sabores:</b> Quando começarem a dourar, reduza ligeiramente o lume e adicione o azeite. Junte o alho picado e metade das ervas aromáticas. Tempere com sal e pimenta.</p><p><b>Finalizar:</b> Mexa bem e deixe saltear por mais 2 a 3 minutos até estarem macios. Retire do lume, adicione o sumo de limão (se desejar) e envolva o restante das ervas frescas. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_FEIJAO_VERDE + "', '<h3>Ingredientes (para 4 a 6 doses)</h3><p><b>Para a base (creme):</b></p><ul><li>1 frasco ou lata de feijão manteiga (cerca de 500g já cozido) ou feijão encarnado</li><li>2 batatas médias</li><li>1 cenoura grande</li><li>1 cebola média</li><li>2 dentes de alho</li><li>1 nabo ou um pedaço de abóbora (para dar mais volume e textura)</li></ul><p><b>Para enriquecer a sopa:</b></p><ul><li>200g a 300g de feijão verde lavado e cortado em juliana (fino) ou rodelas muito pequenas</li><li>3 a 4 mãos cheias de massinha (ex: cotovelos, pevide ou estrelinhas)</li><li>1 colher de sopa de azeite (por dose)</li><li>Sal a gosto</li><li>Água q.b.</li></ul><h3>Preparação passo a passo</h3><p><b>Preparar os legumes:</b> Descasque a cebola, os alhos, as batatas, a cenoura e o nabo/abóbora. Corte todos estes legumes em pedaços médios.</p><p><b>Cozer a base:</b> Coloque todos os legumes cortados num tacho grande. Adicione o feijão cozido (com alguma da sua água ou caldo, caso o use) e cubra com água a ferver, temperando com uma pitada de sal. Deixe cozinhar em lume médio durante cerca de 15 a 20 minutos, até os legumes estarem bem macios.</p><p><b>Triturar:</b> Retire o tacho do lume e passe a mistura com a varinha mágica ou liquidificador até obter um creme liso e aveludado.</p><p><b>Adicionar o feijão verde e a massa:</b> Volte a colocar o tacho em lume brando. Se o creme estiver muito espesso, adicione um pouco mais de água a ferver. Junte a massinha e o feijão verde cortado.</p><p><b>Cozinhar tudo:</b> Deixe levantar fervura e mexa ocasionalmente para a massa não colar ao fundo do tacho. Deixe cozinhar durante cerca de 8 a 10 minutos (verifique o tempo de cozedura indicado na embalagem da massa).</p><p><b>Finalizar:</b> Quando a massa e o feijão verde estiverem cozidos (o feijão verde deve mudar de cor mas manter-se ligeiramente crocante), retifique o sal se necessário. Desligue o lume, adicione o azeite em fio e envolva tudo.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_BROCOLOS_QUEIJO + "', '<h3>Ingredientes</h3><ul><li>1 maço grande de brócolos (cortado em raminhos)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 batata média (em cubos, para dar textura)</li><li>50 g de manteiga ou 2 colheres de sopa de azeite</li><li>700 ml de caldo de legumes (ou água)</li><li>150 g a 200 g de queijo ralado (Cheddar, Emmental ou Gruyère)</li><li>100 ml de natas (creme de leite) ou leite (opcional para maior cremosidade)</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho grande, derreta a manteiga (ou aqueça o azeite) e refogue a cebola e o alho até dourarem ligeiramente.</p><p><b>Cozer os legumes:</b> Adicione a batata, os brócolos e o caldo de legumes. Tempere com sal e pimenta. Deixe cozinhar em lume brando por cerca de 15 a 20 minutos, ou até que a batata e os brócolos estejam bem macios.</p><p><b>Triturar:</b> Retire do lume e triture tudo com a varinha mágica até obter um creme liso e aveludado.</p><p><b>Adicionar o queijo:</b> Volte a colocar em lume brando e adicione o queijo ralado e as natas/leite. Mexa continuamente até o queijo derreter por completo e o creme ficar homogéneo. Não deixe ferver após colocar o queijo.</p><p><b>Servir:</b> Retifique os temperos e sirva quente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_RUSSA_VEG + "', '<h3>Ingredientes Base</h3><ul><li>4 batatas médias</li><li>2 cenouras grandes</li><li>1 chávena de ervilhas (pode ser congeladas)</li><li>1 chávena de feijão-verde cortado (pode ser congelado)</li><li>1/2 cebola picada finamente (opcional, para dar um toque estaladiço)</li><li>Maionese a gosto (pode optar por maionese tradicional, maionese vegetal à base de soja, ou uma alternativa mais leve como maionese de iogurte/abacate)</li><li>Sal e pimenta preta a gosto</li><li>Salsa fresca picada (para aromatizar e decorar)</li></ul><h3>Preparação</h3><p><b>Preparação dos vegetais:</b> Lave, descasque e corte as batatas e as cenouras em cubos pequenos e uniformes. Prepare também o feijão-verde em pequenos segmentos.</p><p><b>Cozedura:</b> Numa panela com água a ferver temperada com sal, coloque as batatas e as cenouras. A meio da cozedura (cerca de 10 minutos depois), adicione as ervilhas e o feijão-verde para não passarem do ponto.</p><p><b>Arrefecimento:</b> Quando todos os vegetais estiverem tenros mas firmes, retire do lume, escorra muito bem a água e deixe arrefecer completamente.</p><p><b>Mistura:</b> Numa taça grande, envolva os vegetais cozidos e frios. Adicione a cebola e a salsa picadas.</p><p><b>Tempero:</b> Adicione a maionese escolhida, tempere com pimenta preta e verifique o sal. Envolva tudo com cuidado para não desfazer as batatas.</p><p><b>Refrigeração:</b> Leve ao frigorífico durante pelo menos 1 hora para servir bem fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_LEGUMES_EPOCA + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li>1 courgete grande</li><li>2 cenouras médias</li><li>1 nabo</li><li>1 cebola</li><li>1 alho francês (apenas a parte branca e verde clara)</li><li>2 dentes de alho</li><li>1 molho de espinafres frescos</li><li>1 chávena de ervilhas frescas ou congeladas</li><li>Azeite virgem extra e sal a gosto</li><li>Água q.b.</li></ul><h3>Preparação</h3><p><b>Preparação dos vegetais:</b> Lave, descasque e corte todos os legumes (courgete, cenouras, nabo, cebola e alho francês) em pedaços pequenos e regulares. Descasque o alho.</p><p><b>Refogado base:</b> Numa panela, coloque a cebola, o alho francês e os alhos. Adicione um fio de azeite e deixe alourar levemente.</p><p><b>Cozedura:</b> Adicione a courgete, as cenouras e o nabo. Cubra com água (cerca de 1 a 1,5 litros, dependendo da consistência desejada) e tempere com uma pitada de sal. Deixe cozer em lume médio durante cerca de 20 a 25 minutos.</p><p><b>Triturar:</b> Quando os legumes estiverem tenros, retire do lume e passe com a varinha mágica até obter um creme aveludado e sem pedaços.</p><p><b>Adição dos verdes:</b> Leve a panela novamente ao lume. Junte as ervilhas e os espinafres bem lavados. Deixe cozer durante 5 a 8 minutos, para que os verdes mantenham a cor e os nutrientes.</p><p><b>Finalização:</b> Retifique o sal e adicione um fio de azeite cru antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_OMELETE_ESPINAFRES + "', '<h3>Ingredientes</h3><p><b>Para a Omelete:</b></p><ul><li>3 ovos</li><li>1 a 2 mãos-cheias de folhas de espinafre (frescas ou baby)</li><li>1 dente de alho picado</li><li>1 colher de sopa de azeite</li><li>Sal e pimenta preta a gosto</li><li><b>Opcional:</b> Queijo mozarela ralado ou queijo cottage</li></ul><p><b>Para a Salada:</b></p><ul><li>Alface fresca e lavada (ou folhas verdes variadas)</li><li>Tomate cereja cortado ao meio</li><li>1/4 de cebola roxa cortada em meias-luas finas</li><li><b>Temperos:</b> Azeite, vinagre (ou sumo de limão) e sal a gosto</li></ul><h3>Preparação e Confecção</h3><p><b>1. Preparar a Salada:</b> Misture todos os ingredientes da salada numa taça grande. Tempere apenas na hora de servir para manter as folhas frescas e estaladiças.</p><p><b>2. Saltear os Espinafres:</b> Numa frigideira antiaderente, aqueça o azeite em lume médio e junte o alho picado, deixando alourar ligeiramente. Adicione as folhas de espinafre e tempere com uma pitada de sal. Mexa até as folhas murcharem (cerca de 2 a 3 minutos).</p><p><b>3. Bater os Ovos:</b> Enquanto os espinafres salteiam, bata os ovos numa tigela com uma pitada de sal e pimenta.</p><p><b>4. Cozinhar a Omelete:</b> Verta os ovos batidos por cima dos espinafres na frigideira, espalhando uniformemente. Se optar por adicionar queijo, polvilhe-o por cima nesta fase. Deixe cozinhar em lume brando até as bordas começarem a firmar. Com a ajuda de uma espátula, dobre a omelete ao meio e deixe dourar durante mais 1 minuto.</p><p><b>5. Servir:</b> Retire a omelete da frigideira, transfira-a para um prato e sirva de imediato acompanhada pela salada fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ABOBORA_SEMENTES + "', '<h3>Ingredientes</h3><ul><li>800 g de abóbora descascada e cortada em cubos</li><li>2 cenouras médias</li><li>2 cebolas médias</li><li>2 dentes de alho</li><li>1 litro de caldo de legumes (ou água)</li><li>3 colheres de sopa de azeite</li><li>4 colheres de sopa de sementes de abóbora</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Preparar as sementes:</b> Se retirar as sementes diretamente da abóbora, lave-as bem para remover os fiapos e seque-as com um pano. Toste-as numa frigideira em lume médio com um pouco de sal e algumas gotas de azeite até ficarem estaladiças. Reserve.</p><p><b>Refogar:</b> Num tacho grande, aqueça as 3 colheres de sopa de azeite. Junte as cebolas e os alhos picados e deixe alourar.</p><p><b>Cozinhar os legumes:</b> Adicione a abóbora e as cenouras cortadas. Mexa e deixe envolver por 2 a 3 minutos.</p><p><b>Ferver:</b> Vaze o caldo de legumes (ou água) até tapar os vegetais. Tempere com sal e pimenta, tape o tacho e deixe cozinhar em lume brando durante cerca de 25 minutos, até todos os legumes estarem bem macios.</p><p><b>Triturar:</b> Retire do lume e use a varinha mágica para triturar tudo até obter um creme aveludado e homogéneo.</p><p><b>Servir:</b> Rectifique os temperos se necessário. Divida o creme por pratos ou taças e guarneça com as sementes de abóbora tostadas por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_GASPACHO_MORANGO + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Tomates maduros:</b> 500 g (tipo coração-de-boi ou chucha)</li><li><b>Morangos frescos:</b> 250 g a 300 g</li><li><b>Pepino:</b> 1/2 unidade (sem casca e sem sementes)</li><li><b>Cebola ou chalota:</b> 1/2 unidade</li><li><b>Alho:</b> 1 dente</li><li><b>Azeite virgem extra:</b> 4 colheres de sopa</li><li><b>Vinagre (de sidra ou de Jerez):</b> 1 a 2 colheres de sopa</li><li><b>Água gelada:</b> 100 ml (a ajustar conforme a consistência desejada)</li><li><b>Sal e pimenta:</b> q.b.</li><li><b>Opcional (toque clássico):</b> 1/4 de pimento vermelho</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Lave bem o tomate, os morangos e o pepino. Retire os pés aos morangos e corte-os em pedaços. Descasque o pepino e retire as sementes.</p><p><b>Triturar:</b> Coloque todos os ingredientes (tomates, morangos, pepino, cebola, alho) numa liquidificadora ou com a ajuda de uma varinha mágica. Adicione o azeite, o vinagre e tempere com sal e pimenta.</p><p><b>Emulsionar:</b> Triture tudo muito bem até obter uma mistura homogénea e cremosa. Se ficar muito espesso, adicione a água gelada aos poucos até atingir a consistência ideal.</p><p><b>Gelar e servir:</b> Prove e rectifique os temperos. Leve ao frigorífico durante pelo menos 1 hora para servir bem fresco. Sirva decorado com pequenos cubos de morango e pepino, e algumas folhas de manjericão ou hortelã.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_LENTILHAS_VERMELHAS + "', '<h3>Ingredientes base</h3><ul><li>1 chávena de lentilhas vermelhas (previamente lavadas)</li><li>1 cebola picada</li><li>2 dentes de alho picados</li><li>1 pedaço pequeno de gengibre fresco ralado</li><li>2 cenouras médias cortadas em cubos</li><li>1 colher de sopa de azeite</li><li>1 litro de água ou caldo de legumes</li><li>Sal, pimenta e cominhos em pó a gosto</li><li>Sumo de 1/2 limão (opcional, para dar frescura)</li></ul><h3>Preparação passo a passo</h3><p><b>Refogado:</b> Aqueça o azeite numa panela grande e adicione a cebola, o alho e o gengibre. Deixe alourar até começarem a soltar aroma.</p><p><b>Adicionar vegetais e lentilhas:</b> Junte as cenouras e as lentilhas vermelhas lavadas. Envolva tudo durante cerca de 1 minuto.</p><p><b>Cozer:</b> Adicione a água ou o caldo de legumes e tempere com sal, pimenta e uma pitada de cominhos. Deixe levantar fervura, tape a panela e reduza para lume brando.</p><p><b>Finalizar:</b> Deixe cozinhar durante cerca de 20 a 25 minutos, ou até que as lentilhas e as cenouras estejam bem macias.</p><p><b>Triturar:</b> Retire do lume e use a varinha mágica para triturar até obter um creme liso e homogéneo. Caso goste da sopa mais líquida, adicione um pouco mais de água quente.</p><p><b>Toque final:</b> Antes de servir, pode espremer umas gotas de sumo de limão e polvilhar com coentros ou salsa fresca picada.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_GREGA_PEPINO + "', '<h3>Ingredientes</h3><p>Para preparar uma autêntica salada grega, vai precisar dos seguintes produtos frescos:</p><ul><li><b>Tomates:</b> 4 tomates maduros, cortados em pedaços médios.</li><li><b>Pepino:</b> 1 pepino (tipo holandês ou 2 pepinos pequenos), cortado em meias-luas ou cubos.</li><li><b>Cebola Roxa:</b> 1/2 cebola roxa cortada em meias-luas finas.</li><li><b>Pimento:</b> 1 pimento verde ou amarelo, em cubos.</li><li><b>Azeitonas:</b> Cerca de 100 g a 150 g de azeitonas pretas (as azeitonas Kalamata são ideais).</li><li><b>Queijo Feta:</b> 1 bloco (cerca de 150 g a 200 g) de queijo feta.</li><li><b>Tempero:</b> Azeite virgem extra, vinagre de vinho tinto, orégãos secos e sal marinho a gosto.</li></ul><h3>Preparação</h3><p>A simplicidade é o segredo desta salada, valorizando a qualidade e frescura dos ingredientes. Siga estes passos:</p><p><b>Preparar os vegetais:</b> Lave bem todos os vegetais. Corte os tomates, o pepino e o pimento. Fatie a cebola roxa finamente.</p><p><b>Misturar na saladeira:</b> Coloque todos os vegetais preparados numa saladeira grande.</p><p><b>Adicionar azeitonas:</b> Junte as azeitonas pretas, garantindo que estão sem caroço ou inteiras conforme preferir.</p><p><b>Dispor o queijo:</b> Coloque o queijo feta por cima dos vegetais. Pode cortá-lo em cubos ou, seguindo a tradição grega (Horiatiki), colocá-lo em bloco inteiro por cima da salada, para que cada pessoa o despedace no seu prato.</p><p><b>Temperar e servir:</b> Tempere com uma pitada de sal marinho, generosamente com azeite virgem extra e um pouco de vinagre de vinho tinto. Polvilhe com uma quantidade abundante de orégãos secos.</p><p><b>Envolver:</b> Envolva tudo delicadamente (se o feta não estiver em bloco inteiro) e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_COUVE_FLOR + "', '<h3>Ingredientes</h3><ul><li>1 cabeça média de couve-flor</li><li>2 batatas médias ou 1 curgete (para dar textura)</li><li>1/2 cebola picada</li><li>2 dentes de alho</li><li>1 fio de azeite (ou manteiga)</li><li>Água ou caldo de legumes q.b. (o suficiente para cobrir os vegetais)</li><li>Sal e pimenta a gosto</li><li><b>Opcional:</b> 100 ml de natas ou bebida vegetal para maior cremosidade</li></ul><h3>Preparação</h3><p><b>Preparar os legumes:</b> Lave e corte a couve-flor em floretes. Descasque e corte as batatas (ou curgete) em cubos.</p><p><b>Refogar:</b> Numa panela, aqueça o azeite (ou a manteiga) e refogue a cebola e o alho até dourarem ligeiramente.</p><p><b>Cozinhar:</b> Adicione a couve-flor e a batata. Junte o caldo de legumes até cobrir tudo. Deixe ferver e, em seguida, reduza o lume, deixando cozinhar cerca de 15 a 20 minutos, até os vegetais estarem bem macios.</p><p><b>Triturar:</b> Retire do lume e use uma varinha mágica para triturar tudo até obter um creme liso e aveludado.</p><p><b>Finalizar:</b> Tempere com sal, pimenta e, se desejar, adicione as natas para um toque extra de cremosidade. Deixe ferver mais 2 minutos e sirva quente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_LIMAO + "', '<h3>Ingredientes</h3><p>Para preparar esta receita (serve cerca de 2 a 3 pessoas), vai precisar dos seguintes ingredientes:</p><p><b>Para o Tofu:</b></p><ul><li>1 bloco de tofu firme (aprox. 400g a 500g)</li><li><b>Opcional:</b> 1 a 2 colheres de sopa de amido de milho (para uma textura mais crocante)</li></ul><p><b>Para a Marinada e Molho:</b></p><ul><li>Sumo e raspa de 1 limão grande</li><li>2 a 3 colheres de sopa de molho de soja (ou molho tamari)</li><li>1 a 2 colheres de sopa de azeite virgem extra ou óleo de sésamo</li><li>1 dente de alho picado</li><li><b>Opcional:</b> 1/2 colher de chá de gengibre fresco ralado (dá um toque extra)</li><li><b>Opcional:</b> 1 colher de chá de xarope de agave ou xarope de ácer (para equilibrar a acidez)</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Escorra o líquido do pacote de tofu e pressione-o com um pano de cozinha limpo ou papel absorvente para retirar o excesso de água. Corte-o em cubos ou fatias.</p><p><b>Fazer a marinada:</b> Numa tigela, misture o sumo e a raspa de limão, o molho de soja, o azeite, o alho picado, o gengibre e o adoçante (se usar).</p><p><b>Marinar:</b> Coloque os pedaços de tofu numa taça ou num saco hermético, despeje a marinada por cima e envolva bem. Deixe repousar durante pelo menos 15 a 30 minutos (quanto mais tempo ficar, mais intenso será o sabor).</p><p><b>Adicionar a textura:</b> Retire o tofu da marinada (guarde o líquido que sobrar) e envolva os pedaços levemente em amido de milho.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente com um fio de azeite em lume médio. Coloque o tofu e deixe cozinhar durante 3 a 4 minutos de cada lado, até ficar dourado e crocante.</p><p><b>Finalizar com o molho:</b> Verta o resto da marinada que guardou diretamente por cima do tofu na frigideira. Deixe ferver e envolva durante 1 a 2 minutos, até o molho engrossar ligeiramente e cobrir todo o tofu.</p><p><b>Servir:</b> Retire do lume e polvilhe com sementes de sésamo ou cebolinho fresco picado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_GRAO_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>1 frasco ou 500 g de grão-de-bico cozido</li><li>1 chávena de espinafres (de preferência baby)</li><li>1 alho-francês (a parte branca)</li><li>1 cebola média</li><li>1 dente de alho</li><li>200 g de abóbora</li><li>1 curgete</li><li>1 batata média (para dar textura cremosa)</li><li>Azeite, sal e água q.b.</li></ul><h3>Preparação</h3><p><b>Preparar o refogado:</b> Numa panela, coloque um fio de azeite e leve ao lume para refogar a cebola picada e o alho-francês cortado em rodelas.</p><p><b>Cozer os legumes:</b> Adicione o dente de alho picado, a abóbora, a curgete e a batata, tudo cortado em pedaços. Junte cerca de metade ou dois terços do grão-de-bico cozido reservado.</p><p><b>Adicionar água:</b> Cubra tudo com água (ou caldo de cozer o grão) e tempere com uma pitada de sal. Deixe cozinhar em lume médio durante cerca de 20 a 25 minutos, até os legumes estarem macios.</p><p><b>Triturar:</b> Retire do lume e triture tudo com a varinha mágica até obter um creme aveludado e homogéneo.</p><p><b>Adicionar os espinafres:</b> Leve novamente ao lume, junte os espinafres frescos e o restante grão-de-bico inteiro. Deixe ferver durante 3 a 5 minutos, apenas o suficiente para os espinafres murcharem, e desligue.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_RUCULA_PERA + "', '<h3>Ingredientes</h3><p>Para 4 pessoas:</p><ul><li>1 a 2 peras maduras mas firmes (ex: Pera Rocha)</li><li>1 maço ou embalagem de rúcula (aprox. 120 g)</li><li>50 g de miolo de noz</li><li>Queijo (parmesão em lascas, gorgonzola ou queijo azul) a gosto</li></ul><p><b>Para o molho (vinagrete):</b></p><ul><li>3 colheres de sopa de azeite extra virgem</li><li>1 colher de sopa de vinagre balsâmico</li><li><b>Opcional:</b> 1 colher de chá de mel</li><li>Sal e pimenta-do-reino a gosto</li></ul><h3>Preparação</h3><p><b>Prepare as folhas:</b> Lave muito bem a rúcula e seque-a (pode usar uma centrífuga para salada) para que o molho adira melhor. Coloque numa saladeira grande.</p><p><b>Prepare a pera:</b> Lave as peras, corte-as em fatias finas ou cubos (pode retirar ou manter a casca, conforme a sua preferência) e adicione à rúcula.</p><p><b>Adicione as nozes e o queijo:</b> Pique as nozes grosseiramente com as mãos ou uma faca e junte à salada. Adicione o queijo da sua eleição (lascas de parmesão ou pedaços de gorgonzola).</p><p><b>Faça o molho e tempere:</b> Numa pequena taça, misture o azeite, o vinagre balsâmico e o mel até emulsificar. Tempere com sal e pimenta.</p><p><b>Finalize:</b> Regue a salada com o molho apenas no momento de servir para manter a rúcula estaladiça.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ERVILHAS + "', '<h3>Ingredientes</h3><ul><li>500g de ervilhas (pode usar congeladas)</li><li>1 ou 2 batatas médias (para dar textura cremosa)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 pedaço de alho-francês (aprox. 150g) fatiado</li><li>Azeite q.b.</li><li>Sal e pimenta a gosto</li><li>Água quente ou caldo de legumes q.b. (o suficiente para cobrir os legumes)</li><li><b>Opcional:</b> 2 a 3 folhas de hortelã ou coentros (para um toque fresco)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho largo, coloque um fio de azeite e adicione a cebola, o alho e o alho-francês. Deixe refogar em lume brando até começarem a ficar macios e transparentes.</p><p><b>Cozedura:</b> Descasque a batata, corte-a em cubos pequenos e adicione ao tacho. Junte também as ervilhas.</p><p><b>Adicionar líquidos:</b> Cubra tudo com água quente ou caldo de legumes. Tempere com sal e uma pitada de pimenta. Tape o tacho e deixe cozinhar em lume médio durante cerca de 15 a 20 minutos, ou até que a batata e as ervilhas estejam bem macias.</p><p><b>Triturar:</b> Retire o tacho do lume e adicione as folhas de hortelã ou coentros. Com a ajuda de uma varinha mágica, triture tudo muito bem até obter um creme liso e homogéneo.</p><p><b>Ajustar e Servir:</b> Se o creme estiver muito espesso, adicione um pouco mais de água ou caldo até atingir a consistência desejada. Prove, rectifique os temperos se necessário e sirva quente. Pode finalizar com um fio de azeite cru por cima ou croutons.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_OVOS_TOMATE_SHAKSHUKA + "', '<h3>Ingredientes</h3><ul><li>4 a 6 ovos</li><li>1 lata de tomate pelado ou tomate em pedaços (aprox. 400g)</li><li>1 pimentão vermelho cortado em cubos</li><li>1 cebola média picada</li><li>2 a 3 dentes de alho picados</li><li>1 colher de sopa de azeite</li><li>1 colher de chá de páprica (doce ou picante)</li><li>½ colher de chá de cominho em pó</li><li>Sal e pimenta preta a gosto</li><li>Salsa ou coentros frescos picados (para guarnecer)</li></ul><h3>Preparação</h3><p><b>Refogado base:</b> Numa frigideira grande, aqueça o azeite em lume médio. Adicione a cebola e o pimentão e deixe cozinhar até amolecerem (cerca de 5 minutos).</p><p><b>Aromáticos:</b> Junte o alho picado, a páprica e o cominho. Mexa durante 1 minuto para libertar o aroma.</p><p><b>Molho de tomate:</b> Adicione o tomate pelado à frigideira. Tempere com sal e pimenta. Reduza o lume e deixe o preparado apurar durante 10 a 15 minutos, mexendo ocasionalmente, até o molho engrossar.</p><p><b>Escalfar os ovos:</b> Com uma colher, abra pequenas \"covas\" no molho. Parta cada ovo com cuidado e coloque-o diretamente dentro de cada cavidade.</p><p><b>Cozinhar:</b> Tape a frigideira e deixe em lume brando durante 5 a 8 minutos, ou até que as claras fiquem firmes e as gemas mantenham a consistência desejada.</p><p><b>Finalização:</b> Retire do lume, polvilhe com salsa ou coentros picados e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_MINESTRONE_LEVE + "', '<h3>Ingredientes</h3><p>Para preparar a sua versão leve de Minestrone, precisará de:</p><ul><li>1 cebola picada</li><li>2 dentes de alho picados</li><li>1 colher de sopa de azeite</li><li>1 cenoura média, cortada em cubos</li><li>1 curgete (abobrinha) média, cortada em cubos</li><li>1 talo de aipo (salsão) cortado em rodelas</li><li>1 chávena de feijão branco ou vermelho (já cozido)</li><li>1 chávena de tomate pelado ou em pedaços (natural ou de lata)</li><li>1 folha de louro</li><li>1 litro de água ou caldo de legumes natural</li><li>Sal, pimenta preta e oregãos a gosto</li><li>1 mão cheia de espinafres ou couve cortada em juliana fina</li></ul><h3>Preparação</h3><p>O processo foca-se na extração de sabores sem sobrecarregar a sopa:</p><p><b>Refogado:</b> Num tacho largo, aqueça o azeite e adicione a cebola e o alho. Deixe alourar até a cebola amolecer.</p><p><b>Aromáticos:</b> Junte a folha de louro, o aipo e a cenoura. Envolva bem e deixe saltear durante cerca de 3 a 4 minutos.</p><p><b>Caldo e Tomate:</b> Adicione o tomate picado e a água (ou caldo de legumes). Tempere com sal, pimenta e uma pitada de oregãos. Deixe levantar fervura, tape e reduza para lume brando durante 15 minutos.</p><p><b>Legumes tenros:</b> Acrescente a curgete e o feijão. Deixe cozinhar por mais 7 a 8 minutos.</p><p><b>Finalização leve:</b> Por fim, adicione os espinafres ou a couve. Deixe ferver por mais 2 a 3 minutos até murcharem. Retire a folha de louro, rectifique os temperos e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_BETERRABA_LARANJA + "', '<h3>Ingredientes</h3><ul><li>2 a 3 beterrabas (cozidas ou assadas)</li><li>2 laranjas grandes</li><li>1 mão cheia de espinafres frescos ou mistura de folhas verdes</li><li>50 g de queijo feta (ou queijo de cabra/mozzarela)</li><li>1 punhado de nozes ou avelãs picadas</li><li><b>Opcional:</b> 1 colher de sopa de sementes de sésamo</li></ul><h3>Molho</h3><ul><li>3 colheres de sopa de azeite extra virgem</li><li>1 colher de sopa de vinagre balsâmico (ou sumo de limão)</li><li><b>Opcional:</b> 1 colher de chá de mostarda</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Descasque as laranjas retirando toda a pele branca e corte-as em gomos ou rodelas. Corte as beterrabas já cozidas em cubos, quartos ou rodelas.</p><p><b>Montar a salada:</b> Numa saladeira, faça uma cama com os espinafres. Por cima, disponha os pedaços de beterraba e os gomos de laranja.</p><p><b>Adicionar os extras:</b> Espalhe o queijo esfarelado ou em cubos e as nozes picadas.</p><p><b>Fazer o molho:</b> Numa taça pequena, misture o azeite, o vinagre, a mostarda, o sal e a pimenta até emulsionar (ficar cremoso).</p><p><b>Finalizar:</b> Regue a salada com o molho mesmo antes de servir e polvilhe com as sementes de sésamo.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_COURGETTE_MANJERICO + "', '<h3>Ingredientes</h3><ul><li>3 a 4 curgetes médias (cerca de 800g), cortadas em cubos</li><li>1 cebola média picada</li><li>2 dentes de alho</li><li>1 fio de azeite</li><li>Água ou caldo de legumes (o suficiente para cobrir os legumes)</li><li>Sal e pimenta preta a gosto</li><li>8 a 10 folhas de manjericão fresco</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, coloque o fio de azeite e leve ao lume. Adicione a cebola e os dentes de alho picados, deixando refogar até a cebola ficar transparente.</p><p><b>Cozedura:</b> Junte as curgetes cortadas e deixe saltear durante cerca de 3 a 5 minutos. Adicione a água ou o caldo até cobrir os legumes. Tempere com sal a gosto. Tape e deixe cozinhar em lume médio por aproximadamente 10 a 15 minutos, ou até a curgete estar macia.</p><p><b>Triturar:</b> Retire o tacho do lume, adicione as folhas de manjericão fresco e triture tudo com a ajuda de uma varinha mágica até obter um creme aveludado e sem grumos.</p><p><b>Finalização:</b> Prove o creme e rectifique o sal e a pimenta caso seja necessário. Se preferir uma textura mais cremosa, pode adicionar um pouco de natas ou queijo parmesão ralado. Sirva quente ou morno.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PORTOBELLO_GRELHADO + "', '<h3>Ingredientes</h3><ul><li>4 Cogumelos Portobello médios a grandes</li><li>2 colheres de sopa de azeite extra virgem</li><li>2 dentes de alho picados (ou alho em pó)</li><li>Sal e pimenta-do-reino a gosto</li><li><b>Opcional:</b> 1 colher de sopa de vinagre balsâmico ou molho de soja para marinada</li></ul><h3>Preparação</h3><p><b>Limpeza:</b> Limpe os cogumelos cuidadosamente com um pano ou papel de cozinha húmido. Não os passe por água, pois absorvem humidade e perdem sabor.</p><p><b>Preparação:</b> Retire os pés dos cogumelos (pode guardá-los para outras receitas). Se desejar, raspe suavemente as \"lâminas\" escuras do interior com uma colher para obter um aspeto mais limpo.</p><p><b>Tempero:</b> Numa pequena taça, misture o azeite, o alho, o sal e a pimenta. Pincele generosamente ambos os lados dos cogumelos com esta mistura.</p><p><b>Grelhar:</b> Aqueça uma grelha ou frigideira antiaderente em lume médio-alto. Coloque os cogumelos virados para baixo (com a parte de cima para cima) e deixe grelhar cerca de 4 minutos.</p><p><b>Finalização:</b> Vire os cogumelos e pressione suavemente com uma espátula. Deixe grelhar por mais 3 a 4 minutos até que estejam macios, suculentos e com marcas douradas da grelha.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_TOMATE_ARROZ + "', '<h3>Ingredientes</h3><p>Para 4 doses, vai precisar de:</p><ul><li>4 a 5 tomates maduros grandes (ou 500g de polpa de tomate)</li><li>1 chávena (cerca de 150g) de arroz carolino</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 folha de louro</li><li>0,5 dl azeite</li><li>1 litro de água ou caldo de legumes</li><li>Sal e pimenta q.b.</li><li><b>Opcional:</b> 1 colher de sopa de concentrado de tomate para intensificar a cor</li></ul><h3>Preparação</h3><p><b>Preparar os tomates:</b> Lave os tomates e retire-lhes a pele e as sementes. Corte-os em pedaços pequenos.</p><p><b>Fazer o refogado:</b> Num tacho, coloque o azeite, a cebola picada, o alho e a folha de louro. Deixe alourar em lume brando.</p><p><b>Adicionar o tomate:</b> Acrescente o tomate cortado (e o concentrado, se usar) ao refogado. Tempere com sal e deixe cozinhar até o tomate começar a desfazer-se.</p><p><b>Adicionar o líquido:</b> Verta a água ou o caldo quente no tacho e deixe levantar fervura.</p><p><b>Cozinhar o arroz:</b> Junte o arroz, previamente lavado e escorrido. Reduza o calor, tape o tacho parcialmente e deixe cozinhar em lume brando durante cerca de 10 a 15 minutos, ou até o arroz estar tenro (mas ainda com bastante caldo, se preferir uma consistência \"malandrinha\").</p><p><b>Retificar temperos e servir:</b> Prove e ajuste o sal e a pimenta. Sirva de imediato, polvilhado com coentros ou salsa fresca picada.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_ALFACE_MILHO_ABACATE + "', '<h3>Ingredientes</h3><ul><li>1 pé ou maço de alface (alface romana, alface americana ou mistura)</li><li>1 lata (aprox. 250 g a 285 g) de milho doce escorrido</li><li>1 a 2 abacates maduros (mas firmes)</li><li><b>Opcional:</b> Tomate-cereja, cebola roxa cortada fina, ou coentros para dar cor e sabor</li><li><b>Molho:</b> Sumo de 1/2 limão, 2 colheres de sopa de azeite extra virgem, sal e pimenta a gosto</li></ul><h3>Preparação</h3><p><b>Lave e seque:</b> Lave bem as folhas de alface e rasgue-as para uma saladeira ou travessa.</p><p><b>Prepare o abacate:</b> Descasque o abacate, retire o caroço e corte a polpa em cubos ou fatias médias.</p><p><b>Misture:</b> Junte o milho escorrido e o abacate por cima da alface.</p><p><b>Tempere:</b> Regue imediatamente com o sumo de limão (isto previne que o abacate oxide e escureça). Adicione o azeite, o sal e a pimenta, e envolva tudo suavemente para não desfazer o abacate.</p><p><b>Servir:</b> Sirva de imediato como entrada ou refeição principal.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ESPARGOS_VERDES + "', '<h3>Ingredientes (para 4 doses)</h3><ul><li>1 molho de espargos verdes (cerca de 500 g)</li><li>2 batatas médias (para dar cremosidade)</li><li>1 cebola ou 1 alho-francês</li><li>1 dente de alho</li><li>Azeite q.b.</li><li>Sal e pimenta q.b.</li><li>1 Litro de água ou caldo de legumes</li><li><b>Opcional:</b> 100 ml a 200 ml de natas (ou leite de coco/creme de soja)</li></ul><h3>Preparação</h3><p><b>Preparar os espargos:</b> Lave os espargos. Dobre a base do talo até que ela parta naturalmente e descarte-a (é a parte mais fibrosa). Corte os talos em pedaços pequenos. Se quiser decorar, reserve algumas pontas inteiras e coza-as à parte ou no final.</p><p><b>Refogado:</b> Numa panela, coloque um fio de azeite e adicione a cebola (ou alho-francês) e o alho picados. Deixe alourar em lume brando.</p><p><b>Adicionar os legumes:</b> Junte as batatas descascadas e cortadas em cubos, juntamente com os pedaços de espargos. Envolva bem e deixe cozinhar durante cerca de 5 minutos.</p><p><b>Cozer:</b> Adicione a água ou o caldo de legumes até cobrir tudo. Tempere com sal, tape a panela e deixe ferver em lume médio/brando durante cerca de 20 a 30 minutos, até que a batata e os espargos estejam tenros.</p><p><b>Triturar:</b> Retire a panela do lume e triture tudo com uma varinha mágica até obter um creme liso e aveludado. Se estiver muito espesso, adicione um pouco mais de água a ferver.</p><p><b>Finalizar:</b> Volte a colocar em lume brando, adicione as natas (ou o creme vegetal) e mexa bem. Se reservou as pontas dos espargos, adicione-as agora e deixe ferver durante mais 3 minutos. Retifique o sal e a pimenta.</p><p><b>Servir:</b> Sirva quente com um fio de azeite por cima e croutons ou amêndoas laminadas, se desejar.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_MEXIDO_ERVAS + "', '<h3>Ingredientes (2 a 3 doses)</h3><ul><li>250 g a 300 g de tofu firme</li><li>1 colher de sopa de azeite</li><li>1/2 cebola picada ou 1 dente de alho picado</li><li>1/2 colher de chá de cúrcuma (açafrão-da-terra)</li><li>1/2 colher de chá de alho em pó</li><li>Sal marinho ou Sal negro dos Himalaias (este último dá um toque de sabor a \"ovo\") a gosto</li><li>Pimenta-preta moída na hora a gosto</li><li>Ervas a gosto: salsa fresca, cebolinha, manjericão ou orégãos (secos ou frescos)</li><li><b>Opcional:</b> 1 a 2 colheres de sopa de bebida vegetal (ex: soja ou aveia) ou natas vegetais para dar cremosidade</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Retire o tofu da embalagem, passe por água e seque-o com um pano ou papel de cozinha. Coloque-o numa tigela e esfarele-o grosseiramente com um garfo, imitando a textura de ovos mexidos.</p><p><b>Refogar:</b> Numa frigideira, aqueça o azeite em lume médio. Adicione a cebola e o alho picados e deixe alourar ligeiramente.</p><p><b>Temperar a base:</b> Adicione a curcuma, o alho em pó, sal e pimenta ao refogado. Mexa durante cerca de 1 minuto para libertar o aroma das especiarias.</p><p><b>Cozinhar o tofu:</b> Junte o tofu esfarelado à frigideira. Envolva bem nos temperos até que o tofu fique com uma cor amarela uniforme. Se preferir um tofu mais cremoso, adicione agora uma colher de sopa de bebida vegetal ou natas.</p><p><b>Adicionar as ervas:</b> Salteie em lume médio-baixo durante 5 a 7 minutos, mexendo sempre. No final, retire do lume e envolva as ervas aromáticas picadas escolhidas.</p><p><b>Servir:</b> Sirva imediatamente, idealmente quente e acompanhado com uma fatia de pão tostado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_CEBOLA + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li>Cebola: 1 kg (cerca de 5 a 6 cebolas grandes) cortadas em meias-luas finas</li><li>Manteiga: 50 g</li><li>Azeite: 1 colher de sopa</li><li>Farinha de trigo: 2 colheres de sopa</li><li><b>Opcional:</b> Vinho branco seco: 120 ml (para deglaçar)</li><li>Caldo de carne (ou legumes): 1,5 litros</li><li><b>Opcional:</b> Alho: 2 a 3 dentes picados</li><li>Sal e Pimenta-preta: a gosto</li><li><b>Para servir:</b> Pão (tipo baguete ou rústico) fatiado e Queijo (Gruyère ou Emmental ralado)</li></ul><h3>Preparação</h3><p><b>Dourar a cebola:</b> Numa panela grande, derreta a manteiga com o azeite em lume brando. Adicione as cebolas e o alho. Cozinhe lentamente (cerca de 30 a 40 minutos), mexendo ocasionalmente, até que as cebolas fiquem macias, caramelizadas e com uma cor dourada escura.</p><p><b>Polvilhar e Deglaçar:</b> Polvilhe a cebola com a farinha e mexa durante 2 minutos para cozinhar. Se usar vinho branco, adicione-o agora para soltar os sabores do fundo da panela, deixando o álcool evaporar.</p><p><b>Adicionar o caldo:</b> Verta o caldo de carne, tempere com sal e pimenta e deixe levantar fervura. Reduza o lume, tape a panela parcialmente e deixe cozinhar em lume brando por cerca de 20 minutos.</p><p><b>Gratinar (Opcional):</b> Pré-aqueça o forno na função grill. Distribua a sopa por cumbucas que possam ir ao forno. Coloque fatias de pão por cima da sopa e cubra generosamente com o queijo ralado. Leve ao forno até o queijo derreter e ficar dourado (cerca de 5 a 10 minutos).</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_GRAO_CHERRY + "', '<h3>Ingredientes</h3><ul><li>1 lata de grão-de-bico cozido (aprox. 400 g)</li><li>150 a 200 g de tomate-cereja</li><li>½ cebola roxa ou pequena</li><li>2 colheres de sopa de azeite extra virgem</li><li>Sumo de ½ limão ou 1 colher de sopa de vinagre (balsâmico ou de vinho)</li><li>Sal e pimenta preta moída a gosto</li><li><b>Opcional:</b> Orégãos secos a gosto</li><li><b>Extras sugeridos:</b> Salsa fresca picada, azeitonas sem caroço ou 1 lata de atum escorrido.</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Escorra bem o grão-de-bico e passe-o por água fria. Lave os tomates-cereja e corte-os ao meio. Pique a cebola muito finamente.</p><p><b>Misturar tudo:</b> Numa taça grande, coloque o grão-de-bico, o tomate-cereja, a cebola roxa e os extras (se optar por juntar atum ou azeitonas).</p><p><b>Temperar:</b> Numa pequena taça à parte, misture o azeite, o sumo de limão (ou vinagre), o sal, a pimenta e os orégãos. Verta este molho sobre a salada e envolva tudo suavemente.</p><p><b>Servir:</b> Pode servir de imediato ou deixar repousar no frigorífico durante cerca de 20 minutos para que os sabores se fundam.</p>');");

