// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_ANANAS_COCO + "', '<h3>Ingredientes</h3><ul><li><b>Ananás:</b> 1 chávena (cortado em cubos e congelado)</li><li><b>Banana:</b> 1 unidade (descascada e congelada, para dar textura)</li><li><b>Leite de coco:</b> 1 chávena (pode usar de lata para um resultado mais rico ou de compra para uma versão mais leve)</li><li><b>Opcional:</b> 1 colher de sopa de mel, xarope de ácer ou néctar de coco (como adoçante)</li><li><b>Opcional:</b> Algumas gotas de sumo de limão ou folhas de hortelã (para um toque extra)</li></ul><h3>Preparação</h3><p><b>Coloque os ingredientes no liquidificador:</b> Adicione o ananás, a banana, o leite de coco e o adoçante.</p><p><b>Bater:</b> Triture na velocidade máxima durante cerca de 1 a 2 minutos. Se estiver muito espesso, adicione um pouco de água de coco até atingir a consistência desejada.</p><p><b>Servir:</b> Verta para um copo e beba de imediato. Pode decorar com coco ralado ou uma rodela de ananás.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_MORANGO + "', '<h3>Ingredientes (1 pessoa)</h3><ul><li><b>Aveia:</b> 4 a 5 colheres de sopa de flocos de aveia</li><li><b>Líquido:</b> 200 ml de leite (ou bebida vegetal de amêndoa, aveia ou soja)</li><li><b>Morangos:</b> 4 a 5 morangos frescos médios</li><li><b>Adoçante:</b> 1 colher de chá de mel, xarope de ácer ou xilitol</li><li><b>Opcional:</b> Uma pitada de canela em pó ou sementes de chia (para um toque extra)</li></ul><h3>Preparação</h3><p><b>Aquecer o líquido:</b> Num tacho pequeno, coloque o leite ou bebida vegetal e junte a pitada de canela. Leve a lume médio até começar a aquecer (sem deixar ferver).</p><p><b>Juntar aveia:</b> Adicione os flocos de aveia ao tacho e reduza para lume brando.</p><p><b>Deixar engrossar:</b> Mexa continuamente com uma colher de pau durante cerca de 3 a 5 minutos, até a aveia absorver o líquido e atingir a consistência cremosa desejada.</p><p><b>Adicionar morangos:</b> Retire do lume. Corte a maioria dos morangos em pedaços pequenos e misture na papa ainda quente para libertarem sabor. (Guarde um morango laminado para a decoração).</p><p><b>Adoçar:</b> Incorpore o mel ou adoçante e mexa bem.</p><p><b>Servir:</b> Transfira para uma taça e decore o topo com as fatias de morango reservadas e umas lascas de amêndoa ou coco ralado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_RABANETE + "', '<h3>Ingredientes (Para 2 Pessoas)</h3><ul><li><b>Base:</b> 2 fatias de pão rústico ou integral</li><li><b>Creme de Abacate:</b> 1 abacate maduro (ou avocado)</li><li><b>Toque Fresco:</b> 2 a 3 rabanetes frescos</li><li><b>Tempero:</b> Sumo de 1/2 limão, azeite virgem extra, sal e pimenta-preta a gosto</li><li><b>Opcional:</b> 2 ovos (estrelados ou escalfados) e cebolinho picado</li></ul><h3>Preparação</h3><p><b>Torrar o pão:</b> Leve as fatias de pão à torradeira, forno ou frigideira com um fio de azeite até ficarem douradas e estaladiças.</p><p><b>Preparar o abacate:</b> Corte o abacate ao meio, retire o caroço e colha a polpa para uma tigela. Esmague com um garfo até obter uma pasta cremosa, junte o sumo de limão, um fio de azeite, sal e pimenta.</p><p><b>Preparar os rabanetes:</b> Lave muito bem os rabanetes e corte-os em fatias ou rodelas o mais finas possível.</p><p><b>Montagem:</b> Barre generosamente as fatias de pão torrado com o creme de abacate. Disponha as fatias finas de rabanete por cima.</p><p><b>Finalização:</b> Se desejar adicionar proteína, coloque um ovo estrelado ou escalfado por cima de cada torrada. Tempere com uma pitada extra de sal, pimenta e cebolinho picado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PUDIM_CHIA_ANANAS + "', '<h3>Ingredientes</h3><p>Para preparar um pudim de chia com ananás para cerca de 2 a 4 doses, vai precisar de:</p><ul><li>400 ml de leite de coco ou bebida vegetal (amêndoa, aveia)</li><li>60 a 80 g de sementes de chia</li><li>1 a 2 colheres de sobremesa de xarope de ácer, agave ou mel (a gosto)</li><li><b>Opcional:</b> 1 colher de chá de extrato de baunilha</li><li>200 g de ananás fresco, cortado em cubos pequenos</li><li><b>Opcional:</b> 110 g de iogurte grego natural ou natural ligeiro para maior cremosidade</li><li>Raspa de lima ou folhas de hortelã para decorar</li></ul><h3>Preparação</h3><p><b>Preparar o pudim:</b> Numa taça ou frasco, misture bem o leite de coco (ou a bebida vegetal), o xarope de ácer/agave, o extrato de baunilha e as sementes de chia.</p><p><b>Deixar hidratar:</b> Mexa muito bem para não formar grumos. Deixe repousar durante cerca de 10 a 15 minutos, mexa novamente e leve ao frigorífico pelo menos 4 horas ou, idealmente, durante a noite. A chia vai absorver o líquido e ganhar uma textura de pudim.</p><p><b>Preparar a fruta:</b> Corte o ananás em cubos pequenos. Se preferir um sabor mais caramelizado e rico, pode saltear ligeiramente os cubos de ananás numa frigideira com uma pitada de sal e algumas gotas de limão.</p><p><b>Montagem:</b> Na hora de servir, distribua o pudim de chia por taças ou copos e coloque os cubos de ananás por cima. Pode adicionar iogurte grego em camadas alternadas, caso decida utilizá-lo.</p><p><b>Decoração:</b> Finalize com raspa de lima ou uma folha de hortelã fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_MIRTILO_LIMAO + "', '<h3>Ingredientes</h3><ul><li>225 g a 280 g de farinha de trigo</li><li>250 ml a 460 ml de leite (pode usar bebida vegetal)</li><li>2 ovos</li><li>50 g a 60 g de manteiga derretida (ou óleo de coco)</li><li>1 a 2 colheres de sopa de açúcar (ou xarope de ácer)</li><li>1 colher de chá de fermento em pó</li><li>Raspa e umas gotas do sumo de 1 limão</li><li>1 pitada de sal</li><li>1 chávena (c. 100g a 150g) de mirtilos</li></ul><h3>Preparação</h3><p><b>Mistura dos secos:</b> Numa tigela grande, misture a farinha, o fermento, o açúcar e uma pitada de sal.</p><p><b>Mistura dos líquidos:</b> Noutra taça, bata os ovos com o leite, a manteiga derretida, a raspa e o sumo do limão.</p><p><b>Unir os preparados:</b> Verta os líquidos sobre a taça dos ingredientes secos. Mexa delicadamente com uma vara de arames apenas até estarem incorporados (deixe alguns grumos para ficarem mais fofas).</p><p><b>Adicionar os mirtilos:</b> Envolva a maior parte dos mirtilos na massa. Pode guardar alguns para colocar por cima já na frigideira.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente em lume médio e unte com um pouco de manteiga ou óleo. Verta pequenas porções de massa (cerca de 1/4 de chávena) e adicione mais mirtilos no topo da massa.</p><p><b>Virar:</b> Deixe cozinhar até começarem a aparecer pequenas bolhas à superfície (cerca de 2 minutos). Vire com uma espátula e deixe dourar do outro lado por mais 1 minuto.</p><p><b>Servir:</b> Repita até a massa terminar e sirva de imediato com xarope de ácer, mel ou iogurte.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_BOWL_VERDE + "', '<h3>Ingredientes Base</h3><p>Para uma dose individual, vai precisar de:</p><ul><li>1 mão cheia de espinafres frescos (ou couve baby)</li><li>1 fatia de ananás ou abacaxi (fresco ou congelado)</li><li>1/2 manga congelada</li><li>1/2 banana madura congelada (essencial para dar a textura cremosa tipo gelado)</li><li>100 ml a 150 ml de líquido (ex: água de coco, leite de amêndoa ou bebida vegetal à escolha)</li><li><b>Opcional:</b> 1 colher de sopa de sementes de linhaça ou proteína vegetal</li></ul><h3>Preparação</h3><p><b>Coloque os líquidos primeiro:</b> Adicione a água de coco ou o leite vegetal ao copo do liquidificador.</p><p><b>Adicione os vegetais e a fruta:</b> Coloque os espinafres, seguidos da banana, da manga e do ananás.</p><p><b>Triture:</b> Bata tudo na potência máxima até obter um creme homogéneo, denso e aveludado. Se estiver muito espesso, adicione um pequeno fio de líquido e volte a bater.</p><p><b>Sirva:</b> Transfira o creme para uma taça funda.</p><h3>Sugestões de Toppings</h3><p>Para adicionar contraste e textura, decore o topo do seu smoothie bowl com:</p><ul><li>Lascas de coco ou coco ralado</li><li>Sementes de chia ou sementes de sésamo preto</li><li>Pedaços de manga fresca ou frutos vermelhos</li><li>Frutos secos picados (amêndoas ou pistáchios)</li></ul>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_IOGURTE_KIWI + "', '<h3>Ingredientes (para 1 dose)</h3><ul><li><b>Iogurte:</b> 150 g de iogurte natural, grego ou de baunilha</li><li><b>Kiwi:</b> 1 a 2 kiwis maduros</li><li><b>Sementes de chia:</b> 1 a 2 colheres de sopa</li><li><b>Opcional:</b> 1 colher de chá de mel, xarope de ácer ou agave (como adoçante)</li><li><b>Opcional:</b> Granola, nozes ou amêndoas laminadas para dar crocância (como extras)</li></ul><h3>Preparação</h3><p><b>Preparar a fruta:</b> Descasque o kiwi e corte-o em rodelas ou em cubos pequenos.</p><p><b>Montar a taça:</b> Coloque o iogurte no fundo de uma taça.</p><p><b>Adicionar a chia:</b> Polvilhe as sementes de chia por cima do iogurte e adicione o adoçante, caso deseje.</p><p><b>Finalizar:</b> Disponha os pedaços de kiwi por cima e termine com a granola ou frutos secos a gosto.</p><p><b>Servir:</b> Pode consumir imediatamente ou deixar repousar no frigorífico durante 10 a 15 minutos para que as sementes de chia absorvam um pouco da humidade do iogurte e fiquem com uma textura semelhante a um pudim.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_MANTEIGA_AMENDOIM_MORANGO + "', '<h3>Ingredientes</h3><ul><li>1 a 2 fatias de pão (integral, de centeio ou sourdough)</li><li>1 a 2 colheres de sopa de manteiga de amendoim (cremosa ou crocante)</li><li>4 a 5 morangos frescos e lavados</li><li><b>Opcionais:</b> 1 colher de chá de sementes de chia, mel ou um toque de canela</li></ul><h3>Preparação</h3><p><b>Tostar o pão:</b> Coloque a(s) fatia(s) de pão na torradeira ou numa frigideira até ficarem douradas e estaladiças.</p><p><b>Barrar a pasta:</b> Espalhe uma camada generosa de manteiga de amendoim sobre a torrada ainda morna para que derreta ligeiramente.</p><p><b>Preparar a fruta:</b> Corte os morangos em rodelas finas ou em metades.</p><p><b>Montar:</b> Distribua as fatias de morango por cima da torrada com a manteiga de amendoim.</p><p><b>Finalizar:</b> Se desejar, adicione sementes de chia para um toque crocante, um fio de mel para adoçar ou polvilhe com canela.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MEXIDO_TOFU_TOMATE_CHERRY + "', '<h3>Ingredientes</h3><ul><li>200g a 250g de tofu firme (não utilize tofu sedoso)</li><li>100g a 150g de tomate cherry, cortado em metades ou quartos</li><li>1 a 2 colheres de sopa de azeite</li><li>½ colher de chá de cúrcuma (açafrão-da-índia) para dar a cor amarela</li><li>1 colher de chá de alho em pó ou 1 dente de alho picado</li><li>Sal e pimenta-do-reino a gosto</li><li><b>Opcional:</b> 1 a 2 colheres de sopa de levedura nutricional (para um toque de queijo)</li><li>Salsinha fresca ou cebolinha picada para finalizar</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Numa taça, esfarele o tofu com as mãos ou com um garfo até ficar com uma textura granulada, semelhante a ovos mexidos.</p><p><b>Temperar:</b> Adicione a cúrcuma, o alho em pó, a levedura nutricional, o sal e a pimenta. Misture bem para que o tofu ganhe cor e sabor.</p><p><b>Saltear:</b> Numa frigideira antiaderente, aqueça o azeite em lume médio. Adicione o tofu temperado e deixe saltear por alguns minutos, mexendo sempre, até começar a dourar.</p><p><b>Adicionar o tomate:</b> Junte o tomate cherry cortado à frigideira. Deixe cozinhar por mais 2 a 3 minutos até que o tomate fique macio, mas sem se desfazer por completo.</p><p><b>Finalizar e servir:</b> Retire do lume, polvilhe com ervas frescas picadas (salsinha ou cebolinha) e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_COCO_MANGA + "', '<h3>Ingredientes (para 1 dose)</h3><ul><li><b>Aveia:</b> 25 a 30 g de flocos de aveia finos ou grossos</li><li><b>Líquido:</b> 130 a 140 ml de leite de coco (ou bebida vegetal de coco para uma versão mais leve)</li><li><b>Sementes:</b> 1 colher de sobremesa (cerca de 6 g) de sementes de chia ou linhaça moída</li><li><b>Fruta:</b> 120 g de manga fresca cortada em cubos pequenos (cerca de 1/4 de uma manga grande)</li><li><b>Opcionais:</b> 1 colher de sopa de coco ralado ou em lascas, 1 colher de chá de mel ou xarope de ácer, e iogurte natural ou vegetal</li></ul><h3>Preparação</h3><p><b>Misturar os secos:</b> Num frasco de vidro ou taça, coloque os flocos de aveia, as sementes de chia (ou linhaça) e o coco ralado. Misture bem.</p><p><b>Adicionar o líquido:</b> Verta o leite de coco para o frasco. Adicione o adoçante ou mel, se desejar. Mexa para que todos os ingredientes fiquem bem envolvidos no líquido.</p><p><b>Adicionar a manga:</b> Junte metade da manga cortada em cubos à mistura e mexa (pode também triturar parte da manga com o leite de coco para um sabor mais intenso).</p><p><b>Deixar repousar (\"adormecer\"):</b> Tape o frasco e leve ao frigorífico durante a noite (ou por um mínimo de 4 a 6 horas).</p><p><b>Finalizar:</b> No momento de servir, retire do frio, adicione por cima o restante da manga em cubos, um pouco mais de coco ralado e uma colher de iogurte natural, se preferir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_FRAMBOESA_BANANA + "', '<h3>Ingredientes base (1 dose)</h3><ul><li>1 banana madura (idealmente congelada para maior cremosidade)</li><li>120 g de framboesas (ou mistura de frutos vermelhos)</li><li>150 ml a 200 ml de líquido: bebida vegetal (amêndoa, aveia) ou leite meio-gordo</li><li><b>Opcional:</b> 1 a 2 colheres de sopa de iogurte natural ou de aromas</li><li><b>Opcional:</b> 1 colher de chá de mel ou xarope de ácer (para adoçar)</li></ul><h3>Preparação</h3><p><b>Preparar as frutas:</b> Descasque a banana e corte-a em rodelas.</p><p><b>Misturar:</b> Coloque todos os ingredientes no copo do liquidificador ou robot de cozinha.</p><p><b>Triturar:</b> Bata na potência máxima durante 1 a 2 minutos, até obter um batido liso e sem pedaços.</p><p><b>Servir:</b> Verta para um copo e beba de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_AVEIA_MEL + "', '<h3>Ingredientes (para cerca de 4 a 6 panquecas)</h3><ul><li><b>Ovos:</b> 2</li><li><b>Aveia:</b> 100 g de farinha de aveia (ou flocos de aveia triturados)</li><li><b>Líquido:</b> 150 ml de leite ou bebida vegetal (amêndoa, aveia, soja)</li><li><b>Mel:</b> 1 a 2 colheres de sopa (ajuste ao seu gosto)</li><li><b>Opcional:</b> 1 colher de chá de fermento em pó (para torná-las mais fofinhas)</li><li><b>Opcional:</b> 1 pitada de sal e meia colher de chá de canela em pó (como toque extra)</li><li><b>Gordura:</b> Um pouco de manteiga ou óleo de coco para untar a frigideira</li></ul><h3>Preparação</h3><p><b>Misturar os ingredientes:</b> Numa taça ou copo liquidificador, coloque os ovos, o leite e o mel. Bata ou misture bem.</p><p><b>Adicionar os secos:</b> Junte a farinha de aveia, o fermento e a canela. Misture até obter uma masa homogénea e sem grumos.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente em lume médio e unte com um pouco de manteiga ou óleo de coco.</p><p><b>Formar as panquecas:</b> Verta uma pequena porção da massa (cerca de uma concha de sopa) na frigideira. Deixe cozinhar até começarem a surgir pequenas bolhas na superfície (cerca de 2 a 3 minutos).</p><p><b>Virar:</b> Com a ajuda de uma espátula, vire a panqueca e deixe cozinhar o outro lado até ficar dourado.</p><p><b>Servir:</b> Retire para um prato e repita o processo até terminar a massa.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_HUMUS_TOMATE + "', '<h3>Ingredientes</h3><ul><li>2 fatias de pão (o de cereais ou massa fermentada funciona muito bem)</li><li>3 a 4 colheres de sopa de húmus (tradicional ou de tomate seco)</li><li>1 tomate maduro em rodelas ou um punhado de tomate cherry cortado em metades</li><li>Azeite virgem extra (a gosto)</li><li>Sal e pimenta preta (a gosto)</li><li><b>Opcional:</b> Orégãos secos, folhas de manjericão fresco ou sementes de sésamo para polvilhar</li></ul><h3>Preparação</h3><p><b>Torrar o pão:</b> Leve as fatias de pão à torradeira ou a uma frigideira com um fiozinho de azeite até ficarem bem crocantes.</p><p><b>Espalhar o húmus:</b> Divida o húmus pelas fatias de pão, espalhando uniformemente.</p><p><b>Adicionar o tomate:</b> Coloque as rodelas ou as metades de tomate por cima do húmus.</p><p><b>Temperar:</b> Tempere com sal, pimenta preta e um fio fino de azeite.</p><p><b>Finalizar:</b> Decore com manjericão ou orégãos a gosto. Está pronta a servir!</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MUESLI_FRUTOS_VERMELHOS + "', '<h3>Ingredientes (1 pessoa)</h3><ul><li><b>Base:</b> 4 a 5 colheres de sopa de flocos de aveia (finos ou grossos)</li><li><b>Líquido:</b> 150 ml de bebida vegetal (aveia, amêndoa) ou leite</li><li><b>Crocância:</b> 1 colher de sopa de frutos secos picados (nozes, avelãs ou amêndoas) e sementes (linhaça ou chia)</li><li><b>Frutos Vermelhos:</b> 1 mão cheia de mirtilos, framboesas, amoras ou morangos cortados</li><li><b>Opcional:</b> 1 colher de sopa de iogurte natural ou grego e um fio de mel (como toque extra)</li></ul><h3>Preparação</h3><p><b>Mistura inicial:</b> Numa taça, coloque os flocos de aveia, os frutos secos e as sementes.</p><p><b>Hidratação:</b> Adicione a bebida vegetal (ou leite) e o iogurte. Mexa bem até obter uma mistura homogénea.</p><p><b>Frutos:</b> Adicione os frutos vermelhos por cima. Pode guardar a taça no frigorífico durante a noite (estilo overnight oats) para amolecer a aveia, ou consumir de imediato.</p><p><b>Finalização:</b> Antes de comer, pode polvilhar com um pouco de canela ou adicionar mais mel a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAPA_QUINOA_MACA + "', '<h3>Ingredientes (2 doses)</h3><ul><li>1 chávena (aprox. 80 g) de quinoa (previamente lavada para retirar o amargor)</li><li>2 maçãs médias</li><li>2 chávenas (aprox. 500 ml) de bebida vegetal (ex: aveia, amêndoa ou soja) ou leite</li><li>1 pau de canela</li><li>Canela em pó (a gosto)</li><li><b>Opcional:</b> 1 colher de chá de xarope de ácer, agave ou mel</li></ul><h3>Preparação</h3><p><b>Cozer a quinoa:</b> Num tacho, coloque a quinoa lavada e cubra com água ou parte do leite. Deixe cozinhar em lume brando até ficar macia (cerca de 10-15 minutos).</p><p><b>Adicionar os sabores:</b> Junte o leite (ou o restante), o pau de canela e uma maçã cortada em cubos pequenos ou ralada.</p><p><b>Apurar:</b> Deixe ferver, reduza o lume e mexa regularmente até obter a consistência cremosa desejada (cerca de 10 minutos).</p><p><b>Finalizar:</b> Retire o pau de canela. Sirva numa taça e decore com a segunda maçã cortada em fatias finas ou cubos, polvilhe com canela em pó e adicione um fio de xarope de ácer/mel.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_MANGA_LIMA + "', '<h3>Ingredientes (1-2 doses)</h3><ul><li>1 manga madura grande (descascada e cortada em cubos)</li><li>Sumo de 1 lima (e um pouco da raspa para maior intensidade)</li><li>100 ml a 150 ml de água fria, leite vegetal (ex: arroz ou coco) ou iogurte natural</li><li><b>Opcional:</b> 1 c. de sopa de mel ou xarope de ácer (para adoçar)</li><li>4 a 5 cubos de gelo</li></ul><h3>Preparação</h3><p><b>Preparar a fruta:</b> Descasque a manga e corte a polpa em cubos.</p><p><b>Misturar:</b> Coloque os cubos de manga, o sumo e a raspa da lima no liquidificador.</p><p><b>Bater:</b> Adicione o líquido escolhido (água, leite ou iogurte) juntamente com o adoçante (se desejar) e o gelo.</p><p><b>Triturar:</b> Triture na velocidade máxima até obter uma mistura homogénea, cremosa e sem pedaços.</p><p><b>Servir:</b> Verta para um copo alto e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_OVO_ESCALFADO + "', '<h3>Ingredientes (para 1 dose)</h3><ul><li>1 a 2 fatias de pão (ex: pão de fermentação natural, integral ou de sementes)</li><li>1/2 abacate maduro</li><li>1 ovo fresco</li><li>1 colher de chá de sumo de lima ou limão</li><li>1 colher de sopa de vinagre (para escalfar o ovo)</li><li>Azeite, sal e pimenta preta moída a gosto</li></ul><h3>Preparação</h3><p><b>O Abacate:</b> Numa taça, esmague a polpa do abacate com um garfo. Junte o sumo de lima/limão, uma pitada de sal e pimenta. Misture até obter uma pasta cremosa.</p><p><b>O Ovo:</b> Coloque uma panela com água e o vinagre ao lume. Quando começar a levantar fervura, reduza para lume brando. Com uma colher, mexa a água em círculos para criar um remoinho. Parta o ovo para o centro do remoinho e deixe cozer durante 3 minutos (para obter uma gema cremosa). Retire com uma escumadeira e deixe escorrer em papel de cozinha.</p><p><b>A Torrada:</b> Toste o pão até ficar dourado e estaladiço.</p><p><b>Montagem:</b> Barre a torrada com a pasta de abacate e coloque cuidadosamente o ovo escalfado por cima. Tempere o ovo com uma pitada de sal, pimenta e um fio de azeite.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_ACAI_GRANOLA + "', '<h3>Ingredientes</h3><p><b>Para a base cremosa:</b></p><ul><li>200 g de polpa de açaí congelada (ou 2 a 3 colheres de sopa de açaí em pó)</li><li>1 banana madura congelada (essencial para dar textura cremosa)</li><li>50 a 60 ml de líquido (água, água de coco ou bebida vegetal de amêndoa)</li><li><b>Opcional:</b> 1 colher de sopa de iogurte natural ou grego (para maior cremosidade)</li></ul><p><b>Para a cobertura (Toppings):</b></p><ul><li>Granola a gosto (de aveia, frutos secos ou sementes)</li><li>Fruta fresca cortada (morangos, mirtilos, kiwi, manga ou banana)</li><li><b>Opcional:</b> Fios de mel ou xarope de ácer (para adoçar)</li><li>Toques extra: lascas de coco, sementes de chia ou manteiga de amendoim</li></ul><h3>Preparação</h3><p><b>Preparar a base:</b> No liquidificador ou processador de alimentos, coloque a banana congelada em pedaços e a polpa de açaí.</p><p><b>Bater:</b> Adicione o líquido escolhido (ex: água de coco) e bata. Se necessário, pare o liquidificador a meio e empurre a mistura com uma espátula para garantir que fica homogénea e espessa.</p><p><b>Montar a taça:</b> Verta o creme de açaí para uma taça larga.</p><p><b>Decorar:</b> Disponha a fruta fresca cortada e a granola por cima do açaí, criando um contraste de cores e texturas. Finalize com mel ou outros ingredientes extra a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAPAS_MILHO_DOCE + "', '<h3>Ingredientes</h3><p>Para preparar cerca de 4 doses, vai precisar de:</p><ul><li><b>Farinha ou carolo de milho:</b> 150 g</li><li><b>Água:</b> 500 ml</li><li><b>Leite (meio-gordo ou vegetal):</b> 300 ml a 400 ml</li><li><b>Mel:</b> 2 a 3 colheres de sopa (a gosto)</li><li><b>Casca de limão:</b> 1 tira</li><li><b>Pau de canela:</b> 1</li><li><b>Opcional:</b> 1 colher de sobremesa de manteiga</li><li><b>Sal:</b> 1 pitada</li></ul><h3>Preparação</h3><p><b>Dissolver o milho:</b> Numa panela ou tacho, coloque a água fria e adicione a farinha de milho aos poucos, mexendo bem com uma vara de arames para evitar a formação de grumos.</p><p><b>Aromatizar:</b> Junte o pau de canela, a casca de limão e uma pitada de sal.</p><p><b>Cozinhar o milho:</b> Leve ao lume brando/médio e mexa continuamente até começar a engrossar e a farinha absorver a água.</p><p><b>Adicionar o leite:</b> Quando a mistura estiver espessa, adicione o leite morno em fio, sem parar de mexer.</p><p><b>Finalizar:</b> Deixe ferver suavemente até atingir a consistência desejada (cremosa, semelhante a um leite-creme). Retire do lume, retire a casca de limão e o pau de canela.</p><p><b>Temperar:</b> Envolva a manteiga (se usar) e o mel até estarem bem dissolvidos nas papas.</p><p><b>Servir:</b> Verta para taças ou pratos fundos, polvilhe com canela em pó a gosto e finalize com um fio extra de mel por cima.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_BOWL_MORANGO + "', '<h3>Ingredientes Base</h3><ul><li>1 banana congelada (cortada em rodelas)</li><li>1 chávena de morangos congelados (cerca de 7 a 8 morangos)</li><li>2 colheres de sopa de iogurte natural ou grego (ou bebida vegetal/leite para uma opção vegan)</li></ul><h3>Toppings Sugeridos</h3><ul><li>Granola a gosto</li><li>Fruta fresca laminada (morangos ou banana)</li><li>Sementes (chia, sésamo ou linhaça)</li><li>Amêndoas ou outros frutos secos picados</li></ul><h3>Preparação</h3><p><b>Triturar:</b> Coloque a banana congelada, os morangos congelados e o iogurte (ou bebida vegetal) num processador de alimentos ou liquidificador potente.</p><p><b>Bater:</b> Triture tudo na velocidade máxima até obter um creme homogéneo e espesso. Se necessário, pare a meio para empurrar a fruta com a espátula ou adicione apenas um fio muito fino de líquido para ajudar a triturar.</p><p><b>Servir:</b> Verta o creme para uma taça funda.</p><p><b>Decorar:</b> Disponha os toppings por cima em secções organizadas ou misturados a gosto. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_ANANAS_HORTELA + "', '<h3>Ingredientes</h3><ul><li>1 a 2 fatias de ananás maduro (cerca de 100g a 120g)</li><li>3 a 4 folhas frescas de hortelã</li><li>3 colheres de sopa de flocos de aveia (finos ou grossos)</li><li>200 ml de água ou de uma bebida vegetal (como bebida de amêndoa ou aveia)</li><li><b>Opcional:</b> 1 colher de chá de sementes de chia ou linhaça</li><li>Gelo a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Descasque o ananás e corte-o em pedaços pequenos. Lave bem as folhas de hortelã.</p><p><b>Bater:</b> Coloque todos os ingredientes no liquidificador: o ananás, as folhas de hortelã, a aveia, o gelo e a bebida eleita (água ou bebida vegetal).</p><p><b>Servir:</b> Triture tudo na velocidade máxima até obter um batido homogéneo e cremoso. Verta para um copo e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_BANANA_CANELA + "', '<h3>Ingredientes</h3><p>Para fazer cerca de 4 a 5 panquecas pequenas, vai precisar de:</p><ul><li>1 banana grande e madura</li><li>1 ovo</li><li>3 a 4 colheres de sopa de farinha ou flocos de aveia</li><li>1 colher de chá de canela em pó (ou a gosto)</li><li><b>Opcional:</b> 1 colher de café de fermento em pó (para torná-las mais fofas)</li><li>Manteiga ou óleo de coco para untar a frigideira</li></ul><h3>Preparação</h3><p><b>Preparar a massa:</b> Numa taça, coloque a banana e esmague-a bem com um garfo até obter uma pasta.</p><p><b>Juntar os ingredientes:</b> Adicione o ovo e bata tudo muito bem. De seguida, envolva a aveia, a canela e o fermento até obter uma massa homogénea.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente em lume médio e unte-a com um pouco de manteiga ou óleo de coco.</p><p><b>Formar as panquecas:</b> Verta pequenas porções da massa para a frigideira (cerca de 2 colheres de sopa por panqueca).</p><p><b>Virar:</b> Deixe cozinhar em lume brando até começarem a aparecer pequenas bolhas na superfície (cerca de 2-3 minutos). Vire com a ajuda de uma espátula e deixe dourar do outro lado por mais 1 a 2 minutos.</p><p><b>Servir:</b> Retire e sirva quentes com mais canela, mel ou rodelas de banana fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_QUEIJO_FRESCO_TOMATE + "', '<h3>Ingredientes</h3><ul><li>2 a 4 fatias de pão (pão de forma rústico, integral ou baguete)</li><li>1 a 2 queijos frescos (pequenos)</li><li>1 ou 2 tomates maduros (ou tomate cherry)</li><li>Azeite extra virgem q.b.</li><li>Orégãos ou manjericão fresco picado q.b.</li><li><b>Opcional:</b> 1 dente de alho</li><li>Sal e pimenta preta moída na hora q.b.</li></ul><h3>Preparação</h3><p><b>Tostar o pão:</b> Leve as fatias de pão à torradeira ou ao forno até ficarem douradas e estaladiças.</p><p><b>Esfregar o alho:</b> Se gostar, pegue num dente de alho descascado e corte-o ao meio. Esfregue suavemente o lado cortado do alho sobre o pão ainda quente para lhe dar sabor.</p><p><b>Temperar o tomate:</b> Corte o tomate em cubos pequenos (ou em rodelas, dependendo da sua preferência). Numa tigela, tempere-o com um fio de azeite, uma pitada de sal, orégãos e/ou manjericão picado.</p><p><b>Preparar o queijo:</b> Retire o queijo fresco da água da embalagem e corte-o em fatias ou esfarele-o ligeiramente com um garfo para facilitar na hora de barrar.</p><p><b>Montar a torrada:</b> Distribua o queijo fresco pelas fatias de pão torrado. Por cima do queijo, adicione a mistura de tomate temperado.</p><p><b>Finalizar:</b> Regue com umas gotas de azeite e tempere com pimenta preta moída na hora a gosto. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_IOGURTE_GRANOLA_MIRTILO + "', '<h3>Ingredientes</h3><ul><li>1 a 2 iogurtes (natural, grego ou vegetal)</li><li>1/2 chávena de mirtilos frescos</li><li>2 a 3 colheres de sopa de granola</li><li><b>Opcional:</b> 1 colher de chá de mel, xarope de ácer ou compota</li><li><b>Opcional:</b> Fruta extra (banana, morangos), sementes (chia, linhaça) ou frutos secos</li></ul><h3>Preparação</h3><p><b>Montagem base:</b> Numa taça larga ou num copo de vidro transparente, coloque metade do iogurte.</p><p><b>Adicionar fruta:</b> Acrescente uma camada generosa de mirtilos lavados e bem secos.</p><p><b>Alternar camadas:</b> Adicione o restante iogurte e cubra com mais mirtilos.</p><p><b>Toque crocante:</b> Polvilhe toda a superfície com a granola.</p><p><b>Finalização:</b> Regue com um fio de mel ou xarope de ácer a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_ESPINAFRE_MACA + "', '<h3>Ingredientes</h3><p>Para 1 ou 2 copos:</p><ul><li>1 maçã verde (com casca, mas sem o coração/sementes)</li><li>1/2 pepino médio</li><li>1 a 2 mãos cheias de espinafres frescos (aprox. 50g)</li><li>150 a 200 ml de água ou água de coco (ajuste conforme a textura desejada)</li><li><b>Opcional:</b> Sumo de 1/2 limão e algumas pedras de gelo</li></ul><h3>Preparação</h3><p><b>Preparar os ingredientes:</b> Lave muito bem todos os vegetais e a fruta. Corte a maçã e o pepino em pedaços médios para facilitar na trituração.</p><p><b>Misturar:</b> Coloque todos os ingredientes (maçã, pepino, espinafres, água e o sumo de limão) num liquidificador.</p><p><b>Triturar:</b> Bata na potência máxima durante 1 a 2 minutos, até obter uma mistura homogénea, cremosa e sem pedaços.</p><p><b>Servir:</b> Se preferir um batido mais fresco, adicione pedras de gelo e bata novamente por alguns segundos. Beba de imediato para aproveitar todos os nutrientes.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PUDIM_CHIA_MANGA_COCO + "', '<h3>Ingredientes</h3><ul><li>400 g de leite de coco (pode usar de lata para mais cremosidade ou de compra)</li><li>80 g de sementes de chia</li><li>2 a 3 colheres de sopa de xarope de ácer, agave, ou melado (ajuste a gosto)</li><li>1 colher de chá de extrato de baunilha</li><li>1 manga madura grande (em cubos ou batida como purê)</li><li>Coco ralado para decorar (e tostar, se preferir)</li></ul><h3>Preparação</h3><p><b>Misturar a base:</b> Numa taça ou frasco, misture bem o leite de coco, as sementes de chia, o adoçante escolhido e o extrato de baunilha.</p><p><b>Hidratar:</b> Mexa muito bem para não criar grumos. Deixe repousar por 10 minutos, mexa novamente, tape e leve ao frigorífico durante pelo menos 4 horas (ou durante a noite) até obter uma textura de pudim cremoso.</p><p><b>Preparar a manga:</b> Descasque a manga. Pode cortá-la em cubos pequenos ou triturá-la no liquidificador para fazer um purê aveludado.</p><p><b>Montagem:</b> Em copos ou taças, intercale camadas do pudim de chia com a manga.</p><p><b>Decoração:</b> Finalize o topo com mais cubos de manga e polvilhe generosamente com coco ralado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_PIMENTAO + "', '<h3>Ingredientes</h3><ul><li>1 abacate maduro (de preferência o tipo avocado)</li><li>2 fatias de pão rústico, integral ou de fermentação natural</li><li>Sumo de 1/2 limão</li><li>1 colher de café de pimentão doce (colorau) em pó (pode usar a versão fumada para um toque extra)</li><li>1 colher de sopa de azeite extra virgem</li><li>Sal e pimenta preta moída na hora (a gosto)</li><li><b>Opcional:</b> 1 ovo escalfado ou estrelado para colocar por cima</li></ul><h3>Preparação</h3><p><b>Torrar o pão:</b> Leve as fatias de pão à torradeira ou a uma frigideira com um fio de azeite até ficarem douradas e estaladiças.</p><p><b>Preparar o abacate:</b> Corte o abacate ao meio, retire o caroço e transfira a polpa para uma tigela. Esmague grosseiramente com um garfo até obter uma textura cremosa mas com alguns pedaços.</p><p><b>Temperar:</b> Junte o sumo de limão, o azeite, o sal e a pimenta ao abacate e envolva bem.</p><p><b>Montagem:</b> Distribua o abacate esmagado pelas fatias de pão já tostadas.</p><p><b>Finalização:</b> Polvilhe generosamente o pimentão doce por cima do abacate e finalize com um fio extra de azeite. Se optar pelo ovo, coloque-o cuidadosamente no topo antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_CHOCOLATE_MORANGO + "', '<h3>Ingredientes</h3><ul><li>40g de flocos de aveia</li><li>250ml de bebida vegetal (amêndoa, aveia ou soja) ou leite</li><li>1 colher de sopa de cacau em pó (ou cacau puro para um sabor intenso)</li><li>6 a 8 morangos frescos cortados em cubos</li><li><b>Opcional:</b> 1 colher de chá de xarope de ácer, mel ou açúcar de coco</li><li>1 quadradinho de chocolate preto ou pepitas de chocolate para derreter por cima (ex: 70% cacau)</li></ul><h3>Preparação</h3><p>Numa panela pequena, coloque a aveia, o cacau em pó e o adoçante (se optar por usar).</p><p>Adicione a bebida vegetal ou leite e mexa bem.</p><p>Leve a lume brando, mexendo sempre, até começar a engrossar e ganhar uma textura cremosa (cerca de 3 a 5 minutos).</p><p>Retire do lume e adicione metade dos morangos picados.</p><p>Transfira para uma taça, adicione o resto dos morangos por cima e polvilhe com as pepitas de chocolate ou o chocolate preto picado. O calor residual das papas vai derreter ligeiramente o chocolate.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_SILVESTRE_LINHACA + "', '<h3>Ingredientes (1 pessoa)</h3><ul><li><b>Frutos silvestres:</b> 150g a 200g (mirtilos, amoras, framboesas ou morangos), frescos ou congelados</li><li><b>Linhaça:</b> 1 colher de sobremesa de sementes (preferencialmente moídas para melhor absorção)</li><li><b>Líquido base:</b> 150ml a 200ml (água, água de coco, leite magro ou bebida vegetal, como amêndoa ou aveia)</li><li><b>Opcional (para cremosidade ou doce):</b> 1 banana pequena ou 1 iogurte natural/vegetal e umas gotas de mel ou xarope de ácer</li></ul><h3>Preparação</h3><p><b>Preparar a linhaça:</b> Se tiver sementes inteiras, triture-as previamente num processador ou triturador de café até obter uma farinha fina.</p><p><b>Adicionar os ingredientes:</b> Coloque a base líquida no liquidificador ou copo misturador primeiro (evita que fique colada ao fundo). De seguida, adicione os frutos silvestres e a linhaça.</p><p><b>Triturar:</b> Triture na potência máxima durante 1 a 2 minutos até obter uma textura cremosa e homogénea.</p><p><b>Ajustar e servir:</b> Se o smoothie estiver muito espesso, adicione um pouco mais de líquido e volte a bater. Sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_INTEGRAIS_FRUTA + "', '<h3>Ingredientes</h3><ul><li>1 chávena de farinha de trigo integral</li><li>1 colher de chá de fermento em pó</li><li>1 pitada de sal</li><li><b>Opcional:</b> 1 colher de sopa de açúcar mascavo, mel ou xarope de ácer</li><li>1 ovo médio</li><li>1 chávena de leite (ou bebida vegetal, como aveia ou amêndoa)</li><li>1 colher de sopa de óleo de coco ou manteiga derretida (para a massa)</li><li>Fruta da época de Maio (morangos fatiados, amoras, banana às rodelas)</li><li>Óleo de coco ou manteiga (para untar a frigideira)</li></ul><h3>Preparação</h3><p><b>Misturar os secos:</b> Numa taça, envolva a farinha integral, o fermento, o sal e o açúcar.</p><p><b>Misturar os líquidos:</b> Noutra tigela ou no liquidificador, bata o ovo e adicione o leite e a manteiga derretida (or óleo).</p><p><b>Unir tudo:</b> Junte os ingredientes líquidos aos secos e mexa delicadamente até obter uma massa homogénea. Não bata em excesso para manter as panquecas fofas.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente em lume médio e unte com um pouco de manteiga ou óleo de coco. Verta uma pequena porção da massa (cerca de 1/4 de chávena) para a frigideira.</p><p><b>Virar:</b> Deixe cozinhar até começarem a surgir pequenas bolhas na superfície (cerca de 2 minutos). Vire a panqueca e deixe dourar do outro lado por mais 1 minuto.</p><p><b>Servir:</b> Repita o processo até terminar a massa. Sirva as panquecas ainda quentes, decoradas com a fruta de Maio e regadas com um fio de mel.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_IOGURTE_MEL_NOZES + "', '<h3>Ingredientes (para 1 taça)</h3><ul><li>1 Iogurte Grego natural (ou natural açucarado, dependendo da preferência)</li><li>1 a 2 colheres de sopa de mel (ajustável ao gosto)</li><li>1 colher de sopa de nozes picadas grosseiramente</li></ul><h3>Preparação</h3><p><b>Disponha o mel:</b> Coloque metade do mel no fundo de uma taça ou copo transparente.</p><p><b>Adicione o iogurte:</b> Vaze o iogurte grego por cima do mel.</p><p><b>Coloque os toppings:</b> Cubra o iogurte com o restante mel e salpique com as nozes picadas.</p><p><b>Sirva:</b> Leve ao frigorífico para servir fresco ou consuma de imediato.</p>');");

        // ==========================================
// ALMOÇOS - MAIO (31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CARIL_GRAO_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>500 g de grão-de-bico cozido (pode usar de frasco ou lata)</li><li>150 g a 200 g de espinafres frescos (ou congelados)</li><li>400 ml de leite de coco (1 lata)</li><li>1 cebola picada</li><li>2 dentes de alho picados</li><li><b>Opcional:</b> 1 c. de sopa de gengibre fresco ralado</li><li>1 a 2 c. de sopa de caril em pó</li><li>1 c. de chá de curcuma em pó</li><li>1 c. de chá de cominhos em pó</li><li>2 c. de sopa de azeite (ou óleo de coco)</li><li>Sal e pimenta preta a gosto</li><li>Coentros frescos picados (para guarnecer)</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Numa frigideira larga ou tacho, aqueça o azeite ou óleo de coco em lume médio. Adicione a cebola picada e deixe alourar durante cerca de 5 minutos até ficar macia. Junte o alho e o gengibre ralado, e deixe cozinhar por mais 1 a 2 minutos.</p><p><b>Especiarias:</b> Adicione o caril, a curcuma e os cominhos. Mexa bem e deixe envolver durante cerca de 1 minuto para libertar os aromas, tendo cuidado para não queimar.</p><p><b>Adicionar o Grão:</b> Junte o grão-de-bico escorrido e envolva bem no preparado de especiarias. Adicione o leite de coco, tempere com sal e pimenta a gosto, e deixe levantar fervura.</p><p><b>Apurar:</b> Reduza para lume brando, tape o tacho e deixe cozinhar durante cerca de 10 a 15 minutos, para que o grão absorva os sabores e o molho engrosse ligeiramente.</p><p><b>Finalizar com os Espinafres:</b> Por fim, adicione as folhas de espinafre. Misture bem e deixe cozinhar por 2 a 3 minutos, apenas até os espinafres murcharem e perderem volume.</p><p><b>Servir:</b> Retire do lume, retifique os temperos e sirva polvilhado com coentros frescos picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_QUINOA_TROPICAL + "', '<h3>Ingredientes</h3><p><b>Base da Salada:</b></p><ul><li>150 g de quinoa (branca ou tricolor)</li><li>300 ml de água (ou caldo de legumes)</li><li>1 chávena de manga madura, cortada em cubos</li><li>1/2 ananás fresco, cortado em cubos pequenos</li><li>1 pimento vermelho, cortado em cubos</li><li>1 cebola roxa pequena, picada finamente</li><li>50 g de caju ou amêndoa tostada (picados)</li><li>Folhas de hortelã fresca ou coentros picados a gosto</li></ul><p><b>Molho:</b></p><ul><li>Sumo de 1 lima (ou limão)</li><li>3 colheres de sopa de azeite extra virgem</li><li>1 colher de chá de mel ou xarope de ágave</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Cozinhar a Quinoa:</b> Lave muito bem a quinoa em água corrente usando um coador fino para remover a saponina (que pode deixar um sabor amargo). Num tacho, coloque a quinoa e a água, adicione uma pitada de sal e deixe ferver. Tape, reduza o lume e deixe cozinhar durante cerca de 12 a 15 minutos, ou até a água ser totalmente absorvida.</p><p><b>Arrefecer:</b> Retire do lume, solte a quinoa com um garfo e transfira-a para uma taça grande. Deixe arrefecer até ficar à temperatura ambiente.</p><p><b>Preparar os ingredientes:</b> Enquanto a quinoa arrefece, corte todos os ingredientes frescos em cubos: o ananás, a manga, o pimento e a cebola roxa.</p><p><b>Misturar:</b> Junte as frutas, o pimento, a cebola e as sementes tostadas (caju/amêndoa) à taça com a quinoa. Adicione também as folhas de hortelã ou coentros.</p><p><b>Fazer o molho:</b> Numa pequena taça ou frasco, misture o sumo de lima, o azeite, o mel, o sal e a pimenta. Mexa bem até emulsionar.</p><p><b>Envolver:</b> Vede a salada com o molho e envolva tudo cuidadosamente para não desfazer a fruta.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MASSA_PRIMAVERA + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Massa:</b> 350 g de massa curta ou longa (ex: penne, fusilli ou tagliatelle)</li><li><b>Vegetais:</b> 1 courgette pequena cortada em cubos, 1 cenoura ralada ou em juliana, 100 g de ervilhas (frescas ou congeladas) e 100 g de tomates cherry cortados ao meio</li><li><b>Aromáticos:</b> 2 dentes de alho picados e 1/2 cebola picada</li><li><b>Tempero:</b> 4 colheres de sopa de azeite, sal, pimenta preta moída e folhas de manjericão fresco</li><li><b>Opcional:</b> 100 ml de natas (ou natas vegetais) e queijo parmesão ralado na hora</li></ul><h3>Preparação</h3><p><b>Cozer a massa:</b> Numa panela grande com água a ferver e sal, coza a massa até ficar al dente (verifique o tempo na embalagem). Reserve uma chávena da água da cozedura e escorra a massa.</p><p><b>Saltear os vegetais:</b> Numa frigideira grande ou wok, aqueça o azeite e refogue a cebola e o alho até dourarem. Adicione a cenoura e a courgette, deixando cozinhar por cerca de 5 minutos até amolecerem ligeiramente.</p><p><b>Juntar os restantes ingredientes:</b> Acrescente as ervilhas e os tomates cherry e deixe saltear por mais 3 minutos. Se desejar um molho mais cremoso, adicione agora as natas e envolva.</p><p><b>Misturar tudo:</b> Junte a massa cozida aos vegetais. Se o preparado estiver muito seco, adicione um pouco da água da cozedura da massa que reservou para criar um molho sedoso.</p><p><b>Finalizar:</b> Tempere com sal, pimenta e misture o manjericão. Sirva de imediato com queijo parmesão ralado a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CHILI_VEGETARIANO_LEVE + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Feijão:</b> 1 lata (400g) de feijão encarnado (ou preto), escorrido</li><li><b>Lentilhas ou Soja:</b> 150g de lentilhas cozidas ou 1 chávena de proteína de soja demolhada</li><li><b>Legumes:</b> 1 cebola, 2 dentes de alho, 1 pimento vermelho em cubos e 1 cenoura ralada</li><li><b>Tomate:</b> 400g de tomate pelado em pedaços (ou polpa de tomate)</li><li><b>Gordura:</b> 1 a 2 colheres de sopa de azeite</li><li><b>Especiarias:</b> 1 c. chá de cominhos, 1 c. chá de pimentão-doce (ou fumado) e 1 folha de louro</li><li><b>Opcional:</b> 1 quadradinho de chocolate preto e sumo de 1/2 lima</li><li><b>Tempero:</b> Sal, pimenta preta e picante (malagueta/piripiri) a gosto</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho largo, aqueça o azeite e salteie a cebola picada, o alho e o louro até a cebola ficar translúcida.</p><p><b>Adicionar vegetais:</b> Junte o pimento e a cenoura ralada. Deixe cozinhar durante 5 minutos para amaciar.</p><p><b>Temperar e apurar:</b> Adicione os cominhos e o pimentão-doce. Mexa bem para libertar o aroma.</p><p><b>Adicionar o tomate e leguminosas:</b> Acrescente o tomate aos pedaços, as lentilhas (ou soja) e o feijão. Tempere com sal, pimenta e picante.</p><p><b>Cozinhar:</b> Tape o tacho e deixe cozinhar em lume brando durante 20 minutos, mexendo ocasionalmente.</p><p><b>Finalizar:</b> Se desejar um toque aveludado, adicione o quadrado de chocolate e mexa até derreter. Retire do lume, regue com o sumo de lima e finalize com coentros frescos picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_RISOTO_COGUMELOS_ERVAS + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Base do Risoto:</b> 320g de arroz para risoto (Arbório ou Carnaroli)</li><li><b>Cogumelos:</b> 400g de cogumelos frescos variados (Shitake, Portobello, Castanho/Marron e Paris)</li><li><b>Líquido:</b> 1,5 litros de caldo de legumes quente</li><li><b>Vinho:</b> 150ml de vinho branco seco</li><li><b>Refogado:</b> 1 cebola média picada e 2 dentes de alho picados</li><li><b>Ervas Aromáticas:</b> Tomilho fresco e salsa picada</li><li><b>Gordura:</b> 3 colheres de sopa de azeite e 2 colheres de sopa de manteiga</li><li><b>Finalização:</b> 80g a 100g de queijo parmesão ralado na hora</li><li><b>Tempero:</b> Sal e pimenta-preta a gosto</li></ul><h3>Preparação</h3><p><b>Preparar o Caldo:</b> Numa panela, mantenha o caldo de legumes a lume brando para estar sempre quente durante a confeção.</p><p><b>Saltear os Cogumelos:</b> Numa frigideira larga, adicione azeite e metade da manteiga. Junte os cogumelos laminados ou cortados grosseiramente, uma pitada de sal, tomilho e salsa. Salteie até dourarem e libertarem o seu aroma. Retire e reserve.</p><p><b>Fazer o Refogado:</b> Na mesma frigideira ou tacho, adicione o resto do azeite e refogue a cebola e o alho até ficarem translúcidos.</p><p><b>Tostar o Arroz:</b> Junte o arroz e envolva no refogado durante 1 a 2 minutos até os grãos ficarem ligeiramente translúcidos nas pontas.</p><p><b>Adicionar o Vinho:</b> Verta o vinho branco e mexa sem parar até o álcool evaporar completamente.</p><p><b>Cozinhar o Risoto:</b> Comece a adicionar o caldo de legumes quente, uma concha de cada vez. Mexa continuamente e só adicione mais caldo depois de o arroz absorver o líquido. O processo demora cerca de 15 a 18 minutos.</p><p><b>Juntar os Cogumelos:</b> A meio do processo, adicione parte dos cogumelos salteados para que o arroz absorva o seu sabor.</p><p><b>Finalizar:</b> Quando o arroz estiver al dente (cozido por fora, mas com um leve centro firme), desligue o lume. Junte o restante caldo (para ficar solto), o queijo parmesão e a manteiga gelada. Mexa vigorosamente para criar um molho cremoso.</p><p><b>Servir:</b> Emprate o risoto e decore com o resto dos cogumelos salteados, salsa fresca picada, um fio de azeite e mais queijo a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_LENTILHAS_FETA + "', '<h3>Ingredientes</h3><p><b>Base da Salada:</b></p><ul><li>300 g de lentilhas (pode usar lentilhas secas cozidas ou lentilhas de conserva já escorridas)</li><li>200 g de queijo Feta</li><li>1 cebola roxa pequena, picada</li><li>2 tomates médios cortados em cubos (ou ≈ 10 tomates-cereja)</li><li>1/2 pepino cortado em cubos</li><li><b>Opcional:</b> azeitonas pretas sem caroço fatiadas</li><li>Ervas frescas picadas (coentros ou hortelã a gosto)</li></ul><p><b>Molho:</b></p><ul><li>Azeite virgem extra (quantidade necessária)</li><li>Vinagre de sidra ou sumo de 1 limão</li><li>Sal e pimenta preta moída na hora (a gosto)</li></ul><h3>Preparação</h3><p><b>Preparar as lentilhas:</b> Se optar pelas lentilhas secas, coza-as com água, uma pitada de sal e uma folha de louro até ficarem tenras, mas firmes (cerca de 15 a 20 minutos). Escorra e deixe arrefecer. Se usar as de conserva, basta passar por água e escorrer bem.</p><p><b>Preparar os vegetais:</b> Numa saladeira grande, coloque as lentilhas frias e junte a cebola roxa, o tomate, o pepino e as azeitonas (se utilizar).</p><p><b>Fazer o vinagrete:</b> Numa pequena taça à parte, misture o azeite, o vinagre (ou sumo de limão), o sal e a pimenta. Emulsionar bem.</p><p><b>Envolver:</b> Junte o molho à salada e misture suavemente para que os sabores se fundam.</p><p><b>Adicionar o Feta:</b> Esfarele ou corte o queijo feta em cubos e adicione à salada, juntamente com as ervas frescas picadas. Envolva com cuidado para não desfazer demasiado o queijo.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORTILHA_ESPINAFRES_COGUMELOS + "', '<h3>Ingredientes (para 1 pessoa)</h3><ul><li>2 tortilhas (wraps) de trigo</li><li>3 a 4 ovos médios</li><li>100g de cogumelos frescos laminados (Paris, Portobello ou Shiitake)</li><li>1 a 2 mãos cheias de folhas de espinafre baby</li><li><b>Opcional:</b> 1 dente de alho picado</li><li>Azeite q.b.</li><li>Sal, pimenta preta e orégãos a gosto</li></ul><h3>Preparação</h3><p><b>Preparar os vegetais:</b> Numa frigideira antiaderente, aqueça um fio de azeite e adicione o dente de alho e os cogumelos laminados. Deixe saltear durante cerca de 3 a 5 minutos até perderem o excesso de água.</p><p><b>Juntar os espinafres:</b> Adicione as folhas de espinafre aos cogumelos e mexa até murcharem (cerca de 1 a 2 minutos). Tempere com sal, pimenta e uma pitada de orégãos.</p><p><b>Adicionar os ovos:</b> Numa taça à parte, bata os ovos com uma pitada de sal. Vaze os ovos batidos diretamente sobre os legumes salteados na frigideira.</p><p><b>Colocar a tortilha:</b> Antes que o ovo cozinhe por completo (enquanto a omelete ainda está ligeiramente líquida no topo), coloque uma tortilha por cima da mistura e pressione levemente. Deixe em lume brando até o ovo firmar.</p><p><b>Virar:</b> Com a ajuda de um prato ou da própria tampa da frigideira, vire a tortilha para que o lado da massa fique virado para baixo. Deixe dourar e adicione queijo (opcional, como muçarela ou mozarela) sobre a tortilha.</p><p><b>Servir:</b> Dobre a tortilha ao meio em forma de meia-lua ou enrole-a, retire para um prato e sirva de imediato.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_ARROZ_ERVAS_TOFU_GRELHADO + "', '<h3>Ingredientes</h3><p><b>Para o Tofu:</b></p><ul><li>1 bloco de tofu firme (aprox. 200g - 250g)</li><li>2 colheres de sopa de molho de soja (shoyu)</li><li>1 colher de sopa de azeite</li><li>1 colher de chá de alho em pó</li><li>Sumo de 1/2 limão</li><li>Pimenta preta a gosto</li></ul><p><b>Para o Arroz de Ervas:</b></p><ul><li>1 chávena de arroz (basmati ou carolino)</li><li>2 chávenas de água quente</li><li>1 cebola pequena picada</li><li>2 dentes de alho picados</li><li>1 molho generoso de ervas frescas picadas (salsa, coentros e cebolinho)</li><li>Azeite q.b.</li><li>Sal q.b.</li></ul><h3>Preparação</h3><p><b>1. Preparar e Marinar o Tofu:</b> Seque o tofu com papel de cozinha e corte-o em fatias ou cubos médios. Numa taça, misture o molho de soja, o azeite, o alho em pó, o sumo de limão e a pimenta. Envolva o tofu nesta marinada e deixe repousar por pelo menos 15 minutos para absorver os sabores.</p><p><b>2. Cozinhar o Arroz:</b> Num tacho, leve ao lume um fio de azeite, a cebola picada e os dentes de alho. Deixe alourar suavemente. Adicione o arroz e envolva bem no refogado durante 1 minuto. Junte a água quente e tempere com uma pitada de sal. Deixe ferver, tape o tacho, reduza o lume para o mínimo e deixe cozinhar até a água evaporar na totalidade (cerca de 10 a 12 minutos). Retire do lume e envolva a maior parte das ervas frescas picadas no arroz quente. Reserve algumas ervas para decorar no final.</p><p><b>3. Grelhar o Tofu:</b> Aqueça bem uma frigideira ou grelhador com um fio de azeite. Coloque as fatias/cubos de tofu e grelhe durante 2 a 3 minutos de cada lado, até ficarem dourados e com uma crosta estaladiça.</p><p><b>4. Finalização:</b> Sirva o arroz de ervas numa travessa ou prato, disponha o tofu grelhado por cima e salpique com as restantes ervas frescas e um fio de azeite a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_GRAO_PIMENTOS + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Grão-de-bico:</b> 1 frasco grande ou lata (aprox. 500 g), cozido e escorrido</li><li><b>Pimentos:</b> 2 pimentos (1 vermelho e 1 amarelo/verde), assados e cortados em tiras</li><li><b>Cebola:</b> 1 cebola roxa pequena, fatiada finamente</li><li><b>Alho:</b> 1 dente de alho picado (opcional)</li><li><b>Azeite:</b> 3 colheres de sopa</li><li><b>Vinagre:</b> 1 colher de sopa (ou sumo de limão)</li><li><b>Salsa ou coentros:</b> 1 raminho picado</li><li><b>Tempero:</b> Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Prepare os pimentos:</b> Se optar por assar os pimentos em casa, leve-os ao forno a 200°C num tabuleiro até a pele ficar ligeiramente queimada. Retire, abafe num saco de plástico durante 5 minutos, retire a pele e as sementes e corte em tiras.</p><p><b>Misture os sólidos:</b> Numa saladeira grande, junte o grão-de-bico escorrido, as tiras de pimentos assados e a cebola roxa.</p><p><b>Faça o vinagrete:</b> Numa taça à parte, misture bem o azeite, o vinagre (ou limão), o sal e a pimenta. Adicione o alho picado se desejar.</p><p><b>Tempere:</b> Vaze o vinagrete sobre a salada, envolva tudo muito bem e polvilhe com salsa ou coentros picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_COUSCOUS_VEGETAIS_GRELHADOS + "', '<h3>Ingredientes</h3><p><b>Para a base de Couscous:</b></p><ul><li>250 g de couscous (sêmola de trigo)</li><li>250 ml a 350 ml de água a ferver ou caldo de legumes</li><li>1 colher de sopa de azeite</li><li>Sal e pimenta q.b.</li></ul><p><b>Para os Vegetais Grelhados:</b></p><ul><li>1 curgete média</li><li>1 beringela</li><li>1 pimento vermelho ou amarelo</li><li>1 cebola roxa</li><li>8 cogumelos</li><li>Azeite para pincelar</li><li>Ervas frescas a gosto (hortelã, coentros ou salsa)</li></ul><h3>Preparação</h3><p><b>Preparar os vegetais:</b> Lave e corte todos os vegetais em fatias ou pedaços médios (pode cortar a curgete, a beringela e os cogumelos em rodelas ou tiras, e os pimentos em palitos largos).</p><p><b>Grelhar:</b> Aqueça bem uma grelha ou frigideira estriada e pincele-a com azeite. Grelhe os vegetais de ambos os lados até ficarem macios e com as marcas da grelha. Tempere com sal e reserve.</p><p><b>Hidratar o couscous:</b> Numa taça grande, coloque o couscous, uma pitada de sal e o azeite. Vede com a água ou o caldo a ferver e envolva.</p><p><b>Descansar:</b> Tape a taça com um prato ou película aderente e deixe repousar durante 3 a 5 minutos, permitindo que o couscous absorva todo o líquido e inche.</p><p><b>Soltar o couscous:</b> Retire a tampa e, com a ajuda de um garfo, solte os grãos suavemente até obter uma textura fofa e homogénea.</p><p><b>Misturar:</b> Junte os vegetais grelhados ao couscous fofo. Se preferir, corte os vegetais em pedaços mais pequenos antes de os juntar.</p><p><b>Finalizar:</b> Tempere com um fio de sumo de limão e adicione ervas frescas picadas. Envolva tudo e sirva.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_LASANHA_VEGETAL_LEVE + "', '<h3>\uD83D\uDED2 Ingredientes</h3><p><b>Para o Recheio de Vegetais:</b></p><ul><li>2 curgetes médias, cortadas em fatias finas</li><li>1 beringela média, cortada em rodelas ou fatias finas</li><li>1 cenoura média, ralada ou em cubos pequenos</li><li>1 alho-francês ou cebola picada</li><li>2 dentes de alho picados</li><li>Azeite, sal, pimenta preta e orégãos a gosto</li></ul><p><b>Para o Molho Branco (Béchamel):</b></p><ul><li>50 g de manteiga</li><li>50 g de farinha de trigo</li><li>500 a 700 ml de leite morno ou bebida vegetal</li><li>Noz-moscada, sal e pimenta a gosto</li></ul><p><b>Montagem:</b></p><ul><li>1 embalagem de placas de lasanha (frescas ou secas)</li><li>150 g a 200 g de queijo ralado (mozzarella ou vegetal) para gratinar</li></ul><h3>\uD83D\uDC69\u200D\uD83C\uDF73 Preparação</h3><p><b>Preparar os vegetais:</b> Salteie o alho e o alho-francês num fio de azeite. Junte a cenoura e deixe amolecer. Se preferir, pode grelhar as fatias de curgete e beringela numa frigideira com um pouco de azeite até dourarem. Tempere tudo com sal, pimenta e orégãos.</p><p><b>Fazer o molho branco:</b> Derreta a manteiga num tacho em lume brando. Adicione a farinha de trigo e mexa por 1 a 2 minutos. Junte o leite aos poucos, mexendo sempre com uma vara de arames para não criar grumos. Deixe engrossar, tempere com sal, pimenta e uma pitada generosa de noz-moscada.</p><p><b>Montagem:</b> Pré-aqueça o forno a 180°C. Numa travessa de ir ao forno, espalhe uma camada fina de molho branco no fundo. Coloque placas de lasanha e cubra com uma camada de vegetais e mais molho branco. Repita o processo até esgotar os ingredientes, terminando com molho branco e uma camada generosa de queijo ralado.</p><p><b>Cozer:</b> Leve ao forno durante cerca de 30 a 40 minutos (verifique o tempo na embalagem da massa), até a massa estar cozida e o queijo derretido e dourado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_MACARRAO_TOMATE_BASILICO + "', '<h3>Ingredientes (para 4 porções)</h3><ul><li>400g a 500g de massa curta (tipo Penne, Parafuso ou Fusilli)</li><li>2 xícaras de tomates-cereja ou 3 a 4 tomates maduros cortados em cubos</li><li>1 xícara de folhas de manjericão fresco</li><li>1/2 xícara de azeite virgem extra</li><li><b>Opcional:</b> 1 dente de alho picado ou laminado</li><li>Sal e pimenta preta a gosto</li><li><b>Opcional:</b> 200g de muçarela de búfala (em cubos ou bolinhas) e azeitonas pretas</li></ul><h3>Preparação</h3><p><b>Cozer a massa:</b> Numa panela grande com água e sal a ferver, cozinhe o macarrão até ficar al dente (cerca de 8 a 10 minutos, ou conforme a embalagem).</p><p><b>Arrefecer:</b> Escorra a massa e passe-a rapidamente por água fria para interromper a cozedura e deixá-la soltinha. Reserve numa taça grande.</p><p><b>Preparar os ingredientes:</b> Lave bem os tomates e corte-os ao meio ou em quartos. Lave e pique grosseiramente as folhas de manjericão.</p><p><b>Temperar:</b> Numa tigela pequena, misture o azeite, o alho, o sal e a pimenta.</p><p><b>Montar a salada:</b> Junte os tomates, o manjericão e o tempero à massa já fria. Se optar por adicionar queijo ou azeitonas, este é o momento de os envolver no preparado.</p><p><b>Servir:</b> Misture tudo delicadamente e sirva de imediato ou leve ao frigorífico para servir bem fresca.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_ESTUFADO_LENTILHAS_VERMELHAS + "', '<h3>Ingredientes (para 4 doses)</h3><ul><li>250 g de lentilhas vermelhas secas</li><li>1 cebola grande picada</li><li>2 dentes de alho picados</li><li>1 cenoura cortada em cubos pequenos</li><li>400 g de tomate pelado picado ou polpa de tomate</li><li>600 ml a 750 ml de água ou caldo de legumes</li><li>2 c. de sopa de azeite</li><li><b>Especiarias a gosto:</b> 1 c. chá de caril, 1 c. chá de gengibre em pó e 1/2 c. chá de cúrcuma (açafrão-da-índia)</li><li>1 folha de louro</li><li>Sal e pimenta preta a gosto</li><li>Coentros ou salsa fresca picada e sumo de limão para finalizar</li></ul><h3>Preparação</h3><p><b>Preparar as lentilhas:</b> Passe as lentilhas vermelhas por água fria num passador até que a água saia limpa. Não precisam de demolho prolongado, pois cozinham muito rápido.</p><p><b>Fazer o refogado:</b> Num tacho largo, aqueça o azeite em lume médio. Junte a cebola e o alho e deixe alourar até ficarem macios.</p><p><b>Adicionar os vegetais e especiarias:</b> Adicione a cenoura e a folha de louro. Polvilhe com o caril, o gengibre e a cúrcuma, mexendo durante 1 a 2 minutos para libertar os aromas.</p><p><b>Estufar:</b> Junte o tomate e envolva bem. De seguida, adicione as lentilhas escorridas e regue com a água ou caldo de legumes. Tempere com sal e pimenta.</p><p><b>Cozinhar:</b> Deixe levantar fervura, reduza para lume brando, tape o tacho e deixe cozinhar durante cerca de 15 a 20 minutos. Mexa ocasionalmente para não pegar ao fundo e adicione um pouco mais de água se o estufado estiver muito espesso.</p><p><b>Finalizar:</b> Quando as lentilhas estiverem desfeitas em puré cremoso e a cenoura tenra, retire do lume. Retire a folha de louro e envolva o sumo de limão e os coentros picados. Sirva quente, simples ou com arroz basmati.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_HAMBURGUER_FEIJAO_SALADA + "', '<h3>Ingredientes (para 4 a 6 hambúrgueres)</h3><p><b>Para os Hambúrgueres:</b></p><ul><li>480 g de feijão preto (previamente cozido e bem escorrido)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li><b>Opcional:</b> 1/2 pimento vermelho cortado em cubos pequenos</li><li>1 cenoura ralada</li><li>4 a 6 colheres de sopa de pão ralado (ou flocos de aveia/farinha de aveia) para dar liga</li><li>1 colher de sopa de azeite (para refogar)</li><li>1 colher de chá de cominhos em pó</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para a Salada de Acompanhamento:</b></p><ul><li>100 g de folhas verdes variadas (alface, rúcula ou agrião)</li><li>1 tomate médio cortado em cubos</li><li>1/2 cebola roxa cortada em tiras finas</li><li>Sumo de 1/2 limão</li><li>1 colher de sopa de azeite virgem extra</li></ul><h3>Preparação</h3><p><b>Refogado base:</b> Numa frigideira com um fio de azeite, salteie a cebola, o alho e o pimento até ficarem macios. Junte a cenoura ralada e os cominhos, deixe cozinhar por mais 2 minutos e retire do lume.</p><p><b>Misturar:</b> Numa taça grande, coloque o feijão cozido e esmague-o com um garfo, mantendo alguma textura (pode usar um processador de alimentos ou picadora para dar apenas alguns toques, sem transformar em puré).</p><p><b>Massa:</b> Adicione o refogado de vegetais ao feijão esmagado. Tempere com sal e pimenta. Comece a juntar o pão ralado ou a aveia, colher a colher, até obter uma massa consistente e moldável.</p><p><b>Moldar:</b> Humedeça as mãos com um pouco de água para a massa não colar e molde pequenas porções em formato de hambúrguer.</p><p><b>Cozinhar:</b> Aqueça uma frigideira antiaderente com um fio de azeite. Grelhe os hambúrgueres cerca de 4 a 5 minutos de cada lado, até ficarem dourados e crocantes. Se preferir uma versão sem gordura, pode levá-los ao forno (a 180ºC) ou à Air Fryer por cerca de 15 minutos.</p><p><b>Preparar a Salada:</b> Numa saladeira, misture as folhas verdes, o tomate e a cebola roxa. Tempere apenas na altura de servir com o azeite, o sumo de limão e uma pitada de sal.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_QUINOA_AVOCADO + "', '<h3>Ingredientes</h3><p><b>Para preparar esta salada (cerca de 2 a 4 doses), vai precisar de:</b></p<p><b>Base da Salada:</b></p><ul><li>1 chávena de quinoa</li><li>2 chávenas de água (para cozer a quinoa)</li><li>1 avocado ou metade de um abacate grande (cortado em cubos)</li><li>1/2 chávena de tomate-cereja (cortado ao meio)</li><li>1/4 de cebola roxa picada finamente</li><li>Coentro ou salsa fresca picada a gosto</li></ul><p><b>Molho (Vinagrete):</b></p><ul><li>Sumo de 1 limão ou lima</li><li>3 colheres de sopa de azeite extra virgem</li><li>Sal e pimenta preta a gosto</li><li><b>Opcional:</b> 1 colher de chá de mostarda ou mel</li></ul><h3>Preparação</h3><p><b>Cozer a Quinoa:</b> Passe a quinoa por água corrente num coador fino. Numa panela, coloque a quinoa e a água, adicione uma pitada de sal e deixe ferver. Reduza o lume, tape e deixe cozinhar por cerca de 15 minutos, ou até a água ser absorvida. Retire do lume e deixe arrefecer.</p><p><b>Preparar os Vegetais:</b> Enquanto a quinoa arrefece, lave e corte o tomate-cereja, o avocado/abacate e pique a cebola roxa.</p><p><b>Fazer o Molho:</b> Numa taça pequena ou frasco com tampa, misture o azeite, o sumo de limão, a mostarda (se usar), o sal e a pimenta. Agite bem até emulsionar.</p><p><b>Misturar tudo:</b> Numa saladeira grande, coloque a quinoa cozida e fria. Adicione o tomate, a cebola e o avocado.</p><p><b>Temperar:</b> Vele o molho sobre a salada e envolva tudo cuidadosamente para não desfazer o avocado. Polvilhe com as ervas frescas antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_ARROZ_TOMATE_PANADOS_VEG + "', '<h3>Ingredientes</h3><ul><li>4 a 6 bifes de soja texturizada média/grande</li><li>1 colher de sopa de molho de soja</li><li>Alho em pó e pimenta preta a gosto</li><li>Sumo de 1/2 limão</li><li>Farinha de trigo (ou amido de milho) para panar</li><li>Pão ralado para panar</li><li>Óleo para fritar (ou azeite)</li></ul><h3>Preparação</h3><p><b>Demolhar:</b> Coloque os bifes de soja numa taça com água morna e o molho de soja durante cerca de 15 a 20 minutos.</p><p><b>Espremer:</b> Retire os bifes e esprema-os muito bem com as mãos (ou com a ajuda de um pano limpo) para retirar todo o excesso de água. Isto é fundamental para não ficarem moles.</p><p><b>Temperar:</b> Tempere os bifes com alho em pó, pimenta e o sumo de limão. Deixe repousar 10 minutos para ganhar sabor.</p><p><b>Panar:</b> Passe cada bife por farinha (pode criar um polme misturando um pouco de água e farinha para o pão ralado agarrar melhor) e, de seguida, passe-o pelo pão ralado, pressionando bem.</p><p><b>Fritar:</b> Frite os bifes em óleo quente até estarem dourados e estaladiços de ambos os lados. Retire e deixe escorrer em papel absorvente.</p><br><h3>Arroz de Tomate (Malandrinho)</h3><h3>Ingredientes</h3><ul><li>1 chávena de arroz carolino</li><li>3 chávenas de água morna (ou caldo de legumes)</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>2 tomates maduros grandes (ou 4 colheres de sopa de polpa de tomate)</li><li>1 folha de louro</li><li>Azeite a gosto</li><li>Sal e coentros ou salsa fresca picada a gosto</li></ul><h3>Preparação</h3><p><b>Refogado:</b> Num tacho, coloque um fio generoso de azeite e leve ao lume. Junte a cebola picada, os alhos e a folha de louro. Deixe alourar.</p><p><b>Adicionar o Tomate:</b> Junte o tomate cortado em cubos pequenos (sem pele, se preferir) ou a polpa de tomate. Deixe cozinhar até o tomate começar a desfazer-se.</p><p><b>Adicionar o Arroz:</b> Junte o arroz carolino e envolva bem no refogado durante 1 a 2 minutos para ganhar sabor.</p><p><b>Cozer:</b> Vede com a água morna ou o caldo de legumes. Tempere com sal a gosto e deixe ferver. Tape e deixe cozinhar em lume brando durante cerca de 12 a 15 minutos, mexendo ocasionalmente.</p><p><b>Finalizar:</b> Quando o arroz estiver cozido mas ainda caldoso, desligue o lume. Junte coentros ou salsa fresca picada, tape e deixe repousar 2 minutos antes de servir com os panados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_QUICHE_ALHO_FRANCES_COGUMELOS + "', '<h3>Ingredientes</h3><ul><li>1 base de massa quebrada (ou massa folhada)</li><li>250 g a 300 g de cogumelos frescos (ex: Paris ou Portobello) fatiados</li><li>1 alho-francês grande (apenas a parte branca) cortado em rodelas finas</li><li>3 a 4 ovos médios</li><li>200 ml de natas (ou natas vegetais/leite)</li><li>Azeite ou manteiga q.b.</li><li>Sal, pimenta-preta e noz-moscada a gosto</li><li><b>Opcional:</b> 100 g a 150 g de queijo ralado (ex: mozzarella, emmental ou queijo da ilha)</li></ul><h3>Preparação</h3><p><b>Preparar a massa:</b> Pré-aqueça o forno a 180 °C. Forre uma tarteira com a massa (deixando o papel vegetal), pique o fundo com um garfo e reserve.</p><p><b>Saltear os legumes:</b> Numa frigideira grande, aqueça um fio de azeite e adicione o alho-francês. Deixe cozinhar até amolecer e, em seguida, adicione os cogumelos laminados. Tempere com sal e pimenta. Deixe saltear até que a água dos cogumelos evapore.</p><p><b>Fazer o creme (o aparelho):</b> Numa tigela, bata os ovos com as natas. Tempere com uma pitada de sal, pimenta e noz-moscada a gosto. Se optar por usar queijo ralado, pode misturar metade dele neste preparado.</p><p><b>Montagem:</b> Espalhe o preparado de alho-francês e cogumelos uniformemente sobre a massa na tarteira. Verta o creme de ovos e natas por cima, cobrindo todos os legumes. Se desejar, polvilhe com o restante queijo ralado por cima.</p><p><b>Cozer:</b> Leve ao forno a 180 °C durante cerca de 30 a 40 minutos, ou até a massa estar dourada e o recheio firme.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_FEIJAO_FRADE_ATUM_VEG + "', '<h3>Ingredientes</h3><p><b>Para o \"Atum\" Vegano:</b></p><ul><li>2 chávenas de grão-de-bico cozido (ou 1 bloco de tempeh)</li><li>1 colher de chá de alga Nori em pó ou 1 folha de nori picada/hidratada (para o sabor a mar)</li><li>1 colher de sopa de sumo de limão</li><li>1 a 2 colheres de sopa de maionese vegana (ou iogurte vegetal) para dar textura</li><li>1 dente de alho pequeno bem picado</li><li>Sal e pimenta preta a gosto</li></ul><p><b>Para a Salada:</b></p><ul><li>1 frasco ou lata grande de feijão-frade cozido (aprox. 500g)</li><li>1 cebola roxa picada</li><li>100 g de tomate cherry ou tomate em cubos</li><li>Salsa fresca ou coentros picados a gosto</li><li><b>Opcional:</b> Azeitonas pretas</li></ul><p><b>Para o Tempero (Molho Vinagrete):</b></p><ul><li>Azeite virgem extra q.b.</li><li>Vinagre de sidra ou sumo de limão q.b.</li><li>1 colher de chá de mostarda Dijon</li></ul><h3>Preparação</h3><p><b>Preparar o \"Atum\":</b> Numa taça, coloque o grão-de-bico escorrido e amasse-o grosseiramente com um garfo (ou desfaça o tempeh em lascas). Adicione a alga Nori, o sumo de limão, o alho, a maionese vegana, sal e pimenta. Envolva tudo muito bem e reserve.</p><p><b>Preparar o Feijão:</b> Passe o feijão-frade por água corrente para retirar o excesso de sal/conservante e escorra-o bem.</p><p><b>Misturar a Salada:</b> Numa saladeira grande, junte o feijão-frade, a cebola roxa picada, o tomate cortado e a salsa.</p><p><b>Juntar tudo:</b> Adicione o \"atum\" vegano preparado no passo 1 à saladeira e misture tudo delicadamente.</p><p><b>Temperar:</b> Numa pequena taça à parte, emulsione o azeite, o vinagre e a mostarda. Verta o vinagrete sobre a salada e envolva.</p><p><b>Finalizar:</b> Decore com azeitonas pretas e mais salsa ou coentros picados. Leve ao frigorífico para refrescar antes de servir.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MASSA_PESTO_TOMATE_CHERRY + "', '<h3>Ingredientes (para 2 a 3 pessoas)</h3><ul><li><b>Massa:</b> 250 g de massa (ex: penne, fusilli ou espaguete)</li><li><b>Tomates:</b> 200 g de tomate cherry (cortados ao meio)</li><li><b>Molho Pesto:</b> 1 a 2 frascos de molho pesto ou feito em casa (manjericão fresco, azeite, alho, queijo parmesão ralado e pinhões/castanhas)</li><li><b>Gordura:</b> Azeite extra virgem (para saltear)</li><li><b>Tempero:</b> Sal e pimenta preta q.b.</li></ul><h3>Preparação</h3><p><b>Cozer a massa:</b> Numa panela com água a ferver e sal, cozinhe a massa até ficar al dente (verifique o tempo na embalagem). Reserve uma chávena pequena da água de cozedura antes de escorrer.</p><p><b>Saltear os tomates:</b> Numa frigideira grande, aqueça um fio de azeite e adicione os tomates cherry. Deixe cozinhar em lume médio durante 2 a 3 minutos até começarem a amolecer e a libertar os sucos. Tempere com sal e pimenta.</p><p><b>Misturar tudo:</b> Junte a massa cozida e escorrida à frigideira com os tomates.</p><p><b>Adicionar o pesto:</b> Reduza o lume ao mínimo, adicione o molho pesto e envolva tudo. Se a massa estiver muito seca, adicione colheres da água de cozedura que reservou para criar um molho cremoso e brilhante.</p><p><b>Servir:</b> Retire do lume e sirva de imediato, decorado com folhas de manjericão fresco ou queijo parmesão extra a gosto.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_GRATINADO_LEGUMES_PRIMAVERA + "', '<h3>Ingredientes</h3><p><b>Base de Legumes (Primavera):</b></p><ul><li>1 curgete (abobrinha) média cortada em meias-luas</li><li>1 molho de brócolos ou espargos verdes tenros cortados em pedaços</li><li>1 cenoura média cortada em rodelas finas</li><li>100 g de ervilhas frescas ou congeladas</li><li>1 alho-francês (parte branca) cortado em rodelas</li></ul><p><b>Molho Cremoso (Bechamel):</b></p><ul><li>2 colheres de sopa de manteiga</li><li>2 colheres de sopa de farinha de trigo</li><li>500 ml de leite morno</li><li>Sal, pimenta preta e noz-moscada a gosto</li></ul><p><b>Cobertura:</b></p><ul><li>80 g de queijo ralado (emental, mozzarella ou parmesão)</li><li><b>Opcional:</b> Pão ralado q.b. (para uma crosta crocante)</li></ul><h3>Preparação</h3><p><b>Branquear os legumes:</b> Numa panela com água a ferver e sal, coza a cenoura e os espargos/brócolos durante 3 minutos. Adicione a curgete e o alho-francês e deixe cozinhar por mais 2 minutos. Junte as ervilhas, escorra tudo de imediato e reserve.</p><p><b>Preparar o molho:</b> Derreta a manteiga num tacho em lume brando. Junte a farinha e mexa com uma vara de arames durante 1 a 2 minutos. Adicione o leite morno aos poucos, mexendo sempre para não ganhar grumos. Deixe engrossar. Tempere com sal, pimenta e noz-moscada.</p><p><b>Misturar:</b> Envolva os legumes cozidos no molho bechamel.</p><p><b>Gratinar:</b> Transfira o preparado para uma travessa de forno, polvilhe com o queijo ralado e (se desejar) um pouco de pão ralado.</p><p><b>Forno:</b> Leve ao forno pré-aquecido a 200 °C por cerca de 20 minutos, ou até a superfície ficar dourada e crocante.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_LENTILHAS_MACA_NOZ + "', '<h3>Ingredientes</h3><p><b>Para a salada:</b></p><ul><li>200 g de lentilhas (verdes ou castanhas)</li><li>1 a 2 maçãs (tipo Granny Smith ou Fuji)</li><li>40 g de miolo de nozes grosseiramente picadas</li><li>1 cebola roxa pequena, picada finamente</li><li>1 folha de louro</li><li>Salsa fresca picada a gosto</li></ul><p><b>Para o molho (vinagrete):</b></p><ul><li>3 a 4 colheres de sopa de azeite extra virgem</li><li>1 colher de sopa de sumo de limão (ou vinagre de maçã)</li><li><b>Opcional:</b> 1 colher de chá de mostarda Dijon (recomendado)</li><li>Sal e pimenta preta a gosto</li></ul><h3>Preparação</h3><p><b>Cozer as lentilhas:</b> Lave as lentilhas e coloque-as numa panela com água, uma pitada de sal e a folha de louro. Deixe cozinhar até ficarem tenras, mas firmes (cerca de 15 a 20 minutos). Escorra bem e deixe arrefecer.</p><p><b>Preparar a maçã:</b> Lave bem a maçã, descarte o centro e corte-a em cubos pequenos. Se preferir, pode regar a maçã com umas gotas de limão para evitar que oxide e escureça.</p><p><b>Fazer o molho:</b> Numa pequena taça ou frasco, misture o azeite, o sumo de limão, a mostarda, o sal e a pimenta. Agite ou mexa bem até emulsionar.</p><p><b>Misturar:</b> Numa saladeira grande, junte as lentilhas frias, os cubos de maçã, a cebola roxa picada e as nozes.</p><p><b>Temperar:</b> Verta o molho sobre a salada, polvilhe com salsa fresca e envolva tudo delicadamente.</p><p><b>Servir:</b> Pode servir de imediato ou guardar no frigorífico durante 30 minutos para apurar os sabores.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_RISOTO_ABOBORA_NOZ_MOSCADA + "', '<h3>Ingredientes (para 4 pessoas)</h3><ul><li><b>Abóbora:</b> 400g (tipo manteiga/butternut ou cabotiá), descascada e cortada em cubos</li><li><b>Arroz:</b> 300g de arroz arbóreo ou carnaroli</li><li><b>Caldo:</b> 1 litro de caldo de legumes quente (caseiro ou de compra)</li><li><b>Vinho:</b> 100 ml de vinho branco seco</li><li><b>Refogado:</b> 1 cebola picada e 2 dentes de alho picados</li><li><b>Especiarias:</b> Noz-moscada ralada na hora (a gosto) e pimenta-preta</li><li><b>Gordura:</b> 2 colheres de sopa de azeite e 50g de manteiga sem sal</li><li><b>Queijo:</b> 100g de queijo parmesão ralado (de preferência fresco)</li></ul><h3>Preparação</h3><p><b>Preparar o puré de abóbora:</b> Coza metade dos cubos de abóbora em água ou no próprio caldo de legumes até ficarem bem macios. Triture com a varinha mágica até obter um puré liso e reserve. Os restantes cubos de abóbora podem ser salteados em azeite para adicionar pedaços inteiros no final.</p><p><b>Fazer o refogado:</b> Num tacho largo, aqueça o azeite e metade da manteiga. Junte a cebola e o alho, deixando refogar até ficarem translúcidos.</p><p><b>Tostar o arroz:</b> Adicione o arroz arbóreo e mexa durante cerca de 2 minutos para envolver nos sabores e tostar ligeiramente.</p><p><b>Adicionar o vinho:</b> Verta o vinho branco e mexa até que o álcool evapore por completo.</p><p><b>Cozinhar o risoto:</b> Adicione o caldo de legumes quente, uma concha de cada vez, mexendo sempre. Espere que o líquido seja absorvido antes de adicionar a concha seguinte. O processo demora cerca de 15 a 18 minutos.</p><p><b>Adicionar a abóbora:</b> A meio do processo, adicione o puré de abóbora e os cubos inteiros que reservou, envolvendo bem.</p><p><b>Finalizar:</b> Quando o arroz estiver al dente e cremoso, desligue o lume. Junte o queijo parmesão, a restante manteiga, uma pitada generosa de noz-moscada e pimenta. Mexa vigorosamente para emulsionar e obter um resultado brilhante.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CANELONES_RICOTA_ESPINAFRES + "', '<h3>Ingredientes</h3><ul><li>1 embalagem de massa para canelones (aprox. 250 g)</li><li>400 g de espinafres (frescos ou congelados)</li><li>400 g de queijo ricota</li><li>1 cebola picada</li><li>2 dentes de alho picados</li><li><b>Opcional:</b> 1 ovo (para dar liga ao recheio)</li><li>Azeite, sal, pimenta preta e noz-moscada q.b.</li><li>1 frasco de molho de tomate (ou molho béchamel para a base)</li><li>Queijo ralado (mozarela ou parmesão) para gratinar</li></ul><h3>Preparação</h3><p><b>Prepare o Recheio:</b> Numa frigideira com um fio de azeite, refogue a cebola e o alho picados. Junte os espinafres e deixe saltear até murcharem e perderem o excesso de água. Escorra bem e pique finamente.</p><p>Numa taça, esmague o queijo ricota e misture com os espinafres salteados. Tempere com sal, pimenta e noz-moscada a gosto. Se usar, adicione o ovo e misture bem até obter uma pasta homogénea.</p><p><b>Recheie:</b> Transfira a mistura para um saco de pasteleiro (ou utilize uma colher pequena) e preencha os tubos de massa para canelones.</p><p><b>Monte o Prato:</b> Cubra o fundo de uma assadeira com uma camada de molho de tomate ou molho béchamel. Disponha os canelones lado a lado e, por cima, cubra com o restante molho.</p><p>Polvilhe generosamente com queijo ralado.</p><p><b>Coza no Forno:</b> Leve ao forno pré-aquecido a 180 °C durante cerca de 30 a 40 minutos, ou até que a massa esteja cozida e o queijo derretido e dourado.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_QUINOA_MANGA_AMENDOA + "', '<h3>Ingredientes</h3><p><b>Para a base da salada:</b></p><ul><li>1 chávena (chá) de quinoa (branca ou mix)</li><li>2 chávenas (chá) de água (ou caldo de legumes)</li><li>1 manga madura e firme, cortada em cubos</li><li>1/2 chávena (chá) de amêndoas laminadas ou em lascas</li><li>1/2 cebola roxa picada finamente</li><li>Folhas frescas (espinafres, rúcula ou hortelã a gosto)</li></ul><p><b>Para o tempero (vinagrete):</b></p><ul><li>Sumo de 1 limão</li><li>2 a 3 colheres (sopa) de azeite extra virgem</li><li>Sal e pimenta-do-reino a gosto</li></ul><h3>Preparação</h3><p><b>Cozinhar a Quinoa:</b> Lave muito bem a quinoa em água corrente usando um coador fino para remover o sabor amargo natural. Numa panela, coloque a quinoa lavada, a água e uma pitada de sal. Deixe ferver, tape e reduza o lume para o mínimo. Deixe cozinhar durante cerca de 15 minutos, ou até que a água seja totalmente absorvida. Retire do lume e deixe repousar por 5 minutos. Depois, solte os grãos com um garfo e deixe arrefecer.</p><p><b>Tostar as Amêndoas:</b> Numa frigideira pequena e sem óleo, coloque as amêndoas e leve ao lume médio, mexendo sempre, até dourarem ligeiramente e libertarem aroma. Retire e reserve para não queimar.</p><p><b>Preparar o Molho:</b> Numa pequena taça ou frasco, misture o sumo de limão, o azeite, o sal e a pimenta-do-reino. Mexa bem até emulsionar.</p><p><b>Montagem:</b> Numa saladeira grande, coloque a quinoa já fria. Junte a cebola roxa, os cubos de manga, as folhas verdes escolhidas e as amêndoas tostadas.</p><p><b>Finalização:</b> Regue a salada com o molho preparado e envolva tudo delicadamente.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CARIL_VEGETAIS_COCO_LEVE + "', '<h3>Ingredientes Base</h3><ul><li>1 lata (400 ml) de leite de coco</li><li>1 cebola média picada</li><li>2 dentes de alho picados</li><li>1 pedaço de gengibre fresco ralado (cerca de 2 cm)</li><li><b>Vegetais variados (pode ajustar ao seu gosto):</b></li><ul><li>1 curgete em cubos</li><li>1 cenoura em rodelas</li><li>1 chávena de brócolos em raminhos</li></ul><li><b>Opcional:</b> 1 chávena de grão-de-bico cozido (para proteína)</li><li>1 a 2 colheres de sopa de óleo de coco ou azeite</li><li><b>Especiarias:</b> 1 a 2 c. de sopa de pó de caril, 1 c. de chá de curcuma (açafrão-das-índias), 1/2 c. de chá de cominhos</li><li>Sal e pimenta preta a gosto</li><li>Coentros frescos picados (para guarnecer)</li></ul><h3>Preparação passo a passo</h3><p><b>Refogado inicial:</b> Num tacho largo ou wok, aqueça o óleo de coco em lume médio. Adicione a cebola, o alho e o gengibre, e deixe refogar até a cebola ficar translúcida.</p><p><b>Adicionar especiarias:</b> Junte o caril em pó, a curcuma e os cominhos ao refogado. Mexa e deixe tostar durante cerca de 1 minuto para libertar os aromas.</p><p><b>Cozinhar os vegetais:</b> Adicione os vegetais mais rijos primeiro (como a cenoura) e envolva bem nas especiarias. Junte um pouco de água (cerca de 50 ml) para não queimar, tape e deixe cozinhar por 3 a 5 minutos.</p><p><b>Adicionar o coco e os vegetais tenros:</b> Junte os restantes vegetais (curgete, brócolos e o grão-de-bico, se usar) e verta o leite de coco por cima. Tempere com sal e pimenta.</p><p><b>Apurar:</b> Tape o tacho e deixe ferver em lume brando durante 10 a 15 minutos, ou até que os vegetais estejam tenros mas não desfeitos.</p><p><b>Servir:</b> Retire do lume, rectifique os temperos se necessário, e polvilhe generosamente com coentros frescos picados. Acompanhe com arroz basmati.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALTEADO_TOFU_LEGUMES_CROCANTES + "', '<h3>Ingredientes (2 a 3 pessoas)</h3><p><b>Para a base e o tofu:</b></p><ul><li>1 embalagem de tofu firme (aprox. 400 g)</li><li><b>Opcional:</b> 1 colher de sopa de amido de milho (para um tofu mais crocante)</li><li>2 colheres de sopa de azeite</li></ul><p><b>Para os legumes crocantes:</b></p><ul><li>1 cenoura média, cortada em tiras finas ou rodelas</li><li>1 pimento vermelho, cortado em tiras</li><li>150 g de brócolos, cortados em floretes pequenos</li><li>100 g de cogumelos frescos, laminados</li><li>1 dente de alho, picado</li><li><b>Opcional:</b> 1 cm de gengibre fresco, ralado</li></ul><p><b>Para o molho e finalização:</b></p><ul><li>3 colheres de sopa de molho de soja (shoyu)</li><li><b>Opcional:</b> 1 colher de sopa de óleo de sésamo (confere um aroma asiático autêntico)</li><li>Sementes de sésamo a gosto</li></ul><h3>Preparação</h3><p><b>Preparar o tofu:</b> Envolva o bloco de tofu em papel de cozinha ou num pano limpo e pressione suavemente para retirar o excesso de água. Corte-o em cubos e, se desejar uma crosta mais estaladiça, polvilhe os cubos com amido de milho.</p><p><b>Dourar o tofu:</b> Aqueça uma colher de sopa de azeite numa frigideira larga ou wok. Adicione o tofu e deixe saltear em lume médio-alto até ficar dourado e crocante de todos os lados (cerca de 5 minutos). Tempere com uma pitada de sal, retire da frigideira e reserve.</p><p><b>Saltear os legumes:</b> Na mesma frigideira ou wok, adicione a colher de sopa de azeite restante. Junte o alho e o gengibre e salteie por 30 segundos. Adicione a cenoura, o pimento, os brócolos e os cogumelos. Salteie em lume alto durante 6 a 8 minutos, mexendo sempre, para que fiquem cozinhados mas mantenham a textura crocante.</p><p><b>Finalizar:</b> Volte a colocar o tofu na frigideira com os legumes. Regue com o molho de soja e o óleo de sésamo. Misture tudo durante 1 a 2 minutos para apurar os sabores.</p><p><b>Servir:</b> Polvilhe com sementes de sésamo e sirva quente, podendo acompanhar com arroz basmati ou noodles.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_TOMATE_OVO_ESCALFADO + "', '<h3>Ingredientes</h3><ul><li>1 kg a 1,5 kg de tomate bem maduro (cortado em pedaços e sem pele)</li><li>1 a 2 cebolas médias (picadas ou em meia-lua)</li><li>2 a 3 dentes de alho (picados)</li><li>4 a 6 ovos</li><li>Azeite q.b.</li><li>Sal e pimenta preta q.b.</li><li>1 pitada de açúcar (para equilibrar a acidez do tomate)</li><li><b>Opcional:</b> 1 folha de louro</li><li>1 ramo de hortelã ou coentros frescos</li><li>Pão de trigo fatiado (preferencialmente pão alentejano ou de fermentação natural)</li></ul><h3>Preparação</h3><p><b>Fazer o refogado:</b> Num tacho largo, leve ao lume o azeite, a cebola e os alhos (e a folha de louro, se usar). Deixe refogar em lume brando até a cebola ficar translúcida.</p><p><b>Adicionar o tomate:</b> Junte os tomates cortados e sem pele. Tempere com sal, pimenta e a pitada de açúcar. Deixe apurar até o tomate começar a desfazer-se.</p><p><b>Adicionar água:</b> Acrescente cerca de 1 litro a 1,5 litros de água (dependendo se prefere a sopa mais rala ou mais espessa). Deixe ferver por cerca de 15 minutos.</p><p><b>Triturar (Opcional):</b> Pode triturar a base da sopa com a varinha mágica para obter um caldo aveludado, ou deixá-la rústica com os pedaços de tomate.</p><p><b>Escalfar os ovos:</b> Com o caldo a ferver suavemente, abra os ovos cuidadosamente e coloque-os dentro da sopa, um a um. Tape o tacho e deixe escalfar durante 3 a 4 minutos, até as claras estarem sólidas mas as gemas ainda líquidas.</p><p><b>Servir:</b> Coloque fatias de pão no fundo da taça ou prato, disponha um ovo escalfado por cima, verta a sopa de tomate bem quente e polvilhe com folhas de hortelã ou coentros picados.</p>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_MACARRAO_PESTO_RUCULA + "', '<h3>Ingredientes:</h3><ul><li>Massa, pesto, rúcula fresca</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Massa com pesto.</li><li><b>Servir:</b> Sobre cama de rúcula.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_EMPADAO_VEGETARIANO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas estufadas, puré de batata</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Lentilhas por baixo.</li><li><b>Assar:</b> Puré por cima no forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAELLA_VEGETARIANA_PRIMAVERA + "', '<h3>Ingredientes:</h3><ul><li>Arroz, ervilhas, espargos, açafrão</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estilo paella com legumes frescos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_GRAO_MEDITERRANICA + "', '<h3>Ingredientes:</h3><ul><li>Grão, tomate, pepino, azeitonas</li><li>Orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Todos os ingredientes.</li><li><b>Temperar:</b> Com bom azeite.</li></ol>');");

        // ==========================================
// JANTARES - MAIO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_ALFACE_HORTELA_LEVE + "', '<h3>Ingredientes:</h3><ul><li>1 alface média limpa</li><li>1 batata e 1 cebola</li><li>4 folhas de hortelã fresca</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve a batata e a cebola cortadas a cozer num tacho com água e sal.</li><li><b>Verdes:</b> Adicione a alface em tiras finas e as folhas de hortelã nos minutos finais.</li><li><b>Triturar:</b> Reduza a um creme aveludado com a varinha mágica e junte um fio de azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TOFU_GRELHADO_SALADA_VERDE + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>Mistura de alfaces frescas</li><li>Folhas de rúcula selvagem</li><li>Azeite e sumo de limão</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Corte o tofu em fatias médias e grelhe numa chapa bem quente até dourar de ambos os lados.</li><li><b>Salada:</b> Numa taça, junte a alface e a rúcula bem lavadas.</li><li><b>Servir:</b> Disponha o tofu por cima dos verdes e tempere com azeite e sumo de limão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_GASPACHO_TOMATE_PEPINO + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros grandes</li><li>1/2 pepino e 1/2 pimento verde</li><li>Azeite, vinagre e água fresca</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Lave e limpe todos os legumes de sementes e peles mais grossas.</li><li><b>Triturar:</b> Coloque tudo no liquidificador com um fio de azeite, vinagre e um pouco de água.</li><li><b>Arrefecer:</b> Misture bem até ficar homogéneo e leve ao frigorífico antes de servir bem fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_TOMATE_MOZZARELLA_BASILICO + "', '<h3>Ingredientes:</h3><ul><li>2 tomates chucha firmes</li><li>100 g de queijo mozarela fresco</li><li>Folhas de manjericão fresco</li><li>Azeite e orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Corte os tomates e o queijo mozarela fresco em rodelas com espessuras semelhantes.</li><li><b>Montar:</b> Intercale as rodelas num prato de servir e decore com as folhas de manjericão.</li><li><b>Tempero:</b> Regue com um fio de azeite virgem extra e polvilhe com uma pitada de orégãos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_CENOURA_GENGIBRE_LEVE + "', '<h3>Ingredientes:</h3><ul><li>4 cenouras médias</li><li>1 cebola pequena</li><li>1 colher de chá de gengibre ralado</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza as cenouras e a cebola num tacho com água temperada com uma pitada de sal.</li><li><b>Aromatizar:</b> Adicione o gengibre fresco ralado e triture tudo muito bem com a varinha mágica.</li><li><b>Finalizar:</b> Incorpore um fio de azeite em cru e mexa a sopa antes de servir bem quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_COGUMELOS_SALTEADOS_ERVAS_FRESCAS + "', '<h3>Ingredientes:</h3><ul><li>250 g de cogumelos frescos laminados</li><li>2 dentes de alho picados</li><li>Salsa e coentros frescos</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Alho:</b> Aloure o alho picado numa frigideira larga com um fio generoso de azeite.</li><li><b>Saltear:</b> Junte os cogumelos laminados em lume forte, mexendo até perderem a humidade.</li><li><b>Ervas:</b> Tempere com sal e polvilhe abundantemente com a salsa e os coentros picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_FEIJAO_VERDE_MASSA_LEVE + "', '<h3>Ingredientes:</h3><ul><li>150 g de feijão verde</li><li>1 batata e 1 cenoura</li><li>2 colheres de sopa de massa pevide</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza a batata e a cenoura e triture para fazer a base cremosa da sopa.</li><li><b>Legume:</b> Corte o feijão verde em tiras finas e adicione à base juntamente com a massa pevide.</li><li><b>Apurar:</b> Deixe ferver em lume brando por 10 minutos até a massa estar cozida. Junte o azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_RUCULA_MORANGO_FETA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de rúcula selvagem</li><li>1/2 chávena de morangos fatiados</li><li>50 g de queijo feta em cubos</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Faça uma cama com as folhas de rúcula bem lavadas no fundo de uma saladeira.</li><li><b>Elementos:</b> Distribua as fatias de morango e os cubos de queijo feta por cima.</li><li><b>Servir:</b> Regue suavemente com um fio de azeite virgem extra mesmo antes de levar à mesa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_BROCOLOS_LEVE + "', '<h3>Ingredientes:</h3><ul><li>1 cabeça de brócolos média</li><li>1 batata pequena e 1 cebola</li><li>Azeite e uma pitada de sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Separe os brócolos em floretes e coza-os com a batata e a cebola num tacho com água.</li><li><b>Processar:</b> Triture os legumes com a varinha mágica até conseguir um creme liso e homogéneo.</li><li><b>Azeite:</b> Retifique os temperos, adicione um fio de azeite em cru e envolva na sopa quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_OMELETE_ESPINAFRES_QUEIJO + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros</li><li>1 chávena de espinafres frescos</li><li>30 g de queijo ralado magro</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Murchar os espinafres numa frigideira antiaderente com uma gota de azeite e reserve.</li><li><b>Cozinhar:</b> Bata os ovos, verta na frigideira e recheie com os espinafres e o queijo ralado.</li><li><b>Dobrar:</b> Dobre a omelete ao meio quando a base estiver firme e deixe dourar ligeiramente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_LEGUMES_DA_HORTA + "', '<h3>Ingredientes:</h3><ul><li>1/4 de abóbora limpa</li><li>1 cenoura e 1 nabo</li><li>1 chávena de couve-coração cortada</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Coza a abóbora, a cenoura e o nabo em pedaços e triture até formar o caldo.</li><li><b>Couve:</b> Adicione a couve-coração cortada em tiras finas e leve de novo ao lume.</li><li><b>Finalizar:</b> Cozinhe por mais 10 minutos, adicione um fio de azeite e retifique o sal.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_RUSSA_VEGETARIANA + "', '<h3>Ingredientes:</h3><ul><li>2 batatas e 1 cenoura grande</li><li>1/2 chávena de ervilhas cozidas</li><li>3 colheres de sopa de maionese vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Cubos:</b> Descasque as batatas e a cenoura, corte em cubos pequenos e coza em água e sal.</li><li><b>Arrefecer:</b> Escorra os legumes cozidos juntamente com as ervilhas e deixe arrefecer por completo.</li><li><b>Envolver:</b> Misture os vegetais delicadamente com a maionese vegetal numa taça e sirva fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_ABOBORA_SEMENTES_GIRASSOL + "', '<h3>Ingredientes:</h3><ul><li>400 g de abóbora</li><li>1 alho-francês em rodelas</li><li>2 colheres de sopa de sementes de girassol</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Sopa:</b> Coza a abóbora e o alho-francês limpos num tacho com água. Triture até fazer um creme.</li><li><b>Sementes:</b> Toste as sementes de girassol numa frigideira antiaderente seca durante 2 minutos.</li><li><b>Topping:</b> Sirva a sopa quente nos pratos com as sementes tostadas espalhadas por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TOFU_MEXIDO_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1/2 pimento vermelho picado</li><li>1 chávena de espinafres e uma pitada de curcuma</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Desfaça o bloco de tofu com um garfo até obter uma textura semelhante a migas.</li><li><b>Saltear:</b> Cozinhe o pimento e os espinafres numa frigideira com um fio de azeite até murcharem.</li><li><b>Envolver:</b> Junte o tofu e a curcuma, mexendo continuamente durante 5 minutos em lume brando.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_LENTILHAS_VERMELHAS_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas vermelhas</li><li>1 cenoura e 1 cebola</li><li>Coentros frescos picados e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Leve as lentilhas vermelhas, a cenoura e a cebola a cozer num tacho com água abundante.</li><li><b>Puré:</b> Triture tudo com a varinha mágica até conseguir uma textura aveludada e cremosa.</li><li><b>Servir:</b> Adicione o azeite e polvilhe generosamente com os coentros frescos picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_GREGA_SIMPLES + "', '<h3>Ingredientes:</h3><ul><li>1 pepino médio</li><li>1 tomate maduro firme</li><li>50 g de queijo feta em cubos</li><li>Azeitonas pretas e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Corte o pepino com casca e o tomate em pedaços médios regulares.</li><li><b>Juntar:</b> Coloque os vegetais numa taça, junte os cubos de queijo feta e as azeitonas pretas.</li><li><b>Tempero:</b> Regue com azeite virgem extra e polvilhe com uma chuva de orégãos secos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_COUVE_FLOR_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>1/2 couve-flor</li><li>1 alho-francês (parte branca)</li><li>Azeite, sal e uma pitada de noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte os floretes de couve-flor e o alho-francês em rodelas finas.</li><li><b>Cozer:</b> Coza os legumes em água temperada com sal e de seguida triture até ficar cremoso.</li><li><b>Especiaria:</b> Junte o fio de azeite e aromatize com uma pitada leve de noz-moscada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_WRAP_TOFU_SALADA + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha ou wrap integral</li><li>100 g de tofu em tiras finas</li><li>Folhas de alface e cenoura ralada</li></ul><h3>Preparação:</h3><ol><li><b>Tofu:</b> Salteie as tiras finas de tofu numa frigideira antiaderente com um fio de azeite até dourarem.</li><li><b>Rechear:</b> Aqueça a tortilha integral, disponha a alface, a cenoura ralada e as tiras de tofu.</li><li><b>Enrolar:</b> Dobre as extremidades da tortilha e enrole firmemente antes de cortar ao meio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_GRAO_ESPINAFRES_LEVE + "', '<h3>Ingredientes:</h3><ul><li>200 g de grão de bico cozido</li><li>1 cenoura e 1 cebola</li><li>1 chávena de folhas de espinafres novos</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Coza a cenoura e a cebola. Triture-as juntamente com metade do grão de bico cozido.</li><li><b>Adicionar:</b> Introduza o restante grão inteiro e as folhas de espinafres lavadas no caldo obtido.</li><li><b>Ferver:</b> Deixe apurar por 5 minutos em lume brando e termine com o azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_ESPINAFRE_MACA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>Folhas de espinafres novos limpas</li><li>1 maçã vermelha com casca</li><li>30 g de nozes picadas e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Lave bem a maçã e corte em fatias ou lamelas muito finas.</li><li><b>Montagem:</b> Numa saladeira coloque os espinafres novos, distribua a maçã e salpique com as nozes.</li><li><b>Tempero:</b> Regue ligeiramente com um fio de azeite virgem extra e envolva com cuidado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_ERVILHAS_HORTELA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>300 g de ervilhas</li><li>1 cebola média</li><li>3 folhas de hortelã fresca</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as ervilhas e a cebola cortada a cozer num tacho com água e uma pitada de sal.</li><li><b>Triturar:</b> Junte as folhas de hortelã frescas e processe tudo com a varinha mágica até ficar aveludado.</li><li><b>Servir:</b> Finalize com um fio de azeite por cima e sirva morna ou quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_OVOS_ESTRELADOS_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros</li><li>200 g de tomate maduro picado</li><li>1/2 cebola e 1 dente de alho</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Refogue a cebola e o alho picados em azeite, junte o tomate e deixe apurar até amaciar.</li><li><b>Ovos:</b> Abra os ovos cuidadosamente sobre o molho de tomate na frigideira.</li><li><b>Cozinhar:</b> Tape a frigideira e deixe cozinhar em lume brando até as claras ficarem firmes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_MINESTRONE_LEVE + "', '<h3>Ingredientes:</h3><ul><li>1 cenoura, 1/2 curgete e 1 aipo</li><li>1/2 de chávena de feijão branco cozido</li><li>Polpa de tomate e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Corte todos os vegetais em cubos muito pequenos e leve a cozer com a polpa de tomate e água.</li><li><b>Feijão:</b> Quando os legumes estiverem tenros, adicione o feijão branco cozido para apurar sabores.</li><li><b>Finalizar:</b> Desligue o lume, regue com o azeite e retifique o sal se for necessário.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_BETERRABA_LARANJA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 beterraba cozida</li><li>1 laranja doce sem caroços</li><li>30 g de nozes partidas e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte a beterraba em cubos finos. Descasque a laranja e separe em gomos pequenos.</li><li><b>Misturar:</b> Junte a beterraba e a laranja numa travessa rasa e salpique com os pedaços de nozes.</li><li><b>Tempero:</b> Regue o preparado com um fio de azeite virgem extra no momento de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_COURGETTE_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>2 curgetes com casca</li><li>1 cebola média</li><li>1 meio molho de coentros frescos</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Lave bem as curgetes, corte em pedaços com a pele e coza com a cebola em água.</li><li><b>Ervas:</b> Adicione os coentros frescos mesmo antes de desligar o lume do tacho.</li><li><b>Triturar:</b> Use a varinha mágica até obter um creme verde e finalize com um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PORTOBELLO_GRELHADO_ERVAS + "', '<h3>Ingredientes:</h3><ul><li>1 cogumelo Portobello grande</li><li>1 dente de alho esmagado</li><li>Misto de ervas finas secas</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Limpar:</b> Limpe bem o cogumelo e retire o talo central. Tempere com o alho e sal.</li><li><b>Grelhar:</b> Coloque na chapa quente untada com azeite e grelhe cerca de 4 minutos de cada lado.</li><li><b>Servir:</b> Polvilhe o chapéu do cogumelo quente com a mistura de ervas finas secas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_TOMATE_ARROZ_LEVE + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros esmagados</li><li>1 cebola picada</li><li>2 colheres de sopa de arroz</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça um refogado leve com a cebola e o azeite, adicionando depois o tomate maduro.</li><li><b>Arroz:</b> Verta água a ferver, junte as colheres de arroz e tempere com uma pitada de sal.</li><li><b>Cozinar:</b> Mantenha em lume brando durante 15 minutos até o arroz estar perfeitamente cozido.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_ALFACE_MILHO_ABACATE + "', '<h3>Ingredientes:</h3><ul><li>Folhas de alface variadas</li><li>1/2 de chávena de milho doce</li><li>1/2 abacate maduro em fatias</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Lave as folhas de alface e corte-as para o fundo de uma taça larga.</li><li><b>Adicionar:</b> Junte o milho doce escorrido e distribua as fatias de abacate fresco por cima.</li><li><b>Tempero:</b> Regue com um fio de azeite virgem extra e envolva os ingredientes com suavidade.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CREME_ESPARGOS_VERDES_LEVE + "', '<h3>Ingredientes:</h3><ul><li>1 molho de espargos verdes</li><li>1 batata pequena e 1 cebola</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Remova a extremidade lenhosa dos espargos e corte os talos tenros em pedaços.</li><li><b>Cozer:</b> Leve a cozer com a batata e a cebola num tacho com água temperada com sal.</li><li><b>Triturar:</b> Reduza tudo a um creme liso com a varinha mágica e adicione um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TOFU_SALTEADO_SOJA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em cubos</li><li>1 colher de chá de gengibre ralado</li><li>1 colher de sopa de molho de soja</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Aromatizar:</b> Salteie o gengibre fresco ralado numa frigideira com um fio de azeite quente.</li><li><b>Tofu:</b> Adicione os cubos de tofu e deixe saltear bem até ficarem com os lados dourados.</li><li><b>Finalizar:</b> Regue com o molho de soja, envolva por mais 1 minuto e retire do lume.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_CEBOLA_LEVE + "', '<h3>Ingredientes:</h3><ul><li>3 cebolas grandes cortadas finas</li><li>500 ml de caldo de vegetais caseiro</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Caramelizar:</b> Cozinhe as rodelas de cebola no azeite em lume brando até dourarem muito bem.</li><li><b>Apurar:</b> Junte o caldo de vegetais quente, retifique o sal e tape o tacho.</li><li><b>Ferver:</b> Deixe a sopa ferver por 15 minutos para apurar completamente todos os sabores da cebola.</li></ol>');");

        // ==========================================
// PEQUENOS-ALMOÇOS - JUNHO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_WAFFLE_TRIGO_SARRACENO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de trigo sarraceno</li><li>150 ml de bebida de amêndoa</li><li>1 colher de chá de fermento em pó</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha de trigo sarraceno, o fermento e a bebida de amêndoa numa taça até obter um preparado homogéneo.</li><li><b>Cozinhar:</b> Verta a massa na máquina de waffles previamente aquecida e untada. Deixe cozer até ficar bem dourada e estaladiça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PANQUECA_ESPINAFRE_COGUMELO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de aveia triturada</li><li>1 ovo médio e 1 punhado de espinafres</li><li>1/2 chávena de cogumelos salteados</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque a aveia, o ovo e os espinafres frescos no liquidificador e triture até formar uma massa esverdeada.</li><li><b>Cozzer:</b> Faça a panqueca numa frigideira antiaderente quente. Adicione os cogumelos salteados no centro e dobre a meio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BATIDO_CELESTE_SPIRULINA + "', '<h3>Ingredientes:</h3><ul><li>1 banana congelada em rodelas</li><li>200 ml de bebida de arroz fresca</li><li>1 colher de café de espirulina em pó</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificar:</b> Introduza as rodelas de banana congelada, a bebida de arroz e a espirulina no copo do liquidificador.</li><li><b>Bater:</b> Processe na velocidade máxima até atingir uma consistência de batido cremoso com um tom azulado único.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_AVEIA_FORNO_NOZES + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de aveia inteiros</li><li>150 ml de bebida vegetal à escolha</li><li>4 miolos de noz picados e canela</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva a aveia em flocos, a bebida vegetal e uma pitada de canela diretamente num pequeno recipiente refratário.</li><li><b>Assar:</b> Espalhe os miolos de noz picados na superfície e leve ao forno a 180 graus durante 15 minutos até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TORRADA_TAPENADE_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grande de pão integral</li><li>1 colher de sopa de tapenade de azeitona</li><li>3 fatias finas de tomate maduro</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque a fatia de pão integral a tostar na torradeira até ficar bem crocante.</li><li><b>Montar:</b> Barre o tapenade de azeitona sobre o pão quente e cubra harmonicamente com as fatias de tomate fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_GRANOLA_SALGADA_IOGURTE + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural denso</li><li>2 colheres de sopa de granola salgada caseira</li><li>Sementes de abóbora e tomilho</li></ul><h3>Preparação:</h3><ol><li><b>Servir:</b> Verta o iogurte natural denso para o fundo de uma taça de pequeno-almoço.</li><li><b>Finalizar:</b> Adicione a granola salgada crocante por cima e salpique com as sementes e um toque de tomilho fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SUMO_PRENSADO_CENOURA_TURMERIC + "', '<h3>Ingredientes:</h3><ul><li>2 cenouras médias limpas</li><li>1 maçã com casca</li><li>1 rodela pequena de curcuma fresca</li></ul><h3>Preparação:</h3><ol><li><b>Extrair:</b> Passe as cenouras, a maçã e a rodela de curcuma fresca pela centrifugadora ou extrator de sumos.</li><li><b>Consumir:</b> Mexa bem o líquido obtido com uma colher e sirva de imediato num copo alto bem fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_MACA_ASSADA_RECHEADA_CHIA + "', '<h3>Ingredientes:</h3><ul><li>1 maçã reineta ou gala grande</li><li>1 colher de sopa de sementes de chia</li><li>1 colher de chá de mel silvestre e canela</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Remova cuidadosamente o caroço central da maçã sem perfurar totalmente a base.</li><li><b>Rechear:</b> Coloque as sementes de chia e o mel no interior da cavidade, polvilhe com canela e asse no micro-ondas ou forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PUDIM_LINHACA_LEITE_AVELA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sementes de linhaça moídas</li><li>200 ml de leite de avelã</li><li>Bagas frescas para decorar</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte as sementes de linhaça moídas e o leite de avelã num copo ou frasco de vidro.</li><li><b>Repousar:</b> Mexa energeticamente e deixe descansar no frigorífico por 30 minutos até espessar. Decore com as bagas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_GALETTE_FRANQUESA_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de aveia integral</li><li>2 colheres de sopa de água</li><li>4 morangos grandes fatiados</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha e a água até conseguir moldar uma bola de massa fina. Estenda com um rolo.</li><li><b>Recheio:</b> Disponha os morangos fatiados no centro, dobre as bordas da massa para dentro e leve ao forno a dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SCOTTISH_OATS_SALGADAS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia grossos</li><li>250 ml de água</li><li>Uma pitada de sal e um fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Leve os flocos de aveia ao lume com a água e a pitada de sal, mexendo sempre até criar uma papa cremosa.</li><li><b>Tempero:</b> Transfira para uma taça funda e finalize adicionando um fio de azeite fino em cru antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_MUFFIN_AVEIA_CENOURA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de aveia</li><li>1/2 cenoura ralada finamente</li><li>3 nozes picadas e 1 ovo</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Numa tigela, junte a aveia, a cenoura ralada, as nozes picadas e o ovo batido até ligar bem.</li><li><b>Cozinhar:</b> Distribua o preparado por formas de queque e leve ao forno a 180 graus durante cerca de 15 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TORRADA_RICOTA_RABANETE_ASSADO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio rústico</li><li>2 colheres de sopa de queijo ricota</li><li>3 rabanetes fatiados e assados</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste a fatia de pão de centeio rústico na torradeira até ficar bem firme.</li><li><b>Montagem:</b> Espalhe o queijo ricota cremoso na torrada e cubra com as rodelas de rabanete previamente assadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BATIDO_PROTEICO_ERVIHA_CACAU + "', '<h3>Ingredientes:</h3><ul><li>1 colher de sopa de proteína de ervilha em pó</li><li>1 colher de chá de cacau puro</li><li>200 ml de bebida de aveia</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Junte a proteína de ervilha, o cacau em pó puro e a bebida de aveia no liquidificador.</li><li><b>Bater:</b> Processe os ingredientes na velocidade máxima até obter um batido proteico sedoso e sem grumos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREPE_AVEIA_COMPOTA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de aveia</li><li>50 ml de água ou clara de ovo</li><li>1 colher de sopa de compota de abóbora</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Misture a aveia com a água ou clara de ovo e coza numa frigideira antiaderente como um crepe muito fino.</li><li><b>Rechear:</b> Espalhe a compota de abóbora caseira sobre o crepe e enrole cuidadosamente antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TACA_QUINOA_INFLADA_FRUTOS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de quinoa inflada pura</li><li>1 iogurte vegetal natural</li><li>Mistura de frutos vermelhos frescos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque o iogurte vegetal natural no fundo de uma taça larga de pequeno-almoço.</li><li><b>Adicionar:</b> Cubra com a quinoa inflada crocante e decore com os frutos vermelhos lavados no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PANQUECA_CHARUTO_REQUEIJAO + "', '<h3>Ingredientes:</h3><ul><li>1 ovo e 2 colheres de farinha de espelta</li><li>50 g de requeijão magro desfeito</li><li>1 colher de chá de mel</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Faça uma panqueca larga e fina numa frigideira antiaderente com a farinha e o ovo batido.</li><li><b>Enrolar:</b> Recheie o interior com o requeijão magro desfeito, regue com o mel e enrole firmemente em formato de charuto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BARRINHA_AVEIA_TARTARO_FRUTA + "', '<h3>Ingredientes:</h3><ul><li>1 barrinha de aveia integral simples</li><li>1/4 de manga e 1/2 kiwi em cubos</li><li>Sumo de lima fresco</li></ul><h3>Preparação:</h3><ol><li><b>Fruta:</b> Pique a manga e o kiwi em cubos milimétricos e misture com umas gotas de sumo de lima.</li><li><b>Acompanhar:</b> Coloque a barrinha de aveia no prato e cubra com o tártaro refrescante de frutas tropicais.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SCONES_INTEGRAIS_PASSO_OESTE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de trigo integral</li><li>60 ml de bebida vegetal de soja</li><li>1 colher de sopa de passas de uva</li></ul><h3>Preparação:</h3><ol><li><b>Amassar:</b> Envolva a farinha integral, a bebida vegetal e as passas de uva até obter uma massa moldável.</li><li><b>Forno:</b> Divida em pequenas porções redondas num tabuleiro e leve ao forno a 180 graus até crescerem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BATIDO_VERDE_COUVE_GALEGA_MACA + "', '<h3>Ingredientes:</h3><ul><li>1 folha de couve galega sem o talo</li><li>1 maçã verde com casca picada</li><li>150 ml de água de coco</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Lave muito bem a couve galega e a maçã verde. Corte tudo em pedaços pequenos.</li><li><b>Bater:</b> Coloque os ingredientes no liquidificador com a água de coco e triture na velocidade máxima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_FOCACCIA_ALECRIM_TOMATE_CHERRY + "', '<h3>Ingredientes:</h3><ul><li>1 fatia média de focaccia caseira</li><li>4 tomates cherry fatiados</li><li>Alecrim fresco e um fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça a fatia de focaccia ligeiras batidas no forno ou na torradeira para reativar os aromas.</li><li><b>Decorar:</b> Disponha os tomates cherry por cima, junte o alecrim fresco e termine com o fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PUDIM_TAPIOCA_LEITE_COCO + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de pérolas de tapioca</li><li>200 ml de leite de coco leve</li><li>Raspas de lima fresca</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Leve as pérolas de tapioca ao lume com o leite de coco, mexendo sempre até ficarem transparentes.</li><li><b>Arrefecer:</b> Verta para uma taça, deixe arrefecer por completo e finalize com as raspas de lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TORRADA_MANTEIGA_SEMENTES_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de sementes integral</li><li>1 colher de sobremesa de manteiga de sementes de abóbora</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Coloque a fatia de pão de sementes a tostar na torradeira até atingir o ponto desejado.</li><li><b>Barrar:</b> Espalhe uma camada uniforme de manteiga pura de sementes de abóbora sobre a torrada morna.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PAPA_PAINCO_CREMOSA_CANELA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de painço em grão</li><li>250 ml de leite magro ou bebida vegetal</li><li>Canela em pó para polvilhar</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Lave o painço e leve a cozer no leite em lume brando, mexendo regularmente até ficar muito macio.</li><li><b>Servir:</b> Coloque a papa cremosa numa taça individual e decore polvilhando abundantemente com canela.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CRUMPETS_AVEIA_GELEIA_FRUTA + "', '<h3>Ingredientes:</h3><ul><li>1 crumpet de aveia espesso</li><li>1 colher de sobremesa de geleia de fruta pura</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Toste ligeiramente o crumpet de aveia na torradeira para que o interior fique macio e a base estaladiça.</li><li><b>Barrar:</b> Retire e espalhe a geleia de fruta sem açúcares adicionados sobre a superfície furada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BOLO_CHAVENA_CACAO_MICROONDAS + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de aveia</li><li>1 colher de chá de cacau puro</li><li>1 ovo e 2 colheres de leite</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte todos os ingredientes diretamente no interior de uma chávena e mexa bem com um garfo.</li><li><b>Cozimento:</b> Coloque no micro-ondas na potência máxima durante 1 minuto a 1 minuto e meio até expandir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TORRADA_PATE_LENTILHAS_ERVAS + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico alentejano</li><li>2 colheres de sopa de paté de lentilhas caseiro</li><li>Ervas frescas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Prepare uma torrada bem estaladiça com a sua fatia de pão rústico alentejano.</li><li><b>Finalizar:</b> Barre o paté de lentilhas cremoso na torrada e salpique com as ervas frescas picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BATIDO_GOIABA_POLPA_COCO + "', '<h3>Ingredientes:</h3><ul><li>1 goiaba madura descascada</li><li>2 colheres de sopa de polpa de coco fresco</li><li>150 ml de água de coco</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificar:</b> Introduza os pedaços de goiaba limpa, a polpa de coco fresco e a água de coco no liquidificador.</li><li><b>Processar:</b> Triture na velocidade máxima durante 1 minuto até conseguir um batido tropical encorpado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_MINI_QUICHE_SEM_MASSA_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros batidos</li><li>2 colheres de sopa de cubos de vegetais mistos (curgete, pimento)</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Junte os ovos batidos com os pequenos cubos de vegetais numa tigela pequena.</li><li><b>Forno:</b> Verta o preparado em formas de silicone e leve ao forno a 180 graus até estarem bem firmes e cozidas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BOLACHAS_AVEIA_BANANA_3_ING + "', '<h3>Ingredientes:</h3><ul><li>1 banana madura grande</li><li>1/2 chávena de flocos de aveia</li><li>1 colher de sopa de pepitas de chocolate negro</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Esmague a banana na totalidade com um garfo, incorpore a aveia e adicione as pepitas de chocolate.</li><li><b>Cozedura:</b> Molde pequenas bolachas num tabuleiro com papel vegetal e leve ao forno por 12 minutos a 180 graus.</li></ol>');");

        // ==========================================
// ALMOÇOS - JUNHO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_FALAFEL_FORNO_MOLHO_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de grão-de-bico cozido</li><li>2 dentes de alho picados</li><li>1 colher de sopa de molho tahini e limão</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Triture o grão-de-bico cozido com o alho e as suas especiarias favoritas até obter uma pasta moldável.</li><li><b>Assar:</b> Forme pequenas bolas, coloque num tabuleiro e leve ao forno a 200 graus até dourar. Sirva com o molho tahini e sumo de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CHILI_VEGANO_SIN_CARNE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão preto cozido</li><li>1/2 pimento vermelho em cubos</li><li>1/2 lata de tomate pelado e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Refugar:</b> Cozinhe a cebola e o pimento vermelho numa frigideira com azeite até amolecerem.</li><li><b>Apurar:</b> Adicione o tomate pelado esmagado, o feijão preto e uma pitada de cominhos. Deixe apurar em lume brando por 15 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_ESPARGUETE_CURGETE_PESTO_AVELA + "', '<h3>Ingredientes:</h3><ul><li>1 curgete grande e firme</li><li>1/2 chávena de avelãs tostadas</li><li>Folhas de manjericão fresco e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Use um espiralizador para cortar a curgete em tiras longas semelhantes a esparguete.</li><li><b>Pesto:</b> Triture as avelãs com as folhas de manjericão e azeite abundante. Envolva o pesto frio diretamente nas tiras de curgete.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_FEIJOADA_COGUMELOS_PLEUROTUS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão encarnado cozido</li><li>150 g de cogumelos Pleurotus</li><li>1 cenoura às rodelas e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Salteie a cenoura às rodelas e os cogumelos Pleurotus cortados em tiras grossas num tacho com azeite.</li><li><b>Estufar:</b> Incorpore a polpa de tomate e o feijão encarnado com um pouco de água. Deixe estufar até o molho ficar bem rico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_ESTUFADO_LENTILHAS_ABOBORA_MANTEIGA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas verdes</li><li>1 chávena de cubos de abóbora-manteiga</li><li>1 cebola média picada</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coloque as lentilhas, os cubos de abóbora e a cebola picada num tacho cobertos com caldo de legumes.</li><li><b>Apurar:</b> Mantenha em lume médio até que as lentilhas fiquem macias e os cubos de abóbora comecem a desfazer ligeiramente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_STIR_FRY_TOFU_BROCOLOS_SESAMO + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em cubos</li><li>1 chávena de floretes de brócolos novos</li><li>Molho de soja e sementes de sésamo</li></ul><h3>Preparação:</h3><ol><li><b>Wok:</b> Aqueça um fio de azeite e salteie os brócolos frescos e os cubos de tofu em lume muito forte.</li><li><b>Finalizar:</b> Regue com uma colher de molho de soja, envolva rapidamente e salpique com as sementes de sésamo inteiras.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_ALHO_FRANCES_RECHEADO_QUINOA + "', '<h3>Ingredientes:</h3><ul><li>1 alho-francês grande (parte branca)</li><li>1/2 de chávena de quinoa cozida</li><li>Cubos finos de pimento vermelho</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Abra o alho-francês ao comprido e escalde as folhas em água a ferver para que fiquem moldáveis.</li><li><b>Forno:</b> Recheie as folhas com a quinoa cozida misturada com os cubos de pimento e leve ao forno a dourar num tabuleiro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SALADA_QUENTE_BATATA_DOCE_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce grande em cubos</li><li>1/2 de chávena de lentilhas cozidas</li><li>Folhas de espinafres novos e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse os cubos de batata-doce no forno com ervas até ficarem macios e dourados.</li><li><b>Misturar:</b> Retire do forno e junte imediatamente as lentilhas e as folhas de espinafres numa taça para murcharem com o calor.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_MASSA_ORZO_TOMATE_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de massa orzo (pevide)</li><li>1 chávena de tomates cherry inteiros</li><li>1 dente de alho picado e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Organizar:</b> Num prato de forno coloque os tomates cherry, o alho, a massa orzo crua e cubra com água fervente.</li><li><b>Cozedura:</b> Leve ao forno a 180 graus até que a massa absorva todo o líquido e os tomates rebentem de forma natural.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CURRY_RAMEN_TOFU_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>1 porção de massa ramen simples</li><li>100 g de tofu fresco em cubos</li><li>1 colher de pó de caril e caldo de vegetais</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Dissolva o pó de caril no caldo de vegetais a ferver. Adicione a massa ramen para cozinhar durante 3 minutos.</li><li><b>Servir:</b> Junte os cubos de tofu fresco diretamente na taça do caldo quente e guarneça com cebolinho picado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_GNOCCHI_ABOBORA_SALVIA_AZEITE + "', '<h3>Ingredientes:</h3><ul><li>150 g de gnocchi de abóbora</li><li>4 folhas de sálvia fresca</li><li>1 colher de sopa de azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Coloque os gnocchi numa panela com água e sal a ferver. Retire-os assim que subirem à superfície.</li><li><b>Saltear:</b> Aqueça o azeite com as folhas de sálvia numa frigideira e envolva os gnocchi escorridos até criarem uma crosta.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_XAREM_ALGARVIO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha de milho</li><li>250 ml de água ou caldo leve</li><li>100 g de cogumelos limpos salteados</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Cozinhe a farinha de milho na água a ferver, mexendo sempre com uma colher para criar a papa típica (xarém).</li><li><b>Finalizar:</b> Incorpore os cogumelos previamente salteados com alho na papa morna e envolva bem antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_BURRITO_BOWL_ARROZ_FEIJAO_PRETO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz integral cozido</li><li>1/2 chávena de feijão preto cozido</li><li>1/2 abacate em cubos e milho doce</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Coloque o arroz integral e o feijão preto em zonas separadas no interior de uma taça larga.</li><li><b>Finalizar:</b> Preencha os restantes espaços com o abacate fresco e o milho. Tempere com umas gotas de sumo de lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_LASANHA_LENTILHAS_FOLHAS_COUVE + "', '<h3>Ingredientes:</h3><ul><li>4 folhas de couve-lombarda grandes</li><li>1 de chávena de lentilhas cozidas com molho de tomate</li><li>Queijo ralado magro</li></ul><h3>Preparação:</h3><ol><li><b>Placas:</b> Escalde as folhas de couve-lombarda em água a ferver durante 2 minutos para que fiquem maleáveis.</li><li><b>Montar:</b> Num pirex intercale camadas de folhas de couve com o estufado de lentilhas. Cubra com o queijo e leve ao forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_COUSCOUS_ISRAELITA_VEGETAIS_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de couscous israelita</li><li>1/2 curgete e 1/2 pimento em cubos</li><li>Azeite e ervas aromáticas</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Asse os cubos de curgete e pimento no forno com um fio de azeite até ficarem tenros e tostados.</li><li><b>Misturar:</b> Coza o couscous israelita em água durante 8 minutos, escorra e envolva os vegetais assados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TABULE_TRIGO_SARRACENO_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de trigo sarraceno cozido</li><li>1 tomate médio firme em cubos</li><li>1/2 pepino picado e folhas de hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Arrefecer:</b> Certifique-se de que o trigo sarraceno cozido está totalmente frio antes de iniciar a montagem.</li><li><b>Envolver:</b> Junte o tomate, o pepino e as folhas de hortelã picadas finamente. Tempere com limão e azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_HAMBURGUER_FEIJAO_FRADE_ARROZ_ESPREGUIADO + "', '<h3>Ingredientes:</h3><ul><li>1 hambúrguer de feijão-frade caseiro</li><li>1/2 de chávena de arroz cozido com alho</li><li>Folhas de alface para acompanhar</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Grelhe o hambúrguer de feijão-frade numa chapa antiaderente bem quente até criar uma crosta firme.</li><li><b>Empratar:</b> Sirva o hambúrguer acompanhado pelo arroz de alho bem quente e uma guarnição simples de alface fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_QUICHE_BATATA_DOCE_ESPINAFRE + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce cozida e esmagada</li><li>2 ovos inteiros batidos</li><li>1 chávena de espinafres murchos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Forre o fundo de uma tarteira antiaderente utilizando a batata-doce esmagada como se fosse uma massa.</li><li><b>Recheio:</b> Misture os ovos batidos com os espinafres, verta sobre a base e leve ao forno até ficar bem firme.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TOFU_BROA_FORNO_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em fatias</li><li>1/2 chávena de broa de milho esfarelada</li><li>2 dentes de alho, coentros e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Crosta:</b> Misture a broa de milho esfarelada com o alho picado, os coentros e um fio de azeite numa tigela.</li><li><b>Assar:</b> Disponha o tofu num pirex, cubra com a mistura da broa e leve ao forno até criar uma superfície dourada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SALADA_MACARRAO_TRIGO_INTEGRAL_PICLES + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de macarrão de trigo integral</li><li>2 colheres de sopa de picles picados</li><li>5 tomates cherry cortados ao meio</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza o macarrão integral al dente, passe por água fria corrente para parar a cozedura e escorra.</li><li><b>Combinar:</b> Junte os tomates cherry e os picles picados numa taça. Adicione a massa e regue com um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_ESTUFADO_GRAO_BICO_ESPINAFRES_COMINHOS + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de grão-de-bico cozido</li><li>1 chávena de folhas de espinafres</li><li>Molho de tomate caseiro e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Coloque o molho de tomate e o grão-de-bico num tacho pequeno e tempere com uma pitada de cominhos.</li><li><b>Finalizar:</b> Junte os espinafres frescos, tape o tacho durante 3 minutos até murcharem e envolva tudo antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_PAELLA_FALSA_TRIGO_SARRACENO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de trigo sarraceno</li><li>1/4 de pimento vermelho e 1/4 de chávena de ervilhas</li><li>Uma pitada de açafrão em pó</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Cozinhe o trigo sarraceno com o pimento e as ervilhas num caldo de legumes temperado com o açafrão.</li><li><b>Secar:</b> Deixe cozinhar em lume brando até que todo o líquido seja absorvido, imitando a textura de uma paella.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SALTEADO_SEITAN_MOLHO_CERVEJA + "', '<h3>Ingredientes:</h3><ul><li>150 g de seitan fresco em tiras</li><li>50 ml de cerveja branca</li><li>Alho picado, louro e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Dourar:</b> Salteie as tiras finas de seitan com o alho picado e a folha de louro numa frigideira com azeite.</li><li><b>Reduzir:</b> Verta a cerveja sobre o preparado em lume forte e deixe ferver até o álcool evaporar e o molho reduzir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_KEDGEREE_VEGANO_ARROZ_CURCUMA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz basmati</li><li>1/2 colher de chá de curcuma em pó</li><li>1/4 de chávena de lentilhas cozidas</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Coza o arroz basmati juntamente com a curcuma na água para que ganhe uma cor amarela viva e aromática.</li><li><b>Misturar:</b> Escorra o arroz, envolva as lentilhas previamente cozidas e salpique com coentros frescos picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_WRAP_QUENTE_FEIJAO_ENCARNADO + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha ou wrap integral</li><li>1/2 de chávena de feijão encarnado cozido</li><li>Folhas de alface e grãos de milho</li></ul><h3>Preparação:</h3><ol><li><b>Pasta:</b> Esmague o feijão encarnado quente com um garfo até obter um puré espesso e barre na tortilha integral.</li><li><b>Enrolar:</b> Adicione a alface e o milho doce por cima, enrole firmemente e passe o wrap na chapa quente para dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_TACOS_JACKFRUIT_MOLHO_BARBECUE + "', '<h3>Ingredientes:</h3><ul><li>2 conchas de taco de milho</li><li>1 chávena de jaca (jackfruit) desfiada</li><li>Molho barbecue caseiro e repolho</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Salteie a jaca desfiada numa frigideira juntamente com o molho barbecue até ficar muito suculenta.</li><li><b>Montagem:</b> Preencha as conchas de taco com a jaca quente e adicione uma fina camada de repolho crocante no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_RISOTO_BETERRABA_CREMOSO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz arbóreo</li><li>1/2 beterraba cozida reduzida a puré</li><li>Caldo de legumes morno e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Inicie a cozedura do arroz arbóreo adicionando o caldo de legumes aos poucos e mexendo de forma constante.</li><li><b>Cor:</b> A meio do processo junte o puré de beterraba cozida. Continue a mexer até o arroz estar cozido e cremoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SALADA_LENTILHAS_BELUGA_NURZ_MOSTARDA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas beluga cozidas</li><li>4 miolos de noz partidos</li><li>1 colher de chá de mostarda antiga e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque as lentilhas beluga cozidas e frias numa taça e misture os miolos de noz partidos à mão.</li><li><b>Molho:</b> Emulsione a mostarda antiga com o azeite num copo pequeno e verta sobre a salada antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_MAC_AND_CHEESE_VEGAN_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de massa macarrão cozida</li><li>1/2 de chávena de puré de abóbora quente</li><li>1 colher de sopa de levedura nutricional</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Misture energeticamente o puré de abóbora com a levedura nutricional para criar um molho com sabor a queijo.</li><li><b>Envolver:</b> Verta este molho cremoso sobre o macarrão integral cozido e envolva tudo muito bem em lume brando.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_EMPADAO_SOJA_TEXTURIZADA_BATATA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de soja granulada cozida em tomate</li><li>2 batatas médias cozidas e esmagadas</li><li>Um pouco de leite vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Puré:</b> Prepare um puré liso misturando as batatas esmagadas com um fio de leite vegetal quente e sal.</li><li><b>Montar:</b> Num pirex coloque a soja texturada cozida na base, cubra com o puré de batata e leve ao forno a dourar.</li></ol>');");

        // ==========================================
// JANTARES - JUNHO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CALDO_VERDE_TRADICIONAL_VEG + "', '<h3>Ingredientes:</h3><ul><li>3 batatas médias</li><li>1 cebola e 2 dentes de alho</li><li>1 chávena de couve-galega cortada fina</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza as batatas, a cebola e os dentes de alho num tacho com água e sal.</li><li><b>Triturar:</b> Reduza os legumes a um creme liso com a varinha mágica.</li><li><b>Finalizar:</b> Junte a couve-galega e deixe ferver por 5 minutos. Adicione um fio de azeite antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_CREME_ALHO_FRANCES_BATATA + "', '<h3>Ingredientes:</h3><ul><li>2 alhos-franceses (parte branca)</li><li>2 batatas e 1 cebola</li><li>1 colher de sopa de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Corte os alhos-franceses, as batatas e a cebola em pedaços e leve a cozer em água.</li><li><b>Creme:</b> Triture tudo muito bem até obter uma consistência cremosa e aveludada.</li><li><b>Servir:</b> Adicione o azeite em cru e retifique o sal ao seu gosto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CANJA_COGUMELOS_SHIITAKE_MASSA + "', '<h3>Ingredientes:</h3><ul><li>150 g de cogumelos shiitake fatiados</li><li>1/2 chávena de massa pevide ou estrelinhas</li><li>1 cebola pequena e hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Faça um refogado leve com a cebola e junte os cogumelos shiitake para libertarem os sucos.</li><li><b>Cozedura:</b> Adicione água a ferver, deite a massa e deixe cozinhar até ficar al dente.</li><li><b>Aromatizar:</b> Sirva a canja bem quente enriquecida com folhas de hortelã fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_FEIJAO_MANTEIGA_REPOLHO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão-manteiga cozido</li><li>1/2 repolho cortado em pedaços</li><li>1 cenoura e 1 cebola</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Triture metade do feijão-manteiga com a cenoura e a cebola cozidas para engrossar o caldo.</li><li><b>Incorporar:</b> Junte o repolho em pedaços e os restantes grãos inteiros de feijão ao tacho.</li><li><b>Apurar:</b> Deixe cozinhar em lume brando até o repolho ficar completamente tenro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_BROCOLOS_AMENDOA_TOSTADA + "', '<h3>Ingredientes:</h3><ul><li>1 cabeça de brócolos</li><li>1 batata e 1 cebola</li><li>2 colheres de sopa de amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Sopa:</b> Coza os floretes de brócolos, a batata e a cebola. Triture até obter um creme uniforme.</li><li><b>Tostar:</b> Aloure as amêndoas laminadas numa frigideira antiaderente seca durante 2 minutos.</li><li><b>Topping:</b> Sirva o creme de brócolos polvilhado com as amêndoas tostadas e crocantes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_TOMATE_ALENTEJANA_OVO + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros grandes</li><li>1 cebola e 2 dentes de alho</li><li>1 ovo e fatias de pão de véspera</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Cozinhe a cebola e o alho em azeite, adicione os tomates esmagados e deixe apurar com água.</li><li><b>Escalfar:</b> Abra o ovo diretamente no caldo a ferver, tape o tacho e deixe cozinhar.</li><li><b>Empratar:</b> Coloque as fatias de pão no fundo do prato e verta a sopa com o ovo por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_ERVIHAS_XUXU_ERVAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de ervilhas frescas</li><li>1 chuchu grande em cubos</li><li>1 cebola, coentros e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as ervilhas, o chuchu e a cebola a cozer num tacho com água temperada com sal.</li><li><b>Processar:</b> Adicione um punhado de coentros e hortelã e triture com a varinha mágica.</li><li><b>Finalizar:</b> Sirva este creme verde claro e perfumado com um fio de azeite virgem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_MINESTRONE_FEIJAO_FRADE + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de feijão-frade cozido</li><li>1/2 curgete e 1 cenoura em cubos</li><li>Massinha de sopa e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Coza a curgete e a cenoura com a polpa de tomate num caldo leve de vegetais.</li><li><b>Apurar:</b> Junte o feijão-frade e a massinha de sopa. Deixe ferver até a massa ficar cozida.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_ABOBORA_ASSADA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>300 g de abóbora assada no forno</li><li>1 cebola e 1 dente de alho</li><li>1 colher de café de gengibre fresco ralado</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza a cebola e o alho em água. Juntar a abóbora que já foi previamente assada.</li><li><b>Triturar:</b> Adicione o gengibre fresco ralado e processe tudo até obter um puré liso e morno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_PEDRA_VEGETARIANA_RIFADO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão encarnado cozido</li><li>1 batata, 1 cenoura e 1 nabo</li><li>Folhas de couve e 1 pedra limpa (simbólica)</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coloque os legumes em cubos e as couves a cozer no caldo de feijão encarnado.</li><li><b>Espessar:</b> Deixe a sopa ferver longamente em lume brando até que todos os ingredientes fiquem desfeitos e ricos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_CENOURA_SOUCHE_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>3 cenouras grandes</li><li>1 chuchu médio descascado</li><li>1 cebola e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte as cenouras, o chuchu e a cebola em pedaços e coza com pouca água.</li><li><b>Finalizar:</b> Adicione os coentros frescos generosamente e triture tudo até obter um creme vibrante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_LENTILHAS_VERMELHAS_COMINHO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas vermelhas</li><li>1 cenoura e 1/2 pimento vermelho</li><li>1 colher de café de cominhos em pó</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza as lentilhas vermelhas com a cenoura e o pimento até estarem completamente macios.</li><li><b>Especiaria:</b> Adicione os cominhos em pó, triture e sirva com um toque rústico e reconfortante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_COUVE_FLOR_ALHO_ASSADO + "', '<h3>Ingredientes:</h3><ul><li>1/2 couve-caulino ou couve-flor</li><li>3 dentes de alho assados no forno</li><li>1 batata pequena e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve a couve-flor e a batata a cozer num tacho com água temperada com sal.</li><li><b>Misturar:</b> Junte a polpa macia dos dentes de alho assados e triture até atingir uma textura de veludo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_JULIANA_LEGUMES_VARIADOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de legumes em juliana (cenoura, repolho, nabo)</li><li>Base triturada de batata e cebola</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Prepare uma base leve de sopa triturando a batata e a cebola cozidas.</li><li><b>Juliana:</b> Junte a mistura de legumes cortados em tiras finas e deixe cozer em lume médio al dente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_XUXU_FOLHAS_NABICA + "', '<h3>Ingredientes:</h3><ul><li>2 chuchus grandes descascados</li><li>1 cebola média</li><li>1 chávena de folhas de nabiça limpas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza os chuchus e a cebola em água e reduza a puré com a varinha mágica.</li><li><b>Nabiças:</b> Introduza as folhas de nabiça cortadas no creme e deixe ferver por mais 5 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_GRAO_BICO_COUVE_LOMBARDA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de grão-de-bico cozido</li><li>3 folhas grandes de couve-lombarda</li><li>Base de cenoura e batata</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Adicione o grão-de-bico e a couve-lombarda em pedaços a uma base de sopa triturada.</li><li><b>Apurar:</b> Cozinhe em lume brando até as folhas de couve estarem macias e o caldo encorpado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_BETERRABA_QUENTE_NOZ_MOSCADA + "', '<h3>Ingredientes:</h3><ul><li>1 beterraba grande cozida</li><li>1 batata e 1 alho-francês</li><li>Uma pitada de noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Sopa:</b> Coza a batata e o alho-francês. Adicione a beterraba cozida e triture tudo em conjunto.</li><li><b>Finalizar:</b> Tempere o creme purpura com a pitada de noz-moscada e um fio de azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_CEBOLA_FRANCESA_TORRADA + "', '<h3>Ingredientes:</h3><ul><li>3 cebolas grandes cortadas em meias-luas</li><li>500 ml de caldo de vegetais</li><li>1 fatia de pão torrado</li></ul><h3>Preparação:</h3><ol><li><b>Dourar:</b> Caramelize as cebolas lentamente num tacho com azeite até ficarem bem escuras e doces.</li><li><b>Ferver:</b> Junte o caldo de vegetais e deixe apurar. Sirva a sopa quente com a torrada colocada no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_CORACAO_ALFACE_ERVIHAS + "', '<h3>Ingredientes:</h3><ul><li>1 coração de alface limpo</li><li>1/2 chávena de ervilhas</li><li>1 cebola pequena e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve o coração de alface, as ervilhas e a cebola a cozer num caldo simples de água.</li><li><b>Triturar:</b> Use a varinha mágica para transformar os ingredientes num creme verde aveludado e leve.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_BATATA_DOCE_ESPINAFFRE + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce grande</li><li>1 cenoura e 1 cebola</li><li>1 chávena de folhas de espinafres frescos</li></ul><h3>Preparação:</h3><ol><li><b>Puré:</b> Coza a batata-doce, a cenoura e a cebola. Triture tudo até obter um caldo cremoso.</li><li><b>Verdes:</b> Junte as folhas de espinafres inteiras ao caldo quente e deixe ferver por 3 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_AIPO_MAC_VERDE_QUENTE + "', '<h3>Ingredientes:</h3><ul><li>2 talos de aipo limpos</li><li>1 maçã verde com casca</li><li>1 cebola e um fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza o aipo e a cebola. Adicione os pedaços de maçã verde nos minutos finais da cozedura.</li><li><b>Processar:</b> Triture energeticamente até desmilinguir as fibras e conseguir um creme sedoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_TRIGO_SARRACENO_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de trigo sarraceno</li><li>1/2 curgete e 1 cenoura em cubos</li><li>Caldo de legumes</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Coloque o trigo sarraceno em grão e os legumes em cubos pequenos a cozer no caldo vegetal.</li><li><b>Textura:</b> Deixe apurar até o trigo expandir e os legumes ficarem perfeitamente cozidos e macios.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_NABIÇAS_TRADICIONAL_MINHO + "', '<h3>Ingredientes:</h3><ul><li>2 batatas grandes e 1 cebola</li><li>1 molho de nabiças frescas limpas</li><li>Azeite abundante</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Prepare a base triturando as batatas e a cebola cozidas num tacho com água.</li><li><b>Nabiças:</b> Junte as nabiças cortadas e coza bem. Sirva com um fio generoso de azeite minhoto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_MISO_TOFU_ALGAS_WAKAME + "', '<h3>Ingredientes:</h3><ul><li>1 colher de sopa de pasta de miso</li><li>50 g de tofu em cubos pequenos</li><li>1 colher de sopa de algas wakame</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Coloque as algas wakame a hidratar num pouco de água morna durante 5 minutos.</li><li><b>Cozinhar:</b> Aqueça água com o tofu e as algas. Desligue o lume e dissolva a pasta de miso sem ferver.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_REPOLHO_BRANCO_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 repolho branco macio</li><li>1/2 chávena de grão-de-bico cozido</li><li>1 cebola pequena</li></ul><h3>Preparação:</h3><ol><li><b>Sopa:</b> Coza o repolho branco cortado e a cebola. Junte o grão-de-bico a meio do processo.</li><li><b>Passar:</b> Triture a totalidade dos ingredientes com a varinha mágica até obter um creme encorpado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_AZEDA_LENTILHAS_LIMON + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas castanhas</li><li>1 chávena de espinafres e 1 cebola</li><li>Sumo de 1/2 limão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Lentilhas:</b> Coza as lentilhas com a cebola picada. Adicione os espinafres quando estiverem macias.</li><li><b>Cítrico:</b> mesmo antes de servir no prato, regue a sopa com o sumo de limão fresco para dar o toque azedo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_ABOBORINHA_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>2 curgetes médias (aboborinhas)</li><li>1 alho-francês largo (alho-porro)</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Limpe o alho-porro, corte as curgetes com casca e leve a cozer em água e sal.</li><li><b>Triturar:</b> Reduza a um creme aveludado com a ajuda da varinha mágica e finalize com um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_RAIZES_PASTINACA_CENOURA + "', '<h3>Ingredientes:</h3><ul><li>1 pastinaca grande (chirivia)</li><li>2 cenouras e 1 cebola</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Descasque as raízes de pastinaca e as cenouras, junte a cebola e coza bem num tacho.</li><li><b>Creme:</b> Triture tudo até obter um puré ou creme espesso muito reconfortante e aromático.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_CREME_FOLHAS_KALE_BATATA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce média</li><li>1 chávena de folhas de couve kale</li><li>1 cebola pequena e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza a batata-doce com a cebola e triture para formar um caldo aveludado.</li><li><b>Kale:</b> Junte as folhas de couve kale cortadas e deixe ferver até estarem perfeitamente cozidas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUN_SOPA_BARRANQUENHA_LEGUMES_PIMENTA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de feijão cozido</li><li>1 batata e 1/2 chávena de beldroegas</li><li>Uma pitada de pimenta em pó</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza a batata e as beldroegas com o feijão num caldo tradicional bem apurado.</li><li><b>Tempero:</b> Finalize adicionando a pitada de pimenta em pó para dar o travo típico e picante desta sopa.</li></ol>');");

        // ==========================================
// PEQUENOS-ALMOÇOS - JULHO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_NECTARINA_GOJI + "', '<h3>Ingredientes:</h3><ul><li>2 nectarinas maduras</li><li>1 colher de sopa de bagas goji</li><li>200 ml de bebida de amêndoa</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Coloque as bagas goji a hidratar em um pouco de água morna por 5 minutos.</li><li><b>Triturar:</b> Triture as nectarinas sem caroço com as bagas escorridas e a bebida de amêndoa até ficar homogéneo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_AVEIA_ADORMECIDA_AMORA_SILVESTRE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>100 ml de leite vegetal</li><li>1 punhado de amoras silvestres</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte os flocos de aveia com o leite vegetal no interior de um frasco limpo.</li><li><b>Repousar:</b> Adicione as amoras ligeiramente esmagadas e deixe repousar no frigorífico durante toda a noite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_ABACATE_GELADO_LIMA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio torrado</li><li>1/2 abacate maduro e fresco</li><li>Sumo e raspa de 1/2 lima</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Esmague a polpa do abacate bem frio com o sumo de lima e uma pitada de sal.</li><li><b>Barrar:</b> Espalhe o preparado sobre a torrada quente e decore com a raspa fina da lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PUDIM_CHIA_FRAMBOESA_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>150 ml de leite de coco leve</li><li>6 framboesas frescas e folhas de hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Junte as sementes de chia ao leite de coco e mexer bem até que comece a espessar de forma natural.</li><li><b>Servir:</b> Distribua as framboesas e as folhas de hortelã picadas por cima antes de consumir frio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PANQUECAS_MIRTILO_LIMAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de aveia</li><li>1 ovo inteiro</li><li>Sumo de 1/4 de limão e mirtilos frescos</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha de aveia, o ovo e o sumo de limão até criar uma massa fofa e homogénea.</li><li><b>Cozinhar:</b> Verta porções na frigideira quente e adicione os mirtilos inteiros mesmo antes de virar a panqueca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_BOWL_FRUTOS_ROXOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de frutos roxos congelados</li><li>1/2 banana madura</li><li>100 ml de água de coco</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Triture todos os ingredientes num robô de cozinha até obter uma consistência espessa de gelado.</li><li><b>Montagem:</b> Deite o preparado numa taça e decore a superfície com sementes ou raspas a gosto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TACA_IOGURTE_GRENADA + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural ou vegetal</li><li>3 colheres de sopa de bagos de romã</li><li>1 colher de sobremesa de sementes de linhaça</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Coloque o iogurte fresco na base de uma taça larga de pequeno-almoço.</li><li><b>Finalizar:</b> Cubra com os bagos de romã sumarentos e salpique com as sementes de linhaça moídas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_FETA_MELANCIA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico torrado</li><li>30 g de queijo feta esfarelado</li><li>1 fatia fina de melancia em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Espalhe o queijo feta esfarelado sobre a fatia de pão torrado enquanto estiver morna.</li><li><b>Topping:</b> Coloque os cubos de melancia por cima e finalize com um toque opcional de pimenta preta.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_MEXIDO_TOFU_TOMATE_PIMENTO + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1/2 tomate limpo em cubos</li><li>1/4 de pimento verde picado e curcuma</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Esmague o tofu com um garfo e salteie na frigideira antiaderente com um fio de azeite.</li><li><b>Cozinhar:</b> Adicione os cubos de tomate, o pimento e a curcuma. Mexa até dourar ligeiramente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_AVEIA_FRIA_MELAO_ALBICOQUE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de aveia</li><li>100 ml de iogurte líquido magro</li><li>Cubos de melão e 1 alperce fatiado</li></ul><h3>Preparação:</h3><ol><li><b>Amolecer:</b> Misture os flocos de aveia com o iogurte líquido numa taça e deixe repousar para hidratar.</li><li><b>Decorar:</b> Adicione os cubos de melão fresco e as fatias de alperce por cima antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_CEREJA_CACAU + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cerejas frescas descaroçadas</li><li>1 colher de sobremesa de cacau puro em pó</li><li>200 ml de bebida de aveia</li></ul><h3>Preparação:</h3><ol><li><b>Juntar:</b> Coloque as cerejas limpas, o cacau em pó e a bebida de aveia no copo misturador.</li><li><b>Bater:</b> Triture na velocidade máxima até obter um batido cremoso e homogéneo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PANQUECAS_COCO_MANGA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha de trigo integral</li><li>1 colher de coco ralado e bebida de coco</li><li>Fatias de manga fresca</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, o coco ralado e a bebida até formar uma massa espessa de panquecas.</li><li><b>Finalizar:</b> Doure as panquecas numa frigideira e sirva acompanhadas com as fatias de manga fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_HUMUS_CURGETE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão alentejano torrado</li><li>2 colheres de sopa de húmus tradicional</li><li>Fatias finas de curgete grelhada</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Espalhe o húmus de forma uniforme sobre a superfície da fatia de pão torrado.</li><li><b>Montar:</b> Dispor as fatias finas de curgete grelhada por cima e regue com um fio de azeite leve.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_MUESLI_TROPICAL_ANANAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de muesli simples</li><li>1 fatia de ananás em cubos pequenos</li><li>150 ml de iogurte com aroma a coco</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Combine o muesli simples com o iogurte numa taça de pequeno-almoço larga.</li><li><b>Fruta:</b> Envolva os cubos de ananás frescos para dar o toque tropical e sumarento antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PAPA_ARROZ_MARACUJA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz-doce simples frio</li><li>Polpa de 1 maracujá fresco</li><li>Raspas finas de lima</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Coloque a porção de arroz-doce frio na taça individual de servir.</li><li><b>Enriquecer:</b> Regue com a polpa ácida do maracujá e perfume a gosto utilizando as raspas de lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_PAPAIA_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 papaia limpa de sementes</li><li>3 folhas de manjericão fresco</li><li>200 ml de água de coco bem fresca</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Divida a polpa da papaia em cubos ou pedaços pequenos fáceis de processar.</li><li><b>Batido:</b> Triture a fruta com as folhas de manjericão e a água de coco até obter um batido leve.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_ABACATE_SOUCHE_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral torrado</li><li>1/2 abacate maduro esmagado</li><li>1 colher de sementes de abóbora tostadas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Cobrir a fatia de pão torrado com o abacate bem esmagado e temperado com uma pitada de sal.</li><li><b>Textura:</b> Salpique com as sementes de abóbora crocantes por cima para garantir textura ao pequeno-almoço.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TACA_ACAI_FRAMBOESA_GRANOLA + "', '<h3>Ingredientes:</h3><ul><li>100 g de polpa de açaí pura</li><li>1/2 chávena de framboesas inteiras</li><li>2 colheres de sopa de granola caseira</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Processe a polpa de açaí até obter uma consistência semelhante a um gelado cremoso.</li><li><b>Decorar:</b> Sirva imediatamente numa taça com as framboesas frescas e a granola crocante dispostas no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PAPAS_AVEIA_FRIAS_HORTELA_CHIA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de aveia</li><li>1 colher de sementes de chia</li><li>120 ml de leite vegetal e folhas de hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte a aveia, a chia e o leite vegetal num frasco ou recipiente fechado.</li><li><b>Frigorífico:</b> Adicione folhas de hortelã picadas e deixe repousar no frio até ao momento de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_BOWL_MELAO_CELESTE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cubos de melão bem frios</li><li>1/2 maçã verde picada</li><li>50 ml de água ou gelo</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificador:</b> Triture os cubos de melão e a maçã verde até obter um creme espesso e gelado.</li><li><b>Finalizar:</b> Verta o líquido numa taça e decore com folhas frescas de hortelã.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_AVEIA_NOITE_PESSEGO_AMENDOA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de aveia</li><li>100 ml de bebida de amêndoa</li><li>1 pêssego maduro fatiado e amêndoas</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Demolhe os flocos de aveia na bebida de amêndoa durante a noite no interior do frigorífico.</li><li><b>Servir:</b> Pela manhã, adicione as fatias de pêssego fresco e salpique com amêndoas picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PANQUECAS_INTEGRAIS_AMEIXA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha integral</li><li>80 ml de leite vegetal</li><li>2 ameixas frescas fatiadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Faça a massa misturando a farinha e o leite. Cozinhe pequenas porções numa chapa bem quente.</li><li><b>Acompanhar:</b> Sirva a pilha de panquecas moles com as fatias de ameixas frescas e frias por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_RICOTA_FIGO_MEL + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico torrado</li><li>2 colheres de sopa de queijo ricota</li><li>1 figo fresco fatiado e um fio de mel</li></ul><h3>Preparação:</h3><ol><li><b>Espalhar:</b> Espalhe o queijo ricota cremoso sobre a superfície da fatia de pão torrado ainda quente.</li><li><b>Montagem:</b> Disponha as fatias do figo fresco e finalize vertendo um fio leve de mel puro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_IOGURTE_GRANOLA_CEREJA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de iogurte grego natural</li><li>3 colheres de sopa de granola</li><li>6 cerejas frescas cortadas ao meio</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque a porção de iogurte grego natural na taça onde vai servir.</li><li><b>Dispor:</b> Adicione a granola crocante numa das metades da taça e preencha o resto com as cerejas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_VERDE_COUVE_MELANCIA + "', '<h3>Ingredientes:</h3><ul><li>1 folha de couve kale sem talo</li><li>1 chávena de melancia em cubos limpos</li><li>Sumo de 1/2 limão</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Triture a folha de couve com os cubos sumarentos de melancia no copo do liquidificador.</li><li><b>Cítrico:</b> Adicione o sumo de limão fresco para equilibrar os sabores e sirva de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PUDIM_CHIA_PESSEGO_CARECA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sementes de chia</li><li>150 ml de leite vegetal</li><li>1 pêssego-careca cortado em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Gelatina:</b> Prepare o pudim misturando a chia com o leite vegetal até criar consistência de gel.</li><li><b>Fruta:</b> Envolva os cubos do pêssego-careca fresco na papa gelatinizada mesmo antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORRADA_MANTEIGA_AMENDOIM_FRAMBOESA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão torrado</li><li>1 colher de sopa de manteiga de amendoim</li><li>Framboesas frescas inteiras</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Espalhe a colher de manteiga de amendoim sobre a superfície da fatia de pão torrado quente.</li><li><b>Finalizar:</b> Coloque as framboesas frescas por cima, esmagando-as ligeiramente com a ajuda de um garfo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_AVEIA_CHOCOLATE_NEGRO_AMORA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de aveia e leite quente</li><li>1 colher de chá de pepitas de chocolate negro</li><li>Amoras frescas</li></ul><h3>Preparação:</h3><ol><li><b>Papas:</b> Cozinhe brevemente a aveia no leite vegetal quente até obter uma consistência cremosa.</li><li><b>Quente:</b> Adicione as pepitas de chocolate negro para que derretam e guarneça com as amoras frescas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SMOOTHIE_UVA_PRETA_FRAMBOESA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de uvas pretas sem grainha</li><li>1/2 chávena de framboesas</li><li>150 ml de água fresca</li></ul><h3>Preparação:</h3><ol><li><b>Colocar:</b> Adicione as uvas pretas lavadas e as framboesas no copo misturador do robô.</li><li><b>Bater:</b> Adicione a água fresca e triture tudo na velocidade máxima até obter um batido refrescante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PANQUECAS_AVEIA_SOUCHE_LINHACA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de aveia triturada</li><li>1 colher de sementes de linhaça moídas</li><li>100 ml de leite vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Bater a farinha de aveia com a linhaça e o leite vegetal para obter uma massa líquida.</li><li><b>Chapa:</b> Cozinhe porções da massa numa frigideira antiaderente virando de ambos os lados até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TACA_IOGURTE_FRUTOS_SILVESTRES + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural espesso</li><li>1/2 chávena de frutos silvestres (mirtilos, amoras e framboesas)</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Verta o iogurte natural espesso para uma taça de cerâmica ou vidro.</li><li><b>Cobrir:</b> Preencha a superfície com os frutos silvestres variados bem lavados antes de saborear.</li></ol>');");

        // ==========================================
// ALMOÇOS - JULHO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_FEIJAO_FRADE_PIMENTO_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão-frade cozido</li><li>1/2 pimento vermelho e verde em cubos</li><li>1/2 cebola roxa e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Enxague e escorra o feijão-frade cozido. Pique finamente os pimentos e a cebola roxa.</li><li><b>Envolver:</b> Junte todos os ingredientes numa saladeira, adicione os coentros picados e tempere com azeite e vinagre.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_QUINOA_MANGA_CHILI + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de quinoa cozida fria</li><li>1/2 manga madura em cubos</li><li>1/4 de pimento vermelho e chili fresco</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte a quinoa fria com os cubos de manga e as tiras finas de pimento vermelho numa taça.</li><li><b>Finalizar:</b> Adicione o chili picado sem sementes e folhas de hortelã. Regue generosamente com sumo de lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_MASSA_FRESCA_TOMATE_CHERRY_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1 porção de massa fresca (talharim)</li><li>1 chávena de tomates cherry</li><li>2 dentes de alho e manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza a massa fresca em água a ferver com sal até ficar al dente e escorra.</li><li><b>Molho:</b> Salteie os dentes de alho e os tomates cherry inteiros em azeite até rebentarem. Envolva a massa e o manjericão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_BURRITO_VEG_FEIJAO_FRITO_PIMENTOS + "', '<h3>Ingredientes:</h3><ul><li>2 tortilhas de trigo ou integrais</li><li>1/2 chávena de feijão preto refrito</li><li>1/2 pimento às tiras e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe as tiras de pimento e cebola numa frigideira com um toque de cominhos até amolecerem.</li><li><b>Montar:</b> Aqueça as tortilhas, barre o feijão preto quente, adicione os pimentos e dobre em formato de burrito.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_RISOTO_HORTELA_LIMAO_JUL + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz arbóreo</li><li>Caldo de legumes morno</li><li>Sumo e raspa de 1/2 limão e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Cozinhe o arroz arbóreo adicionando o caldo de legumes aos poucos e mexendo de forma constante.</li><li><b>Aromatizar:</b> No final da cozedura, apague o lume e envolva a hortelã picada, o sumo e as raspas finas de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_LENTILHAS_ABACAXI_RUCULA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas cozidas</li><li>1 fatia grossa de abacaxi em cubos</li><li>1 chávena de folhas de rúcula selvagem</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Junte as lentilhas cozidas frias com os cubos de abacaxi fresco e as folhas de rúcula numa taça.</li><li><b>Tempero:</b> Polvilhe com sementes de girassol e regue com um fio de azeite virgem extra antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TORTILHA_BATATA_CURGETE_CEBOLA + "', '<h3>Ingredientes:</h3><ul><li>2 batatas médias em rodelas finas</li><li>1/2 curgete fatiada</li><li>3 ovos inteiros e 1/2 cebola</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Amacie as batatas, a curgete e a cebola numa frigideira com azeite em lume brando até ficarem tenras.</li><li><b>Dourar:</b> Escorra o excesso de gordura, envolva com os ovos batidos e coza a tortilha de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_ARROZ_COENTROS_TOFU_FUMADO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de arroz basmati</li><li>100 g de tofu fumado em cubos</li><li>1 dente de alho e 1 molho de coentros</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza o arroz basmati em água e sal. Numa frigideira separada, doure os cubos de tofu fumado com alho.</li><li><b>Finalizar:</b> Pique os coentros frescos finamente e envolva tudo no arroz basmati bem quente antes de empratar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_GRAO_PEPINELLA_RABANETE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de grão-de-bico cozido</li><li>1/2 pepino em cubos</li><li>3 rabanetes em rodelas finas e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte o grão-de-bico escorrido, os cubos de pepino e as rodelas de rabanete numa taça larga.</li><li><b>Servir:</b> Adicione a salsa fresca picada e tempere com azeite virgem e umas gotas de sumo de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_COUSCOUS_JULHO_LEGUMES_GRELHADOS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de couscous simples</li><li>1/2 curgete e 1/2 beringela às fatias</li><li>Azeite e ervas aromáticas</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Cubra o couscous com água a ferver e abafe por 5 minutos até soltar os grãos com um garfo.</li><li><b>Grelhar:</b> Grelhe as fatias de curgete e beringela com azeite e ervas. Misture os legumes grelhados no couscous.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_LASANHA_FRIA_CURGETE_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 curgete larga fatiada ao comprido</li><li>2 tomates maduros picados</li><li>3 colheres de sopa de queijo ricota</li></ul><h3>Preparação:</h3><ol><li><b>Montagem:</b> Utilize as fatias finas de curgete crua como se fossem as placas de massa da lasanha.</li><li><b>Camadas:</b> Intercale num prato camadas de curgete, queijo ricota e o tomate limpo picado. Sirva bem fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_MACARRAO_AZEITONA_CAPRESE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa macarrão cozida</li><li>1/2 chávena de tomates cherry e azeitonas</li><li>50 g de mini bolinhas de mozarela</li></ul><h3>Preparação:</h3><ol><li><b>Juntar:</b> Deixe a massa arrefecer por completo. Adicione os tomates cherry cortados, as azeitonas e a mozarela.</li><li><b>Envolver:</b> Tempere com uma colher de pesto caseiro ou simplesmente azeite e folhas de manjericão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_ESTUFADO_GRAO_TOMATE_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de grão-de-bico cozido</li><li>1/2 lata de tomate pelado picado</li><li>1 cebola pequena e manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça um refogado simples com azeite e cebola. Adicione o tomate pelado e deixe cozinhar.</li><li><b>Apurar:</b> Junte o grão-de-bico ao tacho e deixe apurar por 10 minutos. Adicione o manjericão mesmo antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_HAMBURGUER_LENTILHAS_SALADA_VERAO + "', '<h3>Ingredientes:</h3><ul><li>1 hambúrguer de lentilhas caseiro</li><li>Folhas de alface e rúcula</li><li>1/2 pepino fatiado e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Cozinhe o hambúrguer de lentilhas numa frigideira antiaderente bem quente com um fio de azeite.</li><li><b>Acompanhar:</b> Sirva o hambúrguer diretamente no prato com uma salada verde e fresca de pepino e alface.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_QUINOA_CEREJA_FETA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de quinoa cozida</li><li>1/2 chávena de cerejas descaroçadas</li><li>40 g de queijo feta em cubos e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Combine a quinoa cozida fria com as metades de cerejas frescas e os cubos de queijo feta numa taça.</li><li><b>Finalizar:</b> Salpique com folhas de hortelã fresca picadas e regue com um fio de azeite virgem extra.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_ARROZ_TOMATE_MALANDRINHO_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz agulha</li><li>2 tomates maduros picados</li><li>1/2 cebola, 1 dente de alho e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Pique a cebola e o alho e refogue em azeite. Adicione o tomate e deixe criar um molho macio.</li><li><b>Cozedura:</b> Adicione água a ferver (o triplo do arroz), junte o arroz e coza deixando bastante caldo. Junte coentros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_QUICHE_CURGETE_TOMATE_CHERRY + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada pronta</li><li>1/2 curgete ralada finamente</li><li>1/2 chávena de tomates cherry e 3 ovos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Forre uma forma com a massa quebrada. Bata os ovos com a curgete ralada e envolva tudo.</li><li><b>Forno:</b> Verta o preparado na forma, distribua os tomates cherry inteiros por cima e leve ao forno a assar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_PASTA_GRAO_AZEITONA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa fusilli cozida</li><li>1/2 de chávena de grão-de-bico</li><li>Azeitonas verdes fatiadas e pimento</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Numa saladeira coloque a massa cozida fria, o grão-de-bico escorrido e as azeitonas fatiadas.</li><li><b>Tempero:</b> Adicione pequenos cubos de pimento amarelo e envolva com um molho tradicional de azeite e vinagre.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_MASSA_PESTO_RUCULA_TOMATE_SECO + "', '<h3>Ingredientes:</h3><ul><li>1 porção de massa penne integral</li><li>2 colheres de sopa de pesto de rúcula</li><li>4 pedaços de tomate seco em óleo</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza a massa penne integral em água fervente até ficar al dente. Escorra o líquido de cozedura.</li><li><b>Envolver:</b> Adicione o pesto de rúcula e as tiras de tomate seco fatiadas na massa quente e misture bem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_GRATINADO_BERINJELA_TOMATE_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>1 beringela média em rodelas</li><li>2 tomates maduros em rodelas</li><li>Queijo ralado magro e oregãos</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Num prato de forno untado intercale rodelas de beringela e tomate de forma harmoniosa.</li><li><b>Gratinar:</b> Tempere com sal e oregãos, cubra com o queijo ralado e leve ao forno até dourar a superfície.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_ESPINAFRE_MANGA_PINDAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de espinafres bebés</li><li>1/2 manga fatiada em tiras</li><li>1 colher de sopa de sementes tostadas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Disponha as folhas limpas de espinafres bebés e as tiras de manga fresca num prato raso.</li><li><b>Finalizar:</b> Salpique com as sementes tostadas crocantes e regue com um vinagrete suave de limão e azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_LENTILHAS_AMEIXA_AVOCADO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas cozidas</li><li>2 ameixas frescas em fatias</li><li>1/2 abacate em cubos e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Juntar:</b> Coloque as lentilhas cozidas frias, as fatias de ameixa e os cubos de abacate numa taça larga.</li><li><b>Envolver:</b> Tempere com sumo de lima fresca e um fio de azeite, misturando com cuidado para não esmagar a fruta.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_RISOTO_TOMATE_CONCHAS_BASILICO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz arbóreo</li><li>1/2 chávena de puré de tomate rústico</li><li>Folhas de manjericão fresco e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Refogue o arroz em azeite, incorpore o puré de tomate e junte caldo de legumes aos poucos mexendo sempre.</li><li><b>Terminar:</b> Assim que o arroz estiver cremoso, apague o lume e adicione as folhas de manjericão fresco picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CANELONES_VEGAN_CURGETE + "', '<h3>Ingredientes:</h3><ul><li>1 curgete grande cortada em lâminas finas</li><li>100 g de tofu firme amassado</li><li>1 chávena de espinafres cozidos e molho de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Misture o tofu com os espinafres. Coloque uma porção em cada lâmina de curgete e enrole como um canelone.</li><li><b>Forno:</b> Disponha os rolos num pirex, cubra com o molho de tomate e leve ao forno a assar por 15 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_QUINOA_MELANCIA_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de quinoa cozida fria</li><li>1 chávena de melancia em cubos sem sementes</li><li>Folhas de hortelã picadas e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Numa saladeira junte a quinoa fria com os cubos sumarentos de melancia fresca.</li><li><b>Servir:</b> Adicione a hortelã picada, tempere com um fio de azeite e sumo de lima e sirva de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CARIL_ALBICOQUE_GRAO_BICO + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de grão-de-bico cozido</li><li>2 alperces (albicoques) frescos fatiados</li><li>100 ml de leite de coco e pó de caril</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Faça um refogado com cebola e pó de caril. Junte o leite de coco e o grão-de-bico cozido.</li><li><b>Cozzer:</b> Adicione as fatias de alperce nos minutos finais para que fiquem macias sem se desfazerem por completo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALTEADO_TOFU_MILHO_DOCE + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em cubos</li><li>1/2 chávena de milho doce em grão</li><li>1/4 de pimento vermelho e molho de soja</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure os cubos de tofu numa frigideira com azeite até ganharem uma cor bonita e firme.</li><li><b>Adicionar:</b> Junte o milho doce e o pimento vermelho picado. Regue com uma colher de molho de soja e envolva.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_GAZPACHO_ALGARVIO_PIMENTOS_PEPINO + "', '<h3>Ingredientes:</h3><ul><li>2 tomates maduros bem firmes</li><li>1/2 pepino limpo e 1/4 de pimento verde</li><li>Água fria, gelo, azeite e vinagre</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Pique os tomates, o pepino e o pimento à mão em cubos milimétricos muito pequenos.</li><li><b>Misturar:</b> Junte os vegetais numa tigela com água bem fria, pedras de gelo, alho esmagado, azeite e vinagre.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_MACARRAO_CAPRESE_JULHO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa macarrão cozida fria</li><li>1/2 chávena de tomates cherry fatiados</li><li>40 g de queijo mozarela fresco e manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Montagem:</b> Misture o macarrão frio com as metades de tomate cherry e os pedaços de queijo mozarela.</li><li><b>Tempero:</b> Adicione folhas frescas de manjericão picadas e regue com azeite virgem extra em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_EMPADAO_BATATA_DOCE_LENTILHAS_VERMELHAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas vermelhas cozidas</li><li>1 batata-doce grande cozida e esmagada</li><li>Polpa de tomate e cebola</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Estufe as lentilhas com cebola e polpa de tomate até secar o molho. Coloque no fundo de um pirex.</li><li><b>Cobrir:</b> Cubra com o puré cremoso de batata-doce e leve ao forno a dourar por alguns minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PAELLA_VEGETARIANA_VERAO_JULHO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de arroz vaporizado</li><li>Mistura de legumes de verão (pimento, feijão-verde, curgete)</li><li>Açafrão em pó e caldo de legumes</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os legumes fatiados numa frigideira larga com azeite e uma colher de açafrão em pó.</li><li><b>Arroz:</b> Adicione o arroz e o caldo quente. Deixe cozinhar sem mexer em lume médio até secar o líquido.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_GRAO_MANGA_RUCULA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de grão-de-bico cozido</li><li>1/2 manga madura em cubos</li><li>1 chávena de folhas de rúcula selvagem</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Escorra o grão-de-bico cozido. Junte os cubos de manga e as folhas limpas de rúcula numa saladeira.</li><li><b>Servir:</b> Tempere com um fio de azeite virgem e vinagre balsâmico suave mesmo antes de levar à mesa.</li></ol>');");

        // ==========================================
// JANTARES - JULHO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_GASPACHO_TOMATE_FRIO_CEBOLINHO + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros grandes</li><li>1/4 de pimento verde</li><li>1/2 pepino e cebolinho fresco</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Processe os tomates, o pimento e o pepino descascado com um fio de azeite e água fria.</li><li><b>Arrefecer:</b> Leve ao frigorifico e sirva esta sopa bem fria salpicada com cebolinho picado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TOFU_GRELHADO_SALADA_PEPINO_MENTA + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1 pepino médio</li><li>Folhas de menta fresca e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Corte o tofu em fatias, tempere com sal e grelhe numa chapa bem quente com azeite.</li><li><b>Salada:</b> Fatie o pepino em rodelas finas, junte a menta picada e sirva a acompanhar o tofu.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_FRIO_MELAO_REFRESCANTE + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de polpa de melão bem maduro</li><li>1 colher de sopa de azeite virgem</li><li>Folhas de hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Triture a polpa do melão fresca com o azeite e folhas de hortelã até obter um creme liso.</li><li><b>Servir:</b> Mantenha no frigorifico até ao momento de servir para garantir a máxima frescura.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_MELANCIA_RUCULA_QUEIJO_FETA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de melancia em cubos sem sementes</li><li>1 chávena de folhas de rúcula</li><li>40 g de queijo feta</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Numa taça larga misture os cubos de melancia fresca com as folhas limpas de rúcula.</li><li><b>Finalizar:</b> Salpique com o queijo feta esfarelado e regue com um fio invisível de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_CENOURA_FRESCO_SUMO_LIMAO + "', '<h3>Ingredientes:</h3><ul><li>3 cenouras médias</li><li>1 cebola e 1 dente de alho</li><li>Sumo de 1/2 limão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as cenouras, a cebola e o alho a cozer em água temperada com uma pitada de sal.</li><li><b>Arrefecer:</b> Triture tudo até obter um creme e, depois de frio, misture o sumo de limão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_COGUMELOS_SALTEADOS_ALHO_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>200 g de cogumelos variados limpos</li><li>2 dentes de alho picados</li><li>Salsa fresca picada</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos fatiados numa frigideira com azeite e os dentes de alho picados.</li><li><b>Aromatizar:</b> Deixe os sucos evaporarem até dourarem e polvilhe com a salsa fresca antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_FEIJAO_VERDE_AZEITE_ALHO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão-verde cortado</li><li>1 batata e 1 cebola</li><li>2 dentes de alho</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza a batata e a cebola e triture para formar um caldo simples e leve de sopa.</li><li><b>Legumes:</b> Adicione o feijão-verde limpo e os alhos picados, deixando ferver até ficarem tenros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_RUCULA_AMEIXA_AMENDOA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de rúcula selvagem</li><li>2 ameixas frescas fatiadas</li><li>1 colher de amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Disponha as folhas de rúcula e as fatias de ameixa fresca numa saladeira.</li><li><b>Topping:</b> Junte as amêndoas ligeiramente tostadas e tempere com azeite virgem extra em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_FRIO_ERVILHAS_MENT + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de ervilhas cozidas</li><li>1 cebola pequena</li><li>Folhas de menta fresca</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Triture as ervilhas quentes com a cebola cozida e um punhado de folhas de menta fresca.</li><li><b>Gelo:</b> Passe o creme por um coador se preferir e leve ao frigorifico para servir bem gelado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_OMELETE_TOMATE_CHERRY_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros</li><li>1/2 chávena de tomates cherry</li><li>Oregãos secos</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Bata os ovos com sal e verta na frigideira. Junte os tomates cherry cortados em metades.</li><li><b>Dobrar:</b> Polvilhe com os oregãos e dobre a omelete assim que a base se mostrar firme e cozida.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_LEGUMES_JULHO_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 curgete e 1 cenoura</li><li>1/2 nabo em cubos pequenos</li><li>Folhas de manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Sopa:</b> Coza todos os legumes cortados finamente num caldo rústico de vegetais.</li><li><b>Perfumar:</b> Apague o lume e introduza as folhas de manjericão rasgadas para libertar aroma.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_COLESLAW_IOGURTE_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de repolho branco ralado</li><li>1/2 cenoura ralada</li><li>3 colheres de iogurte e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte o repolho e a cenoura numa taça até estarem bem distribuídos.</li><li><b>Molho:</b> Envolva o iogurte natural e as folhas de hortelã picadas criando uma salada fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_ABOBORA_LEVE_SOUCHE + "', '<h3>Ingredientes:</h3><ul><li>250 g de abóbora limpa</li><li>1 chuchu médio (souche)</li><li>1 cebola pequena e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte os ingredientes em cubos e leve a cozer com uma quantidade mínima de água.</li><li><b>Passar:</b> Triture com a varinha mágica até obter um puré liso e sirva morno ou frio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TOFU_MEXIDO_TOMATE_CHERRY_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1/2 chávena de tomates cherry</li><li>Folhas de manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Esmague o tofu com o garfo e cozinhe em azeite. Adicione os tomates cherry cortados.</li><li><b>Finalizar:</b> Mexa até murcharem e envolva as folhas de manjericão rasgadas mesmo antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_LENTILHAS_VERAO_RASPAS_LIMAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas vermelhas</li><li>1 cenoura pequena</li><li>Raspas de 1/2 limão ou lima</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as lentilhas vermelhas a cozer com a cenoura cortada até ficarem bem macias.</li><li><b>Finalizar:</b> Triture tudo em creme e salpique com as raspas finas de limão para um travo fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_TZATZIKI_PEPINO_MENTA_AZEITE + "', '<h3>Ingredientes:</h3><ul><li>1 pepino médio ralado</li><li>1 iogurte grego natural ou vegetal</li><li>1 dente de alho e folhas de menta</li></ul><h3>Preparação:</h3><ol><li><b>Drenar:</b> Esprema o pepino ralado num pano para retirar o excesso de água acumulada.</li><li><b>Envolver:</b> Misture o pepino com o iogurte, o alho esmagado, azeite e folhas de menta fresca picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_COUVE_FLOR_FRIO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>1/2 couve-flor média</li><li>1 alho-francês (apenas parte branca)</li><li>Azeite virgem</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Corte os vegetais e leve a cozer. Triture energeticamente até atingir textura aveludada.</li><li><b>Frio:</b> Deixe arrefecer por completo e coloque no frigorifico antes de servir à mesa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_WRAP_HUMUS_TOMATE_PEPINO_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha de trigo integral</li><li>2 colheres de sopa de húmus</li><li>Tomate e pepino em cubos pequenos</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Espalhe o húmus de forma homogénea sobre toda a superfície da tortilha mole.</li><li><b>Enrolar:</b> Coloque os cubos frescos de tomate e pepino no centro e feche o wrap firmemente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_GRAO_CURGETE_FOLHAS_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de grão cozido</li><li>1 curgete média com casca</li><li>Folhas de manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza a curgete em pedaços e junte o grão-de-bico já cozido para apurar sabores.</li><li><b>Finalizar:</b> Triture a sopa e perfume o prato utilizando as folhas frescas de manjericão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_ESPINAFRE_MANGA_PINDAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de folhas de espinafres</li><li>1/2 manga madura em tiras</li><li>1 colher de amendoins picados (pindas)</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture as folhas limpas de espinafres com as tiras de manga numa saladeira.</li><li><b>Topping:</b> Salpique com os amendoins picados e tempere recorrendo a azeite e sumo de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_TOMATE_PEPINO_SOPA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>2 tomates maduros e sumarentos</li><li>1/2 pepino e 1/4 pimento vermelho</li><li>Água fresca e pedras de gelo</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Coloque os vegetais limpos no liquidificador com água e triture em velocidade máxima.</li><li><b>Servir:</b> Tempere com azeite e vinagre e sirva com pedras de gelo num copo ou taça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_OVOS_ESCALFADOS_MOLHO_TOMATE_JULHO + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros frescos</li><li>1 chávena de molho de tomate rústico</li><li>Oregãos e sal</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Deite o molho de tomate num tacho pequeno e deixe levantar fervura suave.</li><li><b>Escalfar:</b> Abra os ovos diretamente no molho, tape o tacho e cozinhe por 4 a 5 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_MINESTRONE_JULHO_LEVE + "', '<h3>Ingredientes:</h3><ul><li>Cubos de curgete, cenoura e feijão-verde</li><li>2 colheres de massinha miúda</li><li>Caldo leve de vegetais</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Coza a mistura de legumes picados finamente no caldo de vegetais a ferver.</li><li><b>Massa:</b> Adicione a massinha nos minutos finais e deixe cozinhar até ficar al dente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_BETERRABA_LARANJA_NOZES_JUL + "', '<h3>Ingredientes:</h3><ul><li>1 beterraba cozida</li><li>1/2 laranja em gomos limpos</li><li>3 nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Corte a beterraba cozida e fria em cubos e disponha os gomos de laranja ao lado.</li><li><b>Servir:</b> Distribua as nozes picadas por cima e tempere com um fio leve de azeite rústico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_CURGETE_COENTROS_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>2 curgetes médias</li><li>1 cebola pequena</li><li>Coentros e hortelã frescos</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as curgetes e a cebola a cozer com pouca água temperada com sal.</li><li><b>Triturar:</b> Junte os coentros e a hortelã em cru e reduza a um creme verde e perfumado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_PORTOBELLO_GRELHADO_TOMATE_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1 cogumelo Portobello grande</li><li>1/2 tomate maduro fatiado</li><li>Folhas de manjericão fresco</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Limpe o cogumelo e grelhe-o de ambos os lados numa frigideira quente com azeite.</li><li><b>Montar:</b> Coloque as fatias de tomate sobre o cogumelo e decore com o manjericão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_ALHO_FRANCES_CURGETE_CREME_LEVE + "', '<h3>Ingredientes:</h3><ul><li>1 alho-francês largo</li><li>1 curgete média com casca</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte o alho-francês e a curgete em rodelas e leve a cozer em água fervente.</li><li><b>Puré:</b> Triture tudo muito bem até atingir a consistência de um creme suave e aveludado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SALADA_ALFACE_MILHO_AVOCADO_FRESCO + "', '<h3>Ingredientes:</h3><ul><li>Folhas de alface cortadas</li><li>3 colheres de sopa de milho doce</li><li>1/2 abacate fatiado (avocado)</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque as folhas de alface lavadas numa taça e adicione o milho doce escorrido.</li><li><b>Acabamento:</b> Disponha as fatias de abacate fresco por cima e tempere com sumo de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_CREME_ESPARGOS_FRIO_FOLHAS_MENTA + "', '<h3>Ingredientes:</h3><ul><li>1 molho de espargos verdes limpos</li><li>1 cebola pequena e folhas de menta</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza os espargos e a cebola. Triture tudo em conjunto com as folhas de menta.</li><li><b>Servir:</b> Deixe o creme arrefecer por completo e guarde no frigorifico até servir fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_TOFU_SALTEADO_MANGA_PIMENTOS_DOCES + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu em cubos</li><li>1/2 manga e 1/2 pimento vermelho</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure os cubos de tofu e as tiras de pimento numa frigideira com um fio de azeite.</li><li><b>Fruta:</b> Introduza os cubos de manga nos instantes finais apenas para aquecer e envolver sabores.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_JUL_SOPA_JULIANA_REPOLHO_CENOURA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de legumes em juliana (repolho e cenoura)</li><li>Base de batata e cebola trituradas</li></ul><h3>Preparação:</h3><ol><li><b>Caldo:</b> Prepare uma base de sopa lisa triturando a batata e a cebola cozidas.</li><li><b>Apurar:</b> Adicione a juliana de repolho e cenoura e deixe ferver até os legumes ficarem macios.</li></ol>');");

        // ==========================================
// PEQUENOS ALMOÇOS - AGOSTO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PANQUECA_MILHO_DOCE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de milho doce em grão</li><li>1 ovo inteiro e 2 colheres de farinha de aveia</li><li>Uma pitada de sal fino</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Triture o milho doce com o ovo e a farinha de aveia no liquidificador até obter um creme liso.</li><li><b>Grelhar:</b> Verta porções da massa numa frigideira antiaderente quente e doure ligeiramente de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_OVERNIGHT_TROPICAL_COCO_ANANAS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>1/2 chávena de leite de coco leve</li><li>1 fatia de ananás fresco em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte a aveia com o leite de coco numa taça e adicione os cubos de ananás por cima.</li><li><b>Repousar:</b> Tape a taça e coloque no frigorífico durante a noite para consumir bem fresco pela manhã.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORRADA_SMUSH_ERVIHA_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral ou de sementes</li><li>3 colheres de sopa de ervilhas cozidas</li><li>Folhas de hortelã fresca e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Triture grosseiramente as ervilhas cozidas com folhas de hortelã fresca e um fio de azeite.</li><li><b>Montar:</b> Torre a fatia de pão e espalhe este preparado verde e rústico sobre a superfície quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PUDIM_CHIA_MELOA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>1/2 chávena de bebida vegetal de arroz</li><li>1 fatia de meloa e uma pitada de gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Gelificar:</b> Misture a chia com a bebida vegetal e guarde no frigorífico por quatro horas até espessar.</li><li><b>Finalizar:</b> Reduza a meloa a puré com o gengibre e coloque sobre o pudim de chia mesmo antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BOLO_CANECA_ALFARROBA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 ovo inteiro e 2 colheres de farinha de aveia</li><li>1 colher de sopa de alfarroba em pó</li><li>2 nozes picadas grosseiramente</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte o ovo, a aveia, a alfarroba e as nozes picadas diretamente no interior de uma caneca.</li><li><b>Cozzer:</b> Mexa energicamente com um garfo e leve ao micro-ondas em potência máxima por um minuto e meio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_WAFFLE_AVEIA_COMPOTA_FIGO + "', '<h3>Ingredientes:</h3><ul><li>1 ovo e 3 colheres de sopa de aveia</li><li>2 colheres de sopa de leite magro ou vegetal</li><li>1 colher de compota de figo caseira</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Misture bem o ovo com a aveia e o leite até criar uma massa líquida mas consistente.</li><li><b>Cozinhar:</b> Verta na máquina de waffles untada e cozinhe até dourar. Sirva com a compota de figo no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TACA_AÇAI_RODOLES_BANANA_GRANOLA + "', '<h3>Ingredientes:</h3><ul><li>1 polpa de açaí congelada e pura</li><li>1/2 banana fatiada às rodelas</li><li>2 colheres de sopa de granola crocante</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Processe a polpa de açaí com um pouco de água fresca até obter uma consistência pastosa de colher.</li><li><b>Decorar:</b> Transfira para uma taça larga e organize as rodelas de banana e a granola em faixas paralelas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PÃO_FRIGIDEIRA_RAPIDO_SÉSAMO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de aveia</li><li>1 colher de sopa de iogurte natural</li><li>1 colher de chá de sementes de sésamo</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Amasse a farinha com o iogurte até formar uma bola compacta. Molde um disco plano com as mãos.</li><li><b>Dourar:</b> Polvilhe com o sésamo e cozinhe na frigideira antiaderente quente de ambos os lados até firmar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BATIDO_ENERGIA_PAPAIA_AVEIA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de papaia média e madura</li><li>2 colheres de sopa de flocos de aveia</li><li>1 chávena de bebida de amêndoa bem fria</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Descasque a papaia fresca e descarte as sementes pretas do interior. Corte em cubos.</li><li><b>Liquidificar:</b> Junte a fruta, a aveia e a bebida de amêndoa no liquidificador e triture em velocidade máxima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORRADA_PATE_AZEVITONA_VERDE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio ou rústico</li><li>5 azeitonas verdes sem caroço</li><li>1 colher de sopa de queijo creme leve</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Esmague finamente as azeitonas verdes e misture-as com o queijo creme até formar um paté.</li><li><b>Barrar:</b> Torre a fatia de pão e espalhe este paté rústico caseiro por cima enquanto o pão estiver quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_CREPE_POLVILHADO_CANELA_MACA + "', '<h3>Ingredientes:</h3><ul><li>1 ovo inteiro e 2 colheres de farinha de aveia</li><li>2 colheres de sopa de água fria</li><li>1/2 maçã ralada e canela em pó</li></ul><h3>Preparação:</h3><ol><li><b>Crepe:</b> Bata o ovo com a farinha e a água. Verta na frigideira e faça um crepe fino de ambos os lados.</li><li><b>Recheio:</b> Coloque a maçã ralada no interior do crepe, dobre ao meio e polvilhe generosamente com canela.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_IOGURTE_COCO_BAGAS_GOJI_CRUNCH + "', '<h3>Ingredientes:</h3><ul><li>1 embalagem de iogurte de coco natural</li><li>1 colher de sopa de bagas de goji</li><li>1 colher de sopa de sementes de girassol</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Verta o iogurte de coco fresco diretamente para uma taça ou copo de pequeno-almoço.</li><li><b>Adicionar:</b> Distribua as bagas de goji e as sementes de girassol por cima para criar um contraste crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_MUFFIN_SALGADO_GRAO_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de grão-de-bico</li><li>1 ovo inteiro e cubos de legumes (pimento e curgete)</li><li>Sal fino e uma pitada de fermento</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva a farinha de grão com o ovo batido, o fermento, uma pitada de sal e os legumes picados.</li><li><b>Assar:</b> Deite o preparado numa forma de silicone para queques e leve ao forno a assar por 15 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SMOOTHIE_VERDE_ESPINAFRE_MANGA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de folhas de espinafres limpos</li><li>1/2 manga madura descascada</li><li>1/2 copo de água mineral fresca</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Insira as folhas de espinafres, os cubos de manga e a água fria no copo do liquidificador.</li><li><b>Bater:</b> Processe energeticamente até que o líquido fique homogéneo, verde brilhante e sem pedaços de folhas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORRADA_RICOTA_AMIXA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral torrado</li><li>2 colheres de sopa de queijo ricota cremoso</li><li>1 ameixa fresca fatiada em lamelas</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Cubra a superfície da torrada integral com o queijo ricota de forma uniforme e suave.</li><li><b>Montar:</b> Organize as fatias de ameixa fresca por cima do queijo para um pequeno-almoço fresco de agosto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TACA_QUINOA_DOCE_LEITE_COCO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de quinoa cozida simples</li><li>1/2 chávena de leite de coco leve</li><li>Casca de limão e canela moída</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Leve a quinoa cozida ao lume com o leite de coco e a casca de limão até ferver e engrossar.</li><li><b>Servir:</b> Verta para uma taça individual e polvilhe com a canela em pó para perfumar o prato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SCOTTISH_PORRIDGE_SALGADA_AZEITE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia grossos</li><li>1 chávena de água quente</li><li>Uma pitada de sal e um fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Cozinhe os flocos de aveia na água com a pitada de sal até criar papas cremosas e firmes.</li><li><b>Empratar:</b> Transfira para uma taça rasa e adicione um fio de azeite virgem extra em cru mesmo antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BATIDO_CACAU_PURO_MANTEIGA_AMENDOIM + "', '<h3>Ingredientes:</h3><ul><li>1 banana média e madura</li><li>1 colher de chá de cacau puro em pó</li><li>1 colher de manteiga de amendoim e leite vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Coloque a banana fatiada, o cacau em pó, a manteiga de amendoim e o leite vegetal no liquidificador.</li><li><b>Procesar:</b> Misture tudo na velocidade máxima até ganhar uma textura espessa e aveludada de batido.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_GALETTE_RUSTICA_MORANGO_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>1 mini disco de massa quebrada pronta</li><li>4 morangos frescos fatiados</li><li>Folhas frescas de manjericão picado</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Coloque os morangos fatiados no centro da massa e dobre as abas laterais para dentro.</li><li><b>Forno:</b> Leve ao forno a assar até dourar a massa. Decore com o manjericão fresco picado por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORRADA_GELEIA_PIMENTO_QUEIJO_VEG + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico de mafra torrado</li><li>1 colher de sopa de queijo creme vegetal</li><li>1 colher de chá de geleia de pimento doce</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Aplique o queijo creme vegetal sobre a torrada quente criando uma base aveludada.</li><li><b>Cobrir:</b> Disponha uma camada muito fina de geleia de pimento doce para um toque agridoce especial.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BARRINHA_CRUDA_TAMARA_AVELA + "', '<h3>Ingredientes:</h3><ul><li>4 tâmaras secas e sem caroço</li><li>6 avelãs inteiras sem casca</li><li>1 colher de sopa de flocos de aveia finos</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque todos os ingredientes num processador de alimentos potente e pique até formar uma pasta moldável.</li><li><b>Moldar:</b> Retire a pasta, molde em formato de barra retangular e refrigere antes de consumir para firmar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SUMO_PRENSADO_MELANCIA_LIMA + "', '<h3>Ingredientes:</h3><ul><li>2 fatias generosas de melancia fria</li><li>Sumo espremido de 1/2 lima fresca</li><li>Cubos de gelo a gosto</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificar:</b> Introduza a melancia limpa de casca e o sumo de lima fresca no copo do liquidificador.</li><li><b>Servir:</b> Triture na velocidade máxima, passe por um coador se preferir e sirva num copo com gelo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PANQUECA_TRIGO_SARRACENO_FRUTOS + "', '<h3>Ingredientes:</h3><ul><li>1 ovo inteiro e 2 colheres de farinha de trigo sarraceno</li><li>2 colheres de leite magro ou água</li><li>Mistura de frutos vermelhos</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Mexa bem o ovo com a farinha de trigo sarraceno e o leite até criar uma polpa sem grumos.</li><li><b>Cozzer:</b> Faça a panqueca numa frigideira quente antiaderente e sirva coberta com os frutos vermelhos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SCONES_AVEIA_PASSA_UVA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de aveia fina</li><li>2 colheres de sopa de iogurte natural</li><li>1 colher de sopa de passas de uva</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Envolva a farinha de aveia, o iogurte natural e as passas numa tigela até formar uma pasta densa.</li><li><b>Forno:</b> Molde pequenos montinhos com as mãos, coloque num tabuleiro de forno e asse por 12 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BATIDO_GOIABA_POLPA_FRESCA + "', '<h3>Ingredientes:</h3><ul><li>Polpa limpa de 1 goiaba fresca e madura</li><li>1/2 chávena de iogurte natural líquido</li><li>1/2 copo de água mineral fresca</li></ul><h3>Preparação:</h3><ol><li><b>Extrair:</b> Corte a goiaba ao meio e retire toda a polpa interior. Junte o iogurte líquido e a água.</li><li><b>Triturar:</b> Processe tudo no liquidificador até obter uma consistência macia e aveludada. Sirva fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORRADA_MANTEIGA_CAJU_SEMENTES + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de sementes ou integral</li><li>1 colher de sopa de manteiga de caju pura</li><li>Mistura de sementes de sésamo e girassol</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Coloque a fatia de pão a torrar até que fique bem estaladiça nas bordas.</li><li><b>Finalizar:</b> Barre a manteiga de caju cremosa na torrada e polvilhe imediatamente com as sementes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TACA_KEFIR_UVA_CRISP_PAINÇO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de kefir natural fresco</li><li>5 uvas frescas cortadas em metades</li><li>2 colheres de sopa de painço expandido (crisp)</li></ul><h3>Preparação:</h3><ol><li><b>Montagem:</b> Coloque o kefir natural fresco na base de uma taça larga de pequeno-almoço.</li><li><b>Topping:</b> Distribua as metades de uva e polvilhe com o painço expandido estaladiço antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PUDIM_LINHAÇA_PERA_ROCHA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de linhaça moída</li><li>1/2 chávena de água morna</li><li>1/2 pera rocha fatiada em cubos pequenos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture a linhaça moída com a água morna e deixe repousar para criar um gel espesso.</li><li><b>Decorar:</b> Adicione os cubos frescos de pera rocha por cima e saboreie este pudim leve de colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_MINI_QUICHE_TOFU_SEM_MASSA + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu firme amassado com garfo</li><li>1 ovo inteiro fresco</li><li>Sal fino e ervas aromáticas frescas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva energeticamente o tofu amassado com o ovo inteiro batido e adicione as ervas e sal.</li><li><b>Assar:</b> Distribua por pequenas formas de queque de silicone e leve ao forno até estarem firmes ao toque.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BOLACHAS_AVEIA_BANANA_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>1 banana grande bem madura</li><li>4 colheres de sopa de flocos de aveia finos</li><li>1 colher de chá de pepitas de chocolate</li></ul><h3>Preparação:</h3><ol><li><b>Amassar:</b> Esmague a banana com um garfo numa tigela. Adicione a aveia e incorpore as pepitas.</li><li><b>Moldar:</b> Faça pequenas esferas espalmadas num tabuleiro e asse no forno até estarem douradas e firmes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BRUSCHETTA_TOMATE_RALADO_AZEITE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grossa de pão alentejano rústico</li><li>1/2 tomate bem maduro ralado na hora</li><li>1 fio generoso de azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Pão:</b> Torre a fatia grossa de pão de forma a ficar com as superfícies estaladiças.</li><li><b>Finalizar:</b> Espalhe o tomate maduro ralado por cima, salpique sal e regue com o azeite em cru.</li></ol>');");

