        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_CEVICHE_PALMITO_MANGA_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de palmito em conserva</li><li>1/2 manga madura em cubos</li><li>Sumo de 2 limas e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Pique o palmito e a manga em cubos pequenos e homogéneos.</li><li><b>Marinar:</b> Junte tudo numa taça, regue com o sumo de lima fresco e polvilhe os coentros picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TABULE_BULGUR_HORTELA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de bulgur cozido</li><li>1/2 chávena de grão-de-bico cozido</li><li>Tomate, pepino e hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva o bulgur frio com o grão-de-bico, o tomate e o pepino cortados em cubos finos.</li><li><b>Temperar:</b> Adicione uma quantidade generosa de hortelã fresca picada, sal e um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_ESPETADAS_TOFU_FUMADO_PIMENTON + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu fumado firme</li><li>1/2 pimento doce vermelho</li><li>1/2 cebola roxa e pimentão doce</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Corte o tofu e os vegetais em quadrados. Alterne-os espetando-os em espetos de madeira.</li><li><b>Grelhar:</b> Polvilhe com o pimentão doce e grelhe numa chapa bem quente untada com azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SALADA_CROCANTE_REPOLHO_AMENDOIM + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de repolho roxo em juliana</li><li>1/2 cenoura ralada</li><li>2 colheres de sopa de amendoins tostados</li></ul><h3>Preparação:</h3><ol><li><b>Envolver:</b> Numa saladeira misture o repolho roxo cortado finamente com a cenoura ralada.</li><li><b>Finalizar:</b> Salpique os amendoins tostados por cima e tempere com azeite e vinagre suave.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BURRITO_FRIO_HUMUS_ALFAFA + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha de trigo integral</li><li>3 colheres de sopa de húmus caseiro</li><li>Rebentos de alfafa e cenoura ralada</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Espalhe o húmus de forma homogénea sobre toda a superfície da tortilha macia.</li><li><b>Enrolar:</b> Disponha os rebentos de alfafa e a cenoura no centro, fechando o burrito firmemente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TACOS_JACKFRUIT_BARBECUE_MILHO + "', '<h3>Ingredientes:</h3><ul><li>2 tortilhas de milho pequenas</li><li>1 chávena de jaca em conserva (jackfruit)</li><li>Molho barbecue e milho doce</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Desfie a jaca limpa e salteie numa frigideira com o molho barbecue até apurar.</li><li><b>Montar:</b> Recheie as tortilhas com a jaca desfiada e adicione grãos de milho doce por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_NOODLES_ARROZ_FRIOS_SESAMO_LIMA + "', '<h3>Ingredientes:</h3><ul><li>100 g de noodles de arroz</li><li>1 colher de sementes de sésamo</li><li>Sumo de 1/2 lima e fitas de pepino</li></ul><h3>Preparação:</h3><ol><li><b>Arrefecer:</b> Coza os noodles, escorra e passe por água gelada para parar a cozedura.</li><li><b>Envolver:</b> Misture as fitas de pepino, polvilhe com o sésamo e regue com o sumo de lima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_FEIJOADA_COGUMELOS_PLEUROTUS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão encarnado cozido</li><li>100 g de cogumelos pleurotus</li><li>Polpa de tomate, cebola e alho</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Faça um refogado leve com cebola e alho. Adicione os cogumelos pleurotus em tiras.</li><li><b>Estufar:</b> Junte o feijão e a polpa de tomate, deixando cozinhar em lume brando até o molho engrossar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_STIR_FRY_SEITAN_BROCOLOS_ALHO + "', '<h3>Ingredientes:</h3><ul><li>150 g de seitan em tiras finas</li><li>1 chávena de floretes de brócolos</li><li>2 dentes de alho e molho de soja</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe o seitan e os brócolos numa frigideira wok com um fio de azeite e alho picado.</li><li><b>Apurar:</b> Regue com um salpico de molho de soja nos instantes finais e mexa bem antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SALADA_QUINOA_VERMELHA_EDAMAME + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de quinoa vermelha cozida</li><li>1/2 chávena de feijão edamame limpo</li><li>Pimento amarelo em cubos e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Junte a quinoa vermelha fria com o feijão edamame numa taça funda de salada.</li><li><b>Finalizar:</b> Adicione os cubos de pimento amarelo, tempere com azeite e sumo de limão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_CHILI_VEGANO_TRES_FEIJOES + "', '<h3>Ingredientes:</h3><ul><li>Feijão preto, encarnado e branco (mistura)</li><li>1/2 chávena de tomate pelado picado</li><li>Cominhos em pó e uma pitada de sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coloque os três feijões e o tomate pelado num tacho pequeno com um pouco de água.</li><li><b>Condimentar:</b> Tempere com os cominhos e deixe ferver até criar um molho de chili espesso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_MAC_AND_CHEESE_ABOBORA_CAJU + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa macarrão cozida</li><li>3 colheres de puré de abóbora cozida</li><li>2 colheres de cajus demolhados e triturados</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Triture os cajus com o puré de abóbora e um pouco de água morna até obter um creme.</li><li><b>Envolver:</b> Misture este creme aveludado com a massa macarrão quente e sirva imediatamente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_KEDGEREE_VEGANO_ARROZ_CURCUMA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de arroz agulha cozido</li><li>1 colher de chá de curcuma em pó</li><li>Ervilhas e tofu fumado esfarelado</li></ul><h3>Preparação:</h3><ol><li><b>Colorir:</b> Aqueça o arroz numa frigideira envolvendo a curcuma até ficar com uma cor amarela.</li><li><b>Misturar:</b> Adicione as ervilhas cozidas e o tofu esfarelado, mexendo até aquecer uniformemente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_XAREM_ALGARVIO_COGUMELOS_SALTEADOS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha de milho</li><li>100 g de cogumelos variados limpos</li><li>Alho, azeite e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Papas:</b> Coza a farinha de milho em água temperada com sal, mexendo sempre até engrossar.</li><li><b>Cobertura:</b> Salteie os cogumelos em azeite e alho e sirva-os dispostos por cima do xarém quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_LASANHA_LENTILHAS_FOLHAS_COUVE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas castanhas cozidas</li><li>Folhas de couve lombarda escaldadas</li><li>Molho de tomate e cubos de curgete</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Num pirex alterne camadas de folhas de couve com o estufado de lentilhas e curgete.</li><li><b>Assar:</b> Cubra com um pouco de molho de tomate rústico e leve ao forno a apurar durante 20 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_GNOCCHI_BATATA_SALVIA_AZEITE + "', '<h3>Ingredientes:</h3><ul><li>150 g de gnocchi de batata frescos</li><li>4 folhas de sálvia fresca inteiras</li><li>1 colher de sopa de azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve o gnocchi a cozer em água a ferver até que subam todos à superfície do tacho.</li><li><b>Saltear:</b> Escorra os gnocchi e passe-os rapidamente por uma frigideira com o azeite e a sálvia.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_FALAFEL_FORNO_MOLHO_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>3 unidades de falafel de grão caseiros</li><li>1 colher de sopa de pasta de tahini</li><li>Sumo de limão e água morna</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Coloque os falafels num tabuleiro e leve ao forno a aquecer e dourar ligeiramente.</li><li><b>Molho:</b> Misture o tahini com sumo de limão e água morna até criar um molho leve para regar por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_COUSCOUS_ISRAELITA_VEGETAIS_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de couscous israelita cozido</li><li>Cubos de beringela, curgete e pimento</li><li>Oregãos secos e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve os cubos de vegetais ao forno com um fio de azeite e oregãos até dourarem.</li><li><b>Misturar:</b> Envolva os vegetais assados no couscous pérola cozido e sirva quente ou morno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_HAMBURGUER_FEIJAO_FRADE_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de feijão-frade cozido</li><li>3 colheres de arroz cozido simples</li><li>1 colher de farinha de aveia e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Esmague o feijão-frade com o arroz, junte a farinha de aveia e a salsa fresca picada.</li><li><b>Dourar:</b> Molde um hambúrguer com as mãos e cozinhe na frigideira antiaderente com azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_POLENTA_FORNO_MOLHO_FUNGHI + "', '<h3>Ingredientes:</h3><ul><li>2 fatias grossas de polenta firme</li><li>2 colheres de cogumelos secos reidratados</li><li>Polpa de tomate e 1 dente de alho</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Coloque as fatias de polenta no forno até formarem uma crosta ligeira e estaladiça.</li><li><b>Molho:</b> Faça um molho espesso com os cogumelos e o tomate e verta generosamente por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SALADA_LENTILHAS_BELUGA_NOZ_MOSTARDA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas beluga cozidas</li><li>3 nozes picadas e folhas de rúcula</li><li>1 colher de chá de mostarda antiga</li></ul><h3>Preparação:</h3><ol><li><b>Juntar:</b> Numa taça coloque as lentilhas pretas cozidas e frias juntamente com as folhas de rúcula.</li><li><b>Molho:</b> Adicione as nozes picadas e envolva com um molho feito de mostarda antiga e azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TABULE_TRIGO_SARRACENO_PEPINELLA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de trigo sarraceno cozido</li><li>1/2 pepino e 1 tomate picados</li><li>Salsa fresca picada e sumo de limão</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte o trigo sarraceno frio com os cubos de pepino e tomate numa saladeira.</li><li><b>Refrescar:</b> Polvilhe com bastante salsa e regue com sumo de limão e azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_ESTUFADO_LENTILHAS_ABOBORA_MANTEIGA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas castanhas</li><li>1/2 chávena de abóbora-manteiga em cubos</li><li>Cebola e 1 folha de louro</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Leve as lentilhas a cozinhar com os cubos de abóbora, cebola picada e o louro.</li><li><b>Apurar:</b> Deixe ferver lentamente até que a abóbora fique macia e o caldo bem aveludado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_QUICHE_BATATA_DOCE_ESPINAFRE_TOFU + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce média cortada em rodelas</li><li>1 chávena de espinafres e 100 g de tofu</li><li>Uma pitada de sal e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Forre o fundo de uma tarteira com as rodelas finas de batata-doce e leve a pré-aquecer.</li><li><b>Recheio:</b> Triture o tofu com os espinafres e sal, verta sobre a base e asse até solidificar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TOFU_BROA_FORNO_COENTROS + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em fatias</li><li>2 colheres de sopa de broa de milho ralada</li><li>1 dente de alho e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Cobertura:</b> Misture a broa ralada com o alho picado, os coentros e um fio generoso de azeite.</li><li><b>Assar:</b> Disponha a mistura sobre as fatias de tofu num pirex e leve ao forno a dourar a broa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_ALHO_FRANCES_RECHEADO_QUINOA + "', '<h3>Ingredientes:</h3><ul><li>2 talos largos de alho-francês (só a parte branca)</li><li>1/2 de chávena de quinoa cozida e nozes</li></ul><h3>Preparação:</h3><ol><li><b>Abrir:</b> Faça um corte longitudinal nos talos e coza-os ligeiramente para que fiquem moldáveis.</li><li><b>Assar:</b> Recheie o interior com a quinoa misturada com nozes picadas e leve ao forno a gratinar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_EMPADAO_SOJA_TEXTURIZADA_PURE + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de soja fina hidratada</li><li>Molho de tomate e puré de batata leve</li><li>Uma pitada de noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Cozinhe a soja fina hidratada no molho de tomate até obter um preparado apurado.</li><li><b>Montar:</b> Coloque a soja num pirex, cubra com o puré de batata e leve ao forno até dourar o topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BURRITO_BOWL_ARROZ_INTEGRAL + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de arroz integral cozido</li><li>1/2 chávena de feijão preto e milho</li><li>1/4 de abacate e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Organize o arroz integral, o feijão preto e o milho em secções numa taça larga.</li><li><b>Finalizar:</b> Adicione as fatias de abacate fresco no topo e salpique com coentros picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SALADA_POTATO_SALAD_MAIONESE_VEG + "', '<h3>Ingredientes:</h3><ul><li>1 batata grande cozida em cubos</li><li>2 colheres de sopa de maionese vegetal</li><li>Cebola roxa picada e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Arrefecer:</b> Deixe os cubos de batata cozida arrefecerem por completo antes de preparar a salada.</li><li><b>Misturar:</b> Envolva delicadamente as batatas com a maionese vegetal, a cebola roxa e a salsa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_PAELLA_FALSA_TRIGO_SARRACENO_ERVIHA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de trigo sarraceno</li><li>Ervilhas, pimento vermelho e açafrão</li><li>Caldo de legumes caseiro</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza o trigo sarraceno com o pimento doce e o açafrão no caldo de legumes a ferver.</li><li><b>Adicionar:</b> Introduza as ervilhas nos minutos finais e deixe secar a água como numa paella.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SUSHIBOWL_ARROZ_AVOCADO_ALGA_NORI + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de arroz para sushi cozido</li><li>1/4 de abacate (avocado) fatiado</li><li>Pepino em rodelas e tiras de alga nori</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o arroz na base de uma taça. Disponha o abacate e o pepino de forma bonita.</li><li><b>Servir:</b> Decore a taça espalhando as tiras de alga nori e sementes de sésamo por cima.</li></ol>');");

        // ==========================================
