        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_WRAP_QUENTE_FEIJAO_ENCARNADO + "', '<h3>Ingredientes:</h3><ul><li>Tortilha, feijão encarnado, especiarias</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Prepare o feijão e enrole na tortilha.</li><li><b>Grelhar:</b> Aqueça na chapa até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_BRUSCHETTA_TAPENADE_TOMATE_SECO + "', '<h3>Ingredientes:</h3><ul><li>Pão, tomate seco, azeitonas</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Faça a tapenade.</li><li><b>Montar:</b> Espalhe sobre o pão torrado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_SALADA_QUENTE_BATATA_DOCE_LENTILHA + "', '<h3>Ingredientes:</h3><ul><li>Batata-doce assada, lentilhas, vinagrete</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva os ingredientes ainda mornos.</li><li><b>Servir:</b> Prato leve e nutritivo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TORTILHA_ESPINAFRES_BATATA_DOCE_FORNO + "', '<h3>Ingredientes:</h3><ul><li>Batata-doce, espinafres, base vegan</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve ao forno numa forma até firmar.</li><li><b>Servir:</b> Fatiada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_ESPARGUETE_CURGETE_PESTO_AVELA + "', '<h3>Ingredientes:</h3><ul><li>Massa, curgete, pesto de avelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Prepare a massa.</li><li><b>Envolver:</b> Adicione o pesto caseiro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_TOFU_GRELHADO_SOJA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>Tofu, molho de soja, gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Marinar:</b> Deixe o tofu no molho.</li><li><b>Grelhar:</b> Sele bem na frigideira.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_AGO_MASSA_ORZO_TOMATE_FORNO_MANJERICAO + "', '<h3>Ingredientes:</h3><ul><li>Massa orzo, tomates cherry, manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Os tomates com a massa.</li><li><b>Finalizar:</b> Com manjericão fresco.</li></ol>');");

