        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_JAN_WRAP_TOFU_FUMADO_ESPINAFRE + "', '<h3>Ingredientes:</h3><ul><li>Wrap, tofu fumado, espinafres</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Enrole.</li><li><b>Aquecer:</b> Grelhe brevemente.</li></ol>');");

