        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_JAN_TARTE_RUSTICA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>Massa, abóbora, especiarias</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Recheie a massa.</li><li><b>Assar:</b> Forno quente.</li></ol>');");

