        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BRUSCHETTA_BROA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de broa de milho</li><li>2 colheres de sopa de puré de abóbora</li><li>Sementes de abóbora tostadas e canela</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Toste a fatia de broa de milho até ficar ligeiramente estaladiça.</li><li><b>Montar:</b> Espalhe o puré de abóbora morno por cima, polvilhe com canela em pó e sementes tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BAKED_OATS_REINETA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de aveia</li><li>1/2 maçã reineta ralada</li><li>1/2 chávena de bebida vegetal e canela</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva os flocos de aveia com a maçã reineta ralada, a bebida vegetal e a canela numa taça.</li><li><b>Cozer:</b> Leve ao forno ou ao microondas durante alguns minutos até a aveia absorver o líquido e dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PAPA_CEVADA_DIOSPIRO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de cevada em pó ou flocos</li><li>1 chávena de água ou bebida de aveia</li><li>1 diospiro bem maduro</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza os flocos de cevada na bebida vegetal em lume brando até obter uma papa cremosa.</li><li><b>Acompanhar:</b> Sirva numa taça com a polpa do diospiro maduro disposta por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TORRADA_MARMELADA_VEG + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de centeio</li><li>Marmelada caseira sem açúcar refinado</li><li>Creme vegetal de barrar à base de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Toste as fatias de pão de centeio ao seu gosto.</li><li><b>Barrar:</b> Passe uma fina camada de creme vegetal e cubra com fatias finas de marmelada caseira.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PANQUECA_BOLOTA_PINHAO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de bolota</li><li>1 colher de sopa de linhaça moída com água</li><li>Pinhões nacionais para salpicar</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha de bolota com a linhaça hidratada até formar uma massa homogénea.</li><li><b>Cozinhar:</b> Deite na frigideira antiaderente, junte os pinhões na superfície e vire quando fizer bolhas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_WAFFLE_ALFARROBA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha de aveia, 1 de alfarroba</li><li>1/2 chávena de bebida de amêndoa</li><li>Miolo de noz picado</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Misture as farinhas com a bebida de amêndoa até criar um polme macio.</li><li><b>Cozeredura:</b> Coloque na máquina de waffles untada e sirva decorado com o miolo de noz picado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PUDIM_CHIA_KAKI_LARANJA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>1/2 chávena de sumo de laranja natural</li><li>1/2 diospiro kaki em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Gelificar:</b> Misture as sementes de chia no sumo de laranja e deixe repousar até espessar.</li><li><b>Camadas:</b> Sirva o pudim fresco com os cubos de diospiro kaki dispostos no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TACA_BATATA_DOCE_COMPOTA + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce pequena cozida ou assada</li><li>1 colher de compota de abóbora caseira</li><li>Amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Abra a batata-doce quente e esmague ligeiramente o seu interior com um garfo.</li><li><b>Enriquecer:</b> Adicione a compota de abóbora por cima e termine com as amêndoas laminadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CREPE_ESPELTA_AMENDOA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha de espelta</li><li>Bebida vegetal até dar consistência fluida</li><li>Manteiga de amêndoa pura</li></ul><h3>Preparação:</h3><ol><li><b>Frigideira:</b> Cozinhe uma camada fina de massa de espelta numa frigideira antiaderente dos dois lados.</li><li><b>Recheio:</b> Pincele o interior do crepe com a manteiga de amêndoa e dobre em triângulo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MUFFIN_CASTANHA_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de castanha</li><li>1 colher de cacau puro em pó, água q.b.</li><li>Pepitas de chocolate negro</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Misture a farinha de castanha, o cacau e a água até obter uma massa fofa de queque.</li><li><b>Forno:</b> Junte as pepitas, deite numa forma pequena e leve ao forno ou airfryer até cozer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_MEXIDO_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu fresco esmagado</li><li>1/4 de alho-porro fatiado fino</li><li>Cúrcuma e uma pitada de sal preto</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe o alho-porro num fio de azeite e junte o tofu esmagado com a cúrcuma.</li><li><b>Finalizar:</b> Mexa bem durante cinco minutos e termine com o sal preto para dar sabor a ovo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PAPA_CENTEIO_MACA_ASSADA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de centeio</li><li>1/2 chávena de água, 1/2 maçã assada</li><li>Canela em pó a gosto</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza os flocos de centeio na água até formar uma papa densa e aveludada.</li><li><b>Incorporar:</b> Misture a maçã assada esmagada e polvilhe generosamente com canela em pó.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BATIDO_QUENTE_AVELA_AVEIA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de bebida de aveia morna</li><li>1 colher de sopa de manteiga de avelã</li><li>1 colher de flocos de aveia finos</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque todos os ingredientes no copo do liquidificador ou use a varinha mágica.</li><li><b>Servir:</b> Processe até obter uma bebida espessa, homogénea e reconfortante para os dias frios.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SCONES_INTEGRAIS_PASSAS + "', '<h3>Ingredientes:</h3><ul><li>5 colheres de farinha de trigo integral</li><li>Bebida vegetal q.b. e uma pitada de fermento</li><li>Uvas passas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Forme uma massa moldável com a farinha, o fermento, as passas e a bebida vegetal.</li><li><b>Assar:</b> Divida em pequenas bolas achatadas e leve ao forno até que fiquem firmes e fofas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TORRADA_SMASH_FEIJAO_ALHO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grande de pão alentejano</li><li>3 colheres de feijão branco cozido</li><li>1 dente de alho e azeite virgem</li></ul><h3>Preparação:</h3><ol><li><b>Alho:</b> Esfregue o dente de alho na fatia de pão acabada de torrar.</li><li><b>Esmagar:</b> Esfregue ou esmague o feijão branco morno sobre o pão e regue com um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BOLO_CANECA_REINETA_CANELA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha de aveia, 1 de linhaça</li><li>1/4 de maçã reineta em cubos minúsculos</li><li>Canela e 3 colheres de água</li></ul><h3>Preparação:</h3><ol><li><b>Mistura:</b> Junte os ingredientes secos e os cubos de maçã dentro de uma caneca.</li><li><b>Microondas:</b> Adicione a água, mexa rapidamente e leve ao microondas por um minuto e meio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GRANOLA_QUENTE_ROMA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de granola caseira</li><li>1/2 chávena de bebida vegetal quente</li><li>Bagas de romã frescas</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Deite a granola numa taça e regue com a sua bebida vegetal preferida bem quente.</li><li><b>Fruta:</b> Salpique a superfície com as bagas de romã ácidas antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PUDIM_LINHACA_MARMELO + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de linhaça moída</li><li>1/2 chávena de água morna</li><li>1 colher de puré de marmelo caseiro</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture a linhaça na água morna e aguarde dez minutos para criar uma textura de pudim.</li><li><b>Sabor:</b> Misture o puré de marmelo delicadamente antes de comer com uma colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TACA_IOGURTE_COCO_AVELA + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte de coco natural sem açúcar</li><li>1 colher de sobremesa de manteiga de avelã</li><li>Avelãs inteiras tostadas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque o iogurte de coco fresco numa taça pequena de pequeno-almoço.</li><li><b>Toque:</b> Adicione um fio de manteiga de avelã e decore com os pedaços de avelãs tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GALETTE_OUTONO_PERA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha de espelta e água q.b.</li><li>1/2 pera rocha fatiada muito fina</li><li>Amêndoa moída para polvilhar</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Estenda uma massa fina de espelta e água num formato circular rústico.</li><li><b>Recheio:</b> Disponha as fatias de pera no centro, dobre as bordas e leve ao forno até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BRUSCHETTA_COGUMELOS_ALECRIM + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de mafra torrado</li><li>3 cogumelos de paris fatiados</li><li>1 haste de alecrim fresco e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos numa frigideira com azeite e as agulhas de alecrim aromático.</li><li><b>Servir:</b> Deite os cogumelos quentes e o seu suco sobre a fatia de pão de mafra.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PANQUECA_CENTEIO_XAROPE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de centeio integral</li><li>Bebida de arroz q.b. até ligar</li><li>Fio de xarope de ácer ou geleia de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Misture a farinha com a bebida e faça uma panqueca alta numa frigideira quente.</li><li><b>Adoçar:</b> Transfira para um prato e regue com um fio muito leve de xarope de ácer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BOLO_FRIGIDEIRA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de puré de abóbora</li><li>2 colheres de farinha de aveia, pitada de bicabornato</li><li>Sementes de girassol</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture o puré com a aveia e o bicarbonato até criar uma massa compacta.</li><li><b>Tapar:</b> Cozinhe na frigideira tapada em lume mínimo, virando a meio para cozer o interior.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BATIDO_DIOSPIRO_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>1 diospiro de roer ou maduro grande</li><li>1/2 chávena de água límpida ou gelo</li><li>1 rodela fina de gengibre fresco</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Descasque o diospiro e coloque-o em pedaços no liquidificador com o gengibre.</li><li><b>Processar:</b> Junte a água e triture na velocidade máxima até ficar um batido cremoso e picante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TACA_KEFIR_NOZES_MEL + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de kéfir de coco ou vegetal</li><li>3 nozes inteiras descascadas</li><li>Fio de geleia de agave ou xarope de coco</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Deite o kéfir vegetal bem fresco numa taça funda de vidro.</li><li><b>Crocante:</b> Parta as nozes com as mãos sobre o kéfir e adicione o xarope de coco a gosto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TORRADA_PATE_CASTANHA + "', '<h3>Ingredientes:</h3><ul><li>2 fatias finas de pão de sementes</li><li>2 colheres de sopa de paté de castanha caseiro</li><li>Tomilho seco</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Prepare as torradas de pão de sementes na torradeira comum.</li><li><b>Finalizar:</b> Barre o paté cremoso de castanha ainda morno e polvilhe com folhas de tomilho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SMOOTHIE_KALE_MACA_REINETA + "', '<h3>Ingredientes:</h3><ul><li>1 folha de couve kale sem o talo médio</li><li>1/2 maçã reineta com casca bem lavada</li><li>1/2 chávena de água</li></ul><h3>Preparação:</h3><ol><li><b>Introduzir:</b> Rasgue a kale e corte a maçã em pedaços para dentro do copo misturador.</li><li><b>Liquefazer:</b> Processe tudo muito bem com a água até não restarem pedaços de folha visíveis.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PAPA_PAINCO_CACAU_NOZ + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de painço</li><li>1 chávena de bebida de amêndoa quente</li><li>1 colher de café de cacau, nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinar:</b> Misture os flocos de painço e o cacau na bebida de amêndoa ao lume até engrossar.</li><li><b>Decorar:</b> Transfira para a taça final e guarneça com os pedaços de noz crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_OVO_ESCALFADO_ESPINAFRE + "', '<h3>Ingredientes:</h3><ul><li>1 ovo fresco do campo</li><li>1 dada de espinafres frescos</li><li>1 colher de sopa de vinagre, água e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Escalfar:</b> Abra o ovo para uma panela com água a ferver suavemente e o vinagre por três minutos.</li><li><b>Cama:</b> Salteie os espinafres num fio de azeite e sirva o ovo escalfado por cima deles.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BOLACHAS_AVEIA_DIOSPIRO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de aveia grossos</li><li>1 diospiro maduro grande esmagado</li><li>Canela em pó</li></ul><h3>Preparação:</h3><ol><li><b>Envolver:</b> Misture os flocos de aveia com a polpa do diospiro e a canela numa tigela pequena.</li><li><b>Furar:</b> Faça pequenas porções achatadas num tabuleiro e leve a assar até ficarem douradas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_WRAP_QUENTE_MANTEIGA_AMENDOIM + "', '<h3>Ingredientes:</h3><ul><li>1 wrap integral pequeno de compra ou caseiro</li><li>1 colher de sopa de manteiga de amendoim</li><li>1/2 banana fatiada às rodelas</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça o wrap trinta segundos numa frigideira limpa para ficar maleável.</li><li><b>Dobrar:</b> Barre a manteiga de amendoim, disponha as rodelas de banana e enrole bem apertado.</li></ol>');");

