        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COZIDO_RUSTICO_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>Batata, cenoura, nabo, couve</li><li>Grão-de-bico, azeite virgem</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Coza os legumes em água e sal.</li><li><b>Servir:</b> Regue com generoso azeite e acompanhe com grão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ASSADO_TABULEIRO_TEMPEH + "', '<h3>Ingredientes:</h3><ul><li>Tempeh, batatinhas, cebola roxa</li><li>Alecrim, azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Disponha tudo no tabuleiro e leve ao forno até dourar.</li><li><b>Finalizar:</b> Sirva com ervas frescas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_RANCHO_VEGANO_GRAO + "', '<h3>Ingredientes:</h3><ul><li>Grão-de-bico, massa, batata, couve</li><li>Colorau, cebola</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe os ingredientes em lume brando.</li><li><b>Finalizar:</b> Adicione um fio de azeite antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TARTE_RUSTICA_GRELOS + "', '<h3>Ingredientes:</h3><ul><li>Massa quebrada, grelos salteados</li><li>Alho, queijo vegan</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Recheie a massa com os grelos.</li><li><b>Assar:</b> Leve ao forno até a massa ficar crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESTUFADO_LENTILHAS_CASTANHAS + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas, castanhas, cebola</li><li>Louro</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as lentilhas com as castanhas.</li><li><b>Servir:</b> Um prato quente típico da época.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ARROZ_MALANDRO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>Arroz, cogumelos, tomate, cebola</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Faça o arroz com bastante caldo.</li><li><b>Servir:</b> Deve ser servido caldoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SEITAN_PIMENTA_TERRA + "', '<h3>Ingredientes:</h3><ul><li>Seitan, pimenta, molho de soja</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Sele o seitan na frigideira.</li><li><b>Finalizar:</b> Tempere com a pimenta e molho de soja.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_EMPADAO_VEGANO_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>Alho-francês, batata, bebida vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Salteie o alho-francês.</li><li><b>Cobrir:</b> Cubra com puré de batata e leve a gratinar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CARIL_ABOBORA_MANTEIGA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>Abóbora-manteiga, grão, caril</li><li>Leite de coco</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe os ingredientes no leite de coco.</li><li><b>Servir:</b> Acompanhe com arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_FEIJOADA_COUVE_LOMBARDA + "', '<h3>Ingredientes:</h3><ul><li>Feijão, couve lombarda, chouriço vegan</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe tudo apurado.</li><li><b>Servir:</b> Prato robusto de outono.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_RISOTO_CEVADA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>Cevada, cogumelos, caldo vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Prepare a cevada até ficar cremosa.</li><li><b>Finalizar:</b> Junte os cogumelos salteados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_LAGAREIRO_BATATA_MURRO + "', '<h3>Ingredientes:</h3><ul><li>Tofu, batatas pequenas, muito alho</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse as batatas e o tofu com muito azeite e alho.</li><li><b>Servir:</b> Típico prato português.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MASSA_FORNO_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>Massa, abóbora assada, sálvia</li></ul><h3>Preparação:</h3><ol><li><b>Envolver:</b> Misture a massa com a abóbora.</li><li><b>Assar:</b> Leve ao forno com sálvia fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_LASANHA_COGUMELOS_CREME_AVELA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de lasanha, cogumelos</li><li>Creme de avelã caseiro</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Camadas de massa e cogumelos.</li><li><b>Gratinar:</b> Leve ao forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ALMONDEGAS_BOLOTA_MOLHO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>Farinha de bolota, tomate</li><li>Ervas aromáticas</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as almôndegas no molho.</li><li><b>Servir:</b> Acompanhe com massa.</li></ol>');");

