        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BATATA_DOCE_RECHEADA + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce média</li><li>2 colheres de sopa de lentilhas estufadas</li><li>Sementes de sésamo para polvilhar</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse a batata-doce no forno até ficar macia.</li><li><b>Rechear:</b> Abra a batata, recheie com as lentilhas estufadas e finalize com as sementes de sésamo por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_POLENTA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de polenta instantânea</li><li>100 g de cogumelos salteados</li><li>Azeite virgem extra e tomilho</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Coza a polenta em água ou caldo vegetal até engrossar.</li><li><b>Servir:</b> Disponha os cogumelos salteados sobre a polenta ainda quente e aromatize com tomilho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_EMPADAO_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1/2 couve-flor em puré</li><li>1/2 chávena de seitan picado</li><li>Cebola e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Salteie o seitan com a cebola e o tomate. Coloque no fundo de um prato de forno.</li><li><b>Cobertura:</b> Cubra com o puré de couve-flor e leve ao forno a dourar por dez minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_CROSTA_AVELA + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu firme</li><li>2 colheres de avelãs moídas grosseiramente</li><li>Mostarda antiga para pincelar</li></ul><h3>Preparação:</h3><ol><li><b>Pincelar:</b> Barre o bloco de tofu com a mostarda e envolva-o nas avelãs picadas.</li><li><b>Grelhar:</b> Leve à frigideira ou forno até a crosta de avelã estar bem crocante e dourada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ABOBORA_FORNO_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>2 fatias grossas de abóbora</li><li>1 colher de sobremesa de tahini</li><li>Sumo de limão e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve as fatias de abóbora ao forno com sal e azeite até ficarem caramelizadas.</li><li><b>Finalizar:</b> Regue com o molho de tahini batido com limão e polvilhe com bastante salsa fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_FRITTATA_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de tofu sedoso batido</li><li>1 alho-francês fatiado fino</li><li>Cúrcuma e levedura nutricional</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva o alho-francês salteado no tofu batido com a cúrcuma.</li><li><b>Cozinhar:</b> Deite numa frigideira pequena, tape e deixe cozer em lume brando até ficar firme.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COGUMELOS_PORTOBELLO_RECHEADOS + "', '<h3>Ingredientes:</h3><ul><li>2 cogumelos Portobello grandes</li><li>3 colheres de sopa de quinoa cozida</li><li>Alho, salsa e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Limpar:</b> Retire o pé dos cogumelos e pique-o finamente para misturar com a quinoa.</li><li><b>Assar:</b> Recheie as abas com a mistura, regue com azeite e leve ao forno até estarem tenros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESTUFADO_LENTILHAS_COUVE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas castanhas</li><li>2 folhas de couve cortadas em tiras</li><li>Cebola, alho e louro</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Coza as lentilhas com os temperos. A meio da cozedura junte a couve.</li><li><b>Servir:</b> Deixe apurar bem até a água evaporar e as lentilhas estarem tenras.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COUVE_CORACAO_RECHEADA + "', '<h3>Ingredientes:</h3><ul><li>4 folhas de couve coração</li><li>1/2 chávena de cuscuz hidratado</li><li>Tomate picado e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Escaldar:</b> Passe as folhas de couve por água a ferver para amolecerem.</li><li><b>Rechear:</b> Envolva o cuscuz no tomate e hortelã, enrole nas folhas e cozinhe ao vapor.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SALADA_QUENTE_KALE + "', '<h3>Ingredientes:</h3><ul><li>2 dadas de couve kale picada</li><li>1/2 maçã reineta em cubos</li><li>Nozes e vinagrete de limão</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Passe a kale rapidamente pela frigideira quente com um fio de azeite.</li><li><b>Misturar:</b> Junte a maçã fresca, as nozes e tempere com o vinagrete de limão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_STROGANOFF_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>150 g de cogumelos frescos</li><li>2 colheres de sopa de iogurte de soja</li><li>Páprica e cebola picada</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos com a cebola e a páprica até ficarem bem dourados.</li><li><b>Finalizar:</b> Adicione o iogurte no fim, fora do lume, para criar um molho aveludado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUICHE_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>1 massa folhada simples</li><li>2 alhos-franceses salteados</li><li>1 pacote de natas de soja para culinária</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Espalhe o alho-francês sobre a massa, cubra com as natas batidas.</li><li><b>Assar:</b> Leve ao forno médio durante vinte minutos até a massa estar estaladiça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CARIL_RECONFORTANTE_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de legumes variados (cenoura, abóbora)</li><li>1/2 chávena de leite de coco</li><li>Caril e gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Cozinhe os legumes no leite de coco com o caril e o gengibre ralado.</li><li><b>Apurar:</b> Deixe ferver até o molho engrossar e os legumes estarem macios.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MIGAS_GRELOS_BROA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de grelos cozidos</li><li>1 chávena de broa de milho esfarelada</li><li>Muito alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure bastante alho em azeite, junte os grelos e depois a broa esfarelada.</li><li><b>Misturar:</b> Salteie tudo junto até a broa ficar ligeiramente tostada e bem integrada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GNOCCHI_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>100 g de gnocchi cozidos</li><li>3 colheres de puré de abóbora</li><li>Folhas de sálvia fresca e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Frite as folhas de sálvia em azeite até ficarem estaladiças.</li><li><b>Misturar:</b> Envolva os gnocchi no puré de abóbora, junte a sálvia e sirva de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BIFE_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grossa de couve-flor</li><li>Temperos (alho, páprica, sal)</li><li>Azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Temperar:</b> Pincele a fatia de couve-flor com o azeite e os temperos de ambos os lados.</li><li><b>Grelhar:</b> Grelhe na chapa quente até ficar macia por dentro e dourada por fora.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BRUSCHETTA_QUENTE_PATE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio torrada</li><li>2 colheres de paté de azeitona caseiro</li><li>Tomate seco picado</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Barre a fatia de pão torrado com o paté de azeitona.</li><li><b>Finalizar:</b> Cubra com o tomate seco picado e leve ao forno dois minutos apenas para aquecer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TEMPEH_GRELHADO_BROCOLOS + "', '<h3>Ingredientes:</h3><ul><li>100 g de tempeh marinado</li><li>1/2 chávena de floretes de brócolos</li><li>Molho de soja e gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Grelhe o tempeh na chapa até dourar.</li><li><b>Vapor:</b> Coza os brócolos ao vapor e sirva ao lado do tempeh com o molho de soja.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PATANISCAS_LEGUMES_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>Farinha, água, cenoura e alho-francês</li><li>1/2 chávena de arroz cozido</li><li>Óleo para fritar ou airfryer</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha e a água com os legumes picados e frite pequenas porções.</li><li><b>Servir:</b> Acompanhe as pataniscas bem estaladiças com uma pequena porção de arroz.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESTUFADO_FEIJAO_BRANCO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão branco cozido</li><li>1/2 tomate picado e espinafres</li><li>Cebola e alho</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Faça o refogado básico, junte o feijão e um pouco de água.</li><li><b>Finalizar:</b> Deixe ferver dez minutos, adicione os espinafres e desligue o lume.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PASTEL_FORNO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>Massa de empanada simples</li><li>Recheio de lentilhas bem espessas</li><li>Pincelado com bebida de soja</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o recheio de lentilhas na massa, feche e pressione as bordas.</li><li><b>Assar:</b> Leve ao forno quente até que a massa fique bem dourada e estaladiça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SARRACENO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de trigo sarraceno cozido</li><li>1/2 chávena de cogumelos fatiados</li><li>Salsa fresca</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos até secarem a sua água.</li><li><b>Misturar:</b> Envolva o sarraceno nos cogumelos e salpique com bastante salsa picada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUINOA_OUTONO_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de quinoa cozida</li><li>Cubos de abóbora e sementes de abóbora</li><li>Canela e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva a quinoa com os cubos de abóbora e as sementes.</li><li><b>Assar:</b> Disponha num pirex, regue com azeite e leve ao forno até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TARTE_FOLHADA_BETERRABA + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa folhada</li><li>1 beterraba cozida fatiada finamente</li><li>Tomilho fresco</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Disponha as fatias de beterraba sobre a massa folhada.</li><li><b>Assar:</b> Polvilhe com tomilho e leve ao forno até a massa folhada subir e dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MASSA_CREMOSA_CAJU + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa integral</li><li>Molho de caju triturado com levedura</li><li>Manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Coza a massa conforme as instruções.</li><li><b>Envolver:</b> Escorra e misture com o molho de caju cremoso e as folhas de manjericão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BURRITO_BOWL_NOITE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz, feijão preto</li><li>Abacate em fatias e tomate</li><li>Lima</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o arroz e o feijão numa taça.</li><li><b>Finalizar:</b> Disponha o abacate, o tomate por cima e esprema o sumo de lima para servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CREPE_SALGADO_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1 crepe de farinha de grão</li><li>Recheio de legumes salteados</li><li>Molho de tahini</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Faça o crepe numa frigideira antiaderente.</li><li><b>Rechear:</b> Coloque os legumes salteados, enrole e regue com o molho de tahini.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESPETADAS_TOFU_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>Cubos de tofu, pimento e cebola</li><li>Molho de soja e mel de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Alterne o tofu e os legumes nos paus de espetada.</li><li><b>Grelhar:</b> Pincele com o molho e grelhe até os legumes estarem marcados e macios.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PAPA_AVEIA_SALGADA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de flocos de aveia</li><li>1 chávena de caldo de legumes</li><li>Sementes de sésamo e cebolinho</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a aveia no caldo até formar uma papa densa.</li><li><b>Finalizar:</b> Sirva com sementes de sésamo e bastante cebolinho picado por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_WRAP_FORNO_FEIJAO + "', '<h3>Ingredientes:</h3><ul><li>1 wrap integral</li><li>1/2 chávena de feijão estufado com tomate</li><li>Queijo vegan para gratinar</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Coloque o feijão no wrap, enrole e coloque num tabuleiro.</li><li><b>Gratinar:</b> Cubra com o queijo e leve ao forno para derreter e dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_XAREM_NOITE_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de milho</li><li>100 g de cogumelos em pedaços</li><li>Alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Faça o xarém simples com água e sal.</li><li><b>Servir:</b> Salteie os cogumelos com alho e sirva por cima do xarém acabado de fazer.</li></ol>');");

