        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_AVEIA_TANGERINA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>1 chávena de bebida de arroz</li><li>Gomos de tangerina fresca</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Ferva a aveia na bebida de arroz até obter uma textura cremosa.</li><li><b>Servir:</b> Adicione os gomos de tangerina por cima antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_DOCE_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de trigo sarraceno</li><li>2 colheres de puré de abóbora assada</li><li>Canela em pó a gosto</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Prepare as torradas de pão de trigo sarraceno.</li><li><b>Barrar:</b> Espalhe o puré de abóbora morno e finalize com uma pitada generosa de canela.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PANQUECA_CASTANHA_CACAU + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de castanha</li><li>1 colher de café de cacau puro, água q.b.</li><li>Pedaços de chocolate negro</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, o cacau e a água até obter um polme.</li><li><b>Cozinhar:</b> Frite na frigideira antiaderente e junte o chocolate no final.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BOLO_CANECA_MARMELO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha de aveia</li><li>1 colher de puré de marmelo caseiro</li><li>3 colheres de água</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte todos os ingredientes numa caneca e mexa bem.</li><li><b>Cozedura:</b> Leve ao microondas por noventa segundos até subir e estar firme.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_WAFFLE_BATATA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1/2 batata-doce cozida e esmagada</li><li>2 colheres de farinha de arroz</li><li>Canela e gengibre em pó</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Processe a batata com a farinha e especiarias até formar uma massa.</li><li><b>Tostar:</b> Coloque na máquina de waffles até ficar bem dourada e estaladiça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PUDIM_CHIA_DIOSPIRO + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>1/2 chávena de bebida de amêndoa</li><li>Polpa de um diospiro bem maduro</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Deixe a chia na bebida vegetal por trinta minutos.</li><li><b>Finalizar:</b> Sirva com a polpa de diospiro disposta por cima do pudim.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TOFU_MEXIDO_GRELOS + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu esmagado</li><li>1 mão cheia de grelos picados</li><li>Cúrcuma e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os grelos em azeite, junte o tofu e a cúrcuma.</li><li><b>Finalizar:</b> Mexa até o tofu estar seco e aromático.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_CREPE_ESPELTA_MACA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de espelta</li><li>Bebida vegetal q.b.</li><li>Fatias finas de maçã</li></ul><h3>Preparação:</h3><ol><li><b>Frigideira:</b> Faça um crepe fino.</li><li><b>Rechear:</b> Coloque as fatias de maçã e dobre o crepe.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_MUFFIN_AVEIA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de aveia, 1 de linhaça</li><li>Miolo de noz picado</li><li>Água quente q.b.</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Junte os ingredientes numa forma de queque.</li><li><b>Assar:</b> Leve ao forno até estarem firmes e dourados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BATIDO_QUENTE_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de bebida de soja quente</li><li>1 colher de cacau em pó</li><li>Canela em pau para aromatizar</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça a bebida de soja com o pau de canela.</li><li><b>Misturar:</b> Retire a canela, junte o cacau e bata até ficar espumoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_CENTEIO_PASSA_UVA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de centeio</li><li>1 chávena de água</li><li>Uvas passas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a farinha na água mexendo sempre.</li><li><b>Finalizar:</b> Junte as passas antes de servir numa taça quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_CREME_CAJU_ANIS + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão integral</li><li>1 colher de creme de caju</li><li>Sementes de anis</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Toste o pão.</li><li><b>Barrar:</b> Espalhe o creme de caju e polvilhe com as sementes de anis.</li></ol>');");

