        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BARRINHA_AVEIA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>Aveia, geleia de arroz, sementes</li><li>Água para dar liga</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Forme uma massa compacta.</li><li><b>Assar:</b> Corte em retângulos e leve ao forno a dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_OVO_FORNO_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>1 ovo, 1 mão de espinafres</li><li>Fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cama:</b> Coloque os espinafres numa forma pequena.</li><li><b>Assar:</b> Parta o ovo por cima e leve ao forno até a clara cozer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_SMOOTHIE_BOWL_KALE_PERA + "', '<h3>Ingredientes:</h3><ul><li>1 folha de kale, 1/2 pera</li><li>1/2 chávena de bebida vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Misture tudo até obter um batido espesso.</li><li><b>Servir:</b> Deite numa taça e coma à colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_SARRACENO_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de trigo sarraceno</li><li>1 colher de cacau, água</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza até ficar com textura de papa.</li><li><b>Finalizar:</b> Misture o cacau e sirva morno.</li></ol>');");

