        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PUDIM_LINHACA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de linhaça moída</li><li>1 colher de puré de abóbora, água</li></ul><h3>Preparação:</h3><ol><li><b>Gelificar:</b> Misture e deixe repousar dez minutos.</li><li><b>Consumir:</b> Coma à colher como pudim fresco.</li></ol>');");

