        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_FEIJOADA_FEIJOCA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijoca cozida</li><li>1 chávena de cogumelos frescos</li><li>Cebola, alho, louro e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Puxe a cebola e o alho em azeite. Junte os cogumelos e o tomate.</li><li><b>Apurar:</b> Adicione a feijoca e deixe cozinhar em lume brando durante vinte minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ASSADO_SÃO_MARTINHO + "', '<h3>Ingredientes:</h3><ul><li>100 g de seitan, castanhas assadas</li><li>Cenoura e batata</li><li>Vinho branco e alecrim</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Disponha os ingredientes num tabuleiro, regue com vinho branco e alecrim.</li><li><b>Forno:</b> Leve a assar até tudo estar macio e bem dourado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_RANCHO_VEGANO_GRÃO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de grão-de-bico cozido</li><li>Massa de cotovelos, couve portuguesa</li><li>Cenoura, cebola e colorau</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza a massa com os vegetais. Adicione o grão no final.</li><li><b>Finalizar:</b> Tempere com colorau e um fio de azeite antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ARROZ_GRELOS_PATANISCAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz, grelos cozidos</li><li>Pataniscas de legumes (cenoura, farinha)</li><li>Alho</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Coza o arroz com os grelos.</li><li><b>Acompanhar:</b> Sirva com as pataniscas fritas ou feitas na airfryer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ESTUFADO_LENTILHAS_CASTANHAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas, castanhas</li><li>Alho-francês, vinho tinto</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie o alho-francês, junte as lentilhas e as castanhas.</li><li><b>Estufar:</b> Adicione um pouco de vinho tinto e deixe cozinhar até reduzir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ARROZ_FORNO_ABOBORA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz, abóbora em cubos</li><li>Grão-de-bico cozido, açafrão</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva o arroz, a abóbora e o grão.</li><li><b>Assar:</b> Leve ao forno com água a ferver até o arroz estar solto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_EMPADAO_SOJA_PURE_CASTANHA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de proteína de soja hidratada</li><li>Puré de castanha, molho de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Estufe a soja com o tomate.</li><li><b>Cobertura:</b> Cubra com o puré de castanha e leve ao forno a dourar.</li></ol>');");

